  // ---- Message templates: ready-made library, your templates (edit /
  // delete), and the editor with "Send" timing. Server: guest-profile.js
  // (templates / saveTemplate / deleteTemplate); timed sending:
  // _template-scheduling.js.
  const TEMPLATE_LIBRARY = [
    { title: 'Booking confirmed', trigger: 'booking_confirmed', days: 0,
      body: 'Hi @guestname,\n\nThank you for booking @listing for @nights night(s), @arrival to @departure. I look forward to hosting you.\n\nI’ll send check-in details before you arrive. Message me here any time.\n\n@hostname' },
    { title: 'Check-in details', trigger: 'before_checkin', days: 2, unit: 'days',
      body: 'Hi @guestname,\n\nYour stay at @listing starts on @arrival.\n\nCheck-in: from @checkin\nCheck-out: by @checkout\nAddress: @location\nMap: @maplink\n\n@checkinsteps\n\nPlease carry a government photo ID for every adult guest.\n\nSee you soon,\n@hostname' },
    { title: 'Welcome on check-in day', trigger: 'checkin_day', days: 0,
      body: 'Welcome, @guestname! Today is check-in day at @listing.\n\nCheck-in: from @checkin\n@wifi\n\nMessage me here if you need anything.' },
    { title: 'Check-out reminder', trigger: 'checkout_day', days: 0,
      body: 'Good morning, @guestname. Check-out is by @checkout today.\n\nBefore you leave: close windows and doors, switch off lights and AC, and leave the keys as agreed.\n\nThank you for staying. Safe travels!' },
    { title: 'Thank you', trigger: 'after_checkout', days: 1, unit: 'days',
      body: 'Hi @guestname,\n\nThank you for staying at @listing. I hope you had a lovely time.\n\nPlease leave a review on Aerva. It helps other guests and me.\n\nYou’re always welcome back,\n@hostname' },
    { title: 'Directions', trigger: 'manual', days: 0,
      body: 'Here is how to find @listing:\n@location\n@maplink' },
    { title: 'WiFi', trigger: 'manual', days: 0, body: '@wifi' }
  ];
  const TIMED_TRIGGER_WORDS = { before_checkin: 'before check-in', after_checkin: 'after check-in', before_checkout: 'before check-out', after_checkout: 'after check-out' };
  // "18:00" → "6:00 pm"
  function tplClock(v){
    const m = String(v || '').match(/^(\d{1,2}):(\d{2})$/); if(!m) return '';
    const h = Number(m[1]); return `${h % 12 || 12}:${m[2]} ${h < 12 ? 'am' : 'pm'}`;
  }
  function templateWhen(t){
    const n = Number(t.send_offset_value) || Number(t.send_offset_days) || 1;
    const unitWord = (u) => ({ minutes: 'minute', hours: 'hour' }[u] || 'day');
    if(TIMED_TRIGGER_WORDS[t.send_trigger]){
      const u = unitWord(t.send_offset_unit);
      return `Sent ${n} ${u}${n === 1 ? '' : 's'} ${TIMED_TRIGGER_WORDS[t.send_trigger]}${t.send_offset_unit !== 'minutes' && t.send_offset_unit !== 'hours' && t.send_at_time ? ', at ' + tplClock(t.send_at_time) : ''}`;
    }
    switch(t.send_trigger){
      case 'booking_confirmed': return Number(t.send_offset_value) > 0 && (t.send_offset_unit === 'minutes' || t.send_offset_unit === 'hours')
        ? `Sent ${n} ${unitWord(t.send_offset_unit)}${n === 1 ? '' : 's'} after a booking is confirmed` : 'Sent when a booking is confirmed';
      case 'checkin_day': return `Sent on check-in day at ${tplClock(t.send_at_time || '07:30')}`;
      case 'checkout_day': return `Sent on check-out day at ${tplClock(t.send_at_time || '07:30')}`;
      default: return 'Sent when you tap it';
    }
  }
  let templateEditingId = null;
  let templateList = [];

  function syncTemplateTriggerFields(){
    const trig = document.getElementById('tplTrigger').value;
    const needsDays = !!TIMED_TRIGGER_WORDS[trig];
    const dayOf = trig === 'checkin_day' || trig === 'checkout_day';
    const confirm = trig === 'booking_confirmed';
    const unitEl = document.getElementById('tplUnit'), daysEl = document.getElementById('tplDays');
    const atEl = document.getElementById('tplAt');
    // On confirmation: straight away (0) or after some minutes or hours.
    unitEl.querySelector('option[value="days"]').hidden = confirm;
    if(confirm && unitEl.value === 'days') unitEl.value = 'minutes';
    document.getElementById('tplDaysWrap').style.display = needsDays || confirm ? 'block' : 'none';
    document.getElementById('tplDaysLabel').textContent = confirm ? 'Send after (0 = straight away)' : 'How long';
    daysEl.min = confirm ? 0 : 1;
    daysEl.max = { minutes: 720, hours: 72, days: 30 }[unitEl.value] || 30;
    // An exact time: on the day itself, or "N days before/after, at …".
    const showAt = dayOf || (needsDays && unitEl.value === 'days');
    document.getElementById('tplAtWrap').style.display = showAt ? 'block' : 'none';
    document.getElementById('tplAtLabel').textContent = dayOf ? 'At' : 'At (optional, a time of day)';
    if(dayOf && !atEl.value) atEl.value = '07:30';
    const note = document.getElementById('tplTimingNote');
    const n = Number(daysEl.value) || 0, unitWord = { minutes: 'minute', hours: 'hour', days: 'day' }[unitEl.value];
    note.textContent = needsDays
      ? ((unitEl.value === 'days' && atEl.value)
          ? `Sent ${n || 1} ${unitWord}${(n || 1) === 1 ? '' : 's'} ${TIMED_TRIGGER_WORDS[trig]}, at ${tplClock(atEl.value)}, in the property’s time zone.`
          : 'Counted from the listing’s ' + (trig.endsWith('checkin') ? 'check-in' : 'check-out') + ' time, in the property’s time zone.')
        + (trig.startsWith('before_') ? ' Booked later than that? Sent as soon as the booking is confirmed.' : '')
      : dayOf ? `Sent at ${tplClock(atEl.value || '07:30')} on the day, in the property’s time zone. Booked later that day? Sent straight away.`
      : confirm ? (n > 0 ? `Sent ${n} ${unitWord}${n === 1 ? '' : 's'} after the booking is confirmed (within about 5 minutes of that time).` : 'Sent the moment the booking is confirmed.') : '';
    note.style.display = note.textContent ? 'block' : 'none';
    document.getElementById('inboxTemplateScheduleOptions').style.display = trig === 'manual' ? 'none' : 'block';
    if(trig !== 'manual' && !inboxTemplateScheduleListingsLoaded) return loadInboxTemplateScheduleListings();
    return Promise.resolve();
  }
  function openTemplateForm(){
    document.getElementById('tplForm').style.display = 'flex';
    document.getElementById('tplCreateBtn').style.display = 'none';
    document.getElementById('inboxTemplateSaveMsg').style.display = 'none';
    try{ document.getElementById('tplForm').scrollIntoView({ behavior: 'smooth', block: 'start' }); }catch(e){}
  }
  function closeTemplateForm(){
    resetTemplateForm();
    document.getElementById('tplForm').style.display = 'none';
    document.getElementById('tplCreateBtn').style.display = '';
  }
  function resetTemplateForm(){
    templateEditingId = null;
    document.getElementById('tplFormTitle').textContent = 'Create template';
    document.getElementById('tplStartFromWrap').style.display = '';
    document.getElementById('tplStartFrom').value = '';
    document.getElementById('inboxTemplateTitleInput').value = '';
    document.getElementById('inboxTemplateBodyInput').value = '';
    document.getElementById('tplTrigger').value = 'manual';
    document.getElementById('tplDays').value = 2;
    document.getElementById('tplUnit').value = 'days';
    document.getElementById('tplAt').value = '';
    document.querySelectorAll('.inbox-template-schedule-listing').forEach(cb => { cb.checked = false; });
    syncTemplateTriggerFields();
  }
  async function editTemplate(t){
    resetTemplateForm();
    openTemplateForm();
    templateEditingId = t.id;
    document.getElementById('tplFormTitle').textContent = 'Edit template';
    document.getElementById('tplStartFromWrap').style.display = 'none';
    document.getElementById('inboxTemplateTitleInput').value = t.title || '';
    document.getElementById('inboxTemplateBodyInput').value = t.body || '';
    document.getElementById('tplTrigger').value = t.send_trigger || 'manual';
    document.getElementById('tplUnit').value = ['minutes', 'hours'].includes(t.send_offset_unit) ? t.send_offset_unit : 'days';
    document.getElementById('tplDays').value = t.send_trigger === 'booking_confirmed' ? (Number(t.send_offset_value) || 0) : (Number(t.send_offset_value) || Number(t.send_offset_days) || 2);
    document.getElementById('tplAt').value = t.send_at_time || '';
    await syncTemplateTriggerFields();
    const ids = (t.auto_send_listing_ids || []).map(Number);
    document.querySelectorAll('.inbox-template-schedule-listing').forEach(cb => { cb.checked = ids.includes(Number(cb.value)); });
  }

  async function saveTemplatePayload(payload){
    const res = await fetch(SUITES_API_BASE + '/api/guest-profile', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
      body: JSON.stringify(Object.assign({ mode: 'saveTemplate' }, payload))
    });
    const data = await res.json().catch(() => ({}));
    if(!res.ok) throw new Error(data.error || 'Could not save template.');
    return data;
  }
  function showTemplateMsg(text, good){
    const el = document.getElementById('inboxTemplateSaveMsg');
    el.textContent = text;
    el.style.display = 'block';
    el.style.color = good ? '#3a7d44' : '#a3402f';
  }

  function renderTemplateLibrary(){ /* ready-made templates now live in Create → Start from */ }

  async function loadInboxTemplateManager(){
    const container = document.getElementById('inboxTemplateListContainer');
    container.innerHTML = '<p class="tpl-hint">Loading…</p>';
    try{
      const res = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=templates', { headers: { 'Authorization': 'Bearer ' + guestAuthToken() } });
      const data = await res.json();
      templateList = data.templates || [];
      renderTemplateLibrary();
      if(!templateList.length){ container.innerHTML = '<p class="tpl-hint">No templates yet. Tap Create template.</p>'; return; }
      const esc = escapeMessageHtml;
      container.innerHTML = templateList.map(t => {
        const n = (t.auto_send_listing_ids || []).length;
        return `<div class="tpl-item">
          <div class="tpl-item-text">
            <strong>${esc(t.title || 'Untitled')}</strong>
            <span class="tpl-when">${esc(templateWhen(t))}${t.send_trigger !== 'manual' && n ? ` · ${n} propert${n === 1 ? 'y' : 'ies'}` : ''}</span>
            <span class="tpl-body">${esc(t.body)}</span>
          </div>
          <div class="tpl-item-actions">
            <button type="button" class="tpl-btn" data-edit-template="${Number(t.id)}">Edit</button>
            <button type="button" class="tpl-btn" data-delete-template="${Number(t.id)}">Delete</button>
          </div>
        </div>`;
      }).join('');
      container.querySelectorAll('[data-edit-template]').forEach(btn => btn.addEventListener('click', () => {
        const t = templateList.find(x => Number(x.id) === Number(btn.dataset.editTemplate));
        if(t) editTemplate(t);
      }));
      container.querySelectorAll('[data-delete-template]').forEach(btn => btn.addEventListener('click', async () => {
        if(!confirm('Delete this template?')) return;
        try{
          await fetch(SUITES_API_BASE + '/api/guest-profile', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
            body: JSON.stringify({ mode: 'deleteTemplate', templateId: Number(btn.dataset.deleteTemplate) })
          });
          if(Number(btn.dataset.deleteTemplate) === templateEditingId) closeTemplateForm();
          loadInboxTemplateManager();
        }catch(err){ /* list stays as it was; tap again */ }
      }));
    }catch(err){
      container.innerHTML = '<p class="tpl-hint" style="color:#a3402f;">Could not load templates.</p>';
    }
  }

  let inboxTemplateScheduleListingsLoaded = false;
  async function loadInboxTemplateScheduleListings(){
    const container = document.getElementById('inboxTemplateScheduleListings');
    try{
      const res = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=myListingsGuidance', { headers: { 'Authorization': 'Bearer ' + guestAuthToken() } });
      const data = await res.json();
      const listings = data.listings || [];
      inboxTemplateScheduleListingsLoaded = true;
      container.innerHTML = listings.length
        ? listings.map(l => `<label class="tpl-check"><input type="checkbox" class="inbox-template-schedule-listing" value="${Number(l.id)}"> ${escapeMessageHtml(l.property_name)}</label>`).join('')
        : '<p class="tpl-hint">You don’t have any properties yet.</p>';
    }catch(err){
      container.innerHTML = '<p class="tpl-hint" style="color:#a3402f;">Could not load your properties.</p>';
    }
  }

  (function wireTemplateEditor(){
    const chips = document.getElementById('tplPlaceholders');
    const bodyEl = document.getElementById('inboxTemplateBodyInput');
    // Every placeholder, existing and new, with what it fills in.
    chips.innerHTML = KEYWORD_SUGGESTIONS.map(k => `<button type="button" class="tpl-ph-row" data-chip="${k.key}"><code>${k.key}</code><span>${escapeMessageHtml(k.desc)}</span></button>`).join('');
    const startFrom = document.getElementById('tplStartFrom');
    startFrom.innerHTML = '<option value="">Blank</option>' + TEMPLATE_LIBRARY.map((t, i) => `<option value="${i}">${escapeMessageHtml(t.title)}</option>`).join('');
    startFrom.addEventListener('change', () => {
      const t = TEMPLATE_LIBRARY[Number(startFrom.value)];
      if(!t) return;
      document.getElementById('inboxTemplateTitleInput').value = t.title;
      bodyEl.value = t.body;
      document.getElementById('tplTrigger').value = t.trigger;
      document.getElementById('tplDays').value = t.days || 2;
      document.getElementById('tplUnit').value = t.unit || 'days';
      syncTemplateTriggerFields();
    });
    document.getElementById('tplCreateBtn').addEventListener('click', () => { resetTemplateForm(); openTemplateForm(); });
    chips.querySelectorAll('[data-chip]').forEach(c => c.addEventListener('click', () => {
      const k = c.dataset.chip;
      const start = bodyEl.selectionStart != null ? bodyEl.selectionStart : bodyEl.value.length;
      const end = bodyEl.selectionEnd != null ? bodyEl.selectionEnd : start;
      const before = bodyEl.value.slice(0, start);
      const needsSpace = before && !/\s$/.test(before);
      bodyEl.value = before + (needsSpace ? ' ' : '') + k + ' ' + bodyEl.value.slice(end);
      const pos = before.length + (needsSpace ? 1 : 0) + k.length + 1;
      bodyEl.focus();
      try{ bodyEl.setSelectionRange(pos, pos); }catch(e){}
    }));
    document.getElementById('tplTrigger').addEventListener('change', syncTemplateTriggerFields);
    document.getElementById('tplUnit').addEventListener('change', syncTemplateTriggerFields);
    document.getElementById('tplDays').addEventListener('input', syncTemplateTriggerFields);
    document.getElementById('tplAt').addEventListener('input', syncTemplateTriggerFields);
    document.getElementById('tplCancelEdit').addEventListener('click', closeTemplateForm);
    document.getElementById('inboxAddTemplateBtn').addEventListener('click', async () => {
      const title = document.getElementById('inboxTemplateTitleInput').value.trim();
      const body = bodyEl.value.trim();
      if(!body){ showTemplateMsg('Write the message first.', false); return; }
      const trigger = document.getElementById('tplTrigger').value;
      const unit = ['minutes', 'hours'].includes(document.getElementById('tplUnit').value) ? document.getElementById('tplUnit').value : 'days';
      const days = trigger === 'booking_confirmed' ? Math.max(0, Number(document.getElementById('tplDays').value) || 0) : (Number(document.getElementById('tplDays').value) || 1);
      const atTime = document.getElementById('tplAt').value || '';
      const ids = trigger === 'manual' ? [] : Array.from(document.querySelectorAll('.inbox-template-schedule-listing:checked')).map(cb => Number(cb.value));
      const btn = document.getElementById('inboxAddTemplateBtn');
      btn.disabled = true;
      try{
        await saveTemplatePayload({ templateId: templateEditingId || undefined, title, body, sendTrigger: trigger, sendOffsetValue: days, sendOffsetUnit: unit, sendOffsetDays: unit === 'days' ? days : undefined, sendAtTime: atTime || undefined, autoSendListingIds: ids });
        const msg = templateEditingId ? 'Changes saved.' : 'Template created.';
        closeTemplateForm();
        showTemplateMsg(msg, true);
        loadInboxTemplateManager();
      }catch(err){ showTemplateMsg(err.message, false); }
      btn.disabled = false;
    });
  })();

  async function performSearch(){
    const arrival = searchArrivalDate;
    const departure = searchDepartureDate;
    const city = document.getElementById('searchCity').value.trim();
    const guests = document.getElementById('searchGuests').value;
    const statusEl = document.getElementById('searchStatus');

    if((arrival && !departure) || (!arrival && departure)){
      statusEl.textContent = 'Please pick both an arrival and departure date, or leave both blank.';
      statusEl.style.display = 'block';
      return;
    }
    if(arrival && departure && new Date(departure) <= new Date(arrival)){
      statusEl.textContent = 'Departure must be after arrival.';
      statusEl.style.display = 'block';
      return;
    }

    const container = document.getElementById('suitesContainer');
    container.innerHTML = '<div class="suites-loading">Searching…</div>';
    statusEl.style.display = 'none';

    // A typed place is turned into "within 200km" rather than an exact
    // text match — geocoding failure (an unrecognized place name) just
    // falls back to no location filter at all, rather than blocking search.
    // If the guest picked a real suggestion, we already have exact
    // coordinates — no need to geocode the same text again. Only fall
    // back to geocoding when they typed freely without selecting one —
    // freeForwardGeocode tries Nominatim first, Google only if that fails.
    const selectedLat = document.getElementById('searchPlaceLat').value;
    const selectedLng = document.getElementById('searchPlaceLng').value;
    const geocoded = (selectedLat && selectedLng)
      ? { lat: Number(selectedLat), lng: Number(selectedLng) }
      : (city ? await freeForwardGeocode(city) : null);

    if(city) saveRecentSearch(city, geocoded ? geocoded.lat : '', geocoded ? geocoded.lng : '');
    searchCenter = (city && geocoded) ? { lat: Number(geocoded.lat), lng: Number(geocoded.lng) } : null;

    const params = new URLSearchParams();
    if(geocoded){
      params.set('lat', geocoded.lat);
      params.set('lng', geocoded.lng);
      params.set('radiusKm', '200');
      // City text is deliberately NOT also sent here — get-listings.js
      // ignores it when a real distance search is active anyway, and
      // more importantly shouldn't apply it: a "Mumbai" search should
      // still surface a nearby Pune listing within 200km, even though
      // its city field says "Pune," not "Mumbai."
    } else if(city){
      // Geocoding failed — still worth trying the old exact-text match
      // as a fallback rather than silently dropping the filter.
      params.set('city', city);
    }
    if(guests) params.set('guests', guests);
    if(arrival && departure){ params.set('arrival', arrival); params.set('departure', departure); }
    // Optional. "At least N rooms" in one property: a home's bedrooms, or
    // a Resort's bookable rooms (free ones, when dates are set). See
    // get-listings.js.
    const roomsNeeded = document.getElementById('roomsNeeded').value;
    if(roomsNeeded) params.set('roomsNeeded', roomsNeeded);

    try{
      // Scoped to whichever tab is actually active — searching while on
      // "Aerva Experience" only touches experience results, and switching
      // to "Suites" afterward shows suites completely unaffected by that
      // search (and vice versa). Only "All" updates both together, since
      // that view is showing both anyway.
      const searchSuites = currentCategoryFilter !== 'experiences';
      const searchExperiences = currentCategoryFilter !== 'suites';
      let suitesCount = approvedListings.length;
      let experiencesCount = approvedExperiences.length;

      if(searchSuites){
        const url = SUITES_API_BASE + '/api/get-listings' + (params.toString() ? '?' + params.toString() : '');
        const res = await fetch(url);
        if(!res.ok) throw new Error('Search failed');
        const data = await res.json();
        approvedListings = visibleOnly(data.listings || []);
        listingsById = {};
        approvedListings.forEach(l => { listingsById[l.id] = l; });
        suitesCount = approvedListings.length;
      }

      // Same location filter now applies to experiences too — same
      // params, same 200km radius, just against the experiences=1 mode
      // instead. Dates now carry over too — a searched date range that
      // overlaps a host-blocked range (or an existing booking) excludes
      // that experience from results, same rule stays already have.
      // Guest count still doesn't carry over — experiences don't have a
      // capacity concept at search time the way a stay's guest count does.
      if(searchExperiences){
        const expParams = new URLSearchParams({ experiences: '1' });
        if(geocoded){
          expParams.set('lat', geocoded.lat);
          expParams.set('lng', geocoded.lng);
          expParams.set('radiusKm', '200');
        } else if(city){
          expParams.set('city', city);
        }
        if(arrival && departure){
          expParams.set('arrival', arrival);
          expParams.set('departure', departure);
        }
        try{
          const expRes = await fetch(SUITES_API_BASE + '/api/get-listings?' + expParams.toString());
          if(expRes.ok){
            const expData = await expRes.json();
            approvedExperiences = visibleOnly(expData.experiences || []);
            experiencesById = {};
            approvedExperiences.forEach(e => { experiencesById[e.id] = e; });
            experiencesLoaded = true;
            experiencesCount = approvedExperiences.length;
          }
        } catch(expErr){
          // Non-fatal — the search still shows correctly-filtered suites
          // even if the experiences half of the request specifically failed.
        }
      }

      const hasFilters = city || guests || (arrival && departure) || roomsNeeded;
      if(hasFilters){
        // Only counts whichever type(s) this search actually touched —
        // a suites-only search reporting an experience count that didn't
        // change would be misleading about what was actually searched.
        const totalResults = (searchSuites ? suitesCount : 0) + (searchExperiences ? experiencesCount : 0);
        statusEl.textContent = totalResults
          ? `Showing ${totalResults} result${totalResults === 1 ? '' : 's'} matching your search.`
          : 'Nothing matches your search — try different dates, guests, or place.';
        statusEl.style.display = 'block';
        // Recounted after the pet, price and badge filters run (see
        // applyFiltersAndRender), so it never says "20 results" over an
        // empty grid.
        searchStatusCounts = { suites: !!searchSuites, experiences: !!searchExperiences };
      }

      // Did the typed/selected place resolve to one specific property's
      // own address, rather than just a general city/area? A guest
      // typing "The Willow Cottage, Jibhi" (or picking that exact
      // address from the autocomplete) will geocode to essentially the
      // same point the host saved for that listing — a general area
      // search never lands this close to one exact building. 300m alone
      // isn't quite enough of a guarantee, though — a broad city/
      // district search (e.g. "Mumbai Suburban") can coincidentally
      // geocode to a point within 300m of some listing purely by chance,
      // especially in a dense area, which used to hide every other
      // result behind a false "this one property matches" screen. Now
      // also requires the searched text to actually share a real word
      // with that listing's own name or address — a genuine address
      // search naturally does; a city/area name coincidentally landing
      // nearby doesn't.
      function sharesSignificantWord(searchText, listingText){
        const STOPWORDS = new Set(['the','and','near','city','area','district','sub','suburban','resort','stay','home','villa','apartment','road','street','nagar']);
        const tokenize = (s) => (s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3 && !STOPWORDS.has(w));
        const searchWords = new Set(tokenize(searchText));
        return tokenize(listingText).some(w => searchWords.has(w));
      }

      specificListingMatch = null;
      specificListingMatchGeo = null;
      if(searchSuites && geocoded){
        const TIGHT_MATCH_KM = 0.3;
        let closest = null, closestKm = Infinity;
        approvedListings.forEach(l => {
          if(l.latitude && l.longitude){
            const km = haversineDistanceKm(geocoded.lat, geocoded.lng, Number(l.latitude), Number(l.longitude));
            if(km < closestKm){ closestKm = km; closest = l; }
          }
        });
        if(closest && closestKm <= TIGHT_MATCH_KM && sharesSignificantWord(city, closest.property_name)){
          specificListingMatch = closest;
          specificListingMatchGeo = geocoded;
        }
      }

      applyFiltersAndRender();
    } catch(err){
      container.innerHTML = '<div class="suites-empty">Could not search right now. Please try again.</div>';
    }
  }

  // ---- Listing detail modal ----
  // Shared by the full listing page (and kept for the modal, in case it's
  // ever wired back up) — builds the photos + content HTML for one
  // listing's detail view. Never trims the description here: that's
  // deliberately kept off the small grid cards, but a guest who opened
  // the full listing page asked to see everything.
  // ---- Photo collage + lightbox (listing detail view only) ----
  // Shows up to 4 photos as a 2x2 grid instead of the one-at-a-time
  // carousel. A 5th+ photo doesn't get hidden — the 4th tile shows a
  // "+N photos" overlay, and any tile click opens the lightbox below
  // with every photo, starting at whichever one was clicked.
  function buildPhotoCollageHtml(photos, altText, listingId){
    if(!photos.length) return '';
    if(photos.length === 1){
      return `<div class="photo-collage-single" data-lightbox-photos data-listing-id="${listingId}"><img src="${escapeMessageHtml(photos[0])}" alt="${escapeMessageHtml(altText)}" loading="lazy" data-lightbox-index="0"></div>`;
    }
    const shown = photos.slice(0, 4);
    const remaining = photos.length - shown.length;
    const tiles = shown.map((url, i) => {
      const isLastVisible = i === shown.length - 1;
      const overlay = (isLastVisible && remaining > 0)
        ? `<div class="photo-collage-more-overlay">+${remaining} photo${remaining === 1 ? '' : 's'}</div>`
        : '';
      return `<div class="photo-collage-tile" data-lightbox-index="${i}"><img src="${escapeMessageHtml(url)}" alt="${escapeMessageHtml(altText)}" loading="lazy">${overlay}</div>`;
    }).join('');
    return `<div class="photo-collage" data-lightbox-photos data-listing-id="${listingId}">${tiles}</div>`;
  }

  let lightboxPhotos = [];
  let lightboxIndex = 0;

  // Shows every room's own photos, clearly labeled, so a guest browsing
  // a Resort with several rooms can actually tell which bedroom is
  // which before picking — the whole-listing photo pool used to mix
  // every room's photos together with no way to tell them apart. Once
  // the guest checks a room (or rooms), this narrows to just those
  // room(s)' own photos instead, since at that point the guest has
  // already told us which room(s) they actually care about.
  function renderRoomAwarePhotos(listing, selectedRoomIds){
    const container = document.getElementById('resortPhotosContainer');
    if(!container) return;
    const rooms = Array.isArray(listing.rooms) ? listing.rooms : [];
    window.roomPhotosForLightbox = window.roomPhotosForLightbox || {};

    const roomsToShow = (selectedRoomIds && selectedRoomIds.length)
      ? rooms.filter(r => selectedRoomIds.includes(r.id))
      : rooms;

    let html = '';
    roomsToShow.forEach(room => {
      const photos = Array.isArray(room.photos) ? room.photos : (room.coverPhotoUrl ? [room.coverPhotoUrl] : []);
      if(!photos.length) return;
      const lightboxId = `room-${listing.id}-${room.id}`;
      window.roomPhotosForLightbox[lightboxId] = photos;
      html += `
        <div style="margin-bottom:18px;">
          <div style="font-size:12.5px; font-weight:600; margin-bottom:8px;">${escapeMessageHtml(room.roomName || 'Room')}</div>
          ${buildPhotoCollageHtml(photos, room.roomName || listing.property_name, lightboxId)}
        </div>
      `;
    });

    // Exterior/common-area shots aren't tied to any one room — shown
    // underneath, once, regardless of which room(s) are selected, so a
    // guest can still see the grounds/shared spaces either way.
    const exteriorPhotos = Array.isArray(listing.exterior_photo_urls) ? listing.exterior_photo_urls : [];
    if(exteriorPhotos.length){
      const lightboxId = `room-${listing.id}-common`;
      window.roomPhotosForLightbox[lightboxId] = exteriorPhotos;
      html += `
        <div style="margin-bottom:18px;">
          <div style="font-size:12.5px; font-weight:600; margin-bottom:8px;">Common Areas &amp; Grounds</div>
          ${buildPhotoCollageHtml(exteriorPhotos, listing.property_name, lightboxId)}
        </div>
      `;
    }

    container.innerHTML = html || '<p style="font-size:13px; opacity:0.6;">No photos available yet.</p>';
  }

  function openPhotoLightbox(photos, startIndex){
    lightboxPhotos = photos;
    lightboxIndex = startIndex || 0;
    renderPhotoLightbox();
  }
  function renderPhotoLightbox(){
    let overlay = document.getElementById('photoLightboxOverlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.className = 'photo-lightbox-overlay';
      overlay.id = 'photoLightboxOverlay';
      document.body.appendChild(overlay);
      overlay.addEventListener('click', (e) => { if(e.target === overlay) closePhotoLightbox(); });
      // Keyboard: Escape closes the photos, arrow keys step through them.
      document.addEventListener('keydown', (e) => {
        if(overlay.style.display !== 'flex') return;
        if(e.key === 'Escape'){ e.preventDefault(); closePhotoLightbox(); }
        else if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){
          const b = document.getElementById(e.key === 'ArrowLeft' ? 'photoLightboxPrevBtn' : 'photoLightboxNextBtn');
          if(b){ e.preventDefault(); b.click(); }
        }
      });
    }
    overlay.innerHTML = `
      <button type="button" class="photo-lightbox-close" id="photoLightboxCloseBtn" aria-label="Close">&times;</button>
      ${lightboxPhotos.length > 1 ? '<button type="button" class="photo-lightbox-nav photo-lightbox-prev" id="photoLightboxPrevBtn" aria-label="Previous photo">&larr;</button>' : ''}
      <img class="photo-lightbox-img" src="${lightboxPhotos[lightboxIndex]}" alt="">
      ${lightboxPhotos.length > 1 ? '<button type="button" class="photo-lightbox-nav photo-lightbox-next" id="photoLightboxNextBtn" aria-label="Next photo">&rarr;</button>' : ''}
      ${lightboxPhotos.length > 1 ? `<div class="photo-lightbox-counter">${lightboxIndex + 1} / ${lightboxPhotos.length}</div>` : ''}
    `;
    overlay.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    document.getElementById('photoLightboxCloseBtn').addEventListener('click', closePhotoLightbox);
    const prevBtn = document.getElementById('photoLightboxPrevBtn');
    const nextBtn = document.getElementById('photoLightboxNextBtn');
    if(prevBtn) prevBtn.addEventListener('click', () => { lightboxIndex = (lightboxIndex - 1 + lightboxPhotos.length) % lightboxPhotos.length; renderPhotoLightbox(); });
    if(nextBtn) nextBtn.addEventListener('click', () => { lightboxIndex = (lightboxIndex + 1) % lightboxPhotos.length; renderPhotoLightbox(); });
  }
  function closePhotoLightbox(){
    const overlay = document.getElementById('photoLightboxOverlay');
    if(overlay) overlay.style.display = 'none';
    document.body.style.overflow = document.getElementById('listingModalOverlay').style.display === 'flex' ? 'hidden' : '';
  }

  // ---- Property walkthrough (listing.walkthrough: [{ url, label }]) ----
  // The host's ordered photos from the entrance to the end of the
  // property; the guest steps through them like walking the route.
  function walkthroughStops(listing){
    const raw = listing && Array.isArray(listing.walkthrough) ? listing.walkthrough : [];
    return raw.map(e => typeof e === 'string' ? { url: e, label: '' } : e)
              .filter(e => e && typeof e.url === 'string' && /^https:\/\/[a-z0-9-]+\.public\.blob\.vercel-storage\.com\//i.test(e.url))
              .map(e => ({ url: e.url, label: typeof e.label === 'string' ? e.label.trim().slice(0, 40) : '' }));
  }
  function buildWalkthroughTeaserHtml(listing){
    const stops = walkthroughStops(listing);
    if(stops.length < 2) return '';
    const esc = escapeMessageHtml;
    const thumbs = stops.slice(0, 3).map(st => `<img src="${esc(st.url)}" alt="" loading="lazy">`).join('');
    const first = stops[0].label, last = stops[stops.length - 1].label;
    const route = first && last ? `From the ${esc(first.toLowerCase())} to the ${esc(last.toLowerCase())}` : 'From the entrance through the whole property';
    return `
      <div class="wt-teaser" data-walkthrough-teaser="${listing.id}">
        <div class="wt-teaser-head">
          <div class="wt-teaser-thumbs">${thumbs}</div>
          <div class="wt-teaser-text"><strong>Walk through the property</strong><span>${route} · ${stops.length} stops</span></div>
        </div>
        <button type="button" class="btn" data-open-walkthrough="${listing.id}">Start the walkthrough</button>
      </div>`;
  }
  let wtState = null;
  function openWalkthrough(listingId){
    const listing = listingsById[listingId];
    const stops = listing ? walkthroughStops(listing) : [];
    if(!stops.length) return;
    wtState = { stops, i: 0, seen: new Set([0]), name: listing.property_name || 'Walkthrough', ended: false };
    let overlay = document.getElementById('walkthroughOverlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = 'walkthroughOverlay';
      overlay.className = 'wt-overlay';
      document.body.appendChild(overlay);
      overlay.addEventListener('click', (e) => {
        const t = e.target.closest('[data-wt]');
        if(!t) return;
        const a = t.dataset.wt;
        if(a === 'close') closeWalkthrough();
        else if(a === 'prev') walkthroughGo(wtState.i - 1);
        else if(a === 'next') walkthroughGo(wtState.i + 1);
        else if(a === 'restart') walkthroughGo(0);
        else if(a === 'stop') walkthroughGo(Number(t.dataset.index));
      });
      let touchX = null;
      overlay.addEventListener('touchstart', (e) => { touchX = e.touches[0].clientX; }, { passive: true });
      overlay.addEventListener('touchend', (e) => {
        if(touchX === null) return;
        const dx = e.changedTouches[0].clientX - touchX; touchX = null;
        if(Math.abs(dx) > 50) walkthroughGo(wtState.i + (dx < 0 ? 1 : -1));
      }, { passive: true });
    }
    overlay.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    document.addEventListener('keydown', walkthroughKeys);
    renderWalkthrough();
    // The next photo is fetched ahead, so stepping forward never waits.
    stops.slice(1, 3).forEach(st => { const im = new Image(); im.src = st.url; });
  }
  function walkthroughKeys(e){
    if(!wtState) return;
    if(e.key === 'Escape') closeWalkthrough();
    else if(e.key === 'ArrowRight') walkthroughGo(wtState.i + 1);
    else if(e.key === 'ArrowLeft') walkthroughGo(wtState.i - 1);
  }
  function walkthroughGo(i){
    if(!wtState) return;
    const n = wtState.stops.length;
    if(i >= n){ wtState.ended = true; renderWalkthrough(); return; }
    if(i < 0) i = 0;
    wtState.i = i; wtState.ended = false; wtState.seen.add(i);
    renderWalkthrough();
    const nxt = wtState.stops[i + 1]; if(nxt){ const im = new Image(); im.src = nxt.url; }
  }
  function renderWalkthrough(){
    const overlay = document.getElementById('walkthroughOverlay');
    if(!overlay || !wtState) return;
    const esc = escapeMessageHtml;
    const { stops, i, ended } = wtState;
    const cur = stops[i];
    const label = cur.label || (i === 0 ? 'Where you arrive' : `Stop ${i + 1}`);
    overlay.innerHTML = `
      <div class="wt-top">
        <span class="wt-title">${esc(wtState.name)} · Walkthrough</span>
        <button type="button" class="wt-close" data-wt="close" aria-label="Close walkthrough">&times;</button>
      </div>
      <div class="wt-stage" id="walkthroughStage">
        <img src="${esc(cur.url)}" alt="${esc(label)}">
        <button type="button" class="wt-nav wt-prev" data-wt="prev" aria-label="Back" ${i === 0 ? 'disabled' : ''}>&larr;</button>
        <button type="button" class="wt-nav wt-next" data-wt="next" aria-label="Next">&rarr;</button>
        <div class="wt-caption"><span class="wt-step">${i + 1} of ${stops.length}</span><span class="wt-label">${esc(label)}</span></div>
        ${ended ? `
        <div class="wt-end">
          <h3>You have walked the whole property</h3>
          <p>${stops.length} stops, from ${esc((stops[0].label || 'the entrance').toLowerCase())} to ${esc((stops[stops.length - 1].label || 'the end').toLowerCase())}.</p>
          <div style="display:flex; gap:10px; flex-wrap:wrap; justify-content:center;">
            <button type="button" class="btn" data-wt="restart">Walk it again</button>
            <button type="button" class="btn solid" data-wt="close">Back to the listing</button>
          </div>
        </div>` : ''}
      </div>
      <div class="wt-progress"><i style="width:${Math.round(((ended ? stops.length : i + 1) / stops.length) * 100)}%"></i></div>
      <div class="wt-route" id="walkthroughRoute">
        ${stops.map((st, k) => `<button type="button" class="wt-stop ${k === i && !ended ? 'is-current' : ''} ${wtState.seen.has(k) ? 'is-seen' : ''}" data-wt="stop" data-index="${k}" title="${esc(st.label || 'Stop ' + (k + 1))}">
            <img src="${esc(st.url)}" alt="" loading="lazy"><span>${k + 1}. ${esc(st.label || 'Stop ' + (k + 1))}</span></button>`).join('')}
      </div>`;
    const curStop = overlay.querySelector('.wt-stop.is-current');
    if(curStop && curStop.scrollIntoView) curStop.scrollIntoView({ block: 'nearest', inline: 'center', behavior: 'smooth' });
  }
  function closeWalkthrough(){
    const overlay = document.getElementById('walkthroughOverlay');
    if(overlay) overlay.style.display = 'none';
    document.removeEventListener('keydown', walkthroughKeys);
    wtState = null;
    document.body.style.overflow = document.getElementById('listingModalOverlay').style.display === 'flex' ? 'hidden' : '';
  }
  document.addEventListener('click', function(e){
    const b = e.target.closest('[data-open-walkthrough]');
    if(b) openWalkthrough(b.dataset.openWalkthrough);
  });
  window.openWalkthrough = openWalkthrough;

  // ---- Ask the host (an enquiry before booking; guest-profile mode 'inquiry') ----
  // Opens the guest's Messages thread with this listing's host. The host
  // is emailed; contact details are removed exactly as in a booking chat.
  let lgCurrentSelection = { arrival: null, departure: null };
  function buildAskHostHtml(listing){
    return `<button type="button" class="ask-host-link" data-ask-host="${listing.id}">Have a question? Ask the host</button>`;
  }
  function openInquiryPanel(listingId){
    const listing = listingsById[listingId];
    if(!listing) return;
    requireLoginForBooking(() => renderInquiryPanel(listing));
  }
  function renderInquiryPanel(listing){
    const esc = escapeMessageHtml;
    let overlay = document.getElementById('inquiryOverlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = 'inquiryOverlay';
      overlay.className = 'inq-overlay';
      document.body.appendChild(overlay);
      overlay.addEventListener('click', (e) => { if(e.target === overlay || e.target.closest('[data-inq-close]')) closeInquiryPanel(); });
    }
    const sel = lgCurrentSelection || {};
    overlay.innerHTML = `
      <div class="inq-card" role="dialog" aria-label="Ask the host">
        <button type="button" class="inq-close" data-inq-close aria-label="Close">&times;</button>
        <h3>Ask ${esc(listing.host_name || 'the host')}</h3>
        <p class="inq-sub">About <strong>${esc(listing.property_name)}</strong>. The host replies in your Messages, usually within a few hours.</p>
        <form id="inquiryForm">
          <div class="inq-grid">
            <div><label for="inqArrival">Check-in (optional)</label><input type="date" id="inqArrival" value="${esc(sel.arrival || '')}"></div>
            <div><label for="inqDeparture">Check-out</label><input type="date" id="inqDeparture" value="${esc(sel.departure || '')}"></div>
            <div><label for="inqGuests">Guests</label><input type="number" id="inqGuests" min="1" max="50" placeholder="2"></div>
          </div>
          <label for="inqText">Your question</label>
          <textarea id="inqText" maxlength="1500" placeholder="Is the pool heated in December? Can we check in after 10 pm?" required></textarea>
          <p class="inq-note">For everyone's safety, keep the conversation and any payment on Aerva. Phone numbers and email addresses are removed from messages automatically.</p>
          <p class="inq-error" id="inqError"></p>
          <button type="submit" class="btn solid" id="inqSendBtn" style="width:100%;">Send to the host</button>
        </form>
      </div>`;
    overlay.style.display = 'flex';
    document.getElementById('inqText').focus();
    document.getElementById('inquiryForm').addEventListener('submit', async (e) => {
      e.preventDefault();
      const btn = document.getElementById('inqSendBtn'), err = document.getElementById('inqError');
      err.style.display = 'none';
      btn.disabled = true; btn.textContent = 'Sending…';
      try{
        const body = { mode: 'inquiry', listingId: listing.id, text: document.getElementById('inqText').value,
          arrival: document.getElementById('inqArrival').value || undefined, departure: document.getElementById('inqDeparture').value || undefined,
          guests: document.getElementById('inqGuests').value ? Number(document.getElementById('inqGuests').value) : undefined };
        const res = await fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() }, body: JSON.stringify(body) });
        const data = await res.json();
        if(!res.ok) throw new Error(data.error || 'Could not send your question.');
        overlay.querySelector('.inq-card').innerHTML = `
          <button type="button" class="inq-close" data-inq-close aria-label="Close">&times;</button>
          <div class="inq-done">
            <h3>Sent to ${esc(listing.host_name || 'the host')}</h3>
            <p>${data.message && data.message.was_redacted ? 'Contact details were removed from your message before it was sent. ' : ''}You will find the reply in your Messages, and get an email when it arrives.</p>
            <a class="btn solid" href="index.html?view=messages">Open Messages</a>
          </div>`;
      } catch(ex){
        err.textContent = ex.message; err.style.display = 'block';
        btn.disabled = false; btn.textContent = 'Send to the host';
      }
    });
  }
  function closeInquiryPanel(){
    const overlay = document.getElementById('inquiryOverlay');
    if(overlay) overlay.style.display = 'none';
  }
  document.addEventListener('click', function(e){
    const b = e.target.closest('[data-ask-host]');
    if(b) openInquiryPanel(b.dataset.askHost);
  });
  window.openInquiryPanel = openInquiryPanel;

  // Delegated click handler — works for any collage rendered anywhere,
  // present or future, without needing per-tile listeners re-attached
  // every time the modal content is rebuilt.
  document.addEventListener('click', function(e){
    const tile = e.target.closest('[data-lightbox-photos] [data-lightbox-index]');
    if(!tile) return;
    const wrap = tile.closest('[data-lightbox-photos]');
    // The collage only ever keeps up to 4 <img> tiles in the DOM even
    // when more photos exist — reopen against the listing's FULL photo
    // list (same order used to build the collage), not just what's
    // visibly rendered, so "+N photos" genuinely shows everything.
    let fullList = Array.from(wrap.querySelectorAll('img')).map(img => img.src);
    const rawId = wrap.dataset.listingId;
    const listing = listingsById[rawId];
    if(listing){
      const ext = Array.isArray(listing.exterior_photo_urls) ? listing.exterior_photo_urls : [];
      const intr = Array.isArray(listing.interior_photo_urls) ? listing.interior_photo_urls : [];
      let all = [...intr, ...ext];
      if(listing.cover_photo_url && all.includes(listing.cover_photo_url)){
        all = [listing.cover_photo_url, ...all.filter(u => u !== listing.cover_photo_url)];
      }
      if(all.length) fullList = all;
    } else if(typeof rawId === 'string' && rawId.startsWith('exp-hosting-')){
      // The "Your Stay" collage inside an experience's detail page (see
      // buildExperienceDetailHtml) — uses the hosting property's OWN
      // photo fields, kept on the experience object itself rather than
      // in listingsById (experiences aren't stay listings).
      const exp = experiencesById[rawId.replace('exp-hosting-', '')];
      if(exp){
        const ext = Array.isArray(exp.hosting_exterior_photo_urls) ? exp.hosting_exterior_photo_urls : [];
        const intr = Array.isArray(exp.hosting_interior_photo_urls) ? exp.hosting_interior_photo_urls : [];
        let all = [...intr, ...ext];
        if(exp.hosting_cover_photo_url && all.includes(exp.hosting_cover_photo_url)){
          all = [exp.hosting_cover_photo_url, ...all.filter(u => u !== exp.hosting_cover_photo_url)];
        }
        if(all.length) fullList = all;
      }
    } else if(typeof rawId === 'string' && rawId.startsWith('exp-')){
      // The experience's own photo collage at the top of its detail page.
      const exp = experiencesById[rawId.replace('exp-', '')];
      if(exp){
        const ext = Array.isArray(exp.exterior_photo_urls) ? exp.exterior_photo_urls : [];
        const intr = Array.isArray(exp.interior_photo_urls) ? exp.interior_photo_urls : [];
        let all = [...intr, ...ext];
        if(exp.cover_photo_url && all.includes(exp.cover_photo_url)){
          all = [exp.cover_photo_url, ...all.filter(u => u !== exp.cover_photo_url)];
        }
        if(all.length) fullList = all;
      }
    } else if(typeof rawId === 'string' && rawId.startsWith('room-')){
      // A specific Resort room's own photo collage (see
      // renderRoomAwarePhotos) — the full list lives in
      // window.roomPhotosForLightbox since these rooms aren't tracked in
      // listingsById at all (that map only holds whole listings).
      const full = window.roomPhotosForLightbox && window.roomPhotosForLightbox[rawId];
      if(Array.isArray(full) && full.length) fullList = full;
    }
    openPhotoLightbox(fullList, Number(tile.dataset.lightboxIndex));
  });

  // ---- Google Map embed (listing detail sidebar) ----
  // Reuses the same Maps JS API script already loaded for address
  // autocomplete elsewhere on this page (see initGoogleMaps near the
  // top) — no second script tag needed. The script loads async, so this
  // polls briefly rather than assuming google.maps is ready the instant
  // the modal opens.
  // Free map display via Leaflet + OpenStreetMap tiles — used everywhere
  // a map is just shown with a pin (listing detail, experience detail,
  // meeting point). Google Maps is only used as a fallback if Leaflet
  // itself somehow failed to load (e.g. its CDN is blocked/unreachable),
  // which keeps this feature working either way while defaulting to the
  // free option to avoid Google Maps API costs.
  function initListingMapEmbed(container, lat, lng, label){
    if(!container) return;
    if(window.L){
      const centerPosition = [Number(lat), Number(lng)];
      const map = L.map(container, { zoomControl: true, attributionControl: true }).setView(centerPosition, 14);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(map);
      L.marker(centerPosition, { title: label }).addTo(map);

      // Recenter control — without this, panning away from the pin (easy
      // to do by accident while zooming/scrolling on a small screen)
      // leaves no way back to the property's actual location short of
      // reloading the whole page.
      const RecenterControl = L.Control.extend({
        options: { position: 'topleft' },
        onAdd: function(){
          const btn = L.DomUtil.create('button', 'leaflet-bar leaflet-control map-recenter-btn');
          btn.type = 'button';
          btn.title = 'Recenter map';
          btn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><circle cx="12" cy="12" r="3"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/></svg>';
          L.DomEvent.disableClickPropagation(btn);
          L.DomEvent.on(btn, 'click', () => map.setView(centerPosition, 14));
          return btn;
        }
      });
      map.addControl(new RecenterControl());
      return;
    }
    // Leaflet not available yet (or failed to load) — wait briefly for it,
    // then fall back to Google Maps if it's genuinely not coming.
    if(!window.google || !window.google.maps){
      let attempts = 0;
      const timer = setInterval(() => {
        attempts++;
        if(window.L || (window.google && window.google.maps)){
          clearInterval(timer);
          initListingMapEmbed(container, lat, lng, label);
        } else if(attempts > 20){
          clearInterval(timer); // ~10s, then give up quietly — the "View on map" link still works
        }
      }, 500);
      return;
    }
    const position = { lat: Number(lat), lng: Number(lng) };
    const map = new google.maps.Map(container, {
      center: position, zoom: 14, disableDefaultUI: true, zoomControl: true,
    });
    new google.maps.Marker({ position, map, title: label });
  }

  function buildListingDetailHtml(listing){
    const exteriorPhotos = Array.isArray(listing.exterior_photo_urls) ? listing.exterior_photo_urls : [];
    const interiorPhotos = Array.isArray(listing.interior_photo_urls) ? listing.interior_photo_urls : [];
    let allPhotos = [...interiorPhotos, ...exteriorPhotos];
    if(listing.cover_photo_url && allPhotos.includes(listing.cover_photo_url)){
      allPhotos = [listing.cover_photo_url, ...allPhotos.filter(url => url !== listing.cover_photo_url)];
    }
    const photosHtml = buildPhotoCollageHtml(allPhotos, listing.property_name, listing.id);

    const amenitiesList = Array.isArray(listing.amenities) ? listing.amenities : [];
    const servicesList = Array.isArray(listing.services) ? listing.services : [];
    const includedList = [...amenitiesList, ...servicesList];
    const amenitiesHtml = includedList.length
      ? `<div class="listing-modal-section-title">What's Included</div>
         <div class="listing-modal-amenity-grid">${includedList.map(a => `<span>✓ ${a}</span>`).join('')}</div>`
      : '';

    const paidAmenities = Array.isArray(listing.paid_amenities) ? listing.paid_amenities : [];
    const paidAmenitiesHtml = paidAmenities.length
      ? `<div class="listing-modal-section-title">Paid Amenities</div>
         ${paidAmenities.map(a => `<div class="listing-modal-paid-amenity"><span>${escapeMessageHtml(a.name)}</span><span>${guestPrice(a.price)}/night</span></div>`).join('')}
         <p style="font-size:11.5px; opacity:0.55; margin-top:6px;">Availability and exact dates confirmed at booking.</p>`
      : '';

    // Kept as its own section, separate from the free amenities grid above
    // — pets come with real rules (a cap, allowed types, an optional fee),
    // not just a yes/no checkbox, so they get their own honest treatment
    // here rather than being buried in a bullet list.
    let petPolicyHtml = '';
    if(listing.pet_friendly === true){
      const petTypes = Array.isArray(listing.allowed_pet_types) && listing.allowed_pet_types.length
        ? listing.allowed_pet_types.join(' & ')
        : 'Dogs & Cats';
      const maxPetsLine = listing.max_pets_allowed
        ? `Up to ${listing.max_pets_allowed} pet${Number(listing.max_pets_allowed) === 1 ? '' : 's'}`
        : 'No stated limit on how many';
      const feeLine = listing.pet_fee && Number(listing.pet_fee) > 0
        ? `${guestPrice(listing.pet_fee)} per pet, per stay`
        : 'No pet fee';
      petPolicyHtml = `
        <div class="listing-modal-section-title">Pet Policy</div>
        <div class="listing-modal-amenity-grid">
          <span>✓ ${petTypes} welcome</span>
          <span>✓ ${maxPetsLine}</span>
          <span>✓ ${feeLine}</span>
        </div>
        <p style="font-size:11.5px; opacity:0.6; margin-top:8px; line-height:1.5;">Service and emotional-support animals aren't counted toward the pet limit. The first one is free; each additional one is charged the pet fee. Young pets (under 1 year) traveling with an adult pet aren't counted either.</p>`;
    } else if(listing.pet_friendly === false){
      petPolicyHtml = `
        <div class="listing-modal-section-title">Pet Policy</div>
        <p style="font-size:13.5px; opacity:0.7;">This property does not allow pets.</p>`;
    }

    const mapLinkHtml = (listing.latitude && listing.longitude)
      ? `<a href="https://www.google.com/maps/search/?api=1&query=${listing.latitude},${listing.longitude}" target="_blank" rel="noopener" class="link" style="font-size:13px;">View on map</a>`
      : '';

    // A Resort's booking column is structurally different enough (room
    // selection instead of a single price/pet-policy/amenities flow)
    // that it's a genuinely separate path here, rather than threading
    // "is this a resort" checks through every line of the regular
    // column below. Photos/map/description are identical either way,
    // so those are reused as-is.
    if(listing.property_type === 'Resort'){
      const rooms = Array.isArray(listing.rooms) ? listing.rooms : [];
      return `
        <div class="listing-modal-content">
          ${/* Name, address and type all sit in the strip below, so
                nothing is repeated above it. */''}
          ${listingStandingHtml(listing, { type: 'stay', subtitle: 'Resort' })}
          ${aervaSpecialHereHtml(listing)}
          <div class="listing-three-col">
            <div class="listing-col-booking">
              ${bookStep(1, 'Choose your dates')}
              <div id="resortBookCalendar" data-listing-id="${listing.id}">
                <p style="font-size:13px; opacity:0.6;">Loading calendar…</p>
              </div>
              <p id="resortDatesPrompt" style="font-size:11.5px; opacity:0.6; margin-top:10px;">Pick your dates first, then choose which room${rooms.length === 1 ? '' : 's'} you need below.</p>
              ${bookStep(2, 'Choose your room' + (rooms.length === 1 ? '' : 's'))}
              <p style="font-size:11.5px; opacity:0.6; margin-top:-4px; margin-bottom:6px;">Each room is booked and priced on its own — pick as many as your group needs. A room greyed out below isn't free for the dates you picked.</p>
              <div id="resortRoomsList">
                ${rooms.length ? '<p style="font-size:12.5px; opacity:0.5;">Pick dates above to see room availability.</p>' : '<p style="font-size:13px; opacity:0.6;">This resort has no rooms set up yet.</p>'}
              </div>
              <div id="resortPriceSummary" style="display:none;"></div>
              <div id="resortBookingAction" style="display:none; margin-top:16px; padding-top:16px; border-top:1px solid var(--line-dark);">
                <div class="sx-slot" data-suggest-exp-for="${Number(listing.id)}"></div>
                ${bookStep(4, 'Your details')}
                <p class="step-help">Your name and the number of guests go to your host; we send your confirmation to this email.</p>
                <div class="field">
                  <label for="resortBookFirstName">First name <span style="color:#a3402f;">*</span></label>
                <input id="resortBookFirstName" type="text" placeholder="First name" autocomplete="given-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="resortBookLastName">Last name <span style="color:#a3402f;">*</span></label>
                <input id="resortBookLastName" type="text" placeholder="Last name" autocomplete="family-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="resortBookEmail">Email <span style="color:#a3402f;">*</span></label>
                  <input id="resortBookEmail" type="email" placeholder="you@email.com" autocomplete="email" required>
                </div>
                <div class="field" style="margin-top:12px;">
                  <label for="resortBookPhone">Mobile number <span style="color:#a3402f;">*</span></label>
                  <input id="resortBookPhone" type="tel" placeholder="10-digit mobile number" autocomplete="tel" required>
                </div>
                <div class="field" style="margin-top:12px;">
                  <label for="resortCouponCode">Coupon code <span class="label-hint">${guestAuthToken() ? '(optional)' : '(optional — log in to use one)'}</span></label>
                  <input id="resortCouponCode" type="text" placeholder="e.g. AERVA-XXXXXXXXXX" style="text-transform:uppercase;">
                  <p class="coupon-rule">Coupons cover the booking price only. Service fee, GST and any deposit are charged in full. Any unused coupon balance is not refunded.</p>
                </div>
                <button type="button" class="btn solid" id="resortBookNowBtn" style="width:100%; margin-top:6px;">Continue to payment</button>
                ${PAY_NOTE_HTML}
                <p id="resortBookError" class="offer" style="display:none; color:#a3402f; margin-top:10px;"></p>
                <p id="resortBookConfirm" style="display:none; color:#3a7d44; font-size:13.5px; margin-top:10px; line-height:1.6;"></p>
              </div>
              ${buildAskHostHtml(listing)}
            </div>
            <div class="listing-col-photos">
              <div class="listing-modal-section-title" style="margin-top:16px;">Photos</div>
              <div id="resortPhotosContainer" data-listing-id="${listing.id}"></div>
              ${buildWalkthroughTeaserHtml(listing)}
              <div class="listing-reviews" data-reviews-for="${listing.id}"></div>
              <p class="desc" style="margin-top:16px;">${escapeMessageHtml(listing.description)}</p>
            </div>
            <div class="listing-col-map">
              <div class="listing-modal-section-title" style="margin-top:16px;">Location</div>
              ${(listing.latitude && listing.longitude) ? `
                <div class="listing-map-embed" id="listingMapEmbed"></div>
                <div style="margin-top:8px;">${mapLinkHtml}</div>
              ` : `<p style="font-size:13px; opacity:0.6;">No location set for this property yet.</p>`}
              <div class="listing-nearby" data-nearby-for="${listing.id}"></div>
              ${aervaHostRecsHtml(listing)}
            </div>
          </div>
          ${amenitiesHtml}
        </div>
      `;
    }

    const priceLine = listing.nightly_rate
      ? `From <strong>${guestPrice(listing.nightly_rate)}</strong>/night`
      : 'Price on request';
    const offerLine = formatOffer(listing);
    const promoOfferLine = formatPromotionOffer(listing);

    return `
      <div class="listing-modal-content">
        ${listingStandingHtml(listing, { type: 'stay', subtitle: listing.property_type || '' })}
        ${aervaSpecialHereHtml(listing)}
        <div class="listing-three-col">
          <div class="listing-col-booking">
            <div class="price">${priceLine}</div>
            ${offerLine ? `<div class="offer" style="margin-top:4px;">${offerLine}</div>` : ''}
            ${promoOfferLine ? `<div class="offer" style="margin-top:4px; color:#2f5c2a;">${promoOfferLine}</div>` : ''}
            ${formatPromotionHint(listing) ? `<div class="offer" style="margin-top:4px; color:#2f5c2a;">${formatPromotionHint(listing)}</div>` : ''}
            ${listing.free_cancel_offered === true ? '<p class="fc-available" data-free-cancel-line>Free cancellation available at checkout</p>' : ''}
            ${bookStep(1, 'Choose your dates')}
            <div id="availabilityCalendar" data-listing-id="${listing.id}">
              <p style="font-size:13px; opacity:0.6;">Loading availability…</p>
            </div>
            <div id="lgCapacityNote" style="display:none; font-size:12.5px; color:#a3402f; padding-top:12px;"></div>
            ${bookStep(2, 'Who is coming')}
            <div class="guest-row" style="border:none; padding-top:4px;">
              <div class="guest-row-text">
                <div class="guest-row-title">Adults</div>
                <div class="guest-row-sub">18 or over</div>
              </div>
              <div class="guest-stepper">
                <button type="button" class="guest-step-btn" data-lg-type="adults" data-lg-action="dec" aria-label="Decrease adults">−</button>
                <span class="guest-count" id="lgCountAdults">1</span>
                <button type="button" class="guest-step-btn" data-lg-type="adults" data-lg-action="inc" aria-label="Increase adults">+</button>
              </div>
            </div>
            <div class="guest-row-divider"></div>
            <div class="guest-row">
              <div class="guest-row-text">
                <div class="guest-row-title">Children</div>
                <div class="guest-row-sub">Ages 2–17</div>
              </div>
              <div class="guest-stepper">
                <button type="button" class="guest-step-btn" data-lg-type="children" data-lg-action="dec" aria-label="Decrease children">−</button>
                <span class="guest-count" id="lgCountChildren">0</span>
                <button type="button" class="guest-step-btn" data-lg-type="children" data-lg-action="inc" aria-label="Increase children">+</button>
              </div>
            </div>
            <div class="guest-row-divider"></div>
            <div class="guest-row">
              <div class="guest-row-text">
                <div class="guest-row-title">Infants</div>
                <div class="guest-row-sub">Under 2</div>
              </div>
              <div class="guest-stepper">
                <button type="button" class="guest-step-btn" data-lg-type="infants" data-lg-action="dec" aria-label="Decrease infants">−</button>
                <span class="guest-count" id="lgCountInfants">0</span>
                <button type="button" class="guest-step-btn" data-lg-type="infants" data-lg-action="inc" aria-label="Increase infants">+</button>
              </div>
            </div>
            ${listing.pet_friendly === true ? `
            <div class="guest-row-divider"></div>
            <div class="guest-row">
              <div class="guest-row-text">
                <div class="guest-row-title">Pets</div>
                <div class="guest-row-sub guest-row-sub-muted">${listing.pet_fee && Number(listing.pet_fee) > 0 ? guestPrice(listing.pet_fee) + ' per pet, per stay' : 'No pet fee'}</div>
              </div>
              <div class="guest-stepper">
                <button type="button" class="guest-step-btn" data-lg-type="animals" data-lg-action="dec" aria-label="Decrease pets">−</button>
                <span class="guest-count" id="lgCountAnimals">0</span>
                <button type="button" class="guest-step-btn" data-lg-type="animals" data-lg-action="inc" aria-label="Increase pets">+</button>
              </div>
            </div>
            <div id="lgPetList" class="lg-pet-list" style="display:none;"></div>
            <p id="lgPetNote" class="lg-pet-note" style="display:none;"></p>
            <p id="lgPetTypesError" class="lg-pet-error" style="display:none;"></p>` : ''}
            <div id="listingAmenitiesPicker"></div>
            <div id="listingExperiencesPicker"></div>
            <div id="listingPriceSummary" style="display:none;"></div>
            <div id="listingBookingAction" style="display:none; margin-top:16px; padding-top:16px; border-top:1px solid var(--line-dark);">
              <div class="sx-slot" data-suggest-exp-for="${Number(listing.id)}"></div>
              ${bookStep(4, 'Your details')}
              <p class="step-help">Your name and the number of guests go to your host; we send your confirmation to this email.</p>
              <div class="field">
                <label for="listingBookFirstName">First name <span style="color:#a3402f;">*</span></label>
                <input id="listingBookFirstName" type="text" placeholder="First name" autocomplete="given-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="listingBookLastName">Last name <span style="color:#a3402f;">*</span></label>
                <input id="listingBookLastName" type="text" placeholder="Last name" autocomplete="family-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="listingBookEmail">Email <span style="color:#a3402f;">*</span></label>
                <input id="listingBookEmail" type="email" placeholder="you@email.com" autocomplete="email" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="listingBookPhone">Mobile number <span style="color:#a3402f;">*</span></label>
                <input id="listingBookPhone" type="tel" placeholder="10-digit mobile number" autocomplete="tel" required>
              </div>
              ${aervaBookOptionsHtml()}
              <div class="field" id="listingCouponField" style="margin-top:12px;">
                <label for="listingCouponCode">Coupon code <span class="label-hint">${guestAuthToken() ? '(optional)' : '(optional — log in to use one)'}</span></label>
                <input id="listingCouponCode" type="text" placeholder="e.g. AERVA-XXXXXXXXXX" style="text-transform:uppercase;">
                <p class="coupon-rule">Coupons cover the booking price only. Service fee, GST and any deposit are charged in full. Any unused coupon balance is not refunded.</p>
              </div>
              <button type="button" class="btn solid" id="listingBookNowBtn" style="width:100%; margin-top:6px;">Continue to payment</button>
              ${PAY_NOTE_HTML}
              <p id="listingBookError" class="offer" style="display:none; color:#a3402f; margin-top:10px;"></p>
              <p id="listingBookConfirm" style="display:none; color:#3a7d44; font-size:13.5px; margin-top:10px; line-height:1.6;"></p>
            </div>
            ${buildAskHostHtml(listing)}
          </div>
          <div class="listing-col-photos">
            <div class="listing-modal-section-title" style="margin-top:16px;">Photos</div>
            ${photosHtml}
            ${buildWalkthroughTeaserHtml(listing)}
            <div class="listing-reviews" data-reviews-for="${listing.id}"></div>
            <p class="desc" style="margin-top:16px;">${escapeMessageHtml(listing.description)}</p>
          </div>
          <div class="listing-col-map">
            <div class="listing-modal-section-title" style="margin-top:16px;">Location</div>
            ${(listing.latitude && listing.longitude) ? `
              <div class="listing-map-embed" id="listingMapEmbed"></div>
              <div style="margin-top:8px;">${mapLinkHtml}</div>
            ` : `<p style="font-size:13px; opacity:0.6;">No location set for this property yet.</p>`}
              <div class="listing-nearby" data-nearby-for="${listing.id}"></div>
              ${aervaHostRecsHtml(listing)}
          </div>
        </div>
        ${amenitiesHtml}
        ${paidAmenitiesHtml}
        ${petPolicyHtml}
      </div>
    `;
  }

  // ---- Reviews under the photos ----
  // Filled after the detail view opens, from get-listings?reviewsFor=.
  // Only published reviews ever arrive here, with first names only.
  // Everything a reviewer wrote is escaped before it touches the page.
  const REVIEW_MONTH_FMT = { month: 'short', year: 'numeric' };
  function reviewMonthLabel(ym){
    if(!ym) return '';
    const d = new Date(ym + '-01T00:00:00');
    return isNaN(d) ? '' : d.toLocaleDateString('en-IN', REVIEW_MONTH_FMT);
  }
  // One plain line: "Hygiene 5.0 · Communication 5.0 · …"
  // ---- Reviews ----
  //
  // What each of these used to be: the summary's factor scores were one
  // run-on line of text ("Cleanliness 4.8 · Communication 4.9 · Value
  // 4.6 · Location 4.7"), which is five numbers a reader has to compare
  // in their head; and every individual review threw its OWN factor
  // scores away entirely, printing only a name, a month and "4.8 out of
  // 5". The endpoint has always sent both.

  // A score as five stars, exact rather than rounded: a full row of
  // outlines with a filled row clipped over it at score/5 of the width.
  // The number always sits beside it — the stars are the quick read, the
  // number is the precise one, and neither is the only source.
  function starsHtml(score, size){
    const pct = Math.max(0, Math.min(100, (Number(score) / 5) * 100));
    return `<span class="rv-stars" style="${size ? `font-size:${size}px;` : ''}" role="img"
      aria-label="${Number(score).toFixed(1)} out of 5"><span class="rv-stars-off">★★★★★</span
      ><span class="rv-stars-on" style="width:${pct.toFixed(1)}%">★★★★★</span></span>`;
  }

  // The summary's factors, as labelled bars. One measure per row, so
  // they can be compared by length instead of by reading five decimals.
  // One series and a number on every row, so the bar's colour carries no
  // meaning of its own and needs none.
  function reviewFactorsHtml(factors){
    const list = factors || [];
    if(!list.length) return '';
    // The three cells go straight into the grid, with no per-row wrapper:
    // a wrapper makes each ROW one grid item, so the track gets no column
    // width and every bar ends up sized by its own content instead of by
    // its score. Flat cells also line the labels and numbers up down the
    // whole block, which is the point of showing them as bars.
    return `<div class="rv-bars">` + list.map(f => {
      const v = Number(f.value);
      return `<span class="rv-bar-label">${escapeMessageHtml(f.label)}</span>`
           + `<span class="rv-bar-track"><span class="rv-bar-fill" style="width:${((v / 5) * 100).toFixed(1)}%"></span></span>`
           + `<span class="rv-bar-value">${v.toFixed(1)}</span>`;
    }).join('') + `</div>`;
  }

  // One review's own factor scores, which were previously discarded.
  // Quiet chips rather than five more bars: at this size the bars would
  // out-weigh the words the guest actually wrote.
  function reviewChipsHtml(factors){
    const list = factors || [];
    if(!list.length) return '';
    return `<div class="rv-chips">` + list.map(f =>
      `<span class="rv-chip">${escapeMessageHtml(f.label)} <b>${Number(f.value).toFixed(0)}</b></span>`).join('') + `</div>`;
  }
  function reviewItemHtml(r, withName){
    const name = String(r.name || 'Guest');
    const initial = name.trim().charAt(0).toUpperCase() || 'G';
    const month = reviewMonthLabel(r.month);
    return `
      <div class="rv-item">
        <div class="rv-item-head">
          ${withName ? `<span class="rv-avatar" aria-hidden="true">${escapeMessageHtml(initial)}</span>` : ''}
          <span class="rv-who">
            ${withName ? `<span class="rv-item-name">${escapeMessageHtml(name)}</span>` : ''}
            ${month ? `<span class="rv-item-meta">${escapeMessageHtml(month)}</span>` : ''}
          </span>
          ${r.score ? `<span class="rv-item-score">${starsHtml(r.score, 13)}<b>${Number(r.score).toFixed(1)}</b></span>` : ''}
        </div>
        ${r.comment ? `<p class="rv-item-text">${escapeMessageHtml(r.comment)}</p>` : ''}
        ${reviewPhotosHtml(r.photos)}
        ${reviewChipsHtml(r.factors)}
      </div>`;
  }
  // A review's photos as small thumbnails under the text; a tap opens
  // them in the photo viewer (Escape closes, arrow keys move).
  function reviewPhotosHtml(photos){
    const list = (Array.isArray(photos) ? photos : []).filter(u => typeof u === 'string' && /^https:\/\/[a-z0-9-]+\.public\.blob\.vercel-storage\.com\//i.test(u)).slice(0, 5);
    if(!list.length) return '';
    return `<div class="rv-photo-row" data-review-photos="${escapeMessageHtml(JSON.stringify(list))}">` + list.map((u, i) =>
      `<button type="button" class="rv-photo-thumb" data-review-photo-index="${i}" aria-label="Open the guest’s photo ${i + 1} of ${list.length}"><img src="${escapeMessageHtml(u)}" alt="" loading="lazy"></button>`).join('') + `</div>`;
  }
  document.addEventListener('click', function(e){
    const thumb = e.target.closest('[data-review-photos] [data-review-photo-index]');
    if(!thumb) return;
    let list = [];
    try{ list = JSON.parse(thumb.closest('[data-review-photos]').dataset.reviewPhotos || '[]'); }catch(err){ list = []; }
    if(list.length) openPhotoLightbox(list, Number(thumb.dataset.reviewPhotoIndex) || 0);
  });
  // How many reviews each press of View more brings in. Five on opening
  // the page, then batches that take the list to 20, then 40, then the
  // rest in 100s (the endpoint's own per-request cap).
  const REVIEW_PAGE_STEPS = [5, 15, 20];
  const REVIEW_PAGE_REST = 100;
  async function loadListingReviews(root, listingId){
    try { aervaLoadNearby(root); } catch (e) { /* never blocks the reviews */ }
    const slot = root && root.querySelector(`.listing-reviews[data-reviews-for="${Number(listingId)}"]`);
    if(!slot) return;
    slot.innerHTML = '';
    let offset = 0;
    let step = 0;
    const load = async () => {
      const limit = REVIEW_PAGE_STEPS[step] || REVIEW_PAGE_REST;
      step++;
      const res = await fetch(SUITES_API_BASE + `/api/get-listings?reviewsFor=${Number(listingId)}&offset=${offset}&limit=${limit}`);
      const data = await res.json();
      if(!res.ok) throw new Error(data.error || 'Failed');
      return data;
    };
    try{
      const data = await load();
      const sm = data.summary || { count: 0 };
      if(!sm.count){
        slot.innerHTML = `
          <div class="listing-modal-section-title">Reviews</div>
          <p class="rv-empty">No reviews yet.</p>`;
        return;
      }
      slot.innerHTML = `
        <div class="listing-modal-section-title">Reviews</div>
        <div class="rv-summary">
          <span class="rv-summary-score">${Number(sm.score).toFixed(1)}</span>
          ${starsHtml(sm.score, 17)}
          <span class="rv-summary-count">${sm.count} review${sm.count === 1 ? '' : 's'}</span>
        </div>
        <div class="rv-factors">${reviewFactorsHtml(sm.factors)}</div>
        <div class="rv-list"></div>
        <button type="button" class="filter-clear rv-more" style="display:none;">View more</button>`;
      const list = slot.querySelector('.rv-list');
      const more = slot.querySelector('.rv-more');
      const append = (d) => {
        list.insertAdjacentHTML('beforeend', (d.reviews || []).map(r => reviewItemHtml(r, true)).join(''));
        offset = d.nextOffset;
        more.style.display = d.nextOffset != null ? '' : 'none';
      };
      append(data);
      more.addEventListener('click', async () => {
        more.disabled = true; more.textContent = 'Loading\u2026';
        try{ append(await load()); }
        catch(err){ /* keep what is shown; the button stays for a retry */ }
        more.disabled = false; more.textContent = 'View more';
      });
    } catch(err){
      // Reviews are supporting detail. A failure here must never break
      // booking, so the section simply stays empty.
      slot.innerHTML = '';
    }
  }

  function openListingDetail(listingId){
    // Saved homes come from their own list (renderWishlist), not the search results.
    const listing = listingsById[listingId] || (typeof wishlistListingsById !== 'undefined' && wishlistListingsById && wishlistListingsById[listingId]);
    if(!listing){ location.href = 'index.html?listing=' + encodeURIComponent(listingId); return; }
    trackRecentlyViewed('stay', listingId);
    document.getElementById('listingModalBody').innerHTML = buildListingDetailHtml(listing);
    document.getElementById('listingModalOverlay').style.display = 'flex';
    document.body.style.overflow = 'hidden';
    loadListingReviews(document.getElementById('listingModalBody'), listing.id);
    const mapEl = document.getElementById('listingMapEmbed');
    if(mapEl && listing.latitude && listing.longitude){
      initListingMapEmbed(mapEl, listing.latitude, listing.longitude, listing.property_name);
    }
    if(listing.property_type === 'Resort'){
      renderResortBookingCalendar(listing);
      renderRoomAwarePhotos(listing, []);
      document.getElementById('resortBookNowBtn').addEventListener('click', () => handleResortBookNow(listing));
      aervaPrefillBooking();
      return;
    }
    loadListingExperiences(listing);
    // This modal previously never actually rendered — buildListingDetailHtml
    // only sets up the "Loading availability…" placeholder markup, the
    // real calendar (and the Book Now button's click handler) were only
    // ever wired up by showFullListingPage, so this modal path silently
    // never worked before now.
    renderAvailabilityCalendar(listing);
    document.getElementById('listingBookNowBtn').addEventListener('click', () => handleListingBookNow(listing));
    aervaPrefillBooking();
  }

  // "This property also offers…" — with-stay experiences hosted at this
  // listing that a guest can add to the SAME booking. create-order.js
  // already accepts a stays[] and an experiences[] together in one
  // request (no new checkout needed) — this is just the picker that
  // feeds that array. Without-stay experiences hosted here are shown
  // too, but as a plain link to book separately, not an add-on toggle —
  // they're not part of "the same booking" the way a with-stay one is.
  async function loadListingExperiences(listing){
    const container = document.getElementById('listingExperiencesPicker');
    if(!container) return;
    container.innerHTML = '';
    try{
      const res = await fetch(SUITES_API_BASE + '/api/get-listings?experiencesFor=' + encodeURIComponent(listing.id));
      if(!res.ok) return;
      const data = await res.json();
      const experiences = Array.isArray(data.experiences) ? data.experiences : [];
      if(!experiences.length) return;
      renderAvailabilityCalendar._lgExperienceOptions = renderAvailabilityCalendar._lgExperienceOptions || {};
      renderAvailabilityCalendar._lgExperienceOptions[listing.id] = experiences;
      renderListingExperiencesPicker(listing);
    } catch(err){
      // Non-fatal — the booking flow works fine with no experiences shown.
    }
  }

  function renderListingExperiencesPicker(listing){
    const container = document.getElementById('listingExperiencesPicker');
    if(!container) return;
    const experiences = ((renderAvailabilityCalendar._lgExperienceOptions || {})[listing.id]) || [];
    if(!experiences.length){ container.innerHTML = ''; return; }

    renderAvailabilityCalendar._lgSelectedExperience = renderAvailabilityCalendar._lgSelectedExperience || {};
    const selected = renderAvailabilityCalendar._lgSelectedExperience[listing.id] || null;

    const withStay = experiences.filter(e => e.experience_type === 'with_stay');
    const withoutStay = experiences.filter(e => e.experience_type !== 'with_stay');
    const counts = (renderAvailabilityCalendar._lgCounts || {})[listing.id] || { adults: 1 };
    const dates = (renderAvailabilityCalendar._lgDates || {})[listing.id] || {};

    // An "Includes a Stay" experience added here takes place during the
    // stay being booked: its nights (one per day) are nights of this stay,
    // so it must start on a day that leaves them all inside the stay. The
    // server checks the same (create-order.js) and charges the nights once.
    const expDays = (exp) => Math.max(1, Number(exp.experience_duration_days) || 1);
    const lastStartFor = (exp) => dates.arrival && dates.departure ? aervaAddDays(dates.departure, -expDays(exp)) : '';
    if(selected){
      const exp = withStay.find(e => String(e.id) === String(selected.listingId));
      const last = exp ? lastStartFor(exp) : '';
      if(selected.date && dates.arrival && (selected.date < dates.arrival || (last && selected.date > last))) selected.date = last >= dates.arrival ? dates.arrival : '';
      if(!selected.date && dates.arrival && last >= dates.arrival) selected.date = dates.arrival;
    }
    const withStayHtml = withStay.length ? `
      <div class="listing-modal-section-title">This Property Also Offers</div>
      ${withStay.map(exp => {
        const isChecked = selected && String(selected.listingId) === String(exp.id);
        const priceLine = exp.price
          ? `${fmtGuest(Number(exp.price))}${exp.experience_price_unit === 'per_person' ? ' / person' : ' / group'}`
          : 'Price on request';
        const days = expDays(exp);
        const last = lastStartFor(exp);
        const fits = !dates.arrival || !dates.departure || last >= dates.arrival;
        return `
          <div class="listing-modal-paid-amenity" style="align-items:flex-start; flex-direction:column; gap:8px; padding:12px 0;">
            <label style="display:flex; align-items:center; gap:8px; cursor:pointer; width:100%;">
              <input type="checkbox" class="lg-experience-checkbox" data-experience-id="${exp.id}" ${isChecked ? 'checked' : ''}>
              <span style="flex:1;"><strong>${escapeMessageHtml(exp.property_name)}</strong> — ${priceLine}</span>
            </label>
            ${isChecked ? `
              <p style="font-size:12px; opacity:0.7; margin:0; padding-left:26px;">Includes ${days} night${days === 1 ? '' : 's'} here, covered by your stay. ${fits ? 'Choose the day it starts, and how many are joining.' : `Your stay is too short for it — choose at least ${days} night${days === 1 ? '' : 's'}.`}</p>
              ${fits ? `<div style="display:flex; gap:10px; padding-left:26px; width:100%; box-sizing:border-box;">
                <input type="date" class="lg-experience-date" data-experience-id="${exp.id}" aria-label="Day the experience starts"
                  value="${selected.date || ''}"
                  min="${dates.arrival || ''}" max="${last || ''}"
                  style="flex:1; padding:8px; font-size:13px; border:1px solid var(--line-dark);">
                <input type="number" class="lg-experience-guests" data-experience-id="${exp.id}" min="1" max="50" step="1" inputmode="numeric" aria-label="Guests joining"
                  value="${selected.guests || counts.adults || 1}"
                  style="width:70px; padding:8px; font-size:13px; border:1px solid var(--line-dark);" title="Guests">
              </div>` : ''}
            ` : ''}
          </div>
        `;
      }).join('')}
    ` : '';

    const withoutStayHtml = withoutStay.length ? `
      <div class="listing-modal-section-title">Also Nearby</div>
      ${withoutStay.map(exp => `
        <div class="listing-modal-paid-amenity">
          <span><a href="index.html?experience=${exp.id}" target="_blank" rel="noopener" style="color:var(--gold-deep); text-decoration:underline;">${escapeMessageHtml(exp.property_name)}</a></span>
          <span>${exp.price ? fmtGuest(Number(exp.price)) + (exp.experience_price_unit === 'per_person' ? '/person' : '/group') : ''}</span>
        </div>
      `).join('')}
    ` : '';

    container.innerHTML = withStayHtml + withoutStayHtml;

    container.querySelectorAll('.lg-experience-checkbox').forEach(cb => {
      cb.addEventListener('change', () => {
        if(cb.checked){
          const exp = withStay.find(e => String(e.id) === cb.dataset.experienceId);
          renderAvailabilityCalendar._lgSelectedExperience[listing.id] = {
            listingId: exp.id, date: dates.arrival || '', guests: counts.adults || 1
          };
        } else {
          delete renderAvailabilityCalendar._lgSelectedExperience[listing.id];
        }
        renderListingExperiencesPicker(listing);
        updateListingPriceSummary(listing, dates.arrival, dates.departure);
      });
    });
    container.querySelectorAll('.lg-experience-date').forEach(input => {
      input.addEventListener('change', () => {
        const sel = renderAvailabilityCalendar._lgSelectedExperience[listing.id];
        if(sel) sel.date = input.value;
        updateListingPriceSummary(listing, dates.arrival, dates.departure);
      });
    });
    container.querySelectorAll('.lg-experience-guests').forEach(input => {
      input.addEventListener('change', () => {
        const sel = renderAvailabilityCalendar._lgSelectedExperience[listing.id];
        // Whole people, 1 to 50 (the server holds the experience's own limit).
        if(sel) sel.guests = Math.min(50, Math.max(1, Math.floor(Number(input.value)) || 1));
        updateListingPriceSummary(listing, dates.arrival, dates.departure);
      });
    });
  }

  function closeListingDetail(){
    document.getElementById('listingModalOverlay').style.display = 'none';
    document.body.style.overflow = '';
  }

  // Full listing page — what actually opens (in a new tab) when a guest
  // clicks a suite card. Same content as buildListingDetailHtml, just
  // rendered into the page itself instead of an overlay, with the rest
  // of the homepage (search, grid) hidden rather than shown alongside it.
  // Every night covered by a booked range, arrival up to (not including)
  // departure — same convention the backend uses (see create-order.js).
  function getNightsInRangeClient(arrival, departure){
    const nights = [];
    let d = new Date(arrival + 'T00:00:00Z');
    const end = new Date(departure + 'T00:00:00Z');
    if(isNaN(d) || isNaN(end)) return nights;
    // Never more than about two years: a calendar imported from another
    // site can carry a block with no real end.
    const stop = Math.min(end.getTime(), d.getTime() + 800 * 864e5);
    while(d.getTime() < stop){
      nights.push(d.toISOString().split('T')[0]);
      d.setUTCDate(d.getUTCDate() + 1);
    }
    return nights;
  }

  // Real availability, not a guess — pulls actual paid bookings for this
  // listing from the server (via get-listings.js's ?availabilityFor= mode
  // — kept in that same file rather than its own endpoint to stay under
  // Vercel's Hobby-plan serverless function limit). Days the guest can
  // actually pick, exactly like the homepage's date picker — arrival
  // first click, departure second — plus a guest count and a live price
  // summary, which the server's own quote replaces (updateListingPriceSummary),
  // so what shows here is what checkout charges.
  async function renderAvailabilityCalendar(listing){
    const container = document.getElementById('availabilityCalendar');
    if(!container) return;
    const listingId = listing.id;

    let bookedRanges = [];
    let blockedRanges = [];
    try {
      const res = await fetch(SUITES_API_BASE + '/api/get-listings?availabilityFor=' + encodeURIComponent(listingId));
      if(res.ok){
        const data = await res.json();
        bookedRanges = Array.isArray(data.bookedRanges) ? data.bookedRanges : [];
        // The backend has always returned this alongside bookedRanges —
        // it just never got read here, so a host's own blocked dates
        // (maintenance, personal use, etc.) never actually greyed out
        // anything on the guest-facing calendar, even though
        // create-order.js was already correctly rejecting a booking
        // attempt against them. A guest could pick a blocked date, fill
        // out the whole form, and only find out it was never actually
        // available at the final submit — this fixes that at the source.
        blockedRanges = Array.isArray(data.blockedRanges) ? data.blockedRanges : [];
      }
    } catch(err){
      console.error('Could not load availability:', err);
    }

    const bookedNights = new Set();
    bookedRanges.forEach(r => {
      if(r.arrival && r.departure) getNightsInRangeClient(r.arrival, r.departure).forEach(n => bookedNights.add(n));
    });
    blockedRanges.forEach(r => {
      if(r.arrival && r.departure) getNightsInRangeClient(r.arrival, r.departure).forEach(n => bookedNights.add(n));
    });

    // Carried over from the main search — via URL params when this is
    // the full standalone listing page (?listing=<id>&arrival=...,
    // reached by a direct link with no shared JS state), or directly
    // from the live search bar's own variables when this is the modal
    // opened straight from a search-results click (same page, same JS
    // scope, nothing needs to round-trip through a URL at all). Only
    // honored if it's actually still a valid, available range for THIS
    // listing — a date that looked free on the search results a moment
    // ago could theoretically already be taken.
    const carriedParams = new URLSearchParams(window.location.search);
    const carriedArrival = carriedParams.get('arrival') || (typeof searchArrivalDate !== 'undefined' ? searchArrivalDate : '') || '';
    const carriedDeparture = carriedParams.get('departure') || (typeof searchDepartureDate !== 'undefined' ? searchDepartureDate : '') || '';
    const todayIsoForValidation = toLocalDateStr(new Date());
    let initialArrival = '';
    let initialDeparture = '';
    if(carriedArrival && carriedDeparture && carriedArrival >= todayIsoForValidation && carriedDeparture > carriedArrival){
      const carriedNights = getNightsInRangeClient(carriedArrival, carriedDeparture);
      const hasConflict = carriedNights.some(n => bookedNights.has(n));
      if(!hasConflict){
        initialArrival = carriedArrival;
        initialDeparture = carriedDeparture;
      }
    }

    // The earliest night a guest can book, on the PROPERTY's clock: tonight
    // until the host's same-day cut-off, then tomorrow (api/_booking-rules.js).
    const todayIso = aervaEarliestArrival((typeof listing !== 'undefined' && listing && listing.timezone) || 'Asia/Kolkata', (typeof listing !== 'undefined' && listing) ? listing.same_day_until : 24);
    let viewYear = new Date().getFullYear();
    let viewMonth = new Date().getMonth();
    if(initialArrival){
      const anchor = new Date(initialArrival);
      viewYear = anchor.getFullYear();
      viewMonth = anchor.getMonth();
    }
    let lgArrival = initialArrival;
    let lgDeparture = initialDeparture;
    let lgSelectingStart = !initialArrival;
    lgCurrentSelection = { arrival: lgArrival, departure: lgDeparture };

    // A selected range is only valid to commit if no night inside it is
    // already booked — picking through a gap between two bookings isn't
    // something this simple two-click flow can express safely.
    function rangeHasConflict(arrival, departure){
      return getNightsInRangeClient(arrival, departure).some(n => bookedNights.has(n));
    }

    function handleDayClick(iso){
      if(lgSelectingStart || !lgArrival){
        lgArrival = iso;
        lgDeparture = '';
        lgSelectingStart = false;
      } else if(iso <= lgArrival || rangeHasConflict(lgArrival, iso)){
        // Picked an earlier/same date, or a range that crosses a booked
        // night — start a fresh selection from here instead.
        lgArrival = iso;
        lgDeparture = '';
        lgSelectingStart = false;
      } else {
        lgDeparture = iso;
        lgSelectingStart = true;
      }
      renderMonth();
      lgCurrentSelection = { arrival: lgArrival, departure: lgDeparture };
      updateListingPriceSummary(listing, lgArrival, lgDeparture);
      renderListingAmenities(listing, lgArrival, lgDeparture);
    }

    function renderMonth(){
      const firstDay = new Date(viewYear, viewMonth, 1);
      const startWeekday = firstDay.getDay();
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const isCurrentMonth = viewYear === new Date().getFullYear() && viewMonth === new Date().getMonth();

      let cellsHtml = '';
      for(let i = 0; i < startWeekday; i++) cellsHtml += '<div class="calendar-day empty"></div>';
      for(let day = 1; day <= daysInMonth; day++){
        const cellDate = new Date(viewYear, viewMonth, day);
        const iso = toLocalDateStr(cellDate);
        const isPast = iso < todayIso;
        const isBooked = bookedNights.has(iso);
        // A booked night can still be the day you leave (you don't sleep
        // there), as in the Check availability calendar.
        const canEnd = isBooked && !isPast && lgArrival && !lgDeparture && iso > lgArrival && !rangeHasConflict(lgArrival, iso);
        const isDisabled = isPast || (isBooked && !canEnd);
        let classes = 'calendar-day';
        if(isDisabled) classes += ' disabled';
        if(iso === lgArrival || iso === lgDeparture) classes += ' selected-start';
        else if(lgArrival && lgDeparture && iso > lgArrival && iso < lgDeparture) classes += ' in-range';
        cellsHtml += `<div class="${classes}" data-lg-date="${iso}">${day}</div>`;
      }

      container.innerHTML = `
        <div class="calendar-month-panel" style="max-width:320px; padding:0;">
          <div class="calendar-month-header">
            <button type="button" class="cal-nav" id="availCalPrev" aria-label="Previous month" ${isCurrentMonth ? 'disabled' : ''}>‹</button>
            <div class="calendar-month-label">${MONTH_NAMES[viewMonth]} ${viewYear}</div>
            <button type="button" class="cal-nav" id="availCalNext" aria-label="Next month">›</button>
          </div>
          <div class="calendar-weekdays">
            <span>S</span><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span>
          </div>
          <div class="calendar-grid">${cellsHtml}</div>
          <p style="font-size:11.5px; opacity:0.6; margin-top:10px;">
            ${lgArrival && !lgDeparture ? 'Now pick your departure date.' : 'Greyed-out dates are already booked or in the past.'}
          </p>
        </div>
      `;

      document.getElementById('availCalPrev').addEventListener('click', () => {
        viewMonth -= 1;
        if(viewMonth < 0){ viewMonth = 11; viewYear -= 1; }
        renderMonth();
      });
      document.getElementById('availCalNext').addEventListener('click', () => {
        viewMonth += 1;
        if(viewMonth > 11){ viewMonth = 0; viewYear += 1; }
        renderMonth();
      });
      container.querySelectorAll('.calendar-day:not(.disabled):not(.empty)').forEach(cell => {
        aervaDayCellA11y(cell, 'data-lg-date');
        cell.addEventListener('click', (e) => {
          e.stopPropagation();
          handleDayClick(cell.dataset.lgDate);
        });
      });
    }

    renderMonth();

    // ---- Guest stepper wiring ----
    const lgCounts = { adults: 1, children: 0, infants: 0, pets: 0, serviceAnimals: 0, youngLitter: 0 };
    // Same carry-over as dates above — URL params for the standalone
    // page's direct-link case, falling back to the live search bar's own
    // guestCounts variable for the modal-from-search-results case.
    const liveGuestCounts = (typeof guestCounts !== 'undefined') ? guestCounts : null;
    if(carriedParams.get('adults')) lgCounts.adults = Math.max(1, parseInt(carriedParams.get('adults'), 10) || 1);
    else if(liveGuestCounts && liveGuestCounts.adults) lgCounts.adults = liveGuestCounts.adults;
    if(carriedParams.get('children')) lgCounts.children = parseInt(carriedParams.get('children'), 10) || 0;
    else if(liveGuestCounts && liveGuestCounts.children) lgCounts.children = liveGuestCounts.children;
    if(carriedParams.get('infants')) lgCounts.infants = parseInt(carriedParams.get('infants'), 10) || 0;
    else if(liveGuestCounts && liveGuestCounts.infants) lgCounts.infants = liveGuestCounts.infants;
    if(carriedParams.get('pets')) lgCounts.pets = parseInt(carriedParams.get('pets'), 10) || 0;
    else if(liveGuestCounts && liveGuestCounts.pets) lgCounts.pets = liveGuestCounts.pets;
    // Respect the host's own cap immediately in the UI, not just as a
    // server-side rejection after the fact — previously this stepper let
    // a guest click all the way to 5 pets even on a listing capped at 1.
    const maxBillablePets = listing.max_pets_allowed ? Math.min(5, Number(listing.max_pets_allowed)) : 5;
    if(lgCounts.pets > maxBillablePets) lgCounts.pets = maxBillablePets;
    ['adults', 'children', 'infants', 'pets'].forEach(type => {
      const countEl = document.getElementById('lgCount' + type.charAt(0).toUpperCase() + type.slice(1));
      if(countEl) countEl.textContent = lgCounts[type];
    });

    // ---- Pets: one card per animal ----
    // Each animal gets: its type, "Service or support animal?" (Yes / No),
    // and — for a pet — how many young (under 1 year) travel with it.
    // Everything the rest of the booking reads is derived from this one
    // list, in the same shape as before:
    //   lgCounts.pets           pets that count toward the limit and fee
    //   lgCounts.serviceAnimals service / support animals (1st free per
    //                           booking, each further one at the pet fee)
    //   lgCounts.youngLitter    young ones travelling with those pets
    //   _lgPetTypeSelections / _lgServiceAnimalSelections  their types
    renderAvailabilityCalendar._lgPetTypeSelections = renderAvailabilityCalendar._lgPetTypeSelections || {};
    renderAvailabilityCalendar._lgServiceAnimalSelections = renderAvailabilityCalendar._lgServiceAnimalSelections || {};
    renderAvailabilityCalendar._lgAnimals = renderAvailabilityCalendar._lgAnimals || {};
    const petTypeOptions = (Array.isArray(listing.allowed_pet_types) && listing.allowed_pet_types.length)
      ? listing.allowed_pet_types : ['Dog', 'Cat'];
    const MAX_SERVICE_ANIMALS = 5;
    const petListEl = container.parentElement.querySelector('#lgPetList');
    const petNoteEl = container.parentElement.querySelector('#lgPetNote');
    const petErrorEl = container.parentElement.querySelector('#lgPetTypesError');
    let animals = renderAvailabilityCalendar._lgAnimals[listingId]
      || Array.from({ length: lgCounts.pets || 0 }, () => ({ type: petTypeOptions[0], service: false, litter: 0 }));
    renderAvailabilityCalendar._lgAnimals[listingId] = animals;

    function syncAnimalCounts(){
      const pets = animals.filter(x => !x.service);
      const service = animals.filter(x => x.service);
      lgCounts.animals = animals.length;
      lgCounts.pets = pets.length;
      lgCounts.serviceAnimals = service.length;
      lgCounts.youngLitter = pets.reduce((sum, x) => sum + (Number(x.litter) || 0), 0);
      renderAvailabilityCalendar._lgPetTypeSelections[listingId] = pets.map(x => x.type);
      renderAvailabilityCalendar._lgServiceAnimalSelections[listingId] = service.map(x => x.type);
      const countEl = document.getElementById('lgCountAnimals');
      if(countEl) countEl.textContent = animals.length;
      // Instructions only.
      if(petNoteEl){
        const notes = [];
        if(service.length) notes.push('First service or support animal is free. Each additional one is charged the pet fee.');
        petNoteEl.textContent = notes.join(' ');
        petNoteEl.style.display = notes.length ? 'block' : 'none';
      }
      if(petErrorEl){
        let msg = '';
        if(pets.length > maxBillablePets) msg = `This home allows up to ${maxBillablePets} pet${maxBillablePets === 1 ? '' : 's'}. Service or support animals are not counted.`;
        else if(service.length > MAX_SERVICE_ANIMALS) msg = `Up to ${MAX_SERVICE_ANIMALS} service or support animals.`;
        petErrorEl.textContent = msg;
        petErrorEl.style.display = msg ? 'block' : 'none';
      }
    }

    function renderAnimalList(){
      if(!petListEl) return;
      petListEl.style.display = animals.length ? 'flex' : 'none';
      petListEl.innerHTML = animals.map((x, i) => `
        <div class="lg-pet-card" data-animal="${i}">
          <div class="lg-pet-head">Pet ${i + 1}</div>
          <label class="lg-pet-field">Type
            <select class="lg-pet-type" data-animal="${i}">
              ${petTypeOptions.map(t => `<option value="${escapeMessageHtml(t)}" ${t === x.type ? 'selected' : ''}>${escapeMessageHtml(petTypeLabel(t))}</option>`).join('')}
            </select>
          </label>
          <div class="lg-pet-field">Service or support animal?
            <div class="lg-pet-yesno" role="group">
              <button type="button" class="lg-yn ${x.service ? '' : 'on'}" data-animal="${i}" data-service="no">No</button>
              <button type="button" class="lg-yn ${x.service ? 'on' : ''}" data-animal="${i}" data-service="yes">Yes</button>
            </div>
          </div>
          ${x.service ? '' : `
          <label class="lg-pet-field">Young ones with this pet (under 1 year)
            <select class="lg-pet-litter" data-animal="${i}">
              ${Array.from({ length: 11 }, (_, n) => `<option value="${n}" ${n === (Number(x.litter) || 0) ? 'selected' : ''}>${n === 0 ? 'None' : n}</option>`).join('')}
            </select>
          </label>`}
        </div>`).join('');
      petListEl.querySelectorAll('.lg-pet-type').forEach(sel => sel.addEventListener('change', () => {
        animals[Number(sel.dataset.animal)].type = sel.value;
        syncAnimalCounts();
      }));
      petListEl.querySelectorAll('.lg-yn').forEach(btn => btn.addEventListener('click', () => {
        const a = animals[Number(btn.dataset.animal)];
        a.service = btn.dataset.service === 'yes';
        if(a.service) a.litter = 0;
        syncAnimalCounts();
        renderAnimalList();
        updateListingPriceSummary(listing, lgArrival, lgDeparture);
      }));
      petListEl.querySelectorAll('.lg-pet-litter').forEach(sel => sel.addEventListener('change', () => {
        animals[Number(sel.dataset.animal)].litter = Number(sel.value) || 0;
        syncAnimalCounts();
        updateListingPriceSummary(listing, lgArrival, lgDeparture);
      }));
    }
    function setAnimalCount(n){
      while(animals.length < n) animals.push({ type: petTypeOptions[0], service: false, litter: 0 });
      while(animals.length > n) animals.pop();
      syncAnimalCounts();
      renderAnimalList();
    }
    syncAnimalCounts();
    renderAnimalList();

    const LG_MAX = { adults: 16, children: 12, infants: 5, animals: maxBillablePets + MAX_SERVICE_ANIMALS };
    // A stay is one physical unit with a real ceiling on how many people
    // can fit — capped here in real time as the stepper moves, not just
    // caught later at checkout (see create-order.js, which still
    // enforces this authoritatively either way). Infants/pets don't
    // count toward this the same way adults/children occupying the
    // space do. Not applied to a Resort: its real capacity lives
    // per-room, not on the listing itself, so there's no single ceiling
    // to check against here.
    // max_guests is free text ("3–4", "9+"): the largest number in it is
    // the limit, as the server reads it (parseMaxGuests in api/_pricing.js).
    const listingMaxGuests = (listing.property_type !== 'Resort') ? aervaParseMaxGuests(listing.max_guests) : null;
    container.parentElement.querySelectorAll('.guest-step-btn[data-lg-type]').forEach(btn => {
      btn.addEventListener('click', () => {
        const type = btn.dataset.lgType;
        const delta = btn.dataset.lgAction === 'inc' ? 1 : -1;
        const next = lgCounts[type] + delta;
        // serviceAnimals/youngLitter have their own floor of 1 while
        // their toggle is on — going to 0 via the stepper doesn't make
        // sense, unchecking the toggle is how you remove them entirely.
        const min = type === 'adults' ? 1 : 0;
        if(type === 'animals'){
          const n = animals.length + delta;
          if(n < 0 || n > LG_MAX.animals) return;
          setAnimalCount(n);
          updateListingPriceSummary(listing, lgArrival, lgDeparture);
          return;
        }
        if(next < min || next > LG_MAX[type]) return;
        if(delta > 0 && (type === 'adults' || type === 'children') && listingMaxGuests > 0){
          const otherType = type === 'adults' ? 'children' : 'adults';
          if(next + lgCounts[otherType] > listingMaxGuests){
            const capNoteEl = container.parentElement.querySelector('#lgCapacityNote');
            if(capNoteEl){
              capNoteEl.textContent = `${listing.property_name || 'This home'} sleeps up to ${listingMaxGuests} guests. For a larger group, please book an additional stay.`;
              capNoteEl.style.display = 'block';
            }
            return;
          }
        }
        lgCounts[type] = next;
        // Any successful change clears a previously-shown capacity
        // warning — otherwise decrementing back down to a valid count
        // would leave the message stuck on screen looking unresolved.
        const capNoteEl = container.parentElement.querySelector('#lgCapacityNote');
        if(capNoteEl) capNoteEl.style.display = 'none';
        const countEl = document.getElementById('lgCount' + type.charAt(0).toUpperCase() + type.slice(1));
        if(countEl) countEl.textContent = next;
        updateListingPriceSummary(listing, lgArrival, lgDeparture);
      });
    });

    // Expose the current guest counts to the price function without a
    // second copy of this state — read straight off the same object the
    // stepper buttons above are mutating.
    container.dataset.listingId = listingId;
    renderAvailabilityCalendar._lgCounts = renderAvailabilityCalendar._lgCounts || {};
    renderAvailabilityCalendar._lgCounts[listingId] = lgCounts;

    // If a valid date range carried over from the search, show the price
    // summary (and any dated amenities) immediately — the whole point of
    // carrying this state over is that the guest shouldn't have to
    // re-select anything they'd already picked.
    if(initialArrival && initialDeparture){
      updateListingPriceSummary(listing, initialArrival, initialDeparture);
      if(typeof renderListingAmenities === 'function') renderListingAmenities(listing, initialArrival, initialDeparture);
    }
  }

  // The dated-amenity picker: night-by-night checkboxes for each paid
  // amenity, respecting its own
  // availability window and excluded weekdays. Selections live in
  // renderAvailabilityCalendar._lgAmenities, read by both the price
  // summary and the actual booking request.
  function renderListingAmenities(listing, arrival, departure){
    const container = document.getElementById('listingAmenitiesPicker');
    if(!container) return;

    renderAvailabilityCalendar._lgAmenities = renderAvailabilityCalendar._lgAmenities || {};
    if(!renderAvailabilityCalendar._lgAmenities[listing.id]) renderAvailabilityCalendar._lgAmenities[listing.id] = {};
    const selectedAmenities = renderAvailabilityCalendar._lgAmenities[listing.id];

    const paidAmenities = Array.isArray(listing.paid_amenities) ? listing.paid_amenities : [];
    if(!arrival || !departure || paidAmenities.length === 0){
      container.innerHTML = '';
      return;
    }

    const nights = getNightsInRangeClient(arrival, departure);

    // Drop selections that no longer make sense now that dates changed.
    const validAmenityIds = new Set(paidAmenities.map(a => String(a.id)));
    Object.keys(selectedAmenities).forEach(aid => {
      if(!validAmenityIds.has(aid)){
        delete selectedAmenities[aid];
      } else {
        const kept = new Set([...selectedAmenities[aid]].filter(d => nights.includes(d)));
        if(kept.size === 0) delete selectedAmenities[aid];
        else selectedAmenities[aid] = kept;
      }
    });

    const rowsHtml = paidAmenities.map(a => {
      const excludedWeekdays = Array.isArray(a.excludedWeekdays) ? a.excludedWeekdays : [];
      const availableNights = nights.filter(n =>
        (!a.availableFrom || n >= a.availableFrom) &&
        (!a.availableUntil || n <= a.availableUntil) &&
        !excludedWeekdays.includes(new Date(n + 'T00:00:00').getDay())
      );
      if(availableNights.length === 0) return '';

      const selected = selectedAmenities[a.id] || new Set();
      const chips = availableNights.map(n => {
        const isChecked = selected.has(n);
        const label = new Date(n + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric' });
        return `<label class="amenity-night-chip${isChecked ? ' checked' : ''}"><input type="checkbox" data-lg-amenity-id="${a.id}" data-lg-amenity-date="${n}" ${isChecked ? 'checked' : ''}> ${label}</label>`;
      }).join('');

      const subtotal = selected.size * Number(a.price);
      const subtotalText = selected.size > 0
        ? `${selected.size} night${selected.size === 1 ? '' : 's'} selected — ${guestPrice(subtotal)}`
        : 'Tap nights to add this';

      return `
        <div class="stay-amenity-row">
          <div class="stay-amenity-head"><strong>${escapeMessageHtml(a.name)}</strong><span>${guestPrice(a.price)}/night</span></div>
          <div class="amenity-night-chips">${chips}</div>
          <div class="stay-amenity-subtotal">${subtotalText}</div>
        </div>
      `;
    }).join('');

    const disclaimer = rowsHtml ? `<p style="font-size:11px; opacity:0.55; margin-top:8px; line-height:1.5;">Paid amenities are available on the dates shown only, and are subject to weather, local circumstances, national holidays, and other factors outside the host's control. If a selected amenity can't be fulfilled, the host will provide a refund for that amenity.</p>` : '';
    container.innerHTML = rowsHtml ? `<div class="listing-modal-section-title">Add Paid Amenities</div>${rowsHtml}${disclaimer}` : '';

    container.querySelectorAll('input[type="checkbox"][data-lg-amenity-id]').forEach(cb => {
      cb.addEventListener('change', () => {
        const aid = cb.dataset.lgAmenityId;
        const date = cb.dataset.lgAmenityDate;
        if(!selectedAmenities[aid]) selectedAmenities[aid] = new Set();
        if(cb.checked) selectedAmenities[aid].add(date);
        else selectedAmenities[aid].delete(date);
        if(selectedAmenities[aid].size === 0) delete selectedAmenities[aid];
        renderListingAmenities(listing, arrival, departure);
        updateListingPriceSummary(listing, arrival, departure);
      });
    });
  }

  function updateListingPriceSummary(listing, arrival, departure){
    const summaryEl = document.getElementById('listingPriceSummary');
    const actionEl = document.getElementById('listingBookingAction');
    if(!summaryEl) return;
    updateListingPriceSummary._last = { listing, arrival, departure };
    const counts = (renderAvailabilityCalendar._lgCounts || {})[listing.id] || { adults: 1, children: 0, infants: 0, pets: 0, serviceAnimals: 0, youngLitter: 0 };

    // Book Now needs to read the current dates too — stashed here since
    // this function already runs on every date/guest change, same as
    // _lgCounts above.
    renderAvailabilityCalendar._lgDates = renderAvailabilityCalendar._lgDates || {};
    renderAvailabilityCalendar._lgDates[listing.id] = { arrival, departure };
    // Refreshes the experience date input's min/max to match the new
    // stay dates, and defaults a freshly-checked experience's date to
    // the new arrival — same reasoning as the amenities picker re-render
    // right above every date change.
    if(typeof renderListingExperiencesPicker === 'function') renderListingExperiencesPicker(listing);

    if(!arrival || !departure){
      summaryEl.style.display = 'none';
      if(actionEl) actionEl.style.display = 'none';
      // No dates chosen: the general "Free cancellation available" line is true again.
      document.querySelectorAll('[data-free-cancel-line]').forEach(el => { el.hidden = false; });
      return;
    }

    const nights = Math.round((new Date(departure) - new Date(arrival)) / (1000 * 60 * 60 * 24));
    const rate = listing.nightly_rate ? Number(listing.nightly_rate) : 0;
    if(!rate || nights <= 0){
      summaryEl.style.display = 'none';
      if(actionEl) actionEl.style.display = 'none';
      return;
    }

    const guests = counts.adults + counts.children;
    const roomTotal = rate * nights;
    const egT = extraGuestTermsOf(listing);
    const extraGuests = Math.max(guests - egT.included, 0);
    const extraTotal = extraGuests * egT.fee * nights;
    const beforeDiscount = roomTotal + extraTotal;
    const discount = calculateDiscount(listing, nights, arrival, beforeDiscount);
    const discountAmount = discount.amount;
    const petFeeAmount = counts.pets > 0 && listing.pet_fee ? Number(listing.pet_fee) * counts.pets : 0;
    // One service/support animal per booking is free; each one after the
    // first is charged at the pet fee (create-order.js charges the same).
    const chargeableServiceAnimals = Math.max(0, (counts.serviceAnimals || 0) - 1);
    const serviceAnimalFee = chargeableServiceAnimals > 0 && listing.pet_fee ? Number(listing.pet_fee) * chargeableServiceAnimals : 0;

    // Amenities are priced client-side here only for an instant estimate —
    // the server's quote (create-order.js, quoteOnly) replaces it.
    let amenityTotal = 0;
    let amenityNightCount = 0;
    const selectedAmenities = (renderAvailabilityCalendar._lgAmenities || {})[listing.id] || {};
    const paidAmenitiesList = Array.isArray(listing.paid_amenities) ? listing.paid_amenities : [];
    Object.entries(selectedAmenities).forEach(([aid, datesSet]) => {
      const amenity = paidAmenitiesList.find(a => String(a.id) === String(aid));
      if(amenity){
        amenityTotal += Number(amenity.price) * datesSet.size;
        amenityNightCount += datesSet.size;
      }
    });

    const staySubtotal = beforeDiscount - discountAmount + petFeeAmount + serviceAnimalFee + amenityTotal;
    const guestServiceFee = Math.round(staySubtotal * (guestFeeRateOf(listing) / 100));
    const stayTax = stayGstFor(beforeDiscount - discountAmount, nights, petFeeAmount + serviceAnimalFee + amenityTotal);
    const total = staySubtotal + guestServiceFee;

    const rows = [];
    rows.push(`<div class="sum-row"><span>${fmtGuest(rate)} × ${nights} night${nights === 1 ? '' : 's'}</span><span>${fmtGuest(roomTotal)}</span></div>`);
    if(extraGuests > 0) rows.push(`<div class="sum-row"><span>${extraGuests} extra guest${extraGuests === 1 ? '' : 's'}</span><span>${fmtGuest(extraTotal)}</span></div>`);
    if(discountAmount > 0) rows.push(`<div class="sum-row"><span>${escapeMessageHtml(discount.name || 'Offer applied')}</span><span>−${fmtGuest(discountAmount)}</span></div>`);
    if(petFeeAmount > 0) rows.push(`<div class="sum-row"><span>Pet fee (${counts.pets} × ${fmtGuest(Number(listing.pet_fee))})</span><span>${fmtGuest(petFeeAmount)}</span></div>`);
    // The first service/support animal is free; any more are charged at
    // the pet fee, shown as their own line so the guest sees why.
    if(counts.serviceAnimals > 0) rows.push(`<div class="sum-row"><span>1 service/support animal</span><span>No charge</span></div>`);
    if(serviceAnimalFee > 0) rows.push(`<div class="sum-row"><span>Additional service/support animal${chargeableServiceAnimals === 1 ? '' : 's'} (${chargeableServiceAnimals} × ${fmtGuest(Number(listing.pet_fee))})</span><span>${fmtGuest(serviceAnimalFee)}</span></div>`);
    if(counts.youngLitter > 0) rows.push(`<div class="sum-row"><span>${counts.youngLitter} young litter pet${counts.youngLitter === 1 ? '' : 's'}</span><span>No charge</span></div>`);
    if(amenityTotal > 0) rows.push(`<div class="sum-row"><span>Amenities (${amenityNightCount} night${amenityNightCount === 1 ? '' : 's'})</span><span>${fmtGuest(amenityTotal)}</span></div>`);
    // Experience add-on is priced and charged as its own separate line
    // in the same order (see create-order.js's experiences[] handling) —
    // shown here too so the total the guest sees before paying already
    // includes it, not just the stay itself.
    const selectedExperience = (renderAvailabilityCalendar._lgSelectedExperience || {})[listing.id] || null;
    let experienceTotal = 0;
    let experienceGst = 0;
    let experienceFee = 0;
    if(selectedExperience){
      const expOptions = ((renderAvailabilityCalendar._lgExperienceOptions || {})[listing.id]) || [];
      const exp = expOptions.find(e => String(e.id) === String(selectedExperience.listingId));
      if(exp && exp.price){
        experienceTotal = exp.experience_price_unit === 'per_person'
          ? Number(exp.price) * (selectedExperience.guests || 1)
          : Number(exp.price);
        rows.push(`<div class="sum-row"><span>${escapeMessageHtml(exp.property_name || '')}</span><span>${fmtGuest(experienceTotal)}</span></div>`);
        experienceGst = experienceGstFor(experienceTotal).gst;
        // The add-on carries its own guest service fee at checkout
        // (create-order.js). It used to be left out of this summary, so
        // the total shown was lower than the amount charged.
        experienceFee = Math.round(experienceTotal * (guestFeeRateOf(exp) / 100));
      }
    }
    const gstShown = stayTax.gst + experienceGst;
    if(gstShown > 0){
      const gstLabel = experienceGst > 0 && stayTax.rate !== GST_EXPERIENCE_RATE ? 'GST' : `GST (${stayTax.rate}%)`;
      rows.push(`<div class="sum-row"><span>${gstLabel}</span><span>${fmtGuest(gstShown)}</span></div>`);
    }
    rows.push(`<div class="sum-row"><span>Guest service fee</span><span>${fmtGuest(guestServiceFee + experienceFee)}</span></div>`);
    if(listing.security_deposit && Number(listing.security_deposit) > 0){
      rows.push(`<div class="sum-row" style="opacity:0.7;"><span>Refundable deposit (covers damage and extra cleaning; refunded after check-out unless damage is reported within 24 hours)</span><span>${fmtGuest(Number(listing.security_deposit))}</span></div>`);
    }

    const grandTotalInr = total + stayTax.gst + (listing.security_deposit ? Number(listing.security_deposit) : 0) + experienceTotal + experienceGst + experienceFee;
    // Payment always actually happens in INR (see the note on fmtGuest) —
    // when showing a converted currency, say so explicitly right here,
    // not just at the final payment button, so there's no surprise later.
    // The second sentence covers the real mechanism: it's the guest's own
    // bank/card network that converts INR to their currency after the
    // fact, at their own rate plus possibly their own fees — Aerva has no
    // part in and no control over that conversion.
    // Only when prices really are converted (no rates loaded = they are shown in rupees).
    const inrNote = currentCurrency !== 'INR' && currencyRatesLoaded && currencyRates[currentCurrency]
      ? `<p style="font-size:11.5px; opacity:0.6; margin-top:4px;">Charged as ${fmt(grandTotalInr)} (Indian Rupees) — shown in ${currentCurrency} at today's rate. Your bank or card network sets the actual exchange rate and may apply its own fees; Aerva is not responsible for any difference between this estimate and what your bank charges.</p>`
      : '';

    summaryEl.innerHTML = `
      ${bookStep(3, 'Check your total')}
      <div class="quote-body">
        ${rows.join('')}
        <div class="sum-row" style="font-weight:600; margin-top:8px; padding-top:8px; border-top:1px solid var(--line-dark);">
          <span>Total</span><span>${fmtGuest(grandTotalInr)}</span>
        </div>
        ${inrNote}
        <p style="font-size:11.5px; opacity:0.55; margin-top:8px;">Checking the exact total…</p>
      </div>
      <p style="font-size:12px; opacity:0.75; margin-top:10px; padding-top:10px; border-top:1px solid var(--line-dark);"><strong>Cancellation:</strong> ${cancellationPolicyText(listing.cancellation_policy)}</p>
      ${listing.free_cancel_offered === true ? '<p class="fc-available" id="listingFreeCancelAvail">Free cancellation available at checkout</p>' : ''}
    `;
    summaryEl.style.display = 'block';
    if(actionEl) actionEl.style.display = 'block';
    if(actionEl) aervaLoadSuggestedExperiences(actionEl);

    // The estimate above appears at once; the server's own price (the one
    // charged, api/create-order.js quoteOnly) replaces it a moment later.
    const quoteBody = summaryEl.querySelector('.quote-body');
    aervaQuote('listing', listingCartPayload(listing)).then(q => {
      if(q && quoteBody.isConnected) quoteBody.innerHTML = aervaQuoteBodyHtml(q);
      if(q) aervaShowFreeCancelOffer(q);
      // The split-payment preview: the whole quote, split by guests (display only; the server splits).
      if(q) aervaRefreshSplit({ total: Number(q.total || 0) + Number(q.feeCredit || 0), guests: counts.adults + counts.children });
    }).catch(err => {
      if(!quoteBody.isConnected) return;
      // The host stopped offering free cancellation while the page was
      // open: the option goes and the price is checked again without it.
      if(err && err.reason === 'free_cancel_not_offered'){
        const t = document.getElementById('listingFreeCancelToggle'), opt = document.getElementById('listingFreeCancelOpt');
        if(opt) opt.hidden = true;
        if(t && t.checked){ t.checked = false; aervaRepriceListing(); return; }
      }
      if(err && err.fromServer) quoteBody.innerHTML = aervaQuoteErrorHtml(err);
      else { const note = quoteBody.querySelector('p:last-child'); if(note) note.textContent = 'We could not check the exact total just now. It is shown again before you pay.'; }
    });
  }

  // What this stay page is booking, in the shape create-order.js takes —
  // the same for the price quote and for the payment itself.
  function listingCartPayload(listing){
    const dates = (renderAvailabilityCalendar._lgDates || {})[listing.id] || {};
    const counts = (renderAvailabilityCalendar._lgCounts || {})[listing.id] || { adults: 1, children: 0, infants: 0, pets: 0, serviceAnimals: 0, youngLitter: 0 };
    const selectedAmenities = (renderAvailabilityCalendar._lgAmenities || {})[listing.id] || {};
    const petTypes = counts.pets > 0 ? ((renderAvailabilityCalendar._lgPetTypeSelections || {})[listing.id] || []) : [];
    const serviceTypes = counts.serviceAnimals > 0 ? ((renderAvailabilityCalendar._lgServiceAnimalSelections || {})[listing.id] || []) : [];
    const selectedExperience = (renderAvailabilityCalendar._lgSelectedExperience || {})[listing.id] || null;
    return {
      stays: [{
        listingId: listing.id, arrival: dates.arrival, departure: dates.departure,
        guests: counts.adults + counts.children, adults: counts.adults,
        pets: counts.pets, petTypes, serviceAnimals: serviceTypes.map(type => ({ type })),
        youngLitterCount: counts.youngLitter > 0 ? counts.youngLitter : 0,
        selectedAmenities: Object.entries(selectedAmenities).map(([amenityId, datesSet]) => ({ amenityId: Number(amenityId), dates: [...datesSet] })),
        // The free cancellation add-on (api/_pricing.js), when ticked.
        freeCancel: !!((document.getElementById('listingFreeCancelToggle') || {}).checked)
      }],
      experiences: selectedExperience && selectedExperience.date
        ? [{ listingId: selectedExperience.listingId, date: selectedExperience.date, guests: selectedExperience.guests || 1 }]
        : []
    };
  }

  // "Complete your profile" (aerva-guest-verify.js) is asked again when a
  // booking is started, while the account has no first name, last name or
  // phone. Saved or "Do it later": the booking then carries on by itself.
  // Returns true when the pop-up was opened (the caller stops; resume runs after).
  function aervaProfilePromptFirst(resume){
    const GV = window.AervaGuestVerify;
    if(!GV || typeof GV.pending !== 'function') return false;
    if(aervaProfilePromptFirst.passed){ aervaProfilePromptFirst.passed = false; return false; }
    if(!GV.pending()) return false;
    GV.promptIfNeeded({ reason: 'booking', then: () => {
      aervaProfilePromptFirst.passed = true;
      // The name just saved goes into "Your details" before the booking
      // carries on (it used to carry on with the fields still empty).
      aervaPrefillPromise = null; aervaPrefillBooking();
      (aervaPrefillPromise || Promise.resolve()).then(resume, resume);
    } });
    return true;
  }

  // Checkout for a single stay (and any experience added to it): the
  // create-order → Razorpay → verify-payment sequence, with the Razorpay
  // key taken from the order create-order.js returns.
  async function handleListingBookNow(listing){
    const errorEl = document.getElementById('listingBookError');
    const confirmEl = document.getElementById('listingBookConfirm');
    const btn = document.getElementById('listingBookNowBtn');
    errorEl.style.display = 'none';
    errorEl.style.color = '#a3402f';
    confirmEl.style.display = 'none';

    if(!guestAuthToken()){
      requireLoginForBooking(() => handleListingBookNow(listing));
      return;
    }
    if(aervaProfilePromptFirst(() => handleListingBookNow(listing))) return;

    const dates = (renderAvailabilityCalendar._lgDates || {})[listing.id] || {};
    if(!dates.arrival || !dates.departure){
      errorEl.textContent = 'Please select your arrival and departure dates first.';
      errorEl.style.display = 'block';
      return;
    }

    const email = document.getElementById('listingBookEmail').value.trim();
    if(!email || !email.includes('@')){
      errorEl.textContent = 'Please enter a valid email address.';
      errorEl.style.display = 'block';
      return;
    }

    // Razorpay's own checkout requires a contact number for its
    // verification step (OTP for UPI/cards) regardless of what we send —
    // collecting it here and prefilling it below means that step is
    // already filled in rather than stopping the guest mid-payment to
    // ask for it themselves.
    // The number exactly as typed goes to the server, which saves it to the
    // account if it has none (create-order.js); Razorpay gets the digits.
    const phoneTyped = document.getElementById('listingBookPhone').value.trim();
    const phone = phoneTyped.replace(/\D/g, '');
    if(!phone || phone.length < 10){
      errorEl.textContent = 'Please enter a valid mobile number.';
      errorEl.style.display = 'block';
      return;
    }

    const counts = (renderAvailabilityCalendar._lgCounts || {})[listing.id] || { adults: 1, children: 0, infants: 0, pets: 0, serviceAnimals: 0, youngLitter: 0 };
    // The guest-count stepper already never lets adults drop below 1
    // (see the min:1 rule near LG_MAX), but this checks it explicitly
    // too — a stay can't be booked by children/infants alone, and the
    // server enforces this for real (see create-order.js); this is just
    // a faster, clearer message than waiting on a round trip.
    if(counts.adults < 1){
      errorEl.textContent = 'At least one adult (18 or over) must be part of the group to book this stay.';
      errorEl.style.display = 'block';
      return;
    }
    // Bringing a pet requires saying what kind — one dropdown per pet
    // slot (see renderPetTypeSlots), so this is always exactly one type
    // per billable pet, never a looser "at least one kind checked."
    const petCap = listing.max_pets_allowed ? Math.min(5, Number(listing.max_pets_allowed)) : 5;
    if(counts.pets > petCap){
      errorEl.textContent = `This home allows up to ${petCap} pet${petCap === 1 ? '' : 's'}. Service or support animals are not counted.`;
      errorEl.style.display = 'block';
      return;
    }
    if(counts.pets > 0){
      const modalRoot = document.getElementById('listingModalBody');
      const petTypes = (renderAvailabilityCalendar._lgPetTypeSelections || {})[listing.id] || [];
      if(petTypes.length !== counts.pets){
        const petTypesError = (modalRoot || document).querySelector('#lgPetTypesError');
        if(petTypesError) petTypesError.style.display = 'block';
        errorEl.textContent = 'Please choose a type for each pet before booking.';
        errorEl.style.display = 'block';
        return;
      }
    }

    // Service/support animals — never counted or charged, only offered
    // on pet-friendly listings (see the booking-modal markup). Types come
    // from the same per-slot picker pattern as billable pets above.
    if(counts.serviceAnimals > 0){
      const modalRoot = document.getElementById('listingModalBody');
      const types = (renderAvailabilityCalendar._lgServiceAnimalSelections || {})[listing.id] || [];
      if(types.length !== counts.serviceAnimals){
        const errEl = (modalRoot || document).querySelector('#lgServiceAnimalError');
        if(errEl) errEl.style.display = 'block';
        errorEl.textContent = 'Please choose a type for each service or support animal before booking.';
        errorEl.style.display = 'block';
        return;
      }
    }

    // If the guest checked a with-stay experience add-on, it needs a
    // date before it can be booked — same requirement create-order.js
    // enforces server-side.
    const selectedExperience = (renderAvailabilityCalendar._lgSelectedExperience || {})[listing.id] || null;
    if(selectedExperience && !selectedExperience.date){
      errorEl.textContent = 'Please pick the day the experience you added starts, or untick it.';
      errorEl.style.display = 'block';
      return;
    }
    const cart = listingCartPayload(listing);
    // "This stay is for someone else" / "Split the payment with friends".
    const bookOpts = aervaReadBookOptions(errorEl, counts.adults + counts.children);
    if(bookOpts === false) return;
    if(bookOpts.group && cart.experiences.length){
      errorEl.textContent = 'A split payment is for the home on its own. Please untick the experience, or pay for the whole booking.';
      errorEl.style.display = 'block';
      return;
    }

    btn.disabled = true;
    btn.textContent = 'Preparing payment…';

    let order;
    try {
      const orderRes = await fetch(API_BASE + '/api/create-order', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
        body: JSON.stringify({
          stays: cart.stays,
          experiences: cart.experiences,
          email,
          // Only takes effect if this currency is admin-enabled for direct
          // international charging server-side (see create-order.js) —
          // otherwise the backend charges INR exactly as it always has.
          preferredCurrency: currentCurrency,
          couponCode: bookOpts.group ? undefined : (document.getElementById('listingCouponCode').value.trim() || undefined),
          pricesSeen: aervaPricesSeen([listing]),
          phone: phoneTyped,
          firstName: (document.getElementById('listingBookFirstName') || {}).value,
          lastName: (document.getElementById('listingBookLastName') || {}).value,
          gift: bookOpts.gift || undefined,
          group: bookOpts.group || undefined
        })
      });
      if(!orderRes.ok){
        const errData = await orderRes.json().catch(() => ({}));
        if(errData.priceChanged){
          aervaShowPriceChange(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment'; aervaSyncBookOptions();
          return;
        }
        if(Array.isArray(errData.needs) && errData.needs.length){
          if(errData.needs.includes('name') || errData.needs.some(n => /^gift/.test(n))){ errorEl.textContent = errData.error; errorEl.style.display = 'block'; }
          else aervaShowNeeds(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment'; aervaSyncBookOptions();
          return;
        }
        throw new Error(errData.error || 'We could not start your payment. Please try again.');
      }
      order = await orderRes.json();
      if(order.group){
        confirmEl.textContent = `You pay ${moneyBoth(order.total)} now for ${order.group.payNow} of ${order.group.places} places. Once paid, your group is open for 2 hours. The place is not held until the last payment.`;
        confirmEl.style.display = 'block';
      }
      if(order.couponDiscount > 0){
        // The discount is already baked into what Razorpay will actually
        // charge (see order.amount below) — this is just confirming to
        // the guest that their code worked, before the payment popup opens.
        confirmEl.textContent = `Coupon applied: ${moneyBoth(order.couponDiscount)} off the booking price. Service fee and GST are charged in full.`
          + (order.couponForfeited > 0 ? ` ${moneyBoth(order.couponForfeited)} of the coupon is unused and is not refunded.` : '');
        confirmEl.style.display = 'block';
      }
    } catch(err){
      btn.disabled = false;
      btn.textContent = 'Continue to payment'; aervaSyncBookOptions();
      errorEl.textContent = err.message || 'We could not start your payment. Please try again.';
      errorEl.style.display = 'block';
      return;
    }

    btn.disabled = false;
    btn.textContent = 'Continue to payment'; aervaSyncBookOptions();

    if(typeof Razorpay === 'undefined'){
      errorEl.textContent = 'Payment gateway did not load. Please check your connection and try again.';
      errorEl.style.display = 'block';
      return;
    }
    if(!order.keyId){
      aervaReleaseHold(order.orderId, 'closed');
      errorEl.textContent = 'Payment is not available right now. Nothing has been charged. Please try again in a few minutes.';
      errorEl.style.display = 'block';
      return;
    }

    const options = {
      key: order.keyId,
      order_id: order.orderId,   // amount/currency come from the order itself — cannot be edited client-side
      timeout: (order && order.holdSeconds) || undefined, // Razorpay closes its window when the payment window ends
      amount: order.amount,
      currency: order.currency,
      name: 'Aerva',
      description: listing.property_name,
      prefill: { email, contact: phone },
      theme: { color: '#a9884f' },
      config: {
        display: {
          sequence: ['upi', 'card', 'netbanking', 'wallet'],
          preferences: { show_default_blocks: true }
        }
      },
      handler: async function(response){
        aervaCheckoutSucceeded();
        try {
          const verifyRes = await fetch(API_BASE + '/api/verify-payment', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(response)
          });
          const verifyData = await verifyRes.json();
          aervaShowPaymentResult(verifyData, { confirmEl, errorEl, btn, suggestFor: listing.id, gift: bookOpts.gift || null });
        } catch(err){
          aervaShowPaymentResult({ pending: true, message: 'Your payment was received, but we could not confirm the booking on this page. We will email you within a few minutes — please do not pay again. Payment ID: ' + response.razorpay_payment_id }, { confirmEl, errorEl, btn });
        }
      },
      modal: { ondismiss: function(){ aervaEndCheckout('closed'); } }
    };

    const rzp = new Razorpay(options);
    rzp.on('payment.failed', function(response){ aervaEndCheckout('failed'); });
    rzp.open();
    aervaWatchCheckout(rzp, order, errorEl);
  }

  // ---- Resort booking: pick dates once, then choose which room(s) —
  // each room independently priced and independently available (see
  // create-order.js's dedicated resort-room branch). No pets or paid
  // amenities here. Each room is booked for the number of guests chosen
  // for it (1 up to what the room sleeps): above 2 guests a room carries
  // the same extra-guest charge as any stay (api/_pricing.js).
  let resortSelectedRooms = {};
  let resortPolicy = 'flexible'; // the resort being booked; set in renderResortRooms
  let resortListing = null;

  async function renderResortBookingCalendar(listing){
    const container = document.getElementById('resortBookCalendar');
    if(!container) return;
    let resortArrival = '';
    let resortDeparture = '';
    let selectingStart = true;
    // The earliest night a guest can book, on the PROPERTY's clock — today,
    // or last night between 12:00 AM and 6:00 AM (same rule as stays and
    // api/_booking-rules.js).
    const minIso = aervaEarliestArrival((listing && listing.timezone) || 'Asia/Kolkata', listing && listing.same_day_until);
    const minDateObj = new Date(minIso + 'T00:00:00');
    let viewYear = minDateObj.getFullYear();
    let viewMonth = minDateObj.getMonth();

    function handleDayClick(iso){
      if(selectingStart || !resortArrival){
        resortArrival = iso; resortDeparture = ''; selectingStart = false;
      } else if(iso <= resortArrival){
        resortArrival = iso; resortDeparture = ''; selectingStart = false;
      } else {
        resortDeparture = iso; selectingStart = true;
      }
      renderMonth();
      if(resortArrival && resortDeparture){
        renderResortRooms(listing, resortArrival, resortDeparture);
      } else {
        // New dates are being picked: the rooms and total chosen for the
        // earlier dates go (they would still have been booked for those dates).
        resortSelectedRooms = {};
        updateResortPriceSummary();
        const list = document.getElementById('resortRoomsList'), prompt = document.getElementById('resortDatesPrompt');
        if(list) list.innerHTML = '';
        if(prompt) prompt.style.display = '';
      }
    }

    function renderMonth(){
      const firstDay = new Date(viewYear, viewMonth, 1);
      const startWeekday = firstDay.getDay();
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const isMinMonth = viewYear === minDateObj.getFullYear() && viewMonth === minDateObj.getMonth();

      let cellsHtml = '';
      for(let i = 0; i < startWeekday; i++) cellsHtml += '<div class="calendar-day empty"></div>';
      for(let day = 1; day <= daysInMonth; day++){
        const iso = toLocalDateStr(new Date(viewYear, viewMonth, day));
        const isDisabled = iso < minIso;
        let classes = 'calendar-day';
        if(isDisabled) classes += ' disabled';
        if(iso === resortArrival || iso === resortDeparture) classes += ' selected-start';
        else if(resortArrival && resortDeparture && iso > resortArrival && iso < resortDeparture) classes += ' in-range';
        cellsHtml += `<div class="${classes}" data-resort-date="${iso}">${day}</div>`;
      }
      const rangeNoteHtml = resortArrival && resortDeparture
        ? `<p style="font-size:12px; margin-top:10px;"><strong>${new Date(resortArrival + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric' })} – ${new Date(resortDeparture + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' })}</strong></p>`
        : resortArrival
        ? `<p style="font-size:11.5px; opacity:0.6; margin-top:10px;">Now pick your checkout date.</p>`
        : `<p style="font-size:11.5px; opacity:0.6; margin-top:10px;">Pick check-in, then checkout.</p>`;

      container.innerHTML = `
        <div class="calendar-month-panel" style="max-width:320px; padding:0;">
          <div class="calendar-month-header">
            <button type="button" class="cal-nav" id="resortCalPrev" aria-label="Previous month" ${isMinMonth ? 'disabled' : ''}>‹</button>
            <div class="calendar-month-label">${MONTH_NAMES[viewMonth]} ${viewYear}</div>
            <button type="button" class="cal-nav" id="resortCalNext" aria-label="Next month">›</button>
          </div>
          <div class="calendar-weekdays"><span>S</span><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span></div>
          <div class="calendar-grid">${cellsHtml}</div>
          ${rangeNoteHtml}
        </div>
      `;
      document.getElementById('resortCalPrev').addEventListener('click', () => {
        viewMonth -= 1; if(viewMonth < 0){ viewMonth = 11; viewYear -= 1; } renderMonth();
      });
      document.getElementById('resortCalNext').addEventListener('click', () => {
        viewMonth += 1; if(viewMonth > 11){ viewMonth = 0; viewYear += 1; } renderMonth();
      });
      container.querySelectorAll('.calendar-day:not(.disabled):not(.empty)').forEach(cell => {
        aervaDayCellA11y(cell, 'data-resort-date');
        cell.addEventListener('click', (e) => { e.stopPropagation(); handleDayClick(cell.dataset.resortDate); });
      });
    }
    renderMonth();
  }

  // Guests for a room when it is first picked: 2, or fewer if it sleeps fewer.
  function resortDefaultGuests(room){
    const max = Math.max(1, Number(room.maxOccupancy) || 1);
    // The guests the room's price covers (set by the host; 2 where not set).
    const inc = parseInt(room.includedGuests, 10) >= 1 ? parseInt(room.includedGuests, 10) : BASE_OCCUPANCY;
    return Math.min(inc, max);
  }

  async function renderResortRooms(listing, arrival, departure){
    resortPolicy = listing && listing.cancellation_policy === 'firm' ? 'firm' : 'flexible';
    resortListing = listing;
    const container = document.getElementById('resortRoomsList');
    const promptEl = document.getElementById('resortDatesPrompt');
    if(promptEl) promptEl.style.display = 'none';
    const rooms = Array.isArray(listing.rooms) ? listing.rooms : [];
    resortSelectedRooms = {};
    updateResortPriceSummary();
    renderRoomAwarePhotos(listing, []);
    if(!rooms.length) return;

    container.innerHTML = '<p style="font-size:12.5px; opacity:0.5;">Checking room availability…</p>';
    const nightsNeeded = getNightsInRangeClient(arrival, departure);

    const roomsWithAvailability = await Promise.all(rooms.map(async room => {
      try{
        const res = await fetch(SUITES_API_BASE + `/api/get-listings?availabilityFor=${listing.id}&roomId=${room.id}`);
        if(!res.ok) return { ...room, available: true }; // fail open — a check failing shouldn't itself block booking
        const data = await res.json();
        const ranges = [...(Array.isArray(data.bookedRanges) ? data.bookedRanges : []), ...(Array.isArray(data.blockedRanges) ? data.blockedRanges : [])];
        const occupied = new Set();
        ranges.forEach(r => { if(r.arrival && r.departure) getNightsInRangeClient(r.arrival, r.departure).forEach(n => occupied.add(n)); });
        return { ...room, available: !nightsNeeded.some(n => occupied.has(n)) };
      } catch(err){
        return { ...room, available: true };
      }
    }));

    const nights = nightsNeeded.length;
    container.innerHTML = roomsWithAvailability.map(room => {
      const max = Math.max(1, Number(room.maxOccupancy) || 1);
      const options = Array.from({ length: max }, (_, i) => i + 1)
        .map(n => `<option value="${n}"${n === resortDefaultGuests(room) ? ' selected' : ''}>${n} guest${n === 1 ? '' : 's'}</option>`).join('');
      return `
      <div class="resort-room" style="padding:10px 0; border-bottom:1px solid var(--line-dark); opacity:${room.available ? '1' : '0.45'};">
        <label style="display:flex; align-items:center; gap:12px; cursor:${room.available ? 'pointer' : 'default'};">
          ${room.coverPhotoUrl
            ? `<img src="${escapeMessageHtml(room.coverPhotoUrl)}" alt="" style="width:64px; height:52px; object-fit:cover; border-radius:4px; flex:0 0 auto;">`
            : `<span style="width:64px; height:52px; flex:0 0 auto; background:var(--cream-deep); border-radius:4px;"></span>`}
          <input type="checkbox" data-room-id="${room.id}" ${room.available ? '' : 'disabled'} style="width:auto;">
          <span style="flex:1; min-width:0;">
            <strong style="display:block; font-size:14px;">${escapeMessageHtml(room.roomName || 'Room')}</strong>
            <span style="font-size:12px; opacity:0.65;">Sleeps up to ${max} · ${fmtGuest(Number(room.price))}/night${room.available ? '' : ' · Not available these dates'}</span>
          </span>
        </label>
        <div class="resort-room-guests" data-guests-for="${room.id}" style="display:none; margin:8px 0 0 88px;">
          <label for="resortGuests${room.id}" style="font-size:12.5px; margin-right:8px;">Guests in this room</label>
          <select id="resortGuests${room.id}" data-room-guests="${room.id}" style="padding:6px 8px; font-size:14px; border:1px solid var(--line-dark);">${options}</select>
          ${(() => { const t = extraGuestTermsOf({ included_guests: room.includedGuests, extra_guest_fee: room.extraGuestFee });
              return max > t.included && t.fee > 0 ? `<p style="font-size:11.5px; opacity:0.6; margin:4px 0 0;">Above ${t.included} guest${t.included === 1 ? '' : 's'}, ${fmtGuest(t.fee)} per extra guest per night.</p>` : ''; })()}
        </div>
      </div>`;
    }).join('');

    container.querySelectorAll('[data-room-id]').forEach(cb => {
      cb.addEventListener('change', () => {
        const room = roomsWithAvailability.find(r => String(r.id) === cb.dataset.roomId);
        const guestsBox = container.querySelector(`[data-guests-for="${room.id}"]`);
        const guestsSel = container.querySelector(`[data-room-guests="${room.id}"]`);
        if(cb.checked) resortSelectedRooms[room.id] = { ...room, arrival, departure, nights, guests: Number(guestsSel.value) || resortDefaultGuests(room) };
        else delete resortSelectedRooms[room.id];
        if(guestsBox) guestsBox.style.display = cb.checked ? 'block' : 'none';
        updateResortPriceSummary();
        renderRoomAwarePhotos(listing, Object.keys(resortSelectedRooms).map(Number));
      });
    });
    container.querySelectorAll('[data-room-guests]').forEach(sel => {
      sel.addEventListener('change', () => {
        const picked = resortSelectedRooms[sel.dataset.roomGuests];
        if(picked){ picked.guests = Number(sel.value) || 1; updateResortPriceSummary(); }
      });
    });
  }

  // One stays[] entry per selected room — each becomes its own order row
  // (create-order.js), with that room's own guest count. adults: 1 — the
  // resort form does not split adults from children; the person booking,
  // signed in with a confirmed email and phone, is the adult on the booking.
  function resortCartStays(listing){
    return Object.values(resortSelectedRooms).map(r => ({
      listingId: listing.id, roomId: r.id, arrival: r.arrival, departure: r.departure, guests: r.guests, adults: 1
    }));
  }

  // The total shown is the server's own price for these rooms and guests
  // (create-order.js, quoteOnly): room rates, extra guests, offers, GST,
  // the guest service fee and any deposit — exactly what is charged.
  function updateResortPriceSummary(){
    const summaryEl = document.getElementById('resortPriceSummary');
    const actionEl = document.getElementById('resortBookingAction');
    if(!summaryEl || !actionEl) return;
    const selected = Object.values(resortSelectedRooms);
    if(!selected.length || !resortListing){
      aervaQuoteSeq.resort = (aervaQuoteSeq.resort || 0) + 1; // any quote on its way is no longer wanted
      summaryEl.style.display = 'none';
      actionEl.style.display = 'none';
      return;
    }
    summaryEl.innerHTML = `
      ${bookStep(3, 'Check your total')}
      <div class="quote-body"><p style="font-size:12.5px; opacity:0.6;">Working out your total…</p></div>
      <p style="font-size:12px; opacity:0.75; margin-top:10px; padding-top:10px; border-top:1px solid var(--line-dark);"><strong>Cancellation:</strong> ${cancellationPolicyText(resortPolicy)}</p>
    `;
    summaryEl.style.display = 'block';
    actionEl.style.display = 'block';
    aervaLoadSuggestedExperiences(actionEl);
    const quoteBody = summaryEl.querySelector('.quote-body');
    aervaQuote('resort', { stays: resortCartStays(resortListing) }).then(q => {
      if(q && quoteBody.isConnected) quoteBody.innerHTML = aervaQuoteBodyHtml(q);
    }).catch(err => { if(quoteBody.isConnected) quoteBody.innerHTML = aervaQuoteErrorHtml(err); });
  }

  async function handleResortBookNow(listing){
    const errorEl = document.getElementById('resortBookError');
    const confirmEl = document.getElementById('resortBookConfirm');
    const btn = document.getElementById('resortBookNowBtn');
    errorEl.style.display = 'none';
    errorEl.style.color = '#a3402f';
    confirmEl.style.display = 'none';

    if(!guestAuthToken()){
      requireLoginForBooking(() => handleResortBookNow(listing));
      return;
    }
    if(aervaProfilePromptFirst(() => handleResortBookNow(listing))) return;
    const selected = Object.values(resortSelectedRooms);
    if(!selected.length){
      errorEl.textContent = 'Please select at least one room.';
      errorEl.style.display = 'block';
      return;
    }
    const email = document.getElementById('resortBookEmail').value.trim();
    if(!email || !email.includes('@')){
      errorEl.textContent = 'Please enter a valid email address.';
      errorEl.style.display = 'block';
      return;
    }
    // The number exactly as typed goes to the server, which saves it to the
    // account if it has none (create-order.js); Razorpay gets the digits.
    const phoneTyped = document.getElementById('resortBookPhone').value.trim();
    const phone = phoneTyped.replace(/\D/g, '');
    if(!phone || phone.length < 10){
      errorEl.textContent = 'Please enter a valid mobile number.';
      errorEl.style.display = 'block';
      return;
    }

    btn.disabled = true;
    btn.textContent = 'Preparing payment…';

    let order;
    try{
      const orderRes = await fetch(API_BASE + '/api/create-order', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
        body: JSON.stringify({ stays: resortCartStays(listing), email, preferredCurrency: currentCurrency, pricesSeen: aervaPricesSeen([listing]), phone: phoneTyped,
          couponCode: ((document.getElementById('resortCouponCode') || {}).value || '').trim() || undefined,
          firstName: (document.getElementById('resortBookFirstName') || {}).value, lastName: (document.getElementById('resortBookLastName') || {}).value })
      });
      if(!orderRes.ok){
        const errData = await orderRes.json().catch(() => ({}));
        if(errData.priceChanged){
          aervaShowPriceChange(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment';
          return;
        }
        if(Array.isArray(errData.needs) && errData.needs.length){
          if(errData.needs.includes('name')){ errorEl.textContent = errData.error; errorEl.style.display = 'block'; }
          else aervaShowNeeds(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment';
          return;
        }
        throw new Error(errData.error || 'We could not start your payment. Please try again.');
      }
      order = await orderRes.json();
      if(order.couponDiscount > 0){
        confirmEl.textContent = `Coupon applied: ${moneyBoth(order.couponDiscount)} off the booking price. Service fee and GST are charged in full.`
          + (order.couponForfeited > 0 ? ` ${moneyBoth(order.couponForfeited)} of the coupon is unused and is not refunded.` : '');
        confirmEl.style.display = 'block';
      }
    } catch(err){
      btn.disabled = false;
      btn.textContent = 'Continue to payment';
      errorEl.textContent = err.message || 'We could not start your payment. Please try again.';
      errorEl.style.display = 'block';
      return;
    }

    btn.disabled = false;
    btn.textContent = 'Continue to payment';

    if(typeof Razorpay === 'undefined'){
      errorEl.textContent = 'Payment gateway did not load. Please check your connection and try again.';
      errorEl.style.display = 'block';
      return;
    }
    if(!order.keyId){
      aervaReleaseHold(order.orderId, 'closed');
      errorEl.textContent = 'Payment is not available right now. Nothing has been charged. Please try again in a few minutes.';
      errorEl.style.display = 'block';
      return;
    }

    const options = {
      key: order.keyId,
      order_id: order.orderId,
      timeout: (order && order.holdSeconds) || undefined, // Razorpay closes its window when the payment window ends
      amount: order.amount,
      currency: order.currency,
      name: 'Aerva',
      description: listing.property_name,
      prefill: { email, contact: phone },
      theme: { color: '#a9884f' },
      config: { display: { sequence: ['upi', 'card', 'netbanking', 'wallet'], preferences: { show_default_blocks: true } } },
      handler: async function(response){
        aervaCheckoutSucceeded();
        try{
          const verifyRes = await fetch(API_BASE + '/api/verify-payment', {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(response)
          });
          const verifyData = await verifyRes.json();
          aervaShowPaymentResult(verifyData, { confirmEl, errorEl, btn, suggestFor: listing.id });
        } catch(err){
          aervaShowPaymentResult({ pending: true, message: 'Your payment was received, but we could not confirm the booking on this page. We will email you within a few minutes — please do not pay again. Payment ID: ' + response.razorpay_payment_id }, { confirmEl, errorEl, btn });
        }
      },
      modal: { ondismiss: function(){ aervaEndCheckout('closed'); } }
    };
    const rzp2 = new Razorpay(options);
    rzp2.on('payment.failed', function(response){ aervaEndCheckout('failed'); });
    rzp2.open();
    aervaWatchCheckout(rzp2, order, errorEl);
  }

  // Experience detail page — mirrors buildListingDetailHtml's structure,
  // but with much simpler booking math (no nights, no discount, price is
  // either per-person or flat) and a "hosted at" cross-sell into the
  // existing, already-working stay booking page rather than trying to
  // embed a second full booking widget inline.
  function buildExperienceDetailHtml(exp){
    const exteriorPhotos = Array.isArray(exp.exterior_photo_urls) ? exp.exterior_photo_urls : [];
    const interiorPhotos = Array.isArray(exp.interior_photo_urls) ? exp.interior_photo_urls : [];
    let allPhotos = [...interiorPhotos, ...exteriorPhotos];
    if(exp.cover_photo_url && allPhotos.includes(exp.cover_photo_url)){
      allPhotos = [exp.cover_photo_url, ...allPhotos.filter(url => url !== exp.cover_photo_url)];
    }
    // Same 4-photo collage + lightbox, same 3-column layout (booking |
    // photos+description | map) the listing detail page already uses —
    // this used to be its own different-looking layout; now the two
    // detail pages read as the same product instead of two different ones.
    const photosHtml = buildPhotoCollageHtml(allPhotos, exp.property_name, 'exp-' + exp.id);

    const priceLine = exp.price
      ? `${fmtGuest(Number(exp.price))}${exp.experience_price_unit === 'per_person' ? ' / person' : ' / group'}`
      : 'Price on request';
    const durationDaysLine = (exp.experience_duration_days && exp.experience_duration_days > 1) ? `${exp.experience_duration_days} days` : '';
    const durationHoursLine = exp.experience_duration_hours ? `${exp.experience_duration_hours} hour${Number(exp.experience_duration_hours) === 1 ? '' : 's'}${durationDaysLine ? '/day' : ''}` : '';
    const durationLine = [durationDaysLine, durationHoursLine].filter(Boolean).join(', ');

    // Availability window (optional, host-set — see the "List Experience"
    // form) — when present, constrains which dates a guest can even pick
    // in the first place, same as a listing's booked-date greying-out,
    // just expressed as native min/max rather than a custom calendar.
    // Today on the experience's own clock is the earliest day (as for
    // stays and resorts; the server checks the same, api/_pricing.js).
    let todayIso = aervaEarliestArrival(exp.timezone || 'Asia/Kolkata');
    // Today is gone once the start time has passed (server: priceExperience).
    try{
      const st = /^(\d{1,2}):(\d{2})/.exec(String(exp.experience_start_time || ''));
      if(st){
        const now = {};
        new Intl.DateTimeFormat('en-US', { timeZone: exp.timezone || 'Asia/Kolkata', hourCycle: 'h23', hour: '2-digit', minute: '2-digit' }).formatToParts(new Date()).forEach(p => { now[p.type] = p.value; });
        if(Number(now.hour) * 60 + Number(now.minute) >= Number(st[1]) * 60 + Number(st[2])) todayIso = aervaAddDays(todayIso, 1);
      }
    }catch(e){}
    const availableFromIso = exp.experience_available_from ? String(exp.experience_available_from).slice(0, 10) : null;
    const availableUntilIso = exp.experience_available_until ? String(exp.experience_available_until).slice(0, 10) : null;
    const bookDateMin = (availableFromIso && availableFromIso > todayIso) ? availableFromIso : todayIso;
    // A host-set "Available Until" date that's already in the past, or
    // earlier than the earliest bookable date, would otherwise disable
    // EVERY day on the calendar with no warning to anyone — every date
    // would count as "overrunning" a window that's already closed. That
    // silently makes the whole experience unbookable: no listener even
    // gets attached to a disabled cell, so clicking does nothing and
    // throws no error either, which is exactly what made this hard to
    // spot. Treated as "no upper bound" instead when it's not actually
    // usable, rather than trusting it blindly.
    const bookDateMax = (availableUntilIso && availableUntilIso >= bookDateMin) ? availableUntilIso : null;
    const availabilityNoteHtml = (availableFromIso || bookDateMax) ? `
      <p style="font-size:11.5px; opacity:0.6; margin-top:4px;">
        ${availableFromIso && bookDateMax
          ? `Available ${new Date(availableFromIso + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric' })} – ${new Date(bookDateMax + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' })}`
          : availableFromIso
          ? `Available from ${new Date(availableFromIso + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' })}`
          : `Available through ${new Date(bookDateMax + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short', day: 'numeric', year: 'numeric' })}`}
      </p>
    ` : '';

    // Only offered as a cross-sell when the hosting property is itself an
    // approved, bookable stay — never for a pending/rejected/no-rate one.
    const hostingIsBookable = exp.hosting_listing_id && exp.hosting_status === 'approved' && exp.hosting_nightly_rate;
    const hostingExteriorPhotos = Array.isArray(exp.hosting_exterior_photo_urls) ? exp.hosting_exterior_photo_urls : [];
    const hostingInteriorPhotos = Array.isArray(exp.hosting_interior_photo_urls) ? exp.hosting_interior_photo_urls : [];
    let hostingAllPhotos = [...hostingInteriorPhotos, ...hostingExteriorPhotos];
    if(exp.hosting_cover_photo_url && hostingAllPhotos.includes(exp.hosting_cover_photo_url)){
      hostingAllPhotos = [exp.hosting_cover_photo_url, ...hostingAllPhotos.filter(url => url !== exp.hosting_cover_photo_url)];
    }
    // The stay's own photos and info show right here, inline — nothing
    // about this card navigates anywhere. Only the explicit "View
    // Listing" button does, and only on a deliberate click, in a new
    // tab, so the guest never loses their place on this experience.
    const hostingPhotosHtml = hostingAllPhotos.length ? buildPhotoCollageHtml(hostingAllPhotos, exp.hosting_property_name, 'exp-hosting-' + exp.id) : '';
    const hostingHtml = exp.hosting_property_name ? `
      <div class="listing-modal-section-title">Hosted At</div>
      <div class="exp-stay-card">
        ${hostingPhotosHtml ? `<div style="margin-bottom:16px;">${hostingPhotosHtml}</div>` : ''}
        <div class="exp-stay-card-head">
          <div>
            <h4>${escapeMessageHtml(exp.hosting_property_name)}</h4>
            <div class="exp-stay-card-loc">${escapeMessageHtml(exp.hosting_area ? exp.hosting_area + ', ' + exp.hosting_city : (exp.hosting_city || ''))}</div>
          </div>
          ${hostingIsBookable ? `<div class="exp-stay-card-price">From <strong>${fmtGuest(Number(exp.hosting_nightly_rate))}</strong>/night</div>` : ''}
        </div>
        ${hostingIsBookable ? `
          <a href="index.html?listing=${exp.hosting_listing_id}" target="_blank" rel="noopener" class="exp-view-listing-btn">
            View Listing
            <svg viewBox="0 0 24 24" fill="none" stroke-width="1.5"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
          </a>
          <p style="font-size:11.5px; opacity:0.6; margin-top:10px;">Booked separately from this experience, on its own page.</p>
        ` : `<p style="font-size:12.5px; opacity:0.6; margin-top:8px;">This property isn't currently bookable as a stay.</p>`}
      </div>
    ` : '';

    // Logistics — all host-defined (see the "List Experience" form),
    // shown as-is rather than Aerva interpreting or enforcing any of it.
    const meetingPointLine = exp.experience_meeting_point_type === 'common_point'
      ? (exp.experience_meeting_point_details || 'A common meeting point (details from host)')
      : 'At the property/hotel';
    const travelValue = exp.experience_arranges_travel
      ? `Arranged by host${exp.experience_travel_details ? ' — ' + exp.experience_travel_details : ''}`
      : 'Not included — guests make their own way there';
    const logisticsItems = [];
    if(exp.experience_start_time){
      logisticsItems.push({
        icon: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/>',
        label: 'Start Time', value: exp.experience_start_time
      });
    }
    logisticsItems.push({
      icon: '<path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/>',
      label: 'Meeting Point', value: meetingPointLine
    });
    logisticsItems.push({
      icon: '<rect x="3" y="7" width="18" height="13" rx="1.5"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>',
      label: 'Travel / Transport', value: travelValue
    });
    const logisticsGridHtml = `
      <div class="exp-logistics-grid">
        ${logisticsItems.map(item => `
          <div class="exp-logistics-item">
            <div class="exp-logistics-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${item.icon}</svg></div>
            <div>
              <div class="exp-logistics-label">${escapeMessageHtml(item.label)}</div>
              <div class="exp-logistics-value">${escapeMessageHtml(item.value)}</div>
            </div>
          </div>
        `).join('')}
      </div>
    `;
    const refundPolicyHtml = exp.experience_refund_policy ? `
      <p style="font-size:12.5px; opacity:0.75; margin-top:6px; padding-top:14px; border-top:1px solid var(--line-dark);"><strong>If you don't reach the meeting point:</strong> ${escapeMessageHtml(exp.experience_refund_policy)}</p>
    ` : '';
    const logisticsHtml = `
      <div class="listing-modal-section-title">Good to Know</div>
      ${logisticsGridHtml}
      ${refundPolicyHtml}
    `;

    // A common meeting point has its own actual pinned location,
    // separate from the experience's own address — shown as its own
    // small map so a guest can see exactly where to go, not just read a
    // text description of it.
    const meetingPointMapHtml = (exp.experience_meeting_point_type === 'common_point' && exp.experience_meeting_point_lat && exp.experience_meeting_point_lng) ? `
      <div class="listing-modal-section-title">Meeting Point Map</div>
      <div class="listing-map-embed" id="expMeetingPointMapEmbed" style="aspect-ratio:16/9;"></div>
      <div style="margin-top:8px;">
        <a href="https://www.google.com/maps/search/?api=1&query=${exp.experience_meeting_point_lat},${exp.experience_meeting_point_lng}" target="_blank" rel="noopener" class="link" style="font-size:13px;">View on map</a>
      </div>
    ` : '';

    const instructionsHtml = exp.experience_instructions ? `
      <div class="listing-modal-section-title">Instructions</div>
      <p style="font-size:13.5px; line-height:1.8; opacity:0.85; white-space:pre-wrap;">${escapeMessageHtml(exp.experience_instructions)}</p>
    ` : '';

    // Kept visually distinct (its own bordered box, not just another
    // paragraph) since this is the kind of thing a guest specifically
    // needs to notice before booking, not casually skim past.
    const specialInstructionsHtml = exp.experience_special_instructions ? `
      <div class="listing-modal-section-title">Special Instructions</div>
      <div style="border:1px solid var(--line-dark); background:var(--cream-deep); padding:14px 16px; font-size:13px; line-height:1.7; opacity:0.9;">
        ${escapeMessageHtml(exp.experience_special_instructions)}
      </div>
    ` : '';

    const mapLinkHtml = (exp.latitude && exp.longitude)
      ? `<a href="https://www.google.com/maps/search/?api=1&query=${exp.latitude},${exp.longitude}" target="_blank" rel="noopener" class="link" style="font-size:13px;">View on map</a>`
      : '';

    // Same title-and-location-above, three-column-below structure the
    // listing detail page uses: booking on the left, photos + description
    // in the middle, map on the right. Logistics/Hosted-At/Address sit
    // below the grid, same as amenities/pet-policy do on the listing page.
    return `
      <div class="listing-modal-content">
        ${listingStandingHtml(exp, { type: 'experience', subtitle: [exp.experience_category, durationLine].filter(Boolean).join(' · '), withStay: exp.experience_type === 'with_stay' })}
        <div class="listing-three-col">
          <div class="listing-col-booking">
            ${bookStep(1, (exp.experience_duration_days && exp.experience_duration_days > 1) ? 'Choose the day it starts' : 'Choose your date')}
            <div class="field">
              <div id="expBookCalendar" data-min="${bookDateMin}" data-max="${bookDateMax || ''}">
                <p style="font-size:13px; opacity:0.6;">Loading calendar…</p>
              </div>
              <input type="hidden" id="expBookDate">
              <input type="hidden" id="expBookEndDate">
              ${availabilityNoteHtml}
            </div>
            ${bookStep(2, 'How many guests')}
            <div class="guest-row" style="padding-top:4px;">
              <div class="guest-row-text">
                <div class="guest-row-title">Guests</div>
                <div class="guest-row-sub">How many are joining</div>
              </div>
              <div class="guest-stepper">
                <button type="button" class="guest-step-btn" id="expGuestsDec" aria-label="Decrease guests">−</button>
                <span class="guest-count" id="expGuestsCount">1</span>
                <button type="button" class="guest-step-btn" id="expGuestsInc" aria-label="Increase guests">+</button>
              </div>
            </div>
            <p id="expFitWarning" style="display:none; font-size:12.5px; color:#a3402f; margin-top:8px;"></p>
            <div id="expPriceSummary" style="display:none;"></div>
            <div id="expBookingAction" style="margin-top:16px; padding-top:16px; border-top:1px solid var(--line-dark);">
              ${bookStep(4, 'Your details')}
              <p class="step-help">Your name and the number of guests go to your host; we send your confirmation to this email.</p>
              <div class="field">
                <label for="expBookFirstName">First name <span style="color:#a3402f;">*</span></label>
                <input id="expBookFirstName" type="text" placeholder="First name" autocomplete="given-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="expBookLastName">Last name <span style="color:#a3402f;">*</span></label>
                <input id="expBookLastName" type="text" placeholder="Last name" autocomplete="family-name" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="expBookEmail">Email <span style="color:#a3402f;">*</span></label>
                <input id="expBookEmail" type="email" placeholder="you@email.com" autocomplete="email" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="expBookPhone">Mobile number <span style="color:#a3402f;">*</span></label>
                <input id="expBookPhone" type="tel" placeholder="10-digit mobile number" autocomplete="tel" required>
              </div>
              <div class="field" style="margin-top:12px;">
                <label for="expCouponCode">Coupon code <span class="label-hint">${guestAuthToken() ? '(optional)' : '(optional — log in to use one)'}</span></label>
                <input id="expCouponCode" type="text" placeholder="e.g. AERVA-XXXXXXXXXX" style="text-transform:uppercase;">
                <p class="coupon-rule">Coupons cover the booking price only. Service fee, GST and any deposit are charged in full. Any unused coupon balance is not refunded.</p>
              </div>
              <button type="button" class="btn solid" id="expBookNowBtn" style="width:100%; margin-top:6px;">Continue to payment</button>
              ${PAY_NOTE_HTML}
              <p id="expBookError" class="offer" style="display:none; color:#a3402f; margin-top:10px;"></p>
              <p id="expBookConfirm" style="display:none; color:#3a7d44; font-size:13.5px; margin-top:10px; line-height:1.6;"></p>
            </div>
            <div class="listing-modal-price-row">
              <div><div class="price">${priceLine}</div></div>
            </div>
          </div>
          <div class="listing-col-photos">
            <div class="listing-modal-section-title" style="margin-top:16px;">Photos</div>
            ${photosHtml}
            <div class="listing-reviews" data-reviews-for="${exp.id}"></div>
            <p class="desc" style="margin-top:16px;">${escapeMessageHtml(exp.description)}</p>
          </div>
          <div class="listing-col-map">
            <div class="listing-modal-section-title" style="margin-top:16px;">Location</div>
            ${!exp.hosting_property_name && (exp.formatted_address || exp.city) ? `<p class="loc" style="margin-bottom:10px; text-transform:none; letter-spacing:normal; font-size:13px; opacity:0.8;">📍 ${escapeMessageHtml(exp.formatted_address || formatCityArea(exp))}</p>` : ''}
            ${(exp.latitude && exp.longitude) ? `
              <div class="listing-map-embed" id="expMapEmbed"></div>
              <div style="margin-top:8px;">${mapLinkHtml}</div>
            ` : `<p style="font-size:13px; opacity:0.6;">No location set for this experience yet.</p>`}
          </div>
        </div>
        ${logisticsHtml}
        ${meetingPointMapHtml}
        ${instructionsHtml}
        ${specialInstructionsHtml}
        ${hostingHtml}
      </div>
    `;
  }

  // A visual calendar for booking an experience — the same month grid as
  // stays. One tap picks the day: the host sets how long the experience
  // runs (experience_duration_days), so a multi-day experience shows its
  // end day worked out from that, exactly as the server prices and records
  // it (api/_pricing.js: one date in, the end from the host's duration).
  function expDurationDays(exp){
    return exp.experience_duration_days && Number(exp.experience_duration_days) > 1 ? Number(exp.experience_duration_days) : 1;
  }
  async function renderExpBookingCalendar(exp){
    const container = document.getElementById('expBookCalendar');
    if(!container) return;
    const minIso = container.dataset.min;
    const maxIso = container.dataset.max || null;
    const days = expDurationDays(exp);

    // A with_stay experience includes nights at a real property
    // (hosting_listing_id), one per day: that home's booked and blocked
    // nights make a start day unavailable when any of its nights is taken.
    const occupiedNights = new Set();
    if(exp.hosting_listing_id && exp.experience_type === 'with_stay'){
      try{
        const res = await fetch(SUITES_API_BASE + '/api/get-listings?availabilityFor=' + encodeURIComponent(exp.hosting_listing_id));
        if(res.ok){
          const data = await res.json();
          const ranges = [...(Array.isArray(data.bookedRanges) ? data.bookedRanges : []), ...(Array.isArray(data.blockedRanges) ? data.blockedRanges : [])];
          ranges.forEach(r => {
            if(r.arrival && r.departure) getNightsInRangeClient(r.arrival, r.departure).forEach(n => occupiedNights.add(n));
          });
        }
      } catch(err){
        console.error('Could not load linked stay availability:', err);
      }
    }

    // Days the host has closed on the experience itself (the server refuses
    // them, api/_pricing.js priceExperience): greyed out like any taken day.
    // Other guests' bookings do not close a day.
    try{
      const res = await fetch(SUITES_API_BASE + '/api/get-listings?availabilityFor=' + encodeURIComponent(exp.id));
      if(res.ok){
        const data = await res.json();
        (Array.isArray(data.blockedRanges) ? data.blockedRanges : []).forEach(r => {
          if(r.arrival && r.departure) getNightsInRangeClient(r.arrival, r.departure).forEach(n => occupiedNights.add(n));
        });
      }
    } catch(err){ /* the price check still refuses a closed day */ }

    let expStart = '';
    const minDateObj = new Date(minIso + 'T00:00:00');
    let viewYear = minDateObj.getFullYear();
    let viewMonth = minDateObj.getMonth();

    // Can the experience start on this day? Every one of its days must be
    // inside the host's window, and every included night free.
    function startAllowed(iso){
      if(iso < minIso) return false;
      const lastDay = aervaAddDays(iso, days - 1);
      if(maxIso && lastDay > maxIso) return false;
      return !getNightsInRangeClient(iso, aervaAddDays(iso, days)).some(n => occupiedNights.has(n));
    }

    function handleExpDayClick(iso){
      expStart = iso;
      document.getElementById('expBookDate').value = expStart;
      // Last day of the experience (inclusive), for display only.
      document.getElementById('expBookEndDate').value = aervaAddDays(expStart, days - 1);
      updateExperiencePriceSummary(exp);
      renderMonth();
    }

    function renderMonth(){
      const firstDay = new Date(viewYear, viewMonth, 1);
      const startWeekday = firstDay.getDay();
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const isMinMonth = viewYear === minDateObj.getFullYear() && viewMonth === minDateObj.getMonth();
      const maxDateObj = maxIso ? new Date(maxIso + 'T00:00:00') : null;
      const isMaxMonth = maxDateObj && viewYear === maxDateObj.getFullYear() && viewMonth === maxDateObj.getMonth();
      const endIso = expStart ? aervaAddDays(expStart, days - 1) : '';

      let cellsHtml = '';
      for(let i = 0; i < startWeekday; i++) cellsHtml += '<div class="calendar-day empty"></div>';
      for(let day = 1; day <= daysInMonth; day++){
        const iso = toLocalDateStr(new Date(viewYear, viewMonth, day));
        let classes = 'calendar-day';
        if(!startAllowed(iso)) classes += ' disabled';
        if(iso === expStart || (days > 1 && iso === endIso)) classes += ' selected-start';
        else if(expStart && days > 1 && iso > expStart && iso < endIso) classes += ' in-range';
        cellsHtml += `<div class="${classes}" data-exp-date="${iso}">${day}</div>`;
      }

      const fmtDay = (iso, withYear) => new Date(iso + 'T00:00:00').toLocaleDateString('en-IN', withYear ? { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' } : { weekday: 'short', month: 'short', day: 'numeric' });
      const noteHtml = expStart
        ? `<p style="font-size:12px; margin-top:10px;"><strong>${days > 1 ? `${fmtDay(expStart)} – ${fmtDay(endIso, true)} (${days} days)` : fmtDay(expStart, true)}</strong></p>`
        : `<p style="font-size:11.5px; opacity:0.6; margin-top:10px;">${days > 1 ? `Tap the day it starts. It runs for ${days} days.` : 'Tap a day to see the price.'}</p>`;

      container.innerHTML = `
        <div class="calendar-month-panel" style="max-width:320px; padding:0;">
          <div class="calendar-month-header">
            <button type="button" class="cal-nav" id="expCalPrev" aria-label="Previous month" ${isMinMonth ? 'disabled' : ''}>‹</button>
            <div class="calendar-month-label">${MONTH_NAMES[viewMonth]} ${viewYear}</div>
            <button type="button" class="cal-nav" id="expCalNext" aria-label="Next month" ${isMaxMonth ? 'disabled' : ''}>›</button>
          </div>
          <div class="calendar-weekdays">
            <span>S</span><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span>
          </div>
          <div class="calendar-grid">${cellsHtml}</div>
          ${noteHtml}
        </div>
      `;

      document.getElementById('expCalPrev').addEventListener('click', () => {
        viewMonth -= 1;
        if(viewMonth < 0){ viewMonth = 11; viewYear -= 1; }
        renderMonth();
      });
      document.getElementById('expCalNext').addEventListener('click', () => {
        viewMonth += 1;
        if(viewMonth > 11){ viewMonth = 0; viewYear += 1; }
        renderMonth();
      });
      container.querySelectorAll('.calendar-day:not(.disabled):not(.empty)').forEach(cell => {
        aervaDayCellA11y(cell, 'data-exp-date');
        cell.addEventListener('click', (e) => {
          e.stopPropagation();
          handleExpDayClick(cell.dataset.expDate);
        });
      });
    }

    renderMonth();
  }

  // The most guests an experience takes: its own max_guests when the host
  // set one, otherwise 50 — the same limit the server applies.
  function expGuestCap(exp){ return aervaParseMaxGuests(exp.max_guests) || 50; }

  // The total shown is the server's own price (create-order.js, quoteOnly):
  // the experience, any offer, and — for one that includes a stay — the
  // nights at the home, with GST, the guest service fee and any deposit.
  function updateExperiencePriceSummary(exp){
    const summaryEl = document.getElementById('expPriceSummary');
    const fitWarningEl = document.getElementById('expFitWarning');
    if(!summaryEl) return;
    if(fitWarningEl) fitWarningEl.style.display = 'none';
    const guests = Number(document.getElementById('expGuestsCount').textContent) || 1;
    const startDate = document.getElementById('expBookDate') ? document.getElementById('expBookDate').value : '';
    if(!exp.price || !startDate){
      aervaQuoteSeq.experience = (aervaQuoteSeq.experience || 0) + 1;
      summaryEl.style.display = 'none';
      return;
    }
    summaryEl.innerHTML = `
      ${bookStep(3, 'Check your total')}
      <div class="quote-body"><p style="font-size:12.5px; opacity:0.6;">Working out your total…</p></div>
      <p style="font-size:12px; opacity:0.75; margin-top:10px; padding-top:10px; border-top:1px solid var(--line-dark);"><strong>Cancellation:</strong> ${cancellationPolicyText(exp.cancellation_policy)}</p>
    `;
    summaryEl.style.display = 'block';
    const quoteBody = summaryEl.querySelector('.quote-body');
    aervaQuote('experience', { experiences: [{ listingId: exp.id, date: startDate, guests }] }).then(q => {
      if(q && quoteBody.isConnected) quoteBody.innerHTML = aervaQuoteBodyHtml(q);
    }).catch(err => { if(quoteBody.isConnected) quoteBody.innerHTML = aervaQuoteErrorHtml(err); });
  }

  async function handleExperienceBookNow(exp){
    const errorEl = document.getElementById('expBookError');
    const confirmEl = document.getElementById('expBookConfirm');
    const btn = document.getElementById('expBookNowBtn');
    errorEl.style.display = 'none';
    errorEl.style.color = '#a3402f';
    confirmEl.style.display = 'none';

    if(!guestAuthToken()){
      requireLoginForBooking(() => handleExperienceBookNow(exp));
      return;
    }
    if(aervaProfilePromptFirst(() => handleExperienceBookNow(exp))) return;

    // One date: the day it starts. The end comes from the host's own
    // duration, on the server as on this page.
    const date = document.getElementById('expBookDate').value;
    if(!date){
      errorEl.textContent = 'Please choose a date first.';
      errorEl.style.display = 'block';
      return;
    }
    const email = document.getElementById('expBookEmail').value.trim();
    if(!email || !email.includes('@')){
      errorEl.textContent = 'Please enter a valid email address.';
      errorEl.style.display = 'block';
      return;
    }
    // The number exactly as typed goes to the server, which saves it to the
    // account if it has none (create-order.js); Razorpay gets the digits.
    const phoneTyped = document.getElementById('expBookPhone').value.trim();
    const phone = phoneTyped.replace(/\D/g, '');
    if(!phone || phone.length < 10){
      errorEl.textContent = 'Please enter a valid mobile number.';
      errorEl.style.display = 'block';
      return;
    }
    const guests = Number(document.getElementById('expGuestsCount').textContent) || 1;

    btn.disabled = true;
    btn.textContent = 'Preparing payment…';

    let order;
    try{
      const orderRes = await fetch(API_BASE + '/api/create-order', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
        body: JSON.stringify({
          experiences: [{ listingId: exp.id, date, guests }],
          email,
          preferredCurrency: currentCurrency,
          couponCode: document.getElementById('expCouponCode').value.trim() || undefined,
          pricesSeen: aervaPricesSeen([exp]),
          phone: phoneTyped,
          firstName: (document.getElementById('expBookFirstName') || {}).value,
          lastName: (document.getElementById('expBookLastName') || {}).value
        })
      });
      if(!orderRes.ok){
        const errData = await orderRes.json().catch(() => ({}));
        if(errData.priceChanged){
          aervaShowPriceChange(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment';
          return;
        }
        if(Array.isArray(errData.needs) && errData.needs.length){
          if(errData.needs.includes('name')){ errorEl.textContent = errData.error; errorEl.style.display = 'block'; }
          else aervaShowNeeds(errorEl, errData, btn);
          btn.disabled = false; btn.textContent = 'Continue to payment';
          return;
        }
        throw new Error(errData.error || 'We could not start your payment. Please try again.');
      }
      order = await orderRes.json();
      if(order.couponDiscount > 0){
        confirmEl.textContent = `Coupon applied: ${moneyBoth(order.couponDiscount)} off the booking price. Service fee and GST are charged in full.`
          + (order.couponForfeited > 0 ? ` ${moneyBoth(order.couponForfeited)} of the coupon is unused and is not refunded.` : '');
        confirmEl.style.display = 'block';
      }
    } catch(err){
      btn.disabled = false;
      btn.textContent = 'Continue to payment';
      errorEl.textContent = err.message || 'We could not start your payment. Please try again.';
      errorEl.style.display = 'block';
      return;
    }

    btn.disabled = false;
    btn.textContent = 'Continue to payment';

    if(typeof Razorpay === 'undefined'){
      errorEl.textContent = 'Payment gateway did not load. Please check your connection and try again.';
      errorEl.style.display = 'block';
      return;
    }
    if(!order.keyId){
      aervaReleaseHold(order.orderId, 'closed');
      errorEl.textContent = 'Payment is not available right now. Nothing has been charged. Please try again in a few minutes.';
      errorEl.style.display = 'block';
      return;
    }

    const options = {
      key: order.keyId,
      order_id: order.orderId,
      timeout: (order && order.holdSeconds) || undefined, // Razorpay closes its window when the payment window ends
      amount: order.amount,
      currency: order.currency,
      name: 'Aerva',
      description: exp.property_name,
      prefill: { email, contact: phone },
      theme: { color: '#a9884f' },
      config: {
        display: { sequence: ['upi', 'card', 'netbanking', 'wallet'], preferences: { show_default_blocks: true } }
      },
      handler: async function(response){
        aervaCheckoutSucceeded();
        try{
          const verifyRes = await fetch(API_BASE + '/api/verify-payment', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(response)
          });
          const verifyData = await verifyRes.json();
          aervaShowPaymentResult(verifyData, { confirmEl, errorEl, btn });
        } catch(err){
          aervaShowPaymentResult({ pending: true, message: 'Your payment was received, but we could not confirm the booking on this page. We will email you within a few minutes — please do not pay again. Payment ID: ' + response.razorpay_payment_id }, { confirmEl, errorEl, btn });
        }
      },
      modal: { ondismiss: function(){ aervaEndCheckout('closed'); } }
    };

    const rzp = new Razorpay(options);
    rzp.on('payment.failed', function(response){ aervaEndCheckout('failed'); });
    rzp.open();
    // An experience on its own holds no dates from anyone else.
    aervaWatchCheckout(rzp, order, errorEl, { holdsDates: exp.experience_type === 'with_stay' });
  }

  // Opens the experience's detail view inline, as a modal — same shell
  // as openListingDetail uses for stays, same booking widget wiring as
  // showExperienceDetailPage (the standalone page, still used for direct
  // ?experience=<id> links) — just inserted into the modal instead of
  // swapping the whole page out, so a click from search results shows
  // the calendar/photos/booking immediately with no extra navigation.
  function openExperienceDetail(experienceId){
    const exp = experiencesById[experienceId];
    if(!exp) return;
    trackRecentlyViewed('experience', experienceId);
    document.getElementById('listingModalBody').innerHTML = buildExperienceDetailHtml(exp);
    document.getElementById('listingModalOverlay').style.display = 'flex';
    document.body.style.overflow = 'hidden';
    loadListingReviews(document.getElementById('listingModalBody'), exp.id);

    const mapEl = document.getElementById('expMapEmbed');
    if(mapEl && exp.latitude && exp.longitude){
      initListingMapEmbed(mapEl, exp.latitude, exp.longitude, exp.property_name);
    }
    const meetingMapEl = document.getElementById('expMeetingPointMapEmbed');
    if(meetingMapEl && exp.experience_meeting_point_lat && exp.experience_meeting_point_lng){
      initListingMapEmbed(meetingMapEl, exp.experience_meeting_point_lat, exp.experience_meeting_point_lng, 'Meeting Point');
    }

    const guestsCountEl = document.getElementById('expGuestsCount');
    document.getElementById('expGuestsDec').addEventListener('click', () => {
      const next = Math.max(1, Number(guestsCountEl.textContent) - 1);
      guestsCountEl.textContent = next;
      updateExperiencePriceSummary(exp);
    });
    document.getElementById('expGuestsInc').addEventListener('click', () => {
      const next = Math.min(expGuestCap(exp), Number(guestsCountEl.textContent) + 1);
      guestsCountEl.textContent = next;
      updateExperiencePriceSummary(exp);
    });
    renderExpBookingCalendar(exp);
    document.getElementById('expBookNowBtn').addEventListener('click', () => handleExperienceBookNow(exp));
    updateExperiencePriceSummary(exp);
    aervaPrefillBooking();
  }

  function showExperienceDetailPage(exp){
    if(exp && hiddenListingIds.has(Number(exp.id))){ alert('This experience is not available.'); return; }
    trackRecentlyViewed('experience', exp.id);
    document.body.classList.remove('showing-hero');
    document.getElementById('suites').style.display = 'none';
    const expSection = document.getElementById('experiences');
    if(expSection) expSection.style.display = 'none';
    document.getElementById('experienceFullViewBody').innerHTML = buildExperienceDetailHtml(exp);
    document.getElementById('experienceFullView').style.display = 'block';
    document.title = exp.property_name + ' — Aerva';
    // The header tab shows where this page belongs.
    const suitesTab = document.getElementById('catSuites');
    const expTab = document.getElementById('catExperience');
    if(suitesTab) suitesTab.classList.remove('active');
    if(expTab) expTab.classList.add('active');

    const mapEl = document.getElementById('expMapEmbed');
    if(mapEl && exp.latitude && exp.longitude){
      initListingMapEmbed(mapEl, exp.latitude, exp.longitude, exp.property_name);
    }
    const meetingMapEl = document.getElementById('expMeetingPointMapEmbed');
    if(meetingMapEl && exp.experience_meeting_point_lat && exp.experience_meeting_point_lng){
      initListingMapEmbed(meetingMapEl, exp.experience_meeting_point_lat, exp.experience_meeting_point_lng, 'Meeting Point');
    }

    const guestsCountEl = document.getElementById('expGuestsCount');
    document.getElementById('expGuestsDec').addEventListener('click', () => {
      const next = Math.max(1, Number(guestsCountEl.textContent) - 1);
      guestsCountEl.textContent = next;
      updateExperiencePriceSummary(exp);
    });
    document.getElementById('expGuestsInc').addEventListener('click', () => {
      const next = Math.min(expGuestCap(exp), Number(guestsCountEl.textContent) + 1);
      guestsCountEl.textContent = next;
      updateExperiencePriceSummary(exp);
    });
    renderExpBookingCalendar(exp);
    document.getElementById('expBookNowBtn').addEventListener('click', () => handleExperienceBookNow(exp));
    updateExperiencePriceSummary(exp);
    aervaPrefillBooking();
  }
  // Smooth in-page return instead of a full reload — the plain
  // href="index.html"/"index.html?view=experiences" fallback still
  // works (e.g. JS disabled, or arriving here via a direct shared link
  // with no prior browse state to return to), but for the common case
  // of a guest browsing, opening a listing, then going back, a full
  // page reload was a jarring way to do something this simple, and lost
  // whatever search/filter state they had going.
  document.getElementById('listingFullViewBackLink').addEventListener('click', (e) => {
    e.preventDefault();
    document.getElementById('listingFullView').style.display = 'none';
    document.getElementById('suites').style.display = 'block';
    document.body.classList.add('showing-hero');
    document.title = 'Aerva — Stay Elegant';
    resetSeoMeta();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
  document.getElementById('experienceFullViewBackLink').addEventListener('click', (e) => {
    e.preventDefault();
    document.getElementById('experienceFullView').style.display = 'none';
    document.getElementById('suites').style.display = 'block';
    const expSection = document.getElementById('experiences');
    if(expSection) expSection.style.display = 'none';
    document.body.classList.add('showing-hero');
    document.title = 'Aerva — Stay Elegant';
    resetSeoMeta();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  // ---- One booking ----
  // Opened from My Bookings. Everything about that stay in one place: the
  // dates and what was paid, where it is, and what other guests have said
  // — rather than a line in a list with two buttons on it.
  function showBookingPage(b){
    const esc = escapeMessageHtml;
    document.body.classList.remove('showing-hero');
    hideMainViews();
    document.getElementById('bookingView').style.display = 'block';
    document.title = (b.suite_name || 'Your booking') + ' — Aerva';
    window.scrollTo({ top: 0 });

    const listing = listingsById[b.listing_id] || null;
    // Dates are calendar days ('YYYY-MM-DD'); read them as local dates so
    // they never shift a day in another timezone.
    const asDate = (d) => { const s = String(d || '').slice(0, 10); const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : (d ? new Date(d) : null); };
    const day = (d) => { const x = asDate(d); return x ? x.toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }) : '—'; };
    const isExp = b.listing_type === 'experience';
    // Shown in the guest's currency; what was actually charged (in rupees)
    // is stated under the total whenever the two differ.
    showBookingPage._last = b;
    const inr = (v) => guestPrice(v);
    const inrExact = (v) => '₹' + Math.round(Number(v) || 0).toLocaleString('en-IN');
    const num = (v) => Math.max(0, Math.round(Number(v) || 0));
    const isCompleted = b.status === 'paid' && b.local_today && String(b.departure).slice(0, 10) < String(b.local_today).slice(0, 10);
    const place = b.listing_city ? (b.listing_area && b.listing_area !== b.listing_city ? `${b.listing_area}, ${b.listing_city}` : b.listing_city) : (listing ? formatCityArea(listing) : '');

    // ---- Price details (adds up to what was charged) ----
    const subtotal = num(b.subtotal), gst = num(b.gst), fee = num(b.guest_service_fee), deposit = num(b.deposit_amount);
    const transferFee = Math.min(fee, num(b.transfer_fee)); // inside guest_service_fee on a transferred part
    const coupon = num(b.coupon_discount), discount = num(b.discount_amount);
    const freeCancel = num(b.free_cancel_fee), freeCancelGst = num(b.free_cancel_gst);
    const paid = Math.max(0, (num(b.total) || subtotal + gst + fee + deposit + freeCancel + freeCancelGst) - coupon);
    const unit = isExp ? `${b.guests || 1} guest${Number(b.guests) === 1 ? '' : 's'}` : `${b.nights || 1} night${Number(b.nights) === 1 ? '' : 's'}`;
    const depositWord = { held: 'held', refunding: 'being refunded', refunded: 'refunded', disputed: 'under review', resolving: 'being settled', resolved: 'settled' }[b.deposit_status] || '';
    const priceRows = [
      [`${isExp ? 'Experience' : 'Stay'} · ${unit}`, inr(subtotal + discount)],
      discount ? ['Offer applied', '−' + inr(discount)] : null,
      freeCancel ? [`Free cancellation${b.free_cancel_until_label ? ` <em>(full refund until ${esc(b.free_cancel_until_label)})</em>` : ''}`, inr(freeCancel)] : null,
      fee - transferFee ? ['Guest service fee', inr(fee - transferFee)] : null,
      transferFee ? ['Aerva transfer fee', inr(transferFee)] : null,
      gst + freeCancelGst ? ['GST', inr(gst + freeCancelGst)] : null,
      deposit ? [`Refundable security deposit${depositWord ? ` <em>(${esc(depositWord)})</em>` : ''}`, inr(deposit)] : null,
      coupon ? ['Aerva coupon', '−' + inr(coupon)] : null
    ].filter(Boolean);
    const refund = b.refunded && b.refunded.amount > 0 ? b.refunded : null;

    // ---- Booking details ----
    const guestName = [b.guest_first_name, b.guest_last_name].filter(Boolean).join(' ');
    const policy = b.cancellation_policy || b.listing_cancellation_policy;
    // A confirmed group booking is non-refundable, whatever the listing's policy (_cancellations.js groupNoRefund).
    const policyName = b.group ? 'Non-refundable group booking' : isExp ? 'Experience policy' : policy === 'firm' ? 'Firm' : policy === 'flexible' ? 'Flexible' : '';
    const policyDoc = b.group ? 'gift-group-bookings' : isExp ? 'cancellation-experiences' : 'cancellation-stays';
    const bookedOn = b.created_at ? new Date(b.created_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
    const pets = Array.isArray(b.pet_types) ? b.pet_types.length : 0;
    const address = b.listing_address || (listing && listing.formatted_address) || '';
    const detailRows = [
      guestName ? ['Booked for', esc(guestName)] : null,
      b.guest_email ? ['Confirmation sent to', esc(b.guest_email)] : null,
      b.host_name ? ['Host', esc(b.host_name)] : null,
      bookedOn ? ['Booked on', esc(bookedOn)] : null,
      policyName ? ['Refund policy', `${esc(policyName)} · <a href="index.html?view=policies&doc=${policyDoc}" target="_blank" rel="noopener">Read it</a>`] : null,
      b.razorpay_payment_id ? ['Payment ID', `<code>${esc(b.razorpay_payment_id)}</code>`] : null,
      b.razorpay_order_id ? ['Booking reference', `<code>${esc(b.razorpay_order_id)}</code>`] : null
    ].filter(Boolean);

    const facts = isExp
      ? [['Date', esc(day(b.arrival))],
         b.experience_start_time ? ['Starts at', esc(b.experience_start_time)] : null,
         b.experience_duration_hours ? ['Duration', `${esc(String(Number(b.experience_duration_hours)))} hour${Number(b.experience_duration_hours) === 1 ? '' : 's'}`] : null,
         ['Guests', String(b.guests || 1)]]
      : [['Check-in', `${esc(day(b.arrival))}${b.check_in_time ? `<small>from ${esc(b.check_in_time)}</small>` : ''}`],
         ['Check-out', `${esc(day(b.departure))}${b.check_out_time ? `<small>by ${esc(b.check_out_time)}</small>` : ''}`],
         ['Nights', String(b.nights || '—')],
         ['Guests', `${b.guests || 1}${pets ? `<small>+ ${pets} pet${pets === 1 ? '' : 's'}</small>` : ''}`]];

    const actions = [];
    if(b.status === 'paid' || b.status === 'cancelled'){
      actions.push(`<button type="button" class="filter-clear" id="bkMessage">${b.status === 'paid' && !isCompleted ? 'Message host' : 'View messages'}</button>`);
    }
    if(b.review_state === 'open') actions.push('<button type="button" class="filter-clear" id="bkReview">Leave a review</button>');
    if(listing) actions.push('<button type="button" class="filter-clear" id="bkListing">View the listing</button>');
    actions.push('<button type="button" class="filter-clear" id="bkPrint">Print or save as PDF</button>');

    document.getElementById('bookingViewBody').innerHTML = `
      <p class="bk-eyebrow">Booking summary</p>
      <h2 class="bk-title">${esc(b.suite_name || 'Your booking')}</h2>
      <p class="bk-sub"><span class="bk-status is-${esc(isCompleted ? 'completed' : b.status)}">${esc(statusWordGuest(isCompleted ? 'completed' : b.status))}</span>${place ? `<span class="bk-place">${esc(place)}</span>` : ''}</p>
      ${b.status === 'cancelled' || b.status === 'refunded' ? `<div class="bk-cancelled">This booking was cancelled${b.cancelled_at ? ` on ${esc(new Date(b.cancelled_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }))}` : ''}.${b.cancellation_reason ? ` Reason: ${esc(b.cancellation_reason)}.` : ''}${refund ? ` ${inr(refund.amount)} ${refund.pending ? 'is being refunded' : 'was refunded'} ${b.group ? 'to the people who paid, each to their own payment method' : 'to your original payment method'}.` : ''}</div>` : ''}
      ${b.confirmation_code && b.status === 'paid' ? `<div class="confirm-code bk-code" title="Show this at check-in"><span class="confirm-code-label">Confirmation code</span><span class="confirm-code-value">${esc(b.confirmation_code)}</span><button type="button" class="confirm-code-copy" id="bkCopyCode">Copy</button><span class="bk-code-hint">Show this to your host at ${isExp ? 'the start' : 'check-in'}</span></div>` : ''}
      <div class="bk-facts">${facts.filter(Boolean).map(([k, v]) => `<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>
      ${isExp && (b.meeting_point_address || b.meeting_point_details) ? `<p class="bk-note bk-meet"><strong>Meeting point:</strong> ${esc(b.meeting_point_address || '')}${b.meeting_point_details ? ` — ${esc(b.meeting_point_details)}` : ''}</p>` : ''}
      <div class="bk-actions">${actions.join('')}</div>
      ${aervaPromiseSummaryHtml(b, inr)}
      <div class="bk-summary">
        <div class="bk-card">
          <h3>Price details</h3>
          ${priceRows.map(([k, v]) => `<div class="bk-row"><span>${k}</span><span>${v}</span></div>`).join('')}
          <div class="bk-row bk-total"><span>${b.group ? 'Total paid by the group' : 'Total paid'}${b.charge_currency && b.charge_currency !== 'INR' ? ` <em>(charged in ${esc(b.charge_currency)})</em>` : ''}</span><span>${inr(paid)}</span></div>
          ${b.group && b.group.myPaid ? `<div class="bk-row"><span>Your own share (${Number(b.group.myPlaces) || 0} of ${Number(b.group.places) || 0} places)</span><span>${inr(b.group.myPaid)}</span></div>` : ''}
          ${refund ? `<div class="bk-row bk-refund"><span>${refund.pending ? 'Refund in progress' : 'Refunded'}${b.group ? ' (to each payer)' : ''}</span><span>−${inr(refund.amount)}</span></div>` : ''}
          ${currentCurrency !== 'INR' && fmtGuest(paid) !== inrExact(paid) ? `<p class="bk-fx-note" style="font-size:12px; opacity:0.65; margin:10px 0 0;">Charged in Indian Rupees: ${inrExact(paid)}${refund ? `; ${refund.pending ? 'being refunded' : 'refunded'}: ${inrExact(refund.amount)}` : ''}. Amounts above are shown in ${esc(currentCurrency)} at today's rate.</p>` : ''}
        </div>
        <div class="bk-card">
          <h3>Booking details</h3>
          ${detailRows.map(([k, v]) => `<div class="bk-row"><span>${k}</span><span>${v}</span></div>`).join('')}
        </div>
      </div>
      <div class="bk-cols">
        <div>
          <div class="listing-modal-section-title" style="margin-top:0;">Where it is</div>
          ${listing && listing.latitude && listing.longitude
            ? `<div class="bk-map" id="bkMap"></div>
               <p class="bk-note" style="margin-top:8px;">${esc(listing.formatted_address || formatCityArea(listing))}</p>`
            : `<p class="bk-note">${address || place ? esc(address || place) : 'This listing is no longer published on Aerva, so its map and reviews are not available.'}</p>`}
        </div>
        <div>
          ${listing ? `<div class="listing-reviews" data-reviews-for="${Number(b.listing_id)}"></div>` : ''}
        </div>
      </div>`;

    const msgBtn = document.getElementById('bkMessage');
    if(msgBtn) msgBtn.addEventListener('click', () => openChatForOrder(Number(b.id), b.suite_name || ''));
    const copyBtn = document.getElementById('bkCopyCode');
    if(copyBtn) copyBtn.addEventListener('click', async () => {
      try{ await navigator.clipboard.writeText(b.confirmation_code); copyBtn.textContent = 'Copied'; setTimeout(() => { copyBtn.textContent = 'Copy'; }, 1500); }
      catch(err){ copyBtn.textContent = b.confirmation_code; }
    });
    const printBtn = document.getElementById('bkPrint');
    if(printBtn) printBtn.addEventListener('click', () => {
      document.body.classList.add('printing-booking');
      const done = () => { document.body.classList.remove('printing-booking'); window.removeEventListener('afterprint', done); };
      window.addEventListener('afterprint', done);
      window.print();
    });
    const revBtn = document.getElementById('bkReview');
    if(revBtn) revBtn.addEventListener('click', () => openReviewModal(b));
    const lstBtn = document.getElementById('bkListing');
    if(lstBtn) lstBtn.addEventListener('click', () => {
      document.getElementById('bookingView').style.display = 'none';
      if(isExp) showExperienceDetailPage(listing); else showFullListingPage(listing);
    });
    if(listing){
      loadListingReviews(document.getElementById('bookingViewBody'), b.listing_id);
      if(listing.latitude && listing.longitude){
        initListingMapEmbed(document.getElementById('bkMap'), listing.latitude, listing.longitude, listing.property_name);
      }
    }
  }

  function statusWordGuest(status){
    return status === 'paid' ? 'Confirmed' : status === 'completed' ? 'Completed' : status === 'cancelled' ? 'Cancelled' : status === 'refunded' ? 'Refunded' : String(status || '');
  }

  // ---- Profile ----
  // Every full-page view on index.html. Switching views hides ALL of them
  // first, from this one list — each view used to keep its own list, and
  // Today's had left out the profile, so Today "did nothing" when clicked
  // from the profile (it opened underneath it, out of sight).
  const MAIN_VIEW_IDS = ['suites', 'bookingView', 'profileView', 'todayView', 'listingFullView',
    'experienceFullView', 'add-listing', 'list-experience', 'my-bookings', 'wishlistView', 'settingsView', 'policiesView', 'privacyView', 'termsView', 'helpView', 'groupGiftView'];

  // ---- Agreements shown before payment and before listing ----
  // The guest booking agreement sits directly above every Book button; the
  // host agreement above every "Submit for review" button. Nothing is sent
  // until its box is ticked: the booking/listing request itself is checked
  // on its way out (below), and the server refuses it without the current
  // version too (create-order.js, submit-listing.js). Text and version come
  // from aerva-policies.js, the same source as the Policies page.
  const BOOKING_BUTTONS = '#listingBookNowBtn, #resortBookNowBtn, #expBookNowBtn, #groupPayBtn';
  const LISTING_BUTTONS = '#listingSubmitBtn, #expSubmitBtn';
  function agreementBoxHtml(kind){
    const A = window.AERVA_POLICIES && window.AERVA_POLICIES.agreements;
    if(!A || !A[kind]) return '';
    const a = A[kind];
    const esc = escapeMessageHtml;
    const body = a.clauses
      ? `<div class="agreement-scroll">${a.intro ? `<p class="agreement-intro">${esc(a.intro)}</p>` : ''}${a.clauses.map(c => `<div class="agreement-clause"><div class="agreement-clause-title">${esc(c.title)}</div><ul>${c.points.map(p => `<li>${esc(p)}</li>`).join('')}</ul></div>`).join('')}</div>`
      : `<ul>${a.points.map(p => `<li>${esc(p)}</li>`).join('')}</ul>`;
    const rules = kind === 'guest' && Array.isArray(A.beforeYouPay) && A.beforeYouPay.length
      ? `<div class="agreement-rules" style="margin:0 0 10px; padding:10px 12px; border:1px solid #c9a96a; border-radius:8px; background:#fbf6ec;">
          <div style="font-weight:600; margin-bottom:4px;">Before you pay: what you can and cannot do</div>
          <ul style="margin:0; padding-left:18px; font-size:13.5px; line-height:1.55;">${A.beforeYouPay.map(p => `<li>${esc(p)}</li>`).join('')}</ul></div>` : '';
    return `<div class="agreement-box" data-agreement="${kind}">
      ${rules}
      <div class="agreement-title">${esc(a.title)}${kind === 'host' && A.hostVersion ? ` <span class="agreement-version">version ${esc(A.hostVersion)}</span>` : ''}</div>
      ${body}
      <label class="agreement-accept"><input type="checkbox" class="agreement-check"> <span>${esc(a.accept)}</span></label>
      <a class="agreement-link" href="index.html?view=policies${kind === 'host' ? '&doc=host-agreement' : ''}" target="_blank" rel="noopener">${kind === 'host' ? 'Open the Host Agreement in a new tab' : 'Read Aerva’s Policies'}</a>
    </div>`;
  }
  function mountAgreements(root){
    (root || document).querySelectorAll(BOOKING_BUTTONS + ', ' + LISTING_BUTTONS).forEach(btn => {
      const prev = btn.previousElementSibling;
      if(prev && prev.classList && prev.classList.contains('agreement-box')) return;
      const kind = btn.matches(LISTING_BUTTONS) ? 'host' : 'guest';
      const html = agreementBoxHtml(kind);
      if(html) btn.insertAdjacentHTML('beforebegin', html);
    });
  }
  mountAgreements();
  new MutationObserver(() => mountAgreements()).observe(document.body, { childList: true, subtree: true });

  // Which button started this request: its box is the one that must be ticked.
  let lastAgreementButton = null;
  document.addEventListener('click', function(e){
    const b = e.target.closest && e.target.closest(BOOKING_BUTTONS + ', ' + LISTING_BUTTONS);
    if(b) lastAgreementButton = b;
  }, true);
  function agreementTicked(btn){
    const box = btn && btn.previousElementSibling;
    const check = box && box.classList && box.classList.contains('agreement-box') ? box.querySelector('.agreement-check') : null;
    return !!(check && check.checked);
  }
  (function guardRequests(){
    const originalFetch = window.fetch ? window.fetch.bind(window) : null;
    if(!originalFetch) return;
    // A plain response-like object (not `new Response`, which some
    // environments lack) — so a missing tick can never slip through.
    const refuse = (msg) => {
      const bodyText = JSON.stringify({ error: msg });
      const res = { ok: false, status: 400, statusText: 'Bad Request', headers: { get: () => 'application/json' },
        json: async () => JSON.parse(bodyText), text: async () => bodyText };
      res.clone = () => res;
      return Promise.resolve(res);
    };
    window.fetch = function(input, init){
      try{
        const url = typeof input === 'string' ? input : (input && input.url) || '';
        const isOrderApi = url.indexOf('/api/create-order') !== -1;
        const isListing = url.indexOf('/api/submit-listing') !== -1;
        if((isOrderApi || isListing) && init && typeof init.body === 'string'){
          const body = JSON.parse(init.body);
          // Only an actual booking needs the agreement: a request that pays
          // for stays or experiences. Price quotes, the payment-window
          // checks, releasing a hold and paying for an accepted change all
          // use the same endpoint and pass straight through.
          const hasItems = (Array.isArray(body.stays) && body.stays.length > 0) || (Array.isArray(body.experiences) && body.experiences.length > 0);
          const isBooking = isOrderApi && hasItems && !body.quoteOnly;
          if(isOrderApi && !isBooking) return originalFetch(input, init);
          // Sorting photos ("Add all your photos") submits nothing.
          if(isListing && body.sortPhotos) return originalFetch(input, init);
          const version = window.AERVA_POLICIES && window.AERVA_POLICIES.agreements && window.AERVA_POLICIES.agreements.version;
          if(isBooking){
            if(!agreementTicked(lastAgreementButton)) return refuse('Please tick the booking agreement to continue.');
            body.agreementVersion = version;
          } else if(!body.isDraft){
            if(!agreementTicked(lastAgreementButton)) return refuse('Please tick the host agreement to submit.');
            body.hostAgreementVersion = (window.AERVA_POLICIES.agreements.hostVersion || version);
          }
          init = Object.assign({}, init, { body: JSON.stringify(body) });
        }
      }catch(e){ /* anything odd: send it as it was; the server still checks */ }
      return originalFetch(input, init);
    };
  })();

  // ---- Policy Center (index.html?view=policies[&doc=<id>]) ----
  // The list of documents, or one document on its own. Text comes from
  // aerva-policies.js (the same file the admin tool shows).
  const POLICY_DOC_LINK = (id) => `index.html?view=policies&doc=${encodeURIComponent(id)}`;
  function policyDocs(){
    const P = window.AERVA_POLICIES || {};
    const A = P.agreements || {};
    return [
      { id: 'terms', title: 'Terms of Service', summary: 'The terms that apply to everyone who uses Aerva.', href: 'index.html?view=terms' },
      { id: 'privacy', title: 'Privacy Policy', summary: 'What information Aerva collects and how it is used.', href: 'index.html?view=privacy' },
      A.guest ? { id: 'booking-agreement', title: A.guest.title, summary: 'The agreement every guest accepts before paying.', sections: [{ title: A.guest.title + ' (version ' + A.version + ')', points: A.guest.points }] } : null,
      A.host ? { id: 'host-agreement', title: A.host.title, summary: 'The agreement every host accepts for each listing.',
        sections: A.host.clauses ? [{ title: A.host.title + ' (version ' + (A.hostVersion || A.version) + ')', points: [A.host.intro] }].concat(A.host.clauses) : [{ title: A.host.title + ' (version ' + A.version + ')', points: A.host.points }] } : null
    ].filter(Boolean).concat(P.documents || []);
  }
  function renderPolicies(docId){
    const P = window.AERVA_POLICIES;
    const body = document.getElementById('policiesBody');
    if(!P || !body) return;
    const esc = escapeMessageHtml;
    const docs = policyDocs();
    const doc = docId ? docs.find(d => d.id === docId && d.sections) : null;
    document.getElementById('policiesUpdated').textContent = 'Last updated ' + P.updated;
    if(doc){
      document.getElementById('policiesTitle').textContent = doc.title;
      document.title = doc.title + ' — Aerva';
      body.innerHTML = `<p class="policy-back"><a href="index.html?view=policies">‹ All policies</a></p>`
        + doc.sections.map(sec => `
          <div class="policy-section">
            <h2>${esc(sec.title)}</h2>
            <ul>${sec.points.map(p => `<li>${esc(p)}</li>`).join('')}</ul>
          </div>`).join('')
        + `<p class="policy-note">Questions? <a href="index.html?view=help&amp;new=1">Raise a request in the Resolution Center</a></p>`;
      return;
    }
    document.getElementById('policiesTitle').textContent = 'Policies';
    document.title = 'Policies — Aerva';
    // Upcoming and recent material changes (AERVA_POLICIES.updates), shown
    // above the list until 60 days after they took effect.
    const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Kolkata' });
    const recent = (P.updates || []).filter(u => u && u.published <= today && (new Date(today) - new Date(u.effective)) / 86400e3 <= 60)
      .sort((a, b) => String(b.published).localeCompare(String(a.published)));
    const fmt = (d) => new Date(d + 'T00:00:00+05:30').toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' });
    const updatesHtml = recent.length ? `<div class="policy-section" id="policyUpdates"><h2>Recent updates</h2>` + recent.map(u => `
        <p style="margin:10px 0 4px;"><strong>${esc(u.title)}</strong> — ${today >= u.effective ? 'in effect since' : 'takes effect on'} ${esc(fmt(u.effective))}${u.audience === 'hosts' ? ' (hosts)' : u.audience === 'guests' ? ' (guests)' : ''}</p>
        <ul>${u.summary.map(p => `<li>${esc(p)}</li>`).join('')}</ul>`).join('') + `</div>` : '';
    body.innerHTML = updatesHtml + `<div class="policy-index">` + docs.map(d => `
      <a class="policy-index-item" href="${esc(d.href || POLICY_DOC_LINK(d.id))}">
        <span class="policy-index-title">${esc(d.title)}</span>
        <span class="policy-index-summary">${esc(d.summary || '')}</span>
      </a>`).join('') + `</div>`;
  }
  // ---- Terms of Service (index.html?view=terms) ----
  // Accepted by continuing on every login / sign-up screen.
  function showTermsView(){
    const P = window.AERVA_POLICIES;
    hideMainViews();
    document.getElementById('termsView').style.display = 'block';
    document.body.classList.remove('showing-hero');
    if(!P || !P.terms){ window.scrollTo(0, 0); return; }
    const T = P.terms;
    const esc = escapeMessageHtml;
    const want = new URLSearchParams(window.location.search).get('region');
    const region = T.regions.find(r => r.id === want) || T.regions[0]; // India first
    document.title = region.label + ' — Aerva';
    document.getElementById('termsTitle').textContent = T.title;
    // Which version applies: India first, then Europe, then everyone else.
    document.getElementById('termsNotice').innerHTML = T.regions.map(r =>
      `<p>${esc(r.applies).replace(esc(r.label), `<a href="index.html?view=terms&region=${esc(r.id)}"${r.id === region.id ? ' aria-current="true"' : ''}>${esc(r.label)}</a>`)}</p>`).join('');
    document.getElementById('termsIntro').textContent = T.intro;
    document.getElementById('termsUpdated').textContent = 'Last updated ' + P.updated;
    const docs = policyDocs().filter(d => d.id !== 'terms');
    const section = (sec) => `
      <div class="policy-section" id="terms-${esc(sec.id)}">
        <h2>${esc(sec.title)}</h2>
        <ul>${sec.points.map(p => `<li>${esc(p)}</li>`).join('')}</ul>
      </div>`;
    document.getElementById('termsBody').innerHTML =
      `<h2 class="terms-version">${esc(region.label)}</h2>`
      + `<div class="legal-notice"><p>The documents referred to within these Terms include:</p><ul>`
      + docs.map(d => `<li><a href="${esc(d.href || POLICY_DOC_LINK(d.id))}">${esc(d.title)}</a>, ${esc(String(d.summary || '').replace(/^./, c => c.toLowerCase()))}</li>`).join('')
      + `</ul></div>`
      + T.common.map(section).join('')
      + (T.specific[region.id] || []).map(section).join('');
    window.scrollTo(0, 0);
  }

  // ---- Aerva Privacy (index.html?view=privacy) ----
  // Only what information Aerva collects, why, who gets it, how long it is
  // kept and your rights. The booking / hosting rules are the separate
  // Policies page. Text: aerva-policies.js → privacy.
  function showPrivacyView(){
    const P = window.AERVA_POLICIES;
    hideMainViews();
    document.getElementById('privacyView').style.display = 'block';
    document.body.classList.remove('showing-hero');
    document.title = 'Privacy — Aerva';
    if(P && P.privacy){
      const esc = escapeMessageHtml;
      document.getElementById('privacyTitle').textContent = P.privacy.title;
      document.getElementById('privacyIntro').textContent = P.privacy.intro;
      document.getElementById('privacyUpdated').textContent = 'Last updated ' + P.updated;
      document.getElementById('privacyBody').innerHTML = P.privacy.sections.map(sec => `
        <div class="policy-section" id="privacy-${esc(sec.id)}">
          <h2>${esc(sec.title)}</h2>
          <ul>${sec.points.map(p => `<li>${esc(p)}</li>`).join('')}</ul>
        </div>`).join('')
        + `<p class="policy-note">Booking and hosting rules: <a href="index.html?view=policies">Aerva Policies</a></p>`;
    }
    window.scrollTo(0, 0);
  }

  function showPoliciesView(){
    hideMainViews();
    document.getElementById('policiesView').style.display = 'block';
    document.body.classList.remove('showing-hero');
    const q = new URLSearchParams(window.location.search);
    // Older links: &tab=host → the Host Agreement, &tab=guest → the Booking Agreement.
    const doc = q.get('doc') || (q.get('tab') === 'host' ? 'host-agreement' : q.get('tab') === 'guest' ? 'booking-agreement' : null);
    renderPolicies(doc);
    window.scrollTo(0, 0);
  }
  function hideMainViews(){
    MAIN_VIEW_IDS.forEach(id => {
      const el = document.getElementById(id);
      if(el) el.style.display = 'none';
    });
  }

  // ---- Wishlist ----
  // Every home this account has hearted, newest first, from the profile
  // menu (?view=wishlist). Hearts are the same ones as on every card
  // (getFavoriteIds / toggleFavoriteId), so un-hearting here removes the
  // home from the list at once, and the list follows the guest to every
  // device (guest-profile.js myFavorites). Drawn from the full set of live
  // homes, not just the last search's results.
  let wishlistListingsById = null;
  async function showWishlistView(){
    document.body.classList.remove('showing-hero');
    hideMainViews();
    document.getElementById('wishlistView').style.display = 'block';
    document.title = 'Wishlist — Aerva';
    BROWSE_TABS.concat(['catToday']).forEach(id => {
      const el = document.getElementById(id);
      if(el) el.classList.remove('active');
    });
    window.scrollTo({ top: 0 });
    const container = document.getElementById('wishlistContainer');
    if(!guestAuthToken()){
      container.innerHTML = '<div class="wishlist-empty"><p>Log in to see the homes you have saved.</p><a class="btn" href="guest-login.html?next=index.html%3Fview%3Dwishlist">Log in</a></div>';
      return;
    }
    if(!wishlistListingsById){
      container.innerHTML = '<p class="loading">Loading your wishlist…</p>';
      try{
        await hiddenListingsReady;
        const res = await fetch(SUITES_API_BASE + '/api/get-listings');
        if(!res.ok) throw new Error('load failed');
        const data = await res.json();
        wishlistListingsById = {};
        visibleOnly(data.listings || []).forEach(l => { wishlistListingsById[l.id] = l; });
      }catch(err){
        container.innerHTML = '<div class="wishlist-empty"><p>Your wishlist could not be loaded right now. Please refresh in a moment.</p></div>';
        return;
      }
    }
    renderWishlist();
  }
  function renderWishlistIfOpen(){
    const view = document.getElementById('wishlistView');
    if(view && view.style.display === 'block' && wishlistListingsById) renderWishlist();
  }
  function renderWishlist(){
    const container = document.getElementById('wishlistContainer');
    const countEl = document.getElementById('wishlistCount');
    if(!container) return;
    // Signed in, but the account is still being confirmed (page just
    // opened): the hearts arrive in a moment (setRecentlyViewedOwner).
    if(storageOwner === 'anon'){ container.innerHTML = '<p class="loading">Loading your wishlist…</p>'; return; }
    const ids = getFavoriteIds().map(String).reverse(); // newest first
    const homes = ids.map(id => wishlistListingsById[id]).filter(Boolean);
    const gone = ids.length - homes.length;
    if(countEl) countEl.textContent = homes.length ? `${homes.length} saved home${homes.length === 1 ? '' : 's'}` : '';
    if(!homes.length){
      container.innerHTML = `<div class="wishlist-empty"><p>${gone ? 'The homes you saved are no longer listed.' : 'Nothing saved yet.'} Tap the heart on any home to keep it here.</p><a class="btn" href="index.html">Browse homes</a></div>`;
      return;
    }
    container.innerHTML = '';
    const grid = document.createElement('div');
    grid.className = 'suite-grid';
    homes.forEach((l, i) => {
      const card = buildSuiteCard(l, i);
      card.classList.add('in');
      grid.appendChild(card);
    });
    container.appendChild(grid);
    if(gone){
      const note = document.createElement('p');
      note.className = 'wishlist-note';
      note.textContent = `${gone} saved home${gone === 1 ? ' is' : 's are'} no longer listed, so ${gone === 1 ? 'it is' : 'they are'} not shown.`;
      container.appendChild(note);
    }
  }

  // Who you are on Aerva: your photo, a few lines about you, where you
  // have been, and what others have said. Everything here is your own;
  // see api/_profiles.js for who else may read it.
  let profileQuestions = [];

  async function showProfileView(){
    document.body.classList.remove('showing-hero');
    hideMainViews();
    document.getElementById('profileView').style.display = 'block';
    document.title = 'Profile — Aerva';
    BROWSE_TABS.concat(['catToday']).forEach(id => {
      const el = document.getElementById(id);
      if(el) el.classList.remove('active');
    });
    window.scrollTo({ top: 0 });
    // Signed out (an old link, or the session ended): a way to log in, not a
    // form that cannot be saved.
    if(!guestAuthToken()){
      document.getElementById('profileFields').innerHTML = '<p class="profile-empty">Log in to see your profile.</p><a class="btn" href="guest-login.html?next=index.html%3Fview%3Dprofile">Log in</a>';
      ['profileSave', 'profileChangePhoto', 'profileNameSection', 'profileVerifySection'].forEach(id => { const el = document.getElementById(id); if(el) el.style.display = 'none'; });
      return;
    }
    ['profileSave', 'profileChangePhoto', 'profileNameSection'].forEach(id => { const el = document.getElementById(id); if(el) el.style.display = ''; });
    try{
      const res = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=profile', {
        headers: { 'Authorization': 'Bearer ' + guestAuthToken() }
      });
      const data = await res.json();
      if(!res.ok) throw new Error(data.error || 'Could not load your profile.');
      renderProfile(data.profile);
      { // Not saved yet: start the form from the account's full name, if any.
        const parts = String(data.profile.name || '').trim().split(/\s+/).filter(Boolean);
        renderProfileNameRow(data.profile.firstName, data.profile.lastName, false,
          { first: data.profile.firstName || (parts.length > 1 ? parts[0] : ''), last: data.profile.lastName || (parts.length > 1 ? parts.slice(1).join(' ') : '') }); }
      aervaMountProfileVerify();
      // "Complete your account" (My Bookings) links here to confirm the
      // email and add a phone number: offer that same panel checkout uses,
      // only while one of them is missing (aervaIdPanel checks).
      let box = document.getElementById('profileContactBox');
      if(!box){
        box = document.createElement('div');
        box.id = 'profileContactBox';
        box.style.cssText = 'display:none; margin:0 0 20px;';
        const wrap = document.querySelector('#profileView .profile-wrap');
        if(wrap) wrap.insertBefore(box, wrap.firstChild);
      }
      if(typeof aervaIdPanel === 'function') aervaIdPanel(box, { needs: ['email', 'phone'], message: 'Complete your account',
        onDone: () => { box.style.display = 'none'; box.innerHTML = ''; } });
    }catch(err){
      document.getElementById('profileFields').innerHTML =
        `<p class="profile-empty">${escapeMessageHtml(err.message || 'Could not load your profile.')}</p>`;
    }
  }

  function renderProfile(p){
    const esc = escapeMessageHtml;
    profileQuestions = p.questions || [];
    document.getElementById('profileName').textContent = p.name || 'Your profile';
    document.getElementById('profileMeta').textContent =
      [p.isHost ? 'Host' : 'Guest', p.memberSince ? 'on Aerva since ' + p.memberSince : '', p.idVerified ? '\u2713 ID verified' : ''].filter(Boolean).join(' · ');
    const circle = document.getElementById('profilePhotoCircle');
    circle.innerHTML = p.photoUrl
      ? `<img src="${esc(p.photoUrl)}" alt="">`
      : esc((p.name || 'G').trim().charAt(0).toUpperCase());

    const about = p.about || {};
    document.getElementById('profileFields').innerHTML =
      `<div class="profile-field"><label for="pfWork">What I do</label>
        <input id="pfWork" maxlength="400" value="${esc(p.work || '')}" placeholder="Architect, teacher, retired…"></div>
       <div class="profile-field"><label for="pfHobbies">What I enjoy</label>
        <input id="pfHobbies" maxlength="400" value="${esc(p.hobbies || '')}" placeholder="Trekking, film photography, cooking…"></div>`
      + profileQuestions.map(q => `
        <div class="profile-field">
          <label for="pf_${esc(q.id)}">${esc(q.label)}</label>
          <textarea id="pf_${esc(q.id)}" maxlength="400" placeholder="${esc(q.placeholder || '')}">${esc(about[q.id] || '')}</textarea>
        </div>`).join('');

    // Where they have been, and where they host.
    // Your homes and experiences, as the same cards guests see on your
    // public profile — then the places you have travelled to — then, last,
    // what others have said.
    const cards = listingMiniCardsHtml(p.listings);
    document.getElementById('profileListingsSection').style.display = cards ? 'block' : 'none';
    document.getElementById('profileListings').innerHTML = cards ? `<div class="hp-listings">${cards}</div>` : '';
    const places = p.places || { stayed: [], hosting: [] };
    // Stays and experiences you have booked here, per city.
    const placeBits = (places.stayed || []).map(x => {
      const parts = [];
      if(x.visits > 0) parts.push(`${x.visits} stay${x.visits === 1 ? '' : 's'}`);
      if(x.experiences > 0) parts.push(`${x.experiences} experience${x.experiences === 1 ? '' : 's'}`);
      return `<span class="profile-place">${esc(x.city)}${parts.length ? ' · ' + parts.join(' · ') : ''}</span>`;
    });
    document.getElementById('profilePlacesSection').style.display = placeBits.length ? 'block' : 'none';
    document.getElementById('profilePlaces').innerHTML = `<div class="profile-places">${placeBits.join('')}</div>`;

    // What others have said. Published reviews only.
    const rev = p.reviews || { asGuest: [], asHost: [] };
    const asGuest = (rev.asGuest || []).map(r => reviewItemHtml({ month: r.month, score: r.score, comment: r.comment }, false)).join('');
    const asHost = (rev.asHost || []).map(r => reviewItemHtml({ month: r.month, score: r.score, comment: `${r.property ? r.property + ' — ' : ''}${r.comment}` }, false)).join('');
    const hasReviews = asGuest || asHost;
    document.getElementById('profileReviewsSection').style.display = hasReviews ? 'block' : 'none';
    document.getElementById('profileReviews').innerHTML =
      (asGuest ? `<div class="profile-section-title" style="margin-top:4px;">From hosts you stayed with</div><div class="rv-list">${asGuest}</div>` : '')
      + (asHost ? `<div class="profile-section-title" style="margin-top:18px;">From guests who stayed with you</div><div class="rv-list">${asHost}</div>` : '');
  }

  // ---- Verify your details (owner, 10 Nov 2026; aerva-guest-verify.js) ----
  // Name, phone code and photo ID: optional steps, or — while Aerva requires
  // them — what a booking needs to be confirmed. Hidden before the feature's
  // database update. The setup steps link here with ?verify=phone | id.
  function aervaMountProfileVerify(){
    const sec = document.getElementById('profileVerifySection');
    const box = document.getElementById('profileVerifyBox');
    if(!sec || !box || !window.AervaGuestVerify || !guestAuthToken()){ if(sec) sec.style.display = 'none'; return; }
    let focusStep = null;
    try{ const v = new URLSearchParams(window.location.search).get('verify'); if(v === 'phone' || v === 'id') focusStep = v; }catch(e){}
    if(aervaMountProfileVerify.focused) focusStep = null;
    aervaMountProfileVerify.focused = true;
    sec.style.display = '';
    window.AervaGuestVerify.mountSteps(box, {
      focusStep,
      onUnavailable: () => { sec.style.display = 'none'; },
      onChange: (st) => {
        const hint = document.getElementById('profileVerifyHint');
        if(hint) hint.textContent = st.verified ? 'Your details are verified: your bookings are confirmed as soon as you pay.'
          : st.required ? 'A booking is confirmed once these three are done. Do them now and your next booking is confirmed as soon as you pay.'
          : 'Optional. Your host still checks a photo ID at check-in.';
        // The name saved from here shows in "Your name" above.
        if(st.name.done && !document.getElementById('profileNameValue')){
          renderProfileNameRow(st.name.firstName, st.name.lastName, false);
          const full = st.name.firstName + ' ' + st.name.lastName;
          const n = document.getElementById('profileName'); if(n) n.textContent = full;
          safeStorage.set('aerva_guest_name', full);
          try{ if(window.aervaRefreshIdentity) window.aervaRefreshIdentity(); }catch(e){}
        }
      },
      onConfirmed: () => { try{ if(window.aervaRefreshIdentity) window.aervaRefreshIdentity(); }catch(e){} }
    });
  }

  // ---- Your name (owner, 9 Nov 2026) ----
  // First and last name as on the government ID — the host checks it at
  // check-in. Shown with Edit, or as the form while either is missing
  // (the "Add your first and last name" setup step links here). Saved by
  // api/guest-profile.js mode saveName, which has the final say on what
  // is allowed; the check here only spares a round trip.
  const PROFILE_NAME_OK = /^[\p{L}\p{M} .'’-]+$/u;
  function profileNameProblem(v, label){
    if(!v) return `Please enter your ${label}.`;
    if([...v].length > 50) return `Your ${label} can be at most 50 characters.`;
    if(/\d/.test(v)) return `Your ${label} cannot contain numbers — please write it as on your government ID.`;
    if(!PROFILE_NAME_OK.test(v)) return `Your ${label} can only have letters, spaces, dots, apostrophes and hyphens.`;
    return '';
  }
  function renderProfileNameRow(first, last, editing, draft){
    const box = document.getElementById('profileNameBox');
    if(!box) return;
    const esc = escapeMessageHtml;
    first = String(first || '').trim(); last = String(last || '').trim();
    const complete = !!(first && last);
    const hint = '<p class="profile-hint">As on your government ID — the host checks it at check-in. Bookings you have already made keep the name they were booked with.</p>';
    if(complete && !editing){
      box.innerHTML = `<div class="profile-name-row">
          <span class="profile-name-value" id="profileNameValue">${esc(first + ' ' + last)}</span>
          <button type="button" class="filter-clear" id="profileNameEdit" aria-label="Edit your name">Edit</button>
        </div>${hint}`;
      box.querySelector('#profileNameEdit').addEventListener('click', () => {
        renderProfileNameRow(first, last, true);
        const f = document.getElementById('pnFirst'); if(f){ f.focus(); f.select(); }
      });
      return;
    }
    box.innerHTML = `<div class="profile-name-grid">
        <div class="profile-field"><label for="pnFirst">First name</label>
          <input id="pnFirst" maxlength="50" autocomplete="given-name" autocapitalize="words" spellcheck="false" value="${esc(draft ? draft.first : first)}" placeholder="As on your ID"></div>
        <div class="profile-field"><label for="pnLast">Last name</label>
          <input id="pnLast" maxlength="50" autocomplete="family-name" autocapitalize="words" spellcheck="false" value="${esc(draft ? draft.last : last)}" placeholder="As on your ID"></div>
      </div>${hint}
      <div class="profile-name-actions">
        <button type="button" class="settings-save-btn profile-save" id="profileNameSave">${complete ? 'Save' : 'Save name'}</button>
        ${complete ? '<button type="button" class="filter-clear" id="profileNameCancel">Cancel</button>' : ''}
      </div>
      <p class="profile-msg" id="profileNameMsg" role="alert"></p>`;
    const msg = box.querySelector('#profileNameMsg');
    const btn = box.querySelector('#profileNameSave');
    const fIn = box.querySelector('#pnFirst'), lIn = box.querySelector('#pnLast');
    const say = (t) => { msg.textContent = t; msg.style.color = '#8a2b2b'; };
    const save = async () => {
      if(btn.disabled) return;
      const f = fIn.value.replace(/\s+/g, ' ').trim(), l = lIn.value.replace(/\s+/g, ' ').trim();
      const bad = profileNameProblem(f, 'first name') || profileNameProblem(l, 'last name');
      if(bad){ say(bad); (profileNameProblem(f, 'first name') ? fIn : lIn).focus(); return; }
      btn.disabled = true; btn.textContent = 'Saving…'; msg.textContent = '';
      try{
        const res = await fetch(SUITES_API_BASE + '/api/guest-profile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
          body: JSON.stringify({ mode: 'saveName', firstName: f, lastName: l })
        });
        const data = await res.json().catch(() => ({}));
        if(!res.ok) throw new Error(data.error || 'Could not save your name. Please try again.');
        renderProfileNameRow(data.firstName, data.lastName, false);
        const done = document.createElement('p');
        done.className = 'profile-msg'; done.style.color = '#2f5c2a';
        // An ID verified for the old name is not verified for the new one.
        done.textContent = data.idVerificationCleared ? 'Saved. Your ID was verified for your previous name, so it needs to be verified again (below).' : 'Saved.';
        box.appendChild(done);
        aervaMountProfileVerify();
        document.getElementById('profileName').textContent = data.name;
        const circle = document.getElementById('profilePhotoCircle');
        if(circle && !circle.querySelector('img')) circle.textContent = data.name.charAt(0).toUpperCase();
        safeStorage.set('aerva_guest_name', data.name);
        // Checkout fills in the name from the account: ask again next time.
        aervaPrefillPromise = null;
        // The greeting and the bell ("Complete your account") follow.
        try{ if(window.aervaRefreshIdentity) window.aervaRefreshIdentity(); }catch(e){}
      }catch(err){
        say(err.message || 'Could not save your name. Please try again.');
        btn.disabled = false; btn.textContent = complete ? 'Save' : 'Save name';
      }
    };
    btn.addEventListener('click', save);
    [fIn, lIn].forEach(el => el.addEventListener('keydown', (e) => { if(e.key === 'Enter'){ e.preventDefault(); save(); } }));
    const cancel = box.querySelector('#profileNameCancel');
    if(cancel) cancel.addEventListener('click', () => renderProfileNameRow(first, last, false));
  }

  async function saveProfile(){
    const btn = document.getElementById('profileSave');
    const msg = document.getElementById('profileMsg');
    const about = {};
    profileQuestions.forEach(q => {
      const el = document.getElementById('pf_' + q.id);
      if(el && el.value.trim()) about[q.id] = el.value.trim();
    });
    btn.disabled = true; btn.textContent = 'Saving…'; msg.textContent = '';
    try{
      const res = await fetch(SUITES_API_BASE + '/api/guest-profile', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
        body: JSON.stringify({
          mode: 'saveProfile',
          work: document.getElementById('pfWork').value,
          hobbies: document.getElementById('pfHobbies').value,
          about
        })
      });
      const data = await res.json();
      if(!res.ok) throw new Error(data.error || 'Could not save that.');
      renderProfile(data.profile);
      msg.textContent = 'Saved.';
      msg.style.color = '#2f5c2a';
    }catch(err){
      msg.textContent = err.message || 'Could not save that. Please try again.';
      msg.style.color = '#8a2b2b';
    }
    btn.disabled = false; btn.textContent = 'Save';
  }

  // Log out of all devices (api/guest-profile.js ends every session of
  // this account), then clear this browser's copy and go home.
  (function wireLogoutAll(){
    const btn = document.getElementById('profileLogoutAll');
    if(!btn) return;
    btn.addEventListener('click', async () => {
      const msg = document.getElementById('profileLogoutAllMsg');
      if(!confirm('Log out of Aerva on every device, including this one?')) return;
      btn.disabled = true; btn.textContent = 'Logging out…'; msg.textContent = '';
      try{
        const res = await fetch(SUITES_API_BASE + '/api/guest-profile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
          body: JSON.stringify({ mode: 'logoutAllDevices' })
        });
        const data = await res.json().catch(() => ({}));
        if(!res.ok && res.status !== 401) throw new Error(data.error || 'Could not log out everywhere. Please try again.');
        if(typeof window.aervaClearGuestSession === 'function') window.aervaClearGuestSession();
        else safeStorage.remove('aerva_guest_session');
        window.location.href = 'index.html';
      }catch(err){
        msg.textContent = err.message || 'Could not log out everywhere. Please try again.';
        msg.style.color = '#8a2b2b';
        btn.disabled = false; btn.textContent = 'Log out of all devices';
      }
    });
  })();

  // ---- Account Settings (?view=settings) ----
  // Separate from Profile: privacy switches (aerva-privacy.js), log out
  // everywhere, pause and delete. A host's personal details and
  // verification stay on My Collection; this page links there.
  function showSettingsView(){
    document.body.classList.remove('showing-hero');
    hideMainViews();
    document.getElementById('settingsView').style.display = 'block';
    document.title = 'Account Settings — Aerva';
    BROWSE_TABS.concat(['catToday']).forEach(id => {
      const el = document.getElementById(id);
      if(el) el.classList.remove('active');
    });
    window.scrollTo({ top: 0 });
    const box = document.getElementById('settingsPrivacyBox');
    if(!guestAuthToken()){
      box.innerHTML = '<p class="profile-hint">Log in to see your account settings.</p><a class="btn" href="guest-login.html">Log in</a>';
      document.getElementById('profileAccountSection').style.display = 'none';
      const idSec = document.getElementById('settingsIdSection'); if(idSec) idSec.style.display = 'none';
      return;
    }
    document.getElementById('settingsEmail').textContent = safeStorage.get('aerva_guest_email') || '';
    if(window.AervaPrivacy) window.AervaPrivacy.mount(box);
    // ID verification (aerva-id-verify.js): checked in seconds, never stored.
    const idSec = document.getElementById('settingsIdSection'); if(idSec) idSec.style.display = '';
    if(window.AervaIdVerify) window.AervaIdVerify.mount(document.getElementById('settingsIdBox'));
  }

  (function wireSettingsAccount(){
    const pauseBtn = document.getElementById('settingsPauseBtn');
    const delBtn = document.getElementById('settingsDeleteBtn');
    const panel = document.getElementById('settingsDeletePanel');
    const msg = document.getElementById('settingsAccountMsg');
    if(!pauseBtn || !delBtn) return;
    const post = (body) => fetch(SUITES_API_BASE + '/api/guest-profile', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
      body: JSON.stringify(body)
    });
    const leave = () => {
      if(typeof window.aervaClearGuestSession === 'function') window.aervaClearGuestSession();
      else safeStorage.remove('aerva_guest_session');
      window.location.href = 'index.html';
    };
    pauseBtn.addEventListener('click', async () => {
      if(!confirm('Pause your account? You will be logged out everywhere. Nothing is erased: log in again to bring it all back.')) return;
      pauseBtn.disabled = true; msg.textContent = '';
      try{
        const r = await post({ mode: 'deactivateAccount' });
        const d = await r.json().catch(() => ({}));
        if(!r.ok) throw new Error(d.error || 'Could not pause your account right now.');
        alert('Your account is paused. Log in again whenever you want it back.');
        leave();
      }catch(err){
        msg.textContent = err.message; msg.style.color = '#8a2b2b'; pauseBtn.disabled = false;
      }
    });
    delBtn.addEventListener('click', async () => {
      const esc = escapeMessageHtml;
      panel.hidden = false;
      panel.innerHTML = '<p class="profile-hint">Checking…</p>';
      let blockers = [];
      try{
        const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=deletionCheck', { headers: { 'Authorization': 'Bearer ' + guestAuthToken() } });
        blockers = (await r.json()).blockers || [];
      }catch(e){ blockers = ['Could not check right now. Try again.']; }
      if(blockers.length){
        panel.innerHTML = '<p><strong>Your account cannot be deleted yet:</strong></p><ul>' + blockers.map(b => `<li>${esc(b)}</li>`).join('') + '</ul>';
        return;
      }
      panel.innerHTML = `<p>Deleting your account removes your name, contact details, photos, profile, sign-in and messages. Booking and payment records are kept without your details, as the law requires. This cannot be undone.</p>
        <label class="settings-delete-confirm">Type DELETE to confirm <input id="settingsDeleteConfirm" autocomplete="off"></label>
        <button type="button" class="settings-danger-solid" id="settingsDeleteGo">Delete my account</button>
        <p class="profile-msg" id="settingsDeleteMsg" style="color:#8a2b2b;"></p>`;
      document.getElementById('settingsDeleteGo').addEventListener('click', async () => {
        const out = document.getElementById('settingsDeleteMsg');
        if(document.getElementById('settingsDeleteConfirm').value.trim() !== 'DELETE'){ out.textContent = 'Type DELETE to confirm.'; return; }
        const r = await post({ mode: 'deleteAccount', confirm: 'DELETE' });
        const d = await r.json().catch(() => ({}));
        if(!r.ok){ out.textContent = (d.blockers && d.blockers.join(' ')) || d.error || 'Could not delete your account.'; return; }
        // This account's own saved lists in this browser go too.
        try{
          const part = String(guestAuthToken() || '').split('.')[0].replace(/-/g, '+').replace(/_/g, '/');
          const id = (JSON.parse(atob(part + '==='.slice((part.length + 3) % 4))) || {}).listingId;
          if(id != null) ['aerva_recently_viewed', 'aerva_favorite_listings', 'aerva_recent_searches'].forEach(k => safeStorage.remove(k + ':' + id));
        }catch(e){}
        alert('Your account has been deleted.');
        leave();
      });
    });
  })();

  // ---- Today (hosts) ----
  // Who is arriving, who is leaving, who is staying on, at this host's own
  // properties. Everything comes from host-listings.js, which works it out
  // on each listing's own clock.
  // "Pets: Dog · Young litter: 2 · Service animal: Dog" — so a host sees
  // who is coming with four legs on the day, not only on the earnings page.
  function todayAnimalsLine(r){
    const bits = [];
    if(Array.isArray(r.petTypes) && r.petTypes.length) bits.push(`Pets: ${r.petTypes.join(', ')}`);
    if(Number(r.youngLitter) > 0) bits.push(`Young litter: ${Number(r.youngLitter)}`);
    const sa = Array.isArray(r.serviceAnimals) ? r.serviceAnimals : [];
    if(sa.length) bits.push(`Service/support animal${sa.length === 1 ? '' : 's'}: ${sa.join(', ')}`);
    return bits.length ? '🐾 ' + bits.join(' · ') : '';
  }

  function renderTodayView(today){
    const box = document.getElementById('todayList');
    if(!box) return;
    const t = Object.assign({ arrivals: [], departures: [], staying: [], experiences: [], upcoming: [] }, today || {});
    const esc = escapeMessageHtml;
    const total = t.arrivals.length + t.departures.length + t.staying.length + t.experiences.length;
    document.getElementById('todayDate').textContent =
      new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' });
    document.getElementById('todayHeading').textContent = total
      ? (total === 1 ? 'You have 1 reservation' : `You have ${total} reservations`)
      : 'Nothing booked for today';
    const row = (r, when, title) => `
      <button type="button" class="today-row" data-today-order="${Number(r.orderId)}">
        <span class="today-when">${esc(when)}</span>
        <span class="today-main">
          <span class="today-title">${esc(title)}</span>
          <span class="today-sub">${esc(r.listingName || '')}</span>
          ${todayAnimalsLine(r) ? `<span class="today-sub today-animals">${esc(todayAnimalsLine(r))}</span>` : ''}
        </span>
        <span class="today-thumbs">
          ${r.guestPhotoUrl
            ? `<img class="today-avatar" src="${esc(r.guestPhotoUrl)}" alt="">`
            : `<span class="today-avatar">${esc((r.guestName || 'G').trim().charAt(0).toUpperCase())}</span>`}
          ${r.photoUrl ? `<img class="today-thumb" src="${esc(r.photoUrl)}" alt="">` : ''}
        </span>
      </button>`;
    const people = (r) => `${r.guestName}${r.guests > 1 ? `'s group of ${r.guests}` : ''}`;
    const column = (label, rows, empty) => `
      <div class="today-col">
        <div class="today-col-head">${esc(label)} <span class="today-col-count">${rows.length}</span></div>
        ${rows.length ? rows.join('') : `<p class="today-col-empty">${esc(empty)}</p>`}
      </div>`;
    const staying = t.staying.map(r => row(r, 'All day',
      `${people(r)} stays for ${r.nightsLeft === 1 ? 'one more day' : r.nightsLeft + ' more days'}`));
    // An experience is not checked into — it runs, at its own start time.
    const experiences = t.experiences.map(r => row(r, r.startTime || 'All day',
      `${people(r)} joins ${r.listingName || 'your experience'}`));
    // Coming up: the next arrivals, grouped by day (host-listings.js today.upcoming).
    const dayLabel = (r) => r.daysAway === 1 ? 'Tomorrow' : new Date(String(r.arrival).slice(0, 10) + 'T00:00:00Z').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
    const upcomingHtml = t.upcoming.length
      ? `<div class="today-staying"><div class="today-group-label">Coming up · next ${Number(t.upcomingDays) || 14} days</div>${t.upcoming.map(r => row(r, dayLabel(r),
          r.kind === 'experience' ? `${people(r)} joins ${r.listingName || 'your experience'}` : `${people(r)} arrives · ${r.nights === 1 ? '1 night' : (r.nights || '') + ' nights'}`)).join('')}</div>`
      : `<div class="today-staying"><div class="today-group-label">Coming up</div><p class="today-col-empty">No arrivals in the next ${Number(t.upcomingDays) || 14} days.</p></div>`;
    if(!total){
      box.innerHTML = '<p class="today-empty">No arrivals, departures or guests staying today.</p>' + upcomingHtml;
      todayRowsById = {};
      t.upcoming.forEach(r => { todayRowsById[r.orderId] = r; });
      box.querySelectorAll('[data-today-order]').forEach(el => el.addEventListener('click', () => openTodayBooking(Number(el.dataset.todayOrder))));
      return;
    }
    box.innerHTML =
      `<div class="today-split">
        ${column('Checking in', t.arrivals.map(r => row(r, r.checkInTime || '1:00 pm', `${people(r)} checks in`)), 'Nobody arriving today.')}
        ${column('Checking out', t.departures.map(r => row(r, r.checkOutTime || '10:00 am', `${people(r)} checks out`)), 'Nobody leaving today.')}
      </div>`
      + (experiences.length
        ? `<div class="today-staying"><div class="today-group-label">Experiences today</div>${experiences.join('')}</div>`
        : '')
      + (staying.length
        ? `<div class="today-staying"><div class="today-group-label">Staying with you</div>${staying.join('')}</div>`
        : '')
      + upcomingHtml;
    // Kept so the panel can show the booking without asking again.
    todayRowsById = {};
    [...t.arrivals, ...t.departures, ...t.staying, ...t.experiences, ...t.upcoming].forEach(r => { todayRowsById[r.orderId] = r; });
    box.querySelectorAll('[data-today-order]').forEach(el => {
      el.addEventListener('click', () => openTodayBooking(Number(el.dataset.todayOrder)));
    });
  }

  let todayRowsById = {};

  // Where the payout stands (host-listings.js payoutStatusFor): the host's
  // payout, or a co-host's own share. Due the day after check-in until sent.
  function todayPayoutLabel(r){
    const day = (v) => { const d = new Date(String(v || '').slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? '' : ' ' + d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' }); };
    switch(r && r.payoutStatus){
      case 'due': return 'Due' + day(r.payoutDueOn);
      case 'sent': return 'Sent' + day(r.payoutSentOn) + (r.payoutReference ? ' · Ref ' + r.payoutReference : '');
      case 'on_hold': return 'On hold';
      case 'failed': return 'Failed';
      case 'cancelled': return 'Cancelled';
      default: return '';
    }
  }

  // ---- One booking, opened from Today ----
  // The stay's own facts, who the guest is, and the thread — so a host can
  // read what was agreed and reply without leaving the page. Messages go
  // through the same conversation the guest sees; nothing here exposes an
  // email or phone number.
  async function openTodayBooking(orderId){
    const r = todayRowsById[orderId];
    if(!r) return;
    const esc = escapeMessageHtml;
    const overlay = document.getElementById('todayBookingOverlay');
    const body = document.getElementById('todayBookingBody');
    const fmtDay = (d) => d ? new Date(d).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' }) : '—';
    overlay.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    body.innerHTML = `
      <div class="tb-head">
        <div>
          <h3 class="tb-name">${esc(r.guestName)}</h3>
          <p class="tb-listing">${esc(r.listingName || '')}</p>
        </div>
        ${r.guestPhotoUrl ? `<img class="tb-avatar" src="${esc(r.guestPhotoUrl)}" alt="">`
          : `<span class="tb-avatar tb-avatar-initial">${esc((r.guestName || 'G').trim().charAt(0).toUpperCase())}</span>`}
      </div>
      <div class="tb-facts">
        ${r.kind === 'experience' ? `
          <div><span>Date</span><strong>${esc(fmtDay(r.arrival))}${r.startTime ? ' · ' + esc(r.startTime) : ''}</strong></div>
          ${r.shareOnly ? '' : `<div><span>Guests</span><strong>${Number(r.guests) || 1}</strong></div>`}
        ` : `
          <div><span>Check-in</span><strong>${esc(fmtDay(r.arrival))}${r.checkInTime ? ' · ' + esc(r.checkInTime) : ''}</strong></div>
          <div><span>Check-out</span><strong>${esc(fmtDay(r.departure))}${r.checkOutTime ? ' · ' + esc(r.checkOutTime) : ''}</strong></div>
          ${r.shareOnly ? '' : `<div><span>Guests</span><strong>${Number(r.guests) || 1}</strong></div>`}
          <div><span>Nights</span><strong>${r.nights || '—'}</strong></div>
        `}
        ${r.payout ? `<div><span>Your payout</span><strong>${fmtGuest(r.payout)}</strong></div>` : ''}
        ${/* a co-host gets their own share instead (the host's payout is never sent) */ ''}
        ${!r.payout && Number(r.share) > 0 ? `<div><span>Your share</span><strong>${fmtGuest(r.share)}</strong></div>` : ''}
        ${todayPayoutLabel(r) ? `<div><span>Payout</span><strong>${esc(todayPayoutLabel(r))}</strong></div>` : ''}
      </div>
      ${r.shareOnly ? `<p class="tb-muted">Your co-host access covers this stay and your share. Guest messages and contact details stay with the host.</p>` : `
      <div class="tb-section-title">Message ${esc((r.guestName || 'your guest').split(' ')[0])}</div>
      <div class="tb-thread" id="tbThread"><p class="tb-muted">Loading messages…</p></div>
      <div class="tb-compose">
        <textarea id="tbText" rows="2" placeholder="Write a message…"></textarea>
        <button type="button" class="filter-clear" id="tbSend">Send</button>
      </div>
      <p class="tb-muted" id="tbMsg"></p>`}`;
    // A co-host without bookings access (host-listings.js trimForCohost):
    // the stay and their share only — no thread to load.
    if(r.shareOnly) return;

    let conversationId = null;
    let tbReload = null;
    let tbPicker = null;
    const thread = document.getElementById('tbThread');
    try{
      const res = await fetch(SUITES_API_BASE + `/api/guest-profile?mode=conversation&orderId=${Number(orderId)}`, {
        headers: { 'Authorization': 'Bearer ' + guestAuthToken() }
      });
      const data = await res.json();
      if(!res.ok) throw new Error(data.error || 'Could not open this conversation.');
      conversationId = data.conversationId;
      const tbBox = document.getElementById('tbText');
      tbPicker = tbBox ? makeChatPhotoPicker(tbBox, tbBox.parentNode) : null;
      if(tbPicker) tbPicker.setAllowed(!!data.photosAllowed);
      if(typeof setChatClosed === 'function') setChatClosed(tbBox, !!data.messagingClosed);
      const drawTb = (msgs) => {
        thread.innerHTML = msgs.length
          ? msgs.map(m => `
              <div class="tb-msg ${m.sender_type === 'host' ? 'tb-msg-mine' : ''}">
                <span class="tb-msg-who">${esc(m.sender_type === 'host' ? 'You' : (m.sender_type === 'system' ? 'Aerva' : r.guestName))}</span>
                ${m.unsent ? `<span class="tb-msg-text msg-unsent-text">${unsentBubbleText(m.sender_type === 'host')}</span>`
                  : `${m.display_text ? `<span class="tb-msg-text">${esc(m.display_text)}</span>` : ''}${chatPhotosHtml(m.photos)}${canUnsendMessage(m, m.sender_type === 'host') ? unsendButtonHtml(m) : ''}${reactionRowHtml(m, m.sender_type === 'host', 'host')}`}
              </div>`).join('')
          : '<p class="tb-muted">No messages yet. Anything you send here reaches them in their Aerva messages.</p>';
        wireUnsendButtons(thread, () => conversationId, 'host', reloadTb);
        wireReactions(thread, () => conversationId, 'host', reloadTb);
        thread.scrollTop = thread.scrollHeight;
      };
      const reloadTb = async () => {
        const rr = await fetch(SUITES_API_BASE + `/api/guest-profile?mode=conversation&orderId=${Number(orderId)}`, { headers: { 'Authorization': 'Bearer ' + guestAuthToken() } });
        const dd = await rr.json().catch(() => ({}));
        if(rr.ok) drawTb(dd.messages || []);
      };
      tbReload = reloadTb;
      drawTb(data.messages || []);
    } catch(err){
      thread.innerHTML = `<p class="tb-muted">${esc(err.message || 'Could not open this conversation.')}</p>`;
    }

    document.getElementById('tbSend').addEventListener('click', async () => {
      const btn = document.getElementById('tbSend');
      const text = document.getElementById('tbText').value.trim();
      const note = document.getElementById('tbMsg');
      const photos = tbPicker && tbPicker.allowed ? tbPicker.urls() : [];
      if(tbPicker && tbPicker.busy()){ note.textContent = 'Photos are still uploading…'; return; }
      if(!text && !photos.length) return;
      if(!conversationId){ note.textContent = 'This conversation could not be opened.'; return; }
      btn.disabled = true; btn.textContent = 'Sending…';
      try{
        const res = await fetch(SUITES_API_BASE + '/api/guest-profile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
          body: JSON.stringify({ mode: 'send', conversationId, text, role: 'host', photos })
        });
        const data = await res.json();
        if(!res.ok) throw new Error(data.error || 'Could not send that.');
        document.getElementById('tbText').value = '';
        if(tbPicker) tbPicker.clear();
        // What was stored (contact details taken out), not what was typed.
        const shown = data.message && typeof data.message.display_text === 'string' ? data.message.display_text : text;
        if(tbReload) await tbReload();
        else thread.insertAdjacentHTML('beforeend',
          `<div class="tb-msg tb-msg-mine"><span class="tb-msg-who">You</span><span class="tb-msg-text">${esc(shown)}</span></div>`);
        if(data.message && data.message.was_redacted) note.textContent = 'Some content was removed \u2014 contact info can\u2019t be shared here.';
        thread.scrollTop = thread.scrollHeight;
        if(!(data.message && data.message.was_redacted)) note.textContent = '';
      } catch(err){
        note.textContent = err.message || 'Could not send that. Please try again.';
      }
      btn.disabled = false; btn.textContent = 'Send';
    });
  }

  function closeTodayBooking(){
    document.getElementById('todayBookingOverlay').style.display = 'none';
    document.body.style.overflow = '';
  }

  const BROWSE_TABS = ['catSuites', 'catExperience'];

  async function showTodayView(){
    document.body.classList.remove('showing-hero');
    hideMainViews();
    document.getElementById('todayView').style.display = 'block';
    document.title = 'Today — Aerva';
    BROWSE_TABS.forEach(id => {
      const el = document.getElementById(id);
      if(el) el.classList.remove('active');
    });
    const tab = document.getElementById('catToday');
    if(tab){ tab.style.display = ''; tab.classList.add('active'); }
    window.scrollTo({ top: 0 });
    try{
      const res = await fetch(SUITES_API_BASE + '/api/host-listings', {
        headers: { 'Authorization': 'Bearer ' + guestAuthToken() }
      });
      const data = await res.json();
      if(!res.ok) throw new Error(data.error || 'Could not load today.');
      renderTodayView(data.today);
    } catch(err){
      document.getElementById('todayList').innerHTML =
        '<p class="today-empty">Could not load today just now. Please refresh.</p>';
    }
  }

  // ---- Search-engine details for the page on screen ----
  // A home opened here (index.html?listing=<id>) names its own page for
  // Google as canonical — /stays/<name>-<city>, built by api/_seo.js with
  // the same slug rule — and carries its own description. Going back to
  // the homepage puts the site's own back.
  const SITE_DESCRIPTION = (document.querySelector('meta[name="description"]') || {}).content || '';
  function seoSlug(s){
    return String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
      .replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
  }
  function stayPathFor(l){
    const name = seoSlug(l.property_name), city = seoSlug(l.city);
    return '/stays/' + ((!city || name.split('-').join(' ').includes(city.split('-').join(' '))) ? (name || String(l.id)) : name + '-' + city);
  }
  function setSeoMeta(description, canonicalPath){
    let d = document.querySelector('meta[name="description"]');
    if(!d){ d = document.createElement('meta'); d.name = 'description'; document.head.appendChild(d); }
    d.content = description || SITE_DESCRIPTION;
    let c = document.querySelector('link[rel="canonical"]');
    if(!c){ c = document.createElement('link'); c.rel = 'canonical'; document.head.appendChild(c); }
    c.href = 'https://aerva.in' + (canonicalPath || '/');
  }
  function resetSeoMeta(){ setSeoMeta(SITE_DESCRIPTION, '/'); }

  function showFullListingPage(listing){
    if(listing && hiddenListingIds.has(Number(listing.id))){ alert('This listing is not available.'); return; }
    trackRecentlyViewed('stay', listing.id);
    document.body.classList.remove('showing-hero');
    document.getElementById('suites').style.display = 'none';
    document.getElementById('listingFullViewBody').innerHTML = buildListingDetailHtml(listing);
    loadListingReviews(document.getElementById('listingFullViewBody'), listing.id);
    document.getElementById('listingFullView').style.display = 'block';
    document.title = listing.property_name + ' — Aerva';
    try{
      const where = formatCityArea(listing);
      setSeoMeta(`${listing.property_name}: ${listing.property_type || 'home'} in ${where}` + (listing.nightly_rate ? `, from ₹${Math.round(Number(listing.nightly_rate)).toLocaleString('en-IN')} a night` : '') + '. Hand-picked and personally reviewed by Aerva.', stayPathFor(listing));
    }catch(e){}
    if(listing.property_type === 'Resort'){
      renderResortBookingCalendar(listing);
      renderRoomAwarePhotos(listing, []);
      document.getElementById('resortBookNowBtn').addEventListener('click', () => handleResortBookNow(listing));
      aervaPrefillBooking();
      return;
    }
    // Same add-on experiences as the booking modal ("This Property Also Offers").
    loadListingExperiences(listing);
    renderAvailabilityCalendar(listing);
    document.getElementById('listingBookNowBtn').addEventListener('click', () => handleListingBookNow(listing));
    aervaPrefillBooking();
  }

  document.getElementById('listingModalClose').addEventListener('click', closeListingDetail);
  document.getElementById('listingModalOverlay').addEventListener('click', (e) => {
    if(e.target.id === 'listingModalOverlay') closeListingDetail();
  });
  // Escape closes the listing too (it had only the × and a tap outside),
  // unless something opened over it (photos, host profile, log-in, payment,
  // a notice) — that layer handles its own Escape first.
  document.addEventListener('keydown', (e) => {
    if(e.key !== 'Escape' || e.defaultPrevented) return;
    const ov = document.getElementById('listingModalOverlay');
    if(!ov || ov.style.display !== 'flex') return;
    if(document.getElementById('aervaCheckoutTimer')) return; // payment window open
    const above = [...document.body.children].some(el => el !== ov && el.offsetParent === null && getComputedStyle(el).position === 'fixed'
      && getComputedStyle(el).display !== 'none' && getComputedStyle(el).visibility !== 'hidden' && el.getBoundingClientRect().height > 0
      && (Number(getComputedStyle(el).zIndex) || 0) > (Number(getComputedStyle(ov).zIndex) || 0));
    if(!above) closeListingDetail();
  });

  function handleCardGridClick(e){
    // "View on map" opens Google Maps in a new tab — let it behave
    // completely normally, not trigger the card's own click action.
    if(e.target.closest('a[target="_blank"]')) return;

    const card = e.target.closest('.suite-card');
    if(!card) return;
    e.preventDefault();

    // Suite and experience cards share the same card markup everywhere
    // (main grid, Recently Viewed, Near You) — each card carries its own
    // type-specific data attribute, so a click routes to the right
    // detail view regardless of which row it was clicked from.
    if(card.dataset.experienceId){
      openExperienceDetail(card.dataset.experienceId);
      return;
    }

    // Opens the same detail view (calendar + photos + booking, all on
    // one screen) right here as a modal — no new tab, no extra click
    // "inside" the listing first. The current search's dates/guests
    // carry straight over since renderAvailabilityCalendar reads the
    // live searchArrivalDate/searchDepartureDate/guestCounts variables
    // directly when there's no ?listing= URL to read them from instead.
    openListingDetail(card.dataset.listingId);
  }
  document.getElementById('suitesContainer').addEventListener('click', handleCardGridClick);
  document.getElementById('recentlyViewedContainer').addEventListener('click', handleCardGridClick);
  document.getElementById('nearbyContainer').addEventListener('click', handleCardGridClick);
  // Previously missing entirely — unavailable cards rendered but were
  // never wired to open anything, making "Check Availability" a label
  // with nothing behind it. openListingDetail() below builds the same
  // detail view (with its own fresh calendar) regardless of whether the
  // card arrived here dimmed as "unavailable" for the originally
  // searched dates.
  document.getElementById('unavailableContainer').addEventListener('click', handleCardGridClick);
  document.getElementById('specificMatchContainer').addEventListener('click', handleCardGridClick);
  document.getElementById('specificMatchNearbyContainer').addEventListener('click', handleCardGridClick);
  // Every other row built from the same cards: tapping anywhere on a card
  // opens it, not only its buttons.
  ['favoritesContainer', 'nearCityContainer', 'resortsContainer', 'wishlistContainer'].forEach(id => {
    const el = document.getElementById(id);
    if(el) el.addEventListener('click', handleCardGridClick);
  });

  document.getElementById('searchBtn').addEventListener('click', performSearch);

  // Recent-search suggestions — shown on focus when the "Where" field is
  // empty, independent of whether the Google Maps script has loaded (that
  // one only powers live address predictions once typing starts). This is
  // the only place that renders into #placeSuggestions before any input,
  // so it never fights with the Maps-driven predictions that take over
  // once the guest starts typing.
  (function initRecentSearchSuggestions(){
    const input = document.getElementById('searchCity');
    const dropdown = document.getElementById('placeSuggestions');
    if(!input || !dropdown) return;

    function showRecent(){
      const recents = getRecentSearches();
      if(recents.length === 0) return;
      dropdown.innerHTML = '<div class="place-suggest-heading">Recent Searches</div>' +
        recents.map((r, i) => `
          <button type="button" class="place-suggest-item" data-recent-index="${i}">${escapeMessageHtml(r.text)}</button>
        `).join('');
      dropdown.style.display = 'block';
      dropdown.querySelectorAll('[data-recent-index]').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const item = recents[Number(btn.dataset.recentIndex)];
          if(!item) return;
          input.value = item.text;
          document.getElementById('searchPlaceLat').value = item.lat || '';
          document.getElementById('searchPlaceLng').value = item.lng || '';
          dropdown.innerHTML = '';
          dropdown.style.display = 'none';
          openCalendar();
        });
      });
    }

    input.addEventListener('focus', function(){
      if(this.value.trim() === '') showRecent();
    });

    document.addEventListener('click', function(e){
      if(input.value.trim() === '' && !dropdown.contains(e.target) && e.target !== input){
        setTimeout(() => { dropdown.innerHTML = ''; dropdown.style.display = 'none'; }, 150);
      }
    });
  })();

  document.getElementById('sortPrice').addEventListener('change', applyFiltersAndRender);
  document.getElementById('badgeFilter').addEventListener('change', applyFiltersAndRender);
  document.getElementById('minPrice').addEventListener('input', applyFiltersAndRender);
  document.getElementById('maxPrice').addEventListener('input', applyFiltersAndRender);
  { const fcf = document.getElementById('freeCancelFilter'); if(fcf) fcf.addEventListener('change', applyFiltersAndRender); }
  // Debounced, and re-runs a full performSearch() rather than the
  // client-side applyFiltersAndRender() min/max price use — this filter
  // needs the server to check real per-room availability against the
  // searched dates, which isn't data the browser already has on hand.
  let roomsNeededDebounce = null;
  document.getElementById('roomsNeeded').addEventListener('input', () => {
    clearTimeout(roomsNeededDebounce);
    roomsNeededDebounce = setTimeout(performSearch, 500);
  });
  document.getElementById('clearFiltersBtn').addEventListener('click', () => {
    searchArrivalDate = '';
    searchDepartureDate = '';
    calSelectingStart = true;
    updateDateRangeBtn();
    document.getElementById('searchCity').value = '';
    // Setting .value directly doesn't fire 'input' on its own, which is
    // what actually re-shows the "Where" field's hint text once it's
    // empty again — without this, clearing filters would leave the
    // field looking permanently filled-in-but-blank.
    document.getElementById('searchCity').dispatchEvent(new Event('input'));
    // Previously left stale — a prior place search's exact coordinates
    // stayed in these hidden fields even after the visible text was
    // cleared, so performSearch() (which reads these first) could still
    // silently run a location-filtered search after "Clear Filters."
    document.getElementById('searchPlaceLat').value = '';
    document.getElementById('searchPlaceLng').value = '';
    specificListingMatch = null;
    specificListingMatchGeo = null;
    guestCounts.adults = 0;
    guestCounts.children = 0;
    guestCounts.infants = 0;
    guestCounts.pets = 0;
    updateGuestsTrigger();
    document.getElementById('sortPrice').value = '';
    document.getElementById('badgeFilter').value = '';
    document.getElementById('minPrice').value = '';
    document.getElementById('maxPrice').value = '';
    document.getElementById('roomsNeeded').value = '';
    { const fcf = document.getElementById('freeCancelFilter'); if(fcf) fcf.checked = false; }
    document.getElementById('searchStatus').style.display = 'none';
    searchStatusCounts = null;
    searchCenter = null;
    performSearch();
  });

  // ---- Custom calendar date-range picker (replaces native date inputs) ----
  let searchArrivalDate = '';
  let searchStatusCounts = null;
  let searchCenter = null; // the searched place's point (performSearch), for "in this city" vs "nearby"
  let searchDepartureDate = '';
  // Set by performSearch() when the typed/selected place resolves to one
  // specific Aerva property's own saved address (not just "somewhere in
  // this city") — see the matching logic there. Read by
  // applyFiltersAndRender() to swap the whole results area for the
  // "matched property + nearby" layout instead of the normal rows.
  let specificListingMatch = null;
  let specificListingMatchGeo = null;
  let calSelectingStart = true;
  let calViewYear, calViewMonth;

  const dateRangeBtn = document.getElementById('dateRangeBtn');
  const calendarDropdown = document.getElementById('calendarDropdown');
  const calMonthLabel1 = document.getElementById('calMonthLabel1');
  const calMonthLabel2 = document.getElementById('calMonthLabel2');
  const calendarGrid1 = document.getElementById('calendarGrid1');
  const calendarGrid2 = document.getElementById('calendarGrid2');
  const calendarHint = document.getElementById('calendarHint');
  const calPrevBtn = document.getElementById('calPrev');
  const calNextBtn = document.getElementById('calNext');
  const calendarClearBtn = document.getElementById('calendarClear');

  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

  // Earliest selectable date across the whole picker: tomorrow — matches
  // the existing "no same-day arrival" rule used elsewhere on the site.
  // Earliest arrival a guest can search: today — the same rule as each
  // home's own calendar and the server (aervaEarliestArrival /
  // _booking-rules.js), so a same-day stay can be found from the homepage,
  // and between midnight and 6 AM last night still counts.
  const calMinDate = (() => {
    let iso;
    try{ iso = aervaEarliestArrival('Asia/Kolkata'); }catch(e){ iso = null; }
    const d = iso ? new Date(iso + 'T00:00:00') : new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  })();

  (function initCalendarView(){
    calViewYear = calMinDate.getFullYear();
    calViewMonth = calMinDate.getMonth();
  })();

  function formatDateLabel(){
    const fmtShort = (iso) => {
      const d = new Date(iso);
      return d.getDate() + ' ' + MONTH_NAMES[d.getMonth()].slice(0, 3);
    };
    if(searchArrivalDate && searchDepartureDate) return fmtShort(searchArrivalDate) + ' – ' + fmtShort(searchDepartureDate);
    if(searchArrivalDate) return fmtShort(searchArrivalDate) + ' – Add departure';
    return '';
  }

  function updateDateRangeBtn(){
    const label = formatDateLabel();
    if(label){
      dateRangeBtn.textContent = label;
      dateRangeBtn.classList.remove('placeholder');
    } else {
      dateRangeBtn.textContent = 'Add dates';
      dateRangeBtn.classList.add('placeholder');
    }
  }

  function renderMonthPanel(year, month, labelEl, gridEl){
    labelEl.textContent = MONTH_NAMES[month] + ' ' + year;

    const firstDay = new Date(year, month, 1);
    const startWeekday = firstDay.getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    let html = '';
    for(let i = 0; i < startWeekday; i++){
      html += '<div class="calendar-day empty"></div>';
    }

    for(let day = 1; day <= daysInMonth; day++){
      const cellDate = new Date(year, month, day);
      cellDate.setHours(0, 0, 0, 0);
      const iso = toLocalDateStr(cellDate);
      const isDisabled = cellDate < calMinDate;

      let classes = 'calendar-day';
      if(isDisabled) classes += ' disabled';
      if(iso === searchArrivalDate) classes += ' selected-start';
      if(iso === searchDepartureDate) classes += ' selected-end';
      if(searchArrivalDate && searchDepartureDate && iso > searchArrivalDate && iso < searchDepartureDate) classes += ' in-range';

      html += `<div class="${classes}" data-date="${iso}">${day}</div>`;
    }

    gridEl.innerHTML = html;

    gridEl.querySelectorAll('.calendar-day:not(.disabled):not(.empty)').forEach(cell => {
      aervaDayCellA11y(cell, 'data-date');
      cell.addEventListener('click', (e) => {
        e.stopPropagation();
        handleDayClick(cell.dataset.date);
      });
    });
  }

  function renderCalendar(){
    const isMinMonth = (calViewYear === calMinDate.getFullYear() && calViewMonth === calMinDate.getMonth());
    calPrevBtn.disabled = isMinMonth;

    // Second panel is always exactly one month ahead of the first.
    let nextMonth = calViewMonth + 1;
    let nextYear = calViewYear;
    if(nextMonth > 11){ nextMonth = 0; nextYear++; }

    renderMonthPanel(calViewYear, calViewMonth, calMonthLabel1, calendarGrid1);
    renderMonthPanel(nextYear, nextMonth, calMonthLabel2, calendarGrid2);

    calendarHint.textContent = calSelectingStart ? 'Pick your arrival date' : 'Now pick your departure date';

    // Highlight whichever quick-pick (if any) matches the current
    // selection exactly — e.g. picking dates by hand that happen to be
    // "earliest arrival + 7 nights" shows "1 week" as selected too.
    const calMinIso = toLocalDateStr(calMinDate);
    document.querySelectorAll('.quick-date-btn').forEach(btn => {
      const matches = searchArrivalDate === calMinIso && searchDepartureDate === isoAddDays(calMinIso, Number(btn.dataset.days));
      btn.classList.toggle('selected', matches);
    });
  }

  function isoAddDays(iso, days){
    const d = new Date(iso + 'T00:00:00');
    d.setDate(d.getDate() + days);
    return toLocalDateStr(d);
  }

  // Quick date-range presets — always anchored to the earliest bookable
  // arrival date (calMinDate), so "1 week" always means "the soonest
  // possible week-long stay" rather than extending whatever the guest may
  // have already picked.
  function selectQuickDateRange(days){
    const arrivalIso = toLocalDateStr(calMinDate);
    searchArrivalDate = arrivalIso;
    searchDepartureDate = isoAddDays(arrivalIso, days);
    calSelectingStart = true;
    updateDateRangeBtn();
    renderCalendar();
    closeCalendar();
    openGuestsDropdown();
  }

  document.querySelectorAll('.quick-date-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      selectQuickDateRange(Number(btn.dataset.days));
    });
  });

  function handleDayClick(iso){
    if(calSelectingStart || !searchArrivalDate){
      searchArrivalDate = iso;
      searchDepartureDate = '';
      calSelectingStart = false;
    } else if(iso <= searchArrivalDate){
      // Picked an earlier (or same) date as the second click — start a
      // fresh range from here instead of allowing an invalid stay.
      searchArrivalDate = iso;
      searchDepartureDate = '';
      calSelectingStart = false;
    } else {
      searchDepartureDate = iso;
      calSelectingStart = true;
      // Chain straight into guest count — a fully automatic Where -> When
      // -> Who flow. This only works because the guests field is a custom
      // dropdown now, not a native <select>; browsers won't let JS force
      // a native select's picker open, which is why this used to just
      // move focus there instead of actually opening it.
      openGuestsDropdown();
    }
    updateDateRangeBtn();
    renderCalendar();
  }

  // Reparents a dropdown to a direct child of <body> and positions it
  // with fixed coordinates computed from its trigger's own wrapper —
  // bypasses this page's dropdown/underlying-card stacking-context bug
  // entirely (raising z-index alone didn't fix it: something in the
  // ancestor chain was creating its own isolated stacking context, which
  // meant no z-index value on the dropdown itself could ever win). Only
  // reparented on open; closing just hides it in place via the .open
  // class exactly as before, so nothing about the show/hide logic
  // elsewhere needs to change.
  //
  // On mobile, top/left are deliberately NOT set here — this is the
  // actual root cause of the calendar appearing off-center on phones:
  // an inline style set via JS always overrides a stylesheet rule
  // (including one inside a media query), no matter how specific that
  // rule is. The CSS media query centers the calendar as a fixed
  // overlay, but this function was silently fighting it on every single
  // open, recalculating top/left from the trigger button's position and
  // overwriting the centering underneath it. Desktop keeps the original
  // anchored-to-trigger behavior; only mobile skips it.
  function openDropdownAsPortal(dropdownEl, wrapperEl){
    document.body.appendChild(dropdownEl);
    dropdownEl.classList.add('open');
    openPanels.set(dropdownEl, wrapperEl);
    document.querySelectorAll('#searchBar > .search-field.is-active').forEach(f => f.classList.remove('is-active'));
    const seg = wrapperEl && wrapperEl.closest('#searchBar > .search-field');
    if(seg) seg.classList.add('is-active');
    placeSearchPanel(dropdownEl, wrapperEl, true);
    lockPageForPanel();
  }

  // Panels (calendar, guests, more filters) are anchored to the PAGE just
  // under their field, never to the window: before, they were fixed to the
  // window, so scrolling slid the page away and left the calendar floating
  // over other content (and wider than the screen on a laptop). While one is
  // open the page behind it is held still, so it stays exactly where it
  // opened; on opening, the page first scrolls just enough for the whole
  // panel to fit. Phones keep the centred sheet (CSS), page held still too.
  const openPanels = new Map();
  function headerBottom(){
    const h = document.getElementById('siteHeader');
    if(!h) return 0;
    const pos = getComputedStyle(h).position;
    return (pos === 'fixed' || pos === 'sticky') ? Math.max(0, h.getBoundingClientRect().bottom) : 0;
  }
  function placeSearchPanel(el, anchor, scrollToFit){
    if(window.innerWidth <= 640 || !anchor){
      el.style.position = 'fixed'; el.style.top = ''; el.style.left = ''; el.style.maxHeight = '';
      return;
    }
    el.style.position = 'absolute';
    el.style.maxHeight = '';
    const gap = 10, margin = 16, top0 = headerBottom() + 12;
    let r = anchor.getBoundingClientRect();
    if(scrollToFit){
      const overflowBelow = r.bottom + gap + el.offsetHeight + margin - window.innerHeight;
      let delta = 0;
      if(r.top < top0) delta = r.top - top0;
      else if(overflowBelow > 0) delta = Math.min(overflowBelow, r.top - top0);
      if(delta) { window.scrollBy({ top: delta, left: 0, behavior: 'instant' }); r = anchor.getBoundingClientRect(); }
    }
    const width = el.offsetWidth;
    const minLeft = margin, maxLeft = Math.max(margin, document.documentElement.clientWidth - width - margin);
    el.style.top = (r.bottom + gap + window.scrollY) + 'px';
    el.style.left = (Math.min(Math.max(r.left, minLeft), maxLeft) + window.scrollX) + 'px';
    const room = window.innerHeight - (r.bottom + gap) - margin;
    if(room > 200 && el.offsetHeight > room){ el.style.maxHeight = room + 'px'; el.style.overflowY = 'auto'; }
  }
  function lockPageForPanel(){
    const root = document.documentElement;
    if(root.classList.contains('search-panel-open')) return;
    const bar = window.innerWidth - root.clientWidth;
    if(bar > 0) document.body.style.paddingRight = bar + 'px';
    root.classList.add('search-panel-open');
  }
  function releasePanel(el){
    openPanels.delete(el);
    if(openPanels.size) return;
    document.documentElement.classList.remove('search-panel-open');
    document.body.style.paddingRight = '';
    document.querySelectorAll('#searchBar > .search-field.is-active').forEach(f => f.classList.remove('is-active'));
  }
  window.addEventListener('resize', () => { openPanels.forEach((anchor, el) => placeSearchPanel(el, anchor, false)); });
  document.addEventListener('keydown', (e) => {
    if(e.key !== 'Escape' || !openPanels.size) return;
    closeCalendar(); closeGuestsDropdown(); closeMoreFiltersDropdown();
  });
  // A click anywhere on a Where / When / Who segment acts on that field,
  // not just on its small text.
  document.querySelectorAll('#searchBar > .search-field').forEach(seg => {
    seg.addEventListener('click', (e) => {
      if(e.target.closest('button, input, a, select, .place-suggestions')) return;
      const target = seg.querySelector('#searchCity, #dateRangeBtn, #guestsTriggerBtn');
      if(!target) return;
      e.stopPropagation();
      if(target.tagName === 'INPUT') target.focus(); else target.click();
    });
  });

  function openCalendar(){
    closeGuestsDropdown();
    closeMoreFiltersDropdown();
    openDropdownAsPortal(calendarDropdown, dateRangeBtn.closest('.date-range-wrapper'));
    calendarDropdown.classList.add('open');
    // Moved to <body> for the same reason the dropdown itself is
    // (openDropdownAsPortal, above) — nested inside the search bar, this
    // backdrop would be contained by its .reveal.in transform (even a
    // translateY(0) counts — any non-"none" transform value creates a
    // new containing block for position:fixed), meaning it would only
    // ever cover the search bar's own box, not the actual viewport.
    document.body.appendChild(document.getElementById('calendarDropdownBackdrop'));
    document.getElementById('calendarDropdownBackdrop').classList.add('open');
    const anchor = searchArrivalDate ? new Date(searchArrivalDate) : calMinDate;
    calViewYear = anchor.getFullYear();
    calViewMonth = anchor.getMonth();
    renderCalendar();
    // Placed again now its months are drawn (its real height).
    placeSearchPanel(calendarDropdown, dateRangeBtn.closest('.date-range-wrapper'), true);
  }
  function closeCalendar(){
    calendarDropdown.classList.remove('open');
    releasePanel(calendarDropdown);
    document.getElementById('calendarDropdownBackdrop').classList.remove('open');
  }

  dateRangeBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if(calendarDropdown.classList.contains('open')) closeCalendar();
    else openCalendar();
  });

  calPrevBtn.addEventListener('click', () => {
    calViewMonth--;
    if(calViewMonth < 0){ calViewMonth = 11; calViewYear--; }
    renderCalendar();
  });
  calNextBtn.addEventListener('click', () => {
    calViewMonth++;
    if(calViewMonth > 11){ calViewMonth = 0; calViewYear++; }
    renderCalendar();
  });

  calendarClearBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    searchArrivalDate = '';
    searchDepartureDate = '';
    calSelectingStart = true;
    updateDateRangeBtn();
    renderCalendar();
  });

  document.addEventListener('click', (e) => {
    if(!calendarDropdown.contains(e.target) && e.target !== dateRangeBtn){
      closeCalendar();
    }
  });

  updateDateRangeBtn();

  // ---- Guests dropdown: a custom widget (not a native <select>) so it
  // can be opened programmatically — completing the Where -> When -> Who
  // chain automatically after departure is picked, which a native select
  // can't do (browsers don't let JS force its picker open). ----
  const guestsTriggerBtn = document.getElementById('guestsTriggerBtn');
  const guestsHiddenInput = document.getElementById('searchGuests');
  const guestsDropdown = document.getElementById('guestsDropdown');

  // Only adults + children count toward a home's sleeping capacity — the
  // hidden #searchGuests value (what performSearch actually sends to
  // get-listings.js's ?guests= filter) is that sum. Infants and pets are
  // tracked for the guest's own planning and shown in the trigger label,
  // but never affect which homes match a capacity search, same as most
  // booking sites treat them.
  const guestCounts = { adults: 0, children: 0, infants: 0, pets: 0 };
  const GUEST_MAX = { adults: 16, children: 12, infants: 5, pets: 5 };

  function capitalize(s){ return s.charAt(0).toUpperCase() + s.slice(1); }

  function guestsSummaryLabel(){
    const sleeping = guestCounts.adults + guestCounts.children;
    if(sleeping === 0 && guestCounts.infants === 0 && guestCounts.pets === 0) return 'Add guests';
    let label = sleeping + (sleeping === 1 ? ' guest' : ' guests');
    const extras = [];
    if(guestCounts.infants > 0) extras.push(guestCounts.infants + (guestCounts.infants === 1 ? ' infant' : ' infants'));
    if(guestCounts.pets > 0) extras.push(guestCounts.pets + (guestCounts.pets === 1 ? ' pet' : ' pets'));
    if(extras.length) label += ', ' + extras.join(', ');
    return label;
  }

  function updateGuestsTrigger(){
    const sleeping = guestCounts.adults + guestCounts.children;
    guestsHiddenInput.value = sleeping > 0 ? String(sleeping) : '';
    guestsTriggerBtn.textContent = guestsSummaryLabel();
    guestsTriggerBtn.classList.toggle('placeholder', sleeping === 0 && guestCounts.infants === 0 && guestCounts.pets === 0);

    Object.keys(guestCounts).forEach(type => {
      const countEl = document.getElementById('guestCount' + capitalize(type));
      if(countEl) countEl.textContent = guestCounts[type];
      const decBtn = guestsDropdown.querySelector(`.guest-step-btn[data-type="${type}"][data-action="dec"]`);
      if(decBtn) decBtn.disabled = guestCounts[type] <= 0;
      const incBtn = guestsDropdown.querySelector(`.guest-step-btn[data-type="${type}"][data-action="inc"]`);
      if(incBtn) incBtn.disabled = guestCounts[type] >= GUEST_MAX[type];
    });
  }

  function openGuestsDropdown(){
    closeCalendar();
    closeMoreFiltersDropdown();
    openDropdownAsPortal(guestsDropdown, guestsTriggerBtn.closest('.search-field'));
    guestsDropdown.classList.add('open');
    document.body.appendChild(document.getElementById('guestsDropdownBackdrop'));
    document.getElementById('guestsDropdownBackdrop').classList.add('open');
  }
  function closeGuestsDropdown(){
    guestsDropdown.classList.remove('open');
    releasePanel(guestsDropdown);
    document.getElementById('guestsDropdownBackdrop').classList.remove('open');
  }

  guestsTriggerBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if(guestsDropdown.classList.contains('open')) closeGuestsDropdown();
    else openGuestsDropdown();
  });

  guestsDropdown.querySelectorAll('.guest-step-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const type = btn.dataset.type;
      const delta = btn.dataset.action === 'inc' ? 1 : -1;
      const next = guestCounts[type] + delta;
      if(next < 0 || next > GUEST_MAX[type]) return;
      guestCounts[type] = next;
      updateGuestsTrigger();
      // Pets drive a client-side amenity filter (pet-friendly homes only)
      // that doesn't need a fresh server search — re-render immediately,
      // same as changing the price filters does. Only once listings have
      // actually loaded, so this doesn't fire prematurely on page load.
      if(type === 'pets' && approvedListings.length > 0) applyFiltersAndRender();
    });
  });

  document.addEventListener('click', (e) => {
    if(!guestsDropdown.contains(e.target) && e.target !== guestsTriggerBtn){
      closeGuestsDropdown();
    }
  });

  updateGuestsTrigger();

  // ---- More Filters: Sort By / Min Price / Max Price, tucked behind a
  // toggle so the filter row only ever shows Clear Filters and Near Me by
  // default. Same open/close pattern as the calendar and guests dropdowns
  // — only one of the three is ever open at once. ----
  const moreFiltersBtn = document.getElementById('moreFiltersBtn');
  const moreFiltersDropdown = document.getElementById('moreFiltersDropdown');

  function openMoreFiltersDropdown(){
    closeCalendar();
    closeGuestsDropdown();
    openDropdownAsPortal(moreFiltersDropdown, moreFiltersBtn.closest('.more-filters-wrapper'));
    moreFiltersDropdown.classList.add('open');
    document.body.appendChild(document.getElementById('moreFiltersDropdownBackdrop'));
    document.getElementById('moreFiltersDropdownBackdrop').classList.add('open');
  }
  function closeMoreFiltersDropdown(){
    moreFiltersDropdown.classList.remove('open');
    releasePanel(moreFiltersDropdown);
    document.getElementById('moreFiltersDropdownBackdrop').classList.remove('open');
  }

  // ---- Only one pop-up open at a time ----
  // Each opener stops its click from reaching the page, so the usual
  // "click anywhere else closes it" listeners never heard a click on a
  // different opener — and the account menu stayed open under the date
  // picker. This listens in the capture phase (before any opener runs) and
  // closes every pop-up the click is not inside, whichever opener it hits.
  document.addEventListener('click', (e) => {
    const t = e.target;
    const inside = (...els) => els.some(el => el && el.contains(t));
    const menu = document.getElementById('navAccountMenu'), menuBtn = document.getElementById('navAccountTrigger');
    if(menu && menu.classList.contains('open') && !inside(menu, menuBtn)) menu.classList.remove('open');
    const bellPanel = document.getElementById('navNotifPanel'), bellBtn = document.getElementById('navBell');
    if(bellPanel && bellPanel.style.display !== 'none' && !inside(bellPanel, bellBtn)) bellPanel.style.display = 'none';
    if(calendarDropdown.classList.contains('open') && !inside(calendarDropdown, dateRangeBtn)) closeCalendar();
    if(guestsDropdown.classList.contains('open') && !inside(guestsDropdown, guestsTriggerBtn)) closeGuestsDropdown();
    if(moreFiltersDropdown.classList.contains('open') && !inside(moreFiltersDropdown, moreFiltersBtn)) closeMoreFiltersDropdown();
    [['currencyTriggerBtn', 'currencyDropdown'], ['currencyTriggerBtnMobile', 'currencyDropdownMobile']].forEach(([b, d]) => {
      const dd = document.getElementById(d);
      if(dd && dd.classList.contains('open') && !inside(dd, document.getElementById(b))) dd.classList.remove('open');
    });
  }, true);

  // Explicit close (×) buttons and backdrop-tap-to-dismiss — only
  // visible/active on mobile (see the max-width:640px rule), where this
  // becomes a centered overlay rather than an anchored dropdown a guest
  // could tap outside of on the visible page behind it.
  document.getElementById('calendarDropdownCloseBtn').addEventListener('click', (e) => { e.stopPropagation(); closeCalendar(); });
  document.getElementById('calendarDropdownBackdrop').addEventListener('click', closeCalendar);
  document.getElementById('guestsDropdownCloseBtn').addEventListener('click', (e) => { e.stopPropagation(); closeGuestsDropdown(); });
  document.getElementById('guestsDropdownBackdrop').addEventListener('click', closeGuestsDropdown);
  document.getElementById('moreFiltersDropdownCloseBtn').addEventListener('click', (e) => { e.stopPropagation(); closeMoreFiltersDropdown(); });
  document.getElementById('moreFiltersDropdownBackdrop').addEventListener('click', closeMoreFiltersDropdown);

  moreFiltersBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    if(moreFiltersDropdown.classList.contains('open')) closeMoreFiltersDropdown();
    else openMoreFiltersDropdown();
  });

  document.addEventListener('click', (e) => {
    if(!moreFiltersDropdown.contains(e.target) && e.target !== moreFiltersBtn){
      closeMoreFiltersDropdown();
    }
  });

  // ---- One shared fetch, powering both the Suites section and the ----
  // ---- Reserve form's "Home" dropdown, so they never disagree. ----
  // Cycles the Place field's animated hint through real property
  // locations (deduplicated city names from current listings) — gives a
  // sense of where Aerva actually has homes before the guest types
  // anything, rather than a static, generic placeholder.
  function startPlaceHintRotation(){
    const cities = [...new Set(approvedListings.map(l => l.city).filter(Boolean))];
    const hintTextEl = document.getElementById('placeHintText');
    if(!hintTextEl || cities.length === 0) return;

    let idx = 0;
    hintTextEl.textContent = 'Try “' + cities[0] + '”';

    setInterval(() => {
      idx = (idx + 1) % cities.length;
      hintTextEl.style.opacity = '0';
      setTimeout(() => {
        const field = document.getElementById('searchCity');
        const hint = document.getElementById('placeHint');
        if(field && hint) hint.style.opacity = field.value === '' ? '1' : '0';
        hintTextEl.textContent = 'Try “' + cities[idx] + '”';
        hintTextEl.style.opacity = '1';
      }, 400);
    }, 2600);
  }

  // Crossfading background behind the search/filter bar, built from one
  // representative photo per listing (cover choice first, falling back to
  // whatever's actually available) — real property photos, not stock
  // imagery, so it stays accurate as listings change.
  // Replaces the old fixed-retreat "Day at Aerva" narrative with real
  // paid amenities pulled from actual approved listings — each shown
  // tied to the specific property offering it, since price and
  // availability genuinely vary host to host rather than being one
  // shared experience.
  // Real counts from actual approved listings, rather than a fixed
  // claim that inevitably goes stale as listings are added.
  function renderLocationStats(){
    const citiesEl = document.getElementById('locStatCities');
    const homesEl = document.getElementById('locStatHomes');
    if(!citiesEl || !homesEl) return;

    const uniqueCities = [...new Set(approvedListings.map(l => l.city).filter(Boolean))];
    citiesEl.textContent = uniqueCities.length ? uniqueCities.join(', ') : '—';
    homesEl.textContent = approvedListings.length ? String(approvedListings.length) : '—';
  }

  function renderExperienceSection(){
    const listEl = document.getElementById('experienceList');
    if(!listEl) return;

    const rows = [];
    approvedListings.forEach(l => {
      const amenities = Array.isArray(l.paid_amenities) ? l.paid_amenities : [];
      amenities.forEach(a => {
        rows.push({ listingName: l.property_name, name: a.name, price: a.price, description: a.description });
      });
    });

    if(rows.length === 0){
      listEl.innerHTML = `<div class="exp-row"><p style="opacity:0.65;">Hosts haven't added any bookable experiences yet — check back soon, or ask your host directly once you've reserved a stay.</p></div>`;
      return;
    }

    listEl.innerHTML = rows.slice(0, 8).map(r => `
      <div class="exp-row">
        <div class="exp-time">${guestPrice(r.price)}/night</div>
        <h3>${escapeMessageHtml(r.name)}</h3>
        <p>${r.description ? escapeMessageHtml(r.description) + ' — ' : ''}Available at ${escapeMessageHtml(r.listingName)}.</p>
      </div>
    `).join('');
  }

  async function startFilterBgSlideshow(){
    const slidesEl = document.getElementById('filterBgSlides');
    if(!slidesEl) return;

    // The admin's chosen photos win if any are set (see admin.html and
    // get-pending-listings.js's POST mode); otherwise prefers approved
    // listings' own cover photos — but a cover photo is only ever set
    // when a host explicitly picks one later in "Manage Price & Offers"
    // (see update-listing-pricing.js); it's never set at initial
    // submission, so most/all listings can easily have none yet. Falling
    // back to ANY exterior/interior photo per-listing was the old
    // behavior this was deliberately changed away from — but falling
    // back to nothing at all just leaves the hero blank, which is worse.
    // The middle ground: use cover photos only when there are enough of
    // them to actually make a slideshow; otherwise fall back to regular
    // photos for now, and naturally shift to cover-photos-only on its own
    // as hosts set them.
    let photos = [];
    try {
      const res = await fetch(SUITES_API_BASE + '/api/get-listings?siteBackground=1');
      if(res.ok){
        const data = await res.json();
        photos = Array.isArray(data.images) ? data.images : [];
      }
    } catch(err){
      console.error('Could not load admin background images, falling back to listing photos:', err);
    }

    // Ten slides, filled in order of preference: the admin's chosen
    // photos, then hosts' cover photos, then other listing photos. It used
    // to switch to cover photos ONLY as soon as three listings had one —
    // which is why the hero dropped from 7–8 slides to 3. The rest are
    // taken one photo per home per pass, so ten slides are spread across
    // homes rather than all coming from the first listing.
    const SLIDE_TARGET = 10;
    const picked = [];
    const seen = new Set();
    const add = (u) => {
      if(typeof u !== 'string' || !u || seen.has(u) || picked.length >= SLIDE_TARGET) return;
      seen.add(u);
      picked.push(u);
    };
    photos.forEach(add);
    approvedListings.forEach(l => add(l.cover_photo_url));
    const pools = approvedListings.map(l => [
      ...(Array.isArray(l.interior_photo_urls) ? l.interior_photo_urls : []),
      ...(Array.isArray(l.exterior_photo_urls) ? l.exterior_photo_urls : [])
    ]);
    for(let round = 0; picked.length < SLIDE_TARGET && pools.some(p => round < p.length); round++){
      pools.forEach(p => add(p[round]));
    }
    photos = picked;

    if(photos.length === 0) return;

    slidesEl.innerHTML = photos.map((url, i) =>
      `<img src="${escapeMessageHtml(url)}" alt="" loading="lazy" class="${i === 0 ? 'is-active' : ''}">`
    ).join('');

    const dotsEl = document.getElementById('filterBgDots');
    if(photos.length === 1){
      if(dotsEl) dotsEl.innerHTML = '';
      return; // nothing to crossfade to, no dots needed for one photo
    }

    let idx = 0;
    const imgs = slidesEl.querySelectorAll('img');

    function goToSlide(newIdx){
      imgs[idx].classList.remove('is-active');
      if(dotsEl) dotsEl.children[idx].classList.remove('is-active');
      idx = newIdx;
      imgs[idx].classList.add('is-active');
      if(dotsEl) dotsEl.children[idx].classList.add('is-active');
    }

    if(dotsEl){
      dotsEl.innerHTML = photos.map((_, i) =>
        `<button type="button" class="${i === 0 ? 'is-active' : ''}" aria-label="Show photo ${i + 1}"></button>`
      ).join('');
      Array.from(dotsEl.children).forEach((dot, i) => {
        dot.addEventListener('click', () => goToSlide(i));
      });
    }

    setInterval(() => {
      goToSlide((idx + 1) % imgs.length);
    }, 5000);
  }

  async function initSite(){
    try{
      await hiddenListingsReady;
      const res = await fetch(SUITES_API_BASE + '/api/get-listings');
      if(!res.ok) throw new Error('Failed to load listings');
      const data = await res.json();
      approvedListings = visibleOnly(data.listings || []);
      listingsById = {};
      approvedListings.forEach(l => { listingsById[l.id] = l; });
      startPlaceHintRotation();
      startFilterBgSlideshow();
      renderExperienceSection();
      renderLocationStats();
    } catch(err){
      approvedListings = [];
      listingsById = {};
      document.getElementById('suitesContainer').innerHTML =
        '<div class="suites-empty">Could not load homes right now. Please refresh, or check back shortly.</div>';
      return;
    }
    applyFiltersAndRender();

    // Experiences are now needed immediately for the combined "All" view
    // (not just when the guest specifically opens the Experience filter),
    // so this fetch always runs — applyFiltersAndRender() runs again on
    // its own once this resolves (see loadExperiences), merging
    // experience cards into the grid already showing suites.
    loadExperiences();

    // Opened as a direct link to one listing or experience — from a host
    // profile card, a co-host's listing slides, a shared link. BOTH kinds
    // are looked for whichever parameter was used: a card only knows what
    // it was told, and landing on the homepage with no explanation is the
    // worst possible answer to a link someone deliberately followed.
    const linkParams = new URLSearchParams(window.location.search);
    // A group booking's share link, or a gift's link (aervaShowGroupPage / aervaShowGiftPage).
    if(linkParams.get('group')){ aervaShowGroupPage(linkParams.get('group')); return; }
    if(linkParams.get('gift') || linkParams.get('giftId')){ aervaShowGiftPage(linkParams.get('gift'), linkParams.get('giftId')); return; }
    const requestedId = linkParams.get('listing') || linkParams.get('experience');
    if(requestedId){
      if(listingsById[requestedId]){ showFullListingPage(listingsById[requestedId]); return; }
      // Experiences load separately; wait for them before giving up.
      await loadExperiences();
      if(experiencesById[requestedId]){ showExperienceDetailPage(experiencesById[requestedId]); return; }
      if(listingsById[requestedId]){ showFullListingPage(listingsById[requestedId]); return; }
      // Genuinely not bookable now (deactivated, removed, or under
      // review). Say so, rather than showing the homepage as if the link
      // had been mistyped.
      const note = document.createElement('div');
      note.setAttribute('role', 'status');
      note.className = 'link-gone';
      note.innerHTML = '<span>That listing is not available right now — it may have been taken down by its host.</span>'
        + '<button type="button" aria-label="Close">\u00d7</button>';
      document.body.appendChild(note);
      note.querySelector('button').addEventListener('click', () => note.remove());
      setTimeout(() => note.remove(), 10000);
    }

    // List Property and List Experience are still their own separate
    // full pages. "All"/"Suites"/"Aerva Experience" are no longer
    // separate sections at all — they're the SAME combined grid,
    // filtered differently (see setCategoryFilter) — so a ?view= of
    // 'suites' or 'experiences' here just sets the initial filter state
    // rather than swapping to a different section.
    const requestedView = new URLSearchParams(window.location.search).get('view');
    // Came back from signing in with a co-host invitation still to answer.
    if(!requestedView && pendingInvite() && guestAuthToken()) openCohostCenter();
    if(requestedView === 'list-property'){
      document.body.classList.remove('showing-hero');
      document.getElementById('suites').style.display = 'none';
      document.getElementById('add-listing').style.display = 'block';
      document.title = 'List your property — Aerva';
    } else if(requestedView === 'list-experience'){
      document.body.classList.remove('showing-hero');
      document.getElementById('suites').style.display = 'none';
      document.getElementById('list-experience').style.display = 'block';
      document.title = 'List your experience — Aerva';
    } else if(requestedView === 'my-bookings'){
      document.body.classList.remove('showing-hero');
      document.getElementById('suites').style.display = 'none';
      document.getElementById('my-bookings').style.display = 'block';
      document.title = 'My Bookings — Aerva';
      loadMyBookings();
    } else if(requestedView === 'wishlist'){
      showWishlistView();
    } else if(requestedView === 'suites'){
      setCategoryFilter('suites');
    } else if(requestedView === 'experiences'){
      setCategoryFilter('experiences');
    } else if(requestedView === 'all'){
      // The combined view is gone: Suites shows stays, Aerva Experience
      // shows experiences. An old ?view=all link lands on Suites.
      setCategoryFilter('suites');
    } else if(requestedView === 'today'){
      showTodayView();
    } else if(requestedView === 'profile'){
      showProfileView();
    } else if(requestedView === 'settings'){
      showSettingsView();
    } else if(requestedView === 'policies'){
      showPoliciesView();
    } else if(requestedView === 'privacy'){
      showPrivacyView();
    } else if(requestedView === 'terms'){
      showTermsView();
    } else if(requestedView === 'help'){
      // The Resolution Center (aerva-help.js).
      hideMainViews();
      document.body.classList.remove('showing-hero');
      if(window.AervaHelp) window.AervaHelp.show();
    } else if(requestedView === 'cohost'){
      openCohostCenter();
    } else if(requestedView === 'messages'){
      // The Messages icon on every other page links here (see
      // aerva-header.js): the inbox lives on this page.
      openInboxOverlay();
    }
  }

  // Switches which cards show in the one combined grid — 'all' shows
  // suites and experiences together, 'suites'/'experiences' show just
  // that type. Updates the active nav tab and the section's own
  // heading/subhead to match, then re-renders from whatever data is
  // already loaded (no re-fetch needed, this is purely a display filter).
  function setCategoryFilter(filter){
    // Leaving the profile or Today: bring the browse grid back.
    const profileSection = document.getElementById('profileView');
    if(profileSection && profileSection.style.display === 'block'){
      profileSection.style.display = 'none';
      document.getElementById('suites').style.display = 'block';
      document.body.classList.add('showing-hero');
      document.title = 'Aerva — Stay Elegant';
    }
    const todaySection = document.getElementById('todayView');
    if(todaySection && todaySection.style.display === 'block'){
      todaySection.style.display = 'none';
      document.getElementById('suites').style.display = 'block';
      document.body.classList.add('showing-hero');
      document.title = 'Aerva — Stay Elegant';
    }
    // Same for a single booking's page, which had been left out here.
    const bookingSection = document.getElementById('bookingView');
    if(bookingSection && bookingSection.style.display === 'block'){
      bookingSection.style.display = 'none';
      document.getElementById('suites').style.display = 'block';
      document.body.classList.add('showing-hero');
      document.title = 'Aerva — Stay Elegant';
    }
    const todayTab = document.getElementById('catToday');
    if(todayTab) todayTab.classList.remove('active');
    currentCategoryFilter = filter;
    document.getElementById('catSuites').classList.toggle('active', filter === 'suites');
    document.getElementById('catExperience').classList.toggle('active', filter === 'experiences');

    const eyebrowEl = document.getElementById('browseEyebrow');
    const headingEl = document.getElementById('browseHeading');
    const subheadEl = document.getElementById('browseSubhead');
    // innerHTML, not textContent — the heading always carries one
    // italicized accent word (see .hero-headline em), matching the
    // premium hero treatment; textContent would silently strip that
    // styling out every time the filter switches.
    document.title = filter === 'experiences' ? 'Aerva Experience — Aerva' : 'Suites — Aerva';
    // The grid's heading names the tab it belongs to.
    const availableHeadingEl = document.getElementById('availableHeading');
    if(availableHeadingEl) availableHeadingEl.textContent = filter === 'experiences' ? 'Aerva Experience' : 'Suites';
    if(filter === 'suites'){
      eyebrowEl.textContent = 'Where You Stay';
      headingEl.innerHTML = 'Homes, personally <em>chosen</em>.';
      subheadEl.textContent = 'Every Aerva home is reviewed and approved individually — never a template, never bulk-listed.';
    } else if(filter === 'experiences'){
      eyebrowEl.textContent = 'Aerva Experience';
      headingEl.innerHTML = 'Moments, not just <em>a stay</em>.';
      subheadEl.textContent = 'Guided treks, cooking classes, local tours — hosted at or near an Aerva property, bookable on their own or alongside a stay.';
    } else {
      eyebrowEl.textContent = 'Discover Aerva';
      headingEl.innerHTML = 'Homes and moments, <em>together</em>.';
      subheadEl.textContent = 'Every stay and every experience on Aerva, reviewed and approved individually — browse both at once, or filter to just one.';
    }
    applyFiltersAndRender();
  }

  const tbClose = document.getElementById('todayBookingClose');
  if(tbClose) tbClose.addEventListener('click', closeTodayBooking);
  const tbOverlay = document.getElementById('todayBookingOverlay');
  if(tbOverlay) tbOverlay.addEventListener('click', (e) => { if(e.target === tbOverlay) closeTodayBooking(); });
  document.addEventListener('keydown', (e) => {
    if(e.key === 'Escape' && tbOverlay && tbOverlay.style.display === 'flex') closeTodayBooking();
  });

  const catTodayEl = document.getElementById('catToday');
  if(catTodayEl){
    catTodayEl.addEventListener('click', (e) => { e.preventDefault(); showTodayView(); });
  }

  // All three tabs stay real, navigable links (so a direct visit or a
  // bookmark to ?view=suites still works correctly via initSite above) —
  // but when the guest is already sitting on this same combined grid,
  // clicking one just switches the filter instantly instead of doing a
  // full page reload for what is, underneath, the exact same data.
  ['catSuites', 'catExperience'].forEach(id => {
    const el = document.getElementById(id);
    if(!el) return;
    el.addEventListener('click', (e) => {
      const suitesSection = document.getElementById('suites');
      if(!suitesSection || suitesSection.style.display === 'none') return; // let it navigate normally
      e.preventDefault();
      const filter = id === 'catSuites' ? 'suites' : 'experiences';
      const url = `index.html?view=${filter}`;
      window.history.pushState({}, '', url);
      setCategoryFilter(filter);
      window.scrollTo({ top: suitesSection.offsetTop - 90, behavior: 'smooth' });
    });
  });

  // ---- Currency picker: builds both the desktop and mobile dropdowns
  // from SUPPORTED_CURRENCIES, so they can never drift out of sync with
  // each other. ----
  (function initCurrencyPicker(){
    const pairs = [
      { trigger: document.getElementById('currencyTriggerBtn'), dropdown: document.getElementById('currencyDropdown') },
      { trigger: document.getElementById('currencyTriggerBtnMobile'), dropdown: document.getElementById('currencyDropdownMobile') },
    ];

    function renderOptions(dropdown){
      dropdown.innerHTML = Object.keys(SUPPORTED_CURRENCIES).map(code => `
        <button type="button" class="currency-option${code === currentCurrency ? ' selected' : ''}" data-currency="${code}">
          <span>${code}</span><span>${SUPPORTED_CURRENCIES[code].symbol}</span>
        </button>
      `).join('');
      dropdown.querySelectorAll('.currency-option').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          setCurrency(btn.dataset.currency, true);
          pairs.forEach(p => p.dropdown.classList.remove('open'));
        });
      });
    }

    pairs.forEach(({ trigger, dropdown }) => {
      if(!trigger || !dropdown) return;
      trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = dropdown.classList.contains('open');
        pairs.forEach(p => p.dropdown.classList.remove('open'));
        if(!isOpen){
          renderOptions(dropdown);
          dropdown.classList.add('open');
        }
      });
    });

    document.addEventListener('click', (e) => {
      pairs.forEach(({ trigger, dropdown }) => {
        if(dropdown && !dropdown.contains(e.target) && e.target !== trigger){
          dropdown.classList.remove('open');
        }
      });
    });
  })();

  initCurrency();
  trackVisitOnce();
  loadLiveProof();
  initSite();

  // ---- Mobile nav toggle ----
  (function initMobileNav(){
    const toggle = document.getElementById('navToggle');
    const panel = document.getElementById('mobileNavPanel');
    const scrim = document.getElementById('mobileNavScrim');
    if(!toggle || !panel || !scrim) return;

    function closeMenu(){
      toggle.classList.remove('is-open');
      toggle.setAttribute('aria-expanded', 'false');
      panel.classList.remove('is-open');
      scrim.classList.remove('is-open');
      document.body.style.overflow = '';
    }
    function openMenu(){
      toggle.classList.add('is-open');
      toggle.setAttribute('aria-expanded', 'true');
      panel.classList.add('is-open');
      scrim.classList.add('is-open');
      document.body.style.overflow = 'hidden';
    }
    toggle.addEventListener('click', () => {
      if(panel.classList.contains('is-open')) closeMenu(); else openMenu();
    });
    scrim.addEventListener('click', closeMenu);
    panel.querySelectorAll('a').forEach(a => a.addEventListener('click', closeMenu));
    // The open panel covers the header's menu button (its × state), so the
    // only way out was the thin strip of page beside it. A close button in
    // the panel itself, and Escape.
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'mobile-nav-close';
    closeBtn.setAttribute('aria-label', 'Close menu');
    closeBtn.innerHTML = '&times;';
    closeBtn.style.cssText = 'position:absolute; top:calc(18px + env(safe-area-inset-top, 0px)); right:18px; width:44px; height:44px; border:none; background:none; font-size:30px; line-height:1; color:var(--ink); cursor:pointer;';
    closeBtn.addEventListener('click', () => { closeMenu(); toggle.focus(); });
    panel.insertBefore(closeBtn, panel.firstChild);
    document.addEventListener('keydown', (e) => { if(e.key === 'Escape' && panel.classList.contains('is-open')){ closeMenu(); toggle.focus(); } });
  })();

  // ---- Standing badge beside the name ----
  // One badge, whichever applies. guest-auth.js decides which: a host's
  // own listing badge wins over their guest tier, since that is the one
  // strangers see. The elite rungs reuse the same feather silhouette the
  // listing cards use, so a host recognises their own mark.
  function renderNavTierBadge(tier){
    const el = document.getElementById('guestTierBadge');
    if(!el) return;
    if(!tier || !tier.label){ el.style.display = 'none'; el.innerHTML = ''; return; }
    const dia = tier.icon === 'feather-diamond';
    const gold = tier.icon === 'feather-gold';
    const uid = 'nvt' + Math.random().toString(36).slice(2, 7);
    let svg = '';
    if(dia || gold){
      const stops = dia
        ? '<stop offset="0" stop-color="#eaf6ff"/><stop offset="0.4" stop-color="#b9d9ec"/><stop offset="1" stop-color="#dff1fb"/>'
        : '<stop offset="0" stop-color="#f0d27a"/><stop offset="0.45" stop-color="#c9a227"/><stop offset="1" stop-color="#8a6c39"/>';
      svg = `<svg viewBox="-26 -40 52 86" aria-hidden="true">
        <defs><linearGradient id="${uid}" x1="0" y1="0" x2="${dia ? 1 : 0}" y2="1">${stops}</linearGradient></defs>
        <path d="${FEATHER_PATH}" fill="url(#${uid})" stroke="${dia ? '#dff1fb' : '#f0d27a'}" stroke-width="2"/>
        <path d="${FEATHER_BARBS}" stroke="${dia ? '#ffffff' : '#fff3cf'}" stroke-width="1.3" opacity="0.7" fill="none"/>
      </svg>`;
    }
    el.className = 'nav-tier-badge' + (dia ? ' tier-diamond' : gold ? ' tier-gold' : '');
    // The blurb is a styled bubble rather than a title attribute. Two
    // reasons: the native tooltip is unstyleable and was rendering clipped
    // against the header, and .title is a PLAIN TEXT property — escaping
    // it, as this used to, makes a blurb containing an apostrophe display
    // a literal &#39; to the user.
    el.innerHTML = svg + escapeMessageHtml(tier.label)
      + (tier.blurb ? `<span class="nav-tier-tip">${escapeMessageHtml(tier.blurb)}</span>` : '');
    el.removeAttribute('title');
    el.style.display = 'inline-flex';
  }

  // ---- Guest login status in the nav bar ----
  // Checks for a stored session token on every page load and asks the
  // backend to confirm it's still valid — this is what makes a returning
  // guest show as logged in automatically ("remembered in the browser"),
  // without ever storing their password client-side, only the signed
  // session token.
  (function initGuestNav(){
    const guestLoginLink = document.getElementById('guestLoginLink');
    const guestAccountBox = document.getElementById('guestAccountBox');
    const guestNameDisplay = document.getElementById('guestNameDisplay');
    const myListingsLink = document.getElementById('myListingsLink');
    const guestLogoutLink = document.getElementById('guestLogoutLink');
    // Mirrors the same elements inside the mobile slide-out panel, so a
    // returning guest sees their login state there too, not just in the
    // desktop nav bar which is hidden on small screens.
    const guestLoginLinkMobile = document.getElementById('guestLoginLinkMobile');
    const guestAccountBoxMobile = document.getElementById('guestAccountBoxMobile');
    const guestNameDisplayMobile = document.getElementById('guestNameDisplayMobile');
    const myListingsLinkMobile = document.getElementById('myListingsLinkMobile');
    const guestLogoutLinkMobile = document.getElementById('guestLogoutLinkMobile');

    function clearGuestSession(){
      safeStorage.remove('aerva_guest_session');
      setRecentlyViewedOwner(null);
      clearLoggedOutPersonalData();
      safeStorage.remove('aerva_guest_email');
      safeStorage.remove('aerva_guest_name');
      try{ renderNavTierBadge(null); }catch(e){}
      // A clone payload is a full copy of one host's listing, parked in
      // storage between the dashboard and the listing form. It is normally
      // consumed on arrival, but a host who clicks Clone and then logs out
      // without completing would otherwise leave it for whoever logs in
      // next on this device.
      safeStorage.remove('aerva_clone_listing');
      safeStorage.remove('aerva_clone_with_photos');
      // Co-host mode belongs to the person who started it.
      safeStorage.remove('aerva_acting_host');
      safeStorage.remove('aerva_pending_cohost_invite');
      // Which notifications were read, and cached co-host conversations,
      // belong to this account — not to whoever logs in next here.
      safeStorage.remove('aerva_notifications_read');
      try{ sessionStorage.removeItem('aerva_cohost_convs'); }catch(e){}
    }

    window.aervaClearGuestSession = clearGuestSession;

    // The session check itself could not run (server busy, 503, network):
    // keep the session and show the logged-in state from what this browser
    // already knows, then try once more a little later.
    let sessionRetried = false;
    function showCachedLoggedIn(){
      const cachedName = safeStorage.get('aerva_guest_name') || safeStorage.get('aerva_guest_email') || '';
      const greeting = 'Hi, ' + (cachedName || 'there');
      if(guestNameDisplay) guestNameDisplay.textContent = greeting;
      if(guestLoginLink) guestLoginLink.style.display = 'none';
      if(guestAccountBox) guestAccountBox.style.display = 'inline-flex';
      if(guestNameDisplayMobile){
        guestNameDisplayMobile.textContent = greeting;
        if(guestLoginLinkMobile) guestLoginLinkMobile.style.display = 'none';
        if(guestAccountBoxMobile) guestAccountBoxMobile.style.display = 'flex';
      }
      if(!sessionRetried){
        sessionRetried = true;
        setTimeout(checkGuestSession, 8000);
      }
    }

    async function checkGuestSession(){
      const token = safeStorage.get('aerva_guest_session');
      if(!token){
        // No session: make sure nothing from a previous identity is still
        // on screen. Without this, a badge rendered for the last account
        // would survive until the next full page load.
        renderNavTierBadge(null);
        setRecentlyViewedOwner(null);
        return;
      }
      try{
        const freshSignIn = isNewSignIn(token);
        const res = await fetch(SUITES_API_BASE + '/api/guest-auth' + (freshSignIn ? '?signin=1' : ''), {
          headers: { 'Authorization': 'Bearer ' + token }
        });
        if(res.ok){
          const data = await res.json();
          // "Complete your profile" (aerva-guest-verify.js): at a new sign-in,
          // before anything else, while the first name, last name or phone is
          // missing. "Do it later" closes it until the next sign-in (or a booking).
          try{ if(window.AervaGuestVerify) window.AervaGuestVerify.sessionSeen(data.guest, token, freshSignIn); }catch(e){ /* never blocks the page */ }
          // Bind Recently Viewed to this account before anything renders
          // with it, so a fresh login never shows the previous person's
          // browsing on this device.
          setRecentlyViewedOwner(data.guest.id);
          loadAccountFavorites();
          renderNavTierBadge(data.guest.tier);
          showReviewReminder(Number(data.guest.pendingReviews) || 0);
          renderNavNotifications(data.guest.notifications || []);
          showWalletReminder(data.guest.wallet, token);
          const greeting = 'Hi, ' + (data.guest.name || data.guest.email || data.guest.phone || 'there');
          if(data.guest.name) safeStorage.set('aerva_guest_name', data.guest.name);
          guestNameDisplay.textContent = greeting;
          guestLoginLink.style.display = 'none';
          guestAccountBox.style.display = 'inline-flex';
          if(guestNameDisplayMobile){
            guestNameDisplayMobile.textContent = greeting;
            guestLoginLinkMobile.style.display = 'none';
            guestAccountBoxMobile.style.display = 'flex';
          }
          // The host-only links — My Collection, Status, My Earnings —
          // appear only once this account has a LIVE listing. An account
          // with nothing listed, or whose only listing is still pending
          // review or was rejected, sees just My Bookings and Account
          // Settings.
          //
          // Gated on hasActiveListing (computed by guest-auth.js's
          // session check), NOT on accountType. account_type flips to
          // 'guest_host' the instant a property is submitted, which meant
          // someone awaiting review was shown three pages that had
          // nothing to show them and no explanation why.
          //
          // "List Experience" is deliberately NOT gated at all — a host
          // can list an experience without ever having listed a property
          // first (a without-stay experience needs no property; see the
          // "Hosted At" rule in submit-listing.js), so it stays visible
          // to any logged-in account. That is the route by which someone
          // with no listing gets their first one.
          // Today is a host's view, revealed on the same signal as the
          // rest of the host navigation.
          if(data.guest.hasActiveListing === true || data.guest.isCohost === true){
            const todayTab = document.getElementById('catToday');
            if(todayTab) todayTab.style.display = '';
          }
          // A co-host works on someone else's listings, so they need the
          // same two pages a host does — but they own nothing, and both
          // links hung off hasActiveListing, which only counts listings
          // this account owns. The result was a co-host with three
          // properties to manage and no way to open any of them: their
          // menu offered Co-hosting, which describes the arrangement, and
          // nothing that led to the properties themselves.
          //
          // Status stays out of it deliberately. It is the HOST's own
          // verification and standing — PAN, bank details, their account
          // health — which is theirs, not their co-host's, and the server
          // sends a co-host no verification data at all.
          const showsHostPages = data.guest.hasActiveListing === true || data.guest.isCohost === true;
          if(showsHostPages){
            // .nav-account-menu a's CSS expects display:block (full-width,
            // stacked, with its own top/bottom padding) — display:inline
            // was silently breaking that spacing the whole time. Only
            // became visually obvious once two conditionally-shown links
            // (My Collection, Status) sat right next to each other.
            myListingsLink.style.display = 'block';
            if(myListingsLinkMobile) myListingsLinkMobile.style.display = 'block';
            // My Earnings: a co-host's own share of what they help earn.
            const earningsMenuLink = document.getElementById('earningsMenuLink');
            const earningsMenuLinkMobile = document.getElementById('earningsMenuLinkMobile');
            if(earningsMenuLink) earningsMenuLink.style.display = 'block';
            if(earningsMenuLinkMobile) earningsMenuLinkMobile.style.display = 'block';
            // Payout details: a host's bank account, or a co-host's own (for their share).
            ['payoutsMenuLink', 'payoutsMenuLinkMobile'].forEach(id => { const el = document.getElementById(id); if(el) el.style.display = 'block'; });
          }
          // Status for a co-host whose host allowed it (in co-host mode).
          {
            const acting = window.AervaCohost && typeof window.AervaCohost.get === 'function' ? window.AervaCohost.get() : null;
            if(acting && (acting.access === 'full' || (acting.permissions || []).includes('status'))){
              ['statusMenuLink', 'statusMenuLinkMobile'].forEach(id => { const el = document.getElementById(id); if(el) el.style.display = 'block'; });
            }
          }
          // Account Settings: a host's settings (payouts, verification) live
          // on the host dashboard; everyone else's account is their profile.
          if(data.guest.hasActiveListing === true || data.guest.accountType === 'guest_host'){
            document.querySelectorAll('.account-settings-link').forEach(a => { a.href = 'host-dashboard.html?openProfile=1'; });
            const pointer = document.getElementById('settingsHostPointer');
            if(pointer) pointer.style.display = 'block';
          }
          if(data.guest.hasActiveListing === true){
            const statusMenuLink = document.getElementById('statusMenuLink');
            const statusMenuLinkMobile = document.getElementById('statusMenuLinkMobile');
            if(statusMenuLink) statusMenuLink.style.display = 'block';
            if(statusMenuLinkMobile) statusMenuLinkMobile.style.display = 'block';
            // Payout details (host-payouts.html), under My Earnings: the
            // host's own bank account. A co-host's is in the Co-hosting centre.
            ['payoutsMenuLink', 'payoutsMenuLinkMobile'].forEach(id => {
              const el = document.getElementById(id);
              if(el) el.style.display = 'block';
            });
          }
          // Messages is available to every logged-in account now, not
          // just hosts — a guest-only account can still have an active
          // conversation on a booking they made, and should be able to
          // see it the same way a host sees theirs.
          const hostMessagesIcon = document.getElementById('hostMessagesIcon');
          if(hostMessagesIcon){
            hostMessagesIcon.style.display = 'flex';
            refreshMessagesBadge();
          }
          // Same icon, mirrored into the mobile slide-out panel — this
          // used to only exist in the desktop nav (.nav-links), which is
          // display:none below 900px, so a phone guest had no way to
          // reach Messages at all.
          const hostMessagesIconMobile = document.getElementById('hostMessagesIconMobile');
          if(hostMessagesIconMobile) hostMessagesIconMobile.style.display = 'flex';
          // Location prompt, once per browser, only for a confirmed
          // logged-in guest — see promptLocationOnceForGuest for the
          // full reasoning. Fires and forgets; doesn't block anything
          // else in this function from continuing.
          promptLocationOnceForGuest();
          // Always fetch the profile now — it's what supplies the
          // avatar (photo or initials) for the new account menu, not
          // just the currency-resume it originally existed for. The
          // currency-setting itself stays conditional as before, so a
          // guest's own in-browser choice is never silently overridden.
          try{
            const profileRes = await fetch(SUITES_API_BASE + '/api/guest-profile', {
              headers: { 'Authorization': 'Bearer ' + token }
            });
            if(profileRes.ok){
              const profileData = await profileRes.json();
              if(profileData.guest){
                if(!safeStorage.get(CURRENCY_STORAGE_KEY) && profileData.guest.preferredCurrency){
                  setCurrency(profileData.guest.preferredCurrency, false);
                }
                const photoUrl = profileData.guest.profilePhotoUrl;
                const initial = (profileData.guest.name || data.guest.email || '?').trim().charAt(0).toUpperCase();
                const avatarInner = photoUrl ? `<img src="${escapeMessageHtml(photoUrl)}" alt="Profile photo">` : escapeMessageHtml(initial);
                ['navAvatarCircle', 'navAvatarCircleMobile'].forEach(id => {
                  const el = document.getElementById(id);
                  if(el) el.innerHTML = avatarInner;
                });
              }
            }
          } catch(err){
            // Not critical — the avatar just falls back to "?" and the
            // location-detected/default currency stays.
          }
        } else if(res.status === 401){
          // Token expired or invalid — quietly fall back to showing
          // "Log in" rather than an error; the guest just logs in again.
          clearGuestSession();
        } else {
          // 503 or similar: the check couldn't run, the session may be fine.
          showCachedLoggedIn();
        }
      } catch(err){
        // Network hiccup — leave storage alone so a temporary outage
        // doesn't force an unnecessary re-login on the next page load.
        showCachedLoggedIn();
      }
    }

    guestLogoutLink.addEventListener('click', function(e){
      e.preventDefault();
      clearGuestSession();
      window.location.href = 'index.html'; // always land on the home page, like every other page's Log Out
    });
    if(guestLogoutLinkMobile){
      guestLogoutLinkMobile.addEventListener('click', function(e){
        e.preventDefault();
        clearGuestSession();
        window.location.href = 'index.html'; // always land on the home page, like every other page's Log Out
      });
    }

    // ---- Account dropdown menu (My Listings / Account Settings / Log Out) ----
    const navAccountTrigger = document.getElementById('navAccountTrigger');
    const navAccountMenu = document.getElementById('navAccountMenu');
    if(navAccountTrigger && navAccountMenu){
      navAccountTrigger.addEventListener('click', (e) => {
        e.stopPropagation();
        navAccountMenu.classList.toggle('open');
      });
      document.addEventListener('click', (e) => {
        if(!navAccountMenu.contains(e.target) && e.target !== navAccountTrigger){
          navAccountMenu.classList.remove('open');
        }
      });
    }

    // Exposed so an in-page login (the booking gate) can refresh the
    // header without a page reload. Previously the token was stored and
    // nothing re-read it, so after logging out of one account and into
    // another in the same visit, the greeting, standing badge and host
    // links all still described the PREVIOUS account until a reload.
    // Every one of those is per-account, so a stale header is a leak.
    window.aervaRefreshIdentity = checkGuestSession;

    checkGuestSession();
  })();

// ---- Payout summary (index.html?payout=<id>) ----
// Opened from the payout notification or the payout email. Shows the same
// figures as the email (api/_payouts.js), for the signed-in host or
// co-host only (host-listings.js ?payoutDetail=<id>).
(function(){
  const id = new URLSearchParams(window.location.search).get('payout');
  if(!id) return;
  let token = null;
  try{ token = localStorage.getItem('aerva_guest_session'); }catch(e){}
  const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const day = (v) => { if(!v) return ''; const d = new Date(String(v).slice(0, 10) + 'T00:00:00Z'); return isNaN(d) ? '' : d.toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }); };
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const overlay = document.createElement('div');
  overlay.className = 'payout-overlay';
  overlay.innerHTML = '<div class="payout-sheet" role="dialog" aria-label="Payout"><button type="button" class="payout-close" aria-label="Close">×</button><div class="payout-body"><p class="payout-muted">Loading…</p></div></div>';
  const close = () => { overlay.remove(); try{ history.replaceState(null, '', 'index.html'); }catch(e){} };
  overlay.addEventListener('click', (e) => { if(e.target === overlay) close(); });
  overlay.querySelector('.payout-close').addEventListener('click', close);
  const show = () => document.body.appendChild(overlay);
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', show); else show();
  const body = overlay.querySelector('.payout-body');
  if(!token){ body.innerHTML = '<p class="payout-muted">Log in to see this payout.</p><p><a href="guest-login.html">Log in</a></p>'; return; }
  fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/host-listings?payoutDetail=' + encodeURIComponent(id), { headers: { 'Authorization': 'Bearer ' + token } })
    .then(r => r.json().then(d => ({ ok: r.ok, d })))
    .then(({ ok, d }) => {
      if(!ok || !d.payout){ body.innerHTML = '<p class="payout-muted">' + esc(d.error || 'This payout could not be found.') + '</p>'; return; }
      const p = d.payout;
      body.innerHTML = `
        <div class="payout-hero"><div class="payout-amount">${inr(p.amount)}</div>${p.viewerIsPayee === false ? `<div class="payout-muted">Paid to ${esc(p.payeeName || (p.payeeType === 'cohost' ? 'co-host' : 'host'))}${p.payeeType === 'cohost' ? ' (co-host)' : ' (host)'}</div>` : ''}</div>
        <div class="payout-card">
          <div class="payout-row"><div><div class="payout-status"><span class="payout-dot"></span>Sent ${esc(day(p.sentAt))}</div>${p.arrivingBy ? `<div class="payout-muted">Arriving by ${esc(day(p.arrivingBy))}</div>` : ''}</div></div>
          <div class="payout-row"><div><div class="payout-label">Bank account</div><div class="payout-muted">${esc(p.bank || '—')}</div></div></div>
          <div class="payout-row"><div><div class="payout-label">Payout ID</div><div class="payout-muted payout-ref">${esc(p.reference)}</div></div></div>
        </div>
        <div class="payout-card">
          <div class="payout-guest">${esc(p.guestName)}</div>
          <div class="payout-muted payout-center">${esc(day(p.arrival))} – ${esc(day(p.departure))}<br>${esc(p.listing)}</div>
          <div class="payout-row"><div><div class="payout-label">Booking</div><div class="payout-muted payout-ref">${esc(p.booking)}</div></div></div>
          <div class="payout-label" style="margin-top:14px;">Earnings</div>
          ${p.lines.map(l => `<div class="payout-line"><span>${esc(l.label)}</span><span style="white-space:nowrap;">${l.value < 0 ? '−' : ''}${inr(Math.abs(l.value))}</span></div>`).join('')}
          <div class="payout-line payout-total"><span>Total (INR)</span><span>${inr(p.amount)}</span></div>
          ${p.note ? `<p class="payout-muted" style="margin:12px 0 0; font-size:13px;">${esc(p.note)}</p>` : ''}
        </div>`;
    })
    .catch(() => { body.innerHTML = '<p class="payout-muted">Could not load this payout. Try again.</p>'; });

  // Material changes to Aerva's terms and policies for guests
  // (AERVA_POLICIES.updates, audience 'guests' or 'all'): a slim banner from
  // the day they are published until 14 days after they take effect.
  // Nothing to accept; "Got it" hides it on this browser (owner, 9 Nov 2026).
  window.addEventListener('load', function policyUpdateBanner(){
    const P = window.AERVA_POLICIES || {};
    const now = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Kolkata' });
    const plus14 = (d) => { const x = new Date(d + 'T00:00:00Z'); x.setUTCDate(x.getUTCDate() + 14); return x.toISOString().slice(0, 10); };
    const seen = (id) => { try { return localStorage.getItem('aerva_update_seen_' + id) === '1'; } catch (e) { return false; } };
    const fmt = (d) => new Date(d + 'T00:00:00+05:30').toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' });
    const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const u = (P.updates || []).find(x => x && (x.audience === 'guests' || x.audience === 'all') && x.published <= now && now <= plus14(x.effective) && !seen(x.id));
    if(!u || document.getElementById('policyUpdateBar')) return;
    const bar = document.createElement('div');
    bar.id = 'policyUpdateBar';
    bar.setAttribute('role', 'status');
    bar.style.cssText = 'background:#faf6ef; border-bottom:1px solid #e3d9cb; color:#1c1a17; font-size:13.5px; line-height:1.5; padding:10px 16px; display:flex; gap:12px; align-items:center; justify-content:center; flex-wrap:wrap; text-align:center;';
    const live = now >= u.effective;
    bar.innerHTML = '<span><strong>' + esc(u.title) + '</strong> — ' + (live ? 'in effect since ' : 'takes effect on ') + esc(fmt(u.effective)) + '. '
      + '<a href="index.html?view=policies" style="color:#8a6c39;">What is changing</a></span>'
      + '<button type="button" style="font-size:12.5px; border:1px solid #c9b48c; background:#fff; border-radius:6px; padding:3px 10px; cursor:pointer;">Got it</button>';
    bar.querySelector('button').addEventListener('click', () => { try { localStorage.setItem('aerva_update_seen_' + u.id, '1'); } catch (e) {} bar.remove(); });
    document.body.insertBefore(bar, document.body.firstChild);
  });
})();


// ---- Same-day bookings: the earliest check-in date right now. Tonight can
// be booked until the host's cut-off (listing.same_day_until: 18 = 6 PM …
// 24 = 12 AM, all day); from then, tomorrow (server: api/_booking-rules.js) ----
function aervaEarliestArrival(zone, untilHour){
  try{
    const parts = {};
    new Intl.DateTimeFormat('en-US', { timeZone: zone || 'Asia/Kolkata', hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit' })
      .formatToParts(new Date()).forEach(p => { parts[p.type] = p.value; });
    const date = `${parts.year}-${parts.month}-${parts.day}`;
    const until = [18, 19, 20, 21, 22, 23, 24].includes(Number(untilHour)) ? Number(untilHour) : 24;
    if(Number(parts.hour) < until) return date;
    const d = new Date(date + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 1);
    return d.toISOString().slice(0, 10);
  }catch(e){ return toLocalDateStr(new Date()); }
}

// ---- Small booking helpers ----
// listings.max_guests is free text ("4", "3–4", "9+"): the largest number
// in it is the limit — the same reading as parseMaxGuests in api/_pricing.js.
function aervaParseMaxGuests(raw){
  const numbers = String(raw == null ? '' : raw).match(/\d+/g);
  return numbers ? Math.max(...numbers.map(Number)) : null;
}
// 'YYYY-MM-DD' + n days (n may be negative).
function aervaAddDays(iso, n){
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

// ---- The price quote: what checkout will charge, from the server ----
// api/create-order.js with quoteOnly prices a booking exactly as it would
// charge it, and changes nothing (no payment, no held dates). The booking
// pages show this, so the total a guest sees is the total they pay.
const aervaQuoteSeq = {};
function aervaQuote(slot, body){
  const n = (aervaQuoteSeq[slot] = (aervaQuoteSeq[slot] || 0) + 1);
  const headers = { 'Content-Type': 'application/json' };
  // Signed in: the quote includes the guest's Aerva credit.
  let token = null;
  try { token = (typeof guestAuthToken === 'function') ? guestAuthToken() : localStorage.getItem('aerva_guest_session'); } catch(e){ token = null; }
  if(token) headers.Authorization = 'Bearer ' + token;
  return fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/create-order', { method: 'POST', headers,
      body: JSON.stringify(Object.assign({}, body, { quoteOnly: true })) })
    .then(async r => {
      const d = await r.json().catch(() => ({}));
      if(aervaQuoteSeq[slot] !== n) return null;                 // a newer quote was asked for
      if(!r.ok) throw Object.assign(new Error(d.error || 'We could not work out the price just now.'), { fromServer: r.status < 500, reason: d.reason || null });
      return d;
    }, err => { if(aervaQuoteSeq[slot] !== n) return null; throw err; });
}
// The quote's lines as summary rows. Amounts go through fmtGuest, so a
// guest browsing in another currency sees them converted like every price.
function aervaQuoteRowsHtml(q){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const lines = (q && q.lines) || [];
  const many = new Set(lines.filter(l => l.item).map(l => l.item)).size > 1;
  return lines.map(l => {
    const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
    let label = l.label;
    if(l.kind === 'room') label = (many ? l.item + ': ' : '') + `${fmtGuest(l.rate)} × ${plural(l.nights, 'night')}`;
    else if(l.kind === 'experience') label = l.perPerson ? `${many ? l.item + ': ' : ''}${fmtGuest(l.unitPrice)} × ${plural(l.guests, 'guest')}` : l.item;
    else if(many && l.item) label = l.item + ': ' + l.label;
    const amount = Number(l.amount) || 0;
    const shown = l.kind === 'service' && amount === 0 ? 'No charge' : (amount < 0 ? '−' + fmtGuest(-amount) : fmtGuest(amount));
    const why = l.kind === 'free_cancel' ? `<div class="sum-note" style="font-size:11.5px; opacity:0.65; margin:-2px 0 6px;">Cancel before then for a full refund of the booking price, GST and any deposit. This add-on and the service fee are not refunded.</div>` : '';
    return `<div class="sum-row"${l.kind === 'deposit' ? ' style="opacity:0.7;"' : ''}><span>${esc(label)}</span><span>${shown}</span></div>${why}`;
  }).join('');
}
// Rows, the total, and (in another currency) what is actually charged.
function aervaQuoteBodyHtml(q){
  // Only when prices really are converted (no rates loaded = they are shown in rupees).
  const inrNote = currentCurrency !== 'INR' && currencyRatesLoaded && currencyRates[currentCurrency]
    ? `<p style="font-size:11.5px; opacity:0.6; margin-top:4px;">Charged as ₹${Number(q.total).toLocaleString('en-IN')} (Indian Rupees) — shown in ${currentCurrency} at today's rate. Your bank or card network sets the actual exchange rate and may apply its own fees; Aerva is not responsible for any difference between this estimate and what your bank charges.</p>`
    : '';
  return `${aervaQuoteRowsHtml(q)}
    <div class="sum-row" style="font-weight:600; margin-top:8px; padding-top:8px; border-top:1px solid var(--line-dark);"><span>Total</span><span>${fmtGuest(Number(q.total) || 0)}</span></div>
    ${inrNote}
    ${Number(q.creditBalance) > 0 ? `<p class="quote-credit" style="font-size:12.5px; margin-top:8px; padding:8px 10px; border-radius:8px; background:var(--cream-2, #f4eadc);">You have ${fmtGuest(Number(q.creditBalance))} Aerva credit${Number(q.feeCredit) > 0 ? `: ${fmtGuest(Number(q.feeCredit))} is taken off this booking${Number(q.creditBalance) > Number(q.feeCredit) ? ', and the rest stays on your credit' : ''}.` : '.'} See it in My Bookings.</p>` : ''}
    <p style="font-size:11.5px; opacity:0.55; margin-top:8px;">This is the total you pay. Any coupon is taken off at payment.</p>`;
}
function aervaQuoteErrorHtml(err){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  return `<p class="quote-error" style="font-size:13px; color:#a3402f; margin:6px 0 0;">${esc(err && err.fromServer ? err.message : 'We could not work out the price just now. Please check your connection and try again.')}</p>`;
}

// ---- Your details: filled in from the signed-in account ----
// Name, email and mobile number, so a guest never types them twice. Only
// empty fields are filled; nothing the guest typed is replaced.
let aervaPrefillPromise = null;
function aervaPrefillBooking(){
  const token = (typeof guestAuthToken === 'function') ? guestAuthToken() : null;
  if(!token) return;
  if(!aervaPrefillPromise){
    aervaPrefillPromise = fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/create-order', { method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token }, body: JSON.stringify({ prefill: true }) })
      .then(r => r.ok ? r.json() : {}).catch(() => ({}));
  }
  aervaPrefillPromise.then(d => {
    if(!d) return;
    const phoneLocal = String(d.phone || '').replace(/^\+91(?=[6-9]\d{9}$)/, '');
    ['listingBook', 'resortBook', 'expBook'].forEach(prefix => {
      const put = (suffix, value) => { const el = document.getElementById(prefix + suffix); if(el && !el.value && value) el.value = value; };
      put('FirstName', d.firstName); put('LastName', d.lastName); put('Email', d.email); put('Phone', phoneLocal);
    });
  });
}

// ---- "Booking confirmed" screen ----
// Shown over the page the moment a payment is confirmed: the code to show
// at check-in, each booking's dates and guests, what was paid, and where the
// confirmation email went. Built only from what verify-payment.js returns.
function aervaShowBookingSuccess(summary, codes, opts){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const day = (d) => d ? new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }) : '';
  const money = (n, cur) => (cur && cur !== 'INR' ? cur + ' ' : '₹') + Number(n).toLocaleString('en-IN', { maximumFractionDigits: 2 });
  const items = (summary && Array.isArray(summary.items) && summary.items.length) ? summary.items
    : (codes || []).map(c => ({ name: c.item, code: c.code }));
  const old = document.getElementById('bookingSuccess');
  if(old) old.remove();
  const wrap = document.createElement('div');
  wrap.id = 'bookingSuccess';
  wrap.className = 'bs-overlay';
  wrap.setAttribute('role', 'dialog');
  wrap.setAttribute('aria-modal', 'true');
  wrap.setAttribute('aria-labelledby', 'bsTitle');
  const itemHtml = items.map(it => {
    const when = it.arrival
      ? (it.experience || !it.departure || it.departure === it.arrival
          ? `<div class="bs-row"><span>Date</span><strong>${esc(day(it.arrival))}</strong></div>`
          : `<div class="bs-dates">
               <div><span>Check-in</span><strong>${esc(day(it.arrival))}</strong>${it.checkIn ? `<em>from ${esc(it.checkIn)}</em>` : ''}</div>
               <div class="bs-arrow" aria-hidden="true">→</div>
               <div><span>Check-out</span><strong>${esc(day(it.departure))}</strong>${it.checkOut ? `<em>by ${esc(it.checkOut)}</em>` : ''}</div>
             </div>`)
      : '';
    const facts = [it.nights && !it.experience ? `${it.nights} night${it.nights === 1 ? '' : 's'}` : '', it.guests ? `${it.guests} guest${it.guests === 1 ? '' : 's'}` : '', it.city || ''].filter(Boolean).join(' · ');
    return `<div class="bs-item">
      <div class="bs-item-head"><h3>${esc(it.name || 'Your booking')}</h3>${facts ? `<p>${esc(facts)}</p>` : ''}</div>
      ${it.code ? `<div class="bs-code"><span>Confirmation code</span><strong>${esc(it.code)}</strong><button type="button" class="bs-copy" data-code="${esc(it.code)}">Copy</button></div>` : ''}
      ${when}
    </div>`;
  }).join('');
  const paid = summary && summary.paid != null ? `<div class="bs-row"><span>Paid</span><strong>${esc(money(summary.paid, summary.currency))}${summary.method ? ` <em>· ${esc(String(summary.method).toUpperCase())}</em>` : ''}</strong></div>` : '';
  const payId = summary && summary.paymentId ? `<div class="bs-row"><span>Payment ID</span><strong class="bs-mono">${esc(summary.paymentId)}</strong></div>` : '';
  wrap.innerHTML = `<div class="bs-card">
      <div class="bs-tick" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></div>
      <p class="bs-eyebrow">Payment received</p>
      <h2 id="bsTitle">Your booking is confirmed</h2>
      <p class="bs-lead">${summary && summary.email ? `We have sent the confirmation to <strong>${esc(summary.email)}</strong>.` : 'We have emailed you the confirmation.'} ${opts && opts.gift ? `This stay is a gift for <strong>${esc([opts.gift.firstName, opts.gift.lastName].filter(Boolean).join(' '))}</strong>: we have emailed them the stay details (never the price) and a link to accept it.` : 'Show your confirmation code at check-in.'}</p>
      ${itemHtml}
      ${paid || payId ? `<div class="bs-pay">${paid}${payId}</div>` : ''}
      ${opts && opts.suggestFor ? `<div class="sx-slot" data-suggest-exp-for="${Number(opts.suggestFor)}"></div>` : ''}
      <div class="bs-actions">
        <a class="bs-btn bs-primary" href="index.html?view=my-bookings">View my bookings</a>
        <button type="button" class="bs-btn bs-secondary" data-bs-close>Done</button>
      </div>
      <p class="bs-note">You can message your host, change dates or cancel from My Bookings.</p>
    </div>`;
  document.body.appendChild(wrap);
  document.documentElement.classList.add('bs-open');
  const close = () => { wrap.remove(); document.documentElement.classList.remove('bs-open'); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if(e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
  wrap.addEventListener('click', (e) => { if(e.target === wrap) close(); });
  wrap.querySelector('[data-bs-close]').addEventListener('click', close);
  aervaLoadSuggestedExperiences(wrap);
  wrap.querySelectorAll('.bs-copy').forEach(b => b.addEventListener('click', async () => {
    try{ await navigator.clipboard.writeText(b.dataset.code); b.textContent = 'Copied'; }
    catch(e){ b.textContent = 'Select and copy'; }
    setTimeout(() => { b.textContent = 'Copy'; }, 1800);
  }));
  setTimeout(() => { const p = wrap.querySelector('.bs-primary'); if(p) p.focus(); }, 50);
}

// ---- After payment: what the guest is told ----
// verify-payment.js answers with the booking's confirmation code(s).
function aervaShowPaymentResult(verifyData, { confirmEl, errorEl, btn, suggestFor = null, gift = null }){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  // A payment for places in a group booking: back to the group's live status.
  if(verifyData && verifyData.group && verifyData.group.token && typeof aervaAfterGroupPayment === 'function'){ aervaAfterGroupPayment(verifyData); return; }
  errorEl.style.display = 'none';
  // Paid, but the guest's details are not verified yet (api/_guest-verify.js):
  // the payment is held, and the booking is confirmed once the three steps
  // are done. The screen has no skip; it turns into the confirmation itself.
  if(verifyData && verifyData.held && window.AervaGuestVerify){
    confirmEl.innerHTML = `<strong>Payment received.</strong> ${esc(verifyData.held.message || window.AervaGuestVerify.HELD_TEXT)}`;
    confirmEl.style.color = '#1c1b19';
    confirmEl.style.display = 'block';
    // Paid: the button stays off, so the same booking is never paid twice.
    if(btn){ btn.disabled = true; btn.textContent = 'Payment received'; }
    window.AervaGuestVerify.showHeld(verifyData.held, {
      onConfirmed: (list) => {
        const ok = (list || []).some(c => c.status === 'confirmed');
        const codes = (list || []).flatMap(c => c.codes || []);
        confirmEl.innerHTML = ok ? `<strong>Booking confirmed.</strong>${codes.length ? ' Your confirmation code is ' + codes.map(c => `<strong>${esc(c.code)}</strong>`).join(', ') + ' — show it at check-in.' : ''} We have emailed you the details.`
          : 'The booking could not be completed, and your payment is being refunded in full — we have emailed you the details.';
        if(btn && ok) btn.textContent = 'Booked';
        if(typeof loadMyBookings === 'function' && document.getElementById('myBookingsContainer')) setTimeout(loadMyBookings, 800);
      }
    });
    return;
  }
  if(verifyData && verifyData.verified){
    const codes = Array.isArray(verifyData.confirmationCodes) ? verifyData.confirmationCodes : [];
    const codeHtml = codes.length === 1
      ? ` Your confirmation code is <strong>${esc(codes[0].code)}</strong> — show it at check-in.`
      : codes.length > 1 ? ' Your confirmation codes: ' + codes.map(c => `<strong>${esc(c.code)}</strong> (${esc(c.item)})`).join(', ') + '.' : '';
    confirmEl.innerHTML = `<strong>Booking confirmed.</strong>${codeHtml} We have emailed you the details.`;
    confirmEl.style.display = 'block';
    // Paid: the button stays off, so the same booking is never paid twice.
    if(btn){ btn.disabled = true; btn.textContent = 'Booked'; }
    aervaShowBookingSuccess(verifyData.summary, codes, { suggestFor, gift });
    return;
  }
  const pending = verifyData && verifyData.pending;
  errorEl.style.color = pending ? '#1c1b19' : '#a3402f';
  if(verifyData && verifyData.message) errorEl.textContent = verifyData.message;
  else aervaHelpMessage(errorEl, 'We could not confirm this payment. Before booking again:', 'category=booking_payment');
  errorEl.style.display = 'block';
  // Paid but still being confirmed: paying again would pay twice.
  if(pending && btn){ btn.disabled = true; btn.textContent = 'Payment received'; }
}

// ---- Calendar days work from the keyboard ----
// The day cells are plain divs, so without this a keyboard or screen-reader
// user could not reach a date at all and so could not book. Each pickable
// day becomes a focusable button; Enter or Space picks it, and focus comes
// back to the same day after the month redraws.
function aervaDayCellA11y(cell, attr){
  const iso = cell.getAttribute(attr);
  cell.tabIndex = 0;
  cell.setAttribute('role', 'button');
  const d = iso ? new Date(iso + 'T00:00:00') : null;
  if(d && !isNaN(d)) cell.setAttribute('aria-label', d.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }));
  cell.addEventListener('keydown', (e) => {
    if(e.key !== 'Enter' && e.key !== ' ') return;
    e.preventDefault();
    cell.click();
    setTimeout(() => { const again = document.querySelector('.calendar-day[' + attr + '="' + iso + '"]'); if(again && again !== document.activeElement && again.tabIndex === 0) again.focus(); }, 0);
  });
}

// ---- Booking steps: a numbered heading for each stage of booking ----
// Booking is a real sequence, so it is numbered: guests of any age can see
// where they are and what comes next.
function bookStep(n, text){
  return `<div class="book-step"><span class="book-step-n" aria-hidden="true">${n}</span><span class="book-step-text">${text}</span></div>`;
}
const PAY_NOTE_HTML = '<p class="pay-note">You pay securely on the next screen by UPI, card or net banking. Your booking is confirmed by email straight after.</p>';

// ---- The payment window, 3 minutes (server: api/_booking-rules.js HOLD_SECONDS) ----
// Starts when the guest taps Continue to payment. A countdown sits above
// Razorpay's window; every few seconds the server is asked whether the
// window is still open (timed out? host changed a price?). Closing the
// window, a failed payment, or the timer running out ends it at once and
// releases the dates. Only a payment made inside the window becomes a booking.
let aervaCheckout = null; // { rzp, orderId, msgEl, tick, poll, bar, holdsDates }
// opts.holdsDates: false for a payment that holds no dates (an experience
// on its own), so the messages never talk about released dates.
function aervaWatchCheckout(rzp, order, msgEl, opts){
  aervaStopCheckout();
  if(!order || !order.orderId) return;
  const seconds = Number(order.holdSeconds) || 0;
  const holdsDates = !(opts && opts.holdsDates === false);
  const state = { rzp, orderId: order.orderId, msgEl, left: seconds, holdsDates, seconds };
  aervaCheckout = state;
  if(!seconds) return; // no window was opened (older server): nothing to time
  const bar = document.createElement('div');
  bar.id = 'aervaCheckoutTimer';
  bar.setAttribute('role', 'timer');
  bar.setAttribute('aria-live', 'polite');
  bar.style.cssText = 'position:fixed; top:0; left:0; right:0; z-index:2147483647; background:#1c1b19; color:#fff; text-align:center;'
    + "padding:calc(10px + env(safe-area-inset-top, 0px)) 16px 10px; font-family:'Jost', sans-serif; font-size:15px; font-weight:500; box-shadow:0 2px 8px rgba(0,0,0,0.25);";
  document.body.appendChild(bar);
  state.bar = bar;
  const paint = () => {
    const m = Math.floor(state.left / 60), sec = String(state.left % 60).padStart(2, '0');
    bar.textContent = `Pay within ${m}:${sec}` + (state.holdsDates ? ' — dates held for you' : '');
    bar.style.background = state.left <= 20 ? '#a3402f' : '#1c1b19';
  };
  paint();
  state.tick = setInterval(() => {
    state.left = Math.max(0, state.left - 1);
    paint();
    if(state.left === 0) aervaEndCheckout('expired');
  }, 1000);
  state.poll = setInterval(async () => {
    try{
      const r = await fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/create-order', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ holdStatus: state.orderId }) });
      const d = await r.json();
      if(aervaCheckout !== state) return;
      if(d && d.active === false) aervaEndCheckout(d.reason || 'released');
      else if(d && typeof d.secondsLeft === 'number' && Math.abs(d.secondsLeft - state.left) > 2) state.left = d.secondsLeft; // stay in step with the server
    }catch(e){ /* keep counting; the server still enforces the window */ }
  }, 4000);
}
// "3-minute" (or "90-second" from an older server).
function aervaWindowLabel(sec){ sec = Number(sec) || 180; return sec % 60 === 0 ? (sec / 60) + '-minute' : sec + '-second'; }
function aervaStopCheckout(){
  if(!aervaCheckout) return;
  clearInterval(aervaCheckout.tick); clearInterval(aervaCheckout.poll);
  if(aervaCheckout.bar) aervaCheckout.bar.remove();
  aervaCheckout = null;
}
// Payment succeeded: the booking takes the dates; nothing to release here.
function aervaCheckoutSucceeded(){ aervaStopCheckout(); aervaStopFollowUp(); }

// ---- When Razorpay's answer never arrives ----
// A card paid on the bank's OTP page, a window closed or timed out while a
// payment was on its way, a phone that switched apps: the page may never
// hear back from Razorpay. After the window ends, the server is asked
// (verify-payment.js checkOrder) whether a payment for this order went
// through, and the guest is shown the real outcome — the booking confirmed
// screen, or that it came too late and is being refunded. When nothing was
// paid, the message already shown stays as it is.
let aervaFollowUp = null;
function aervaStopFollowUp(){ if(aervaFollowUp){ clearTimeout(aervaFollowUp.timer); aervaFollowUp = null; } }
function aervaFollowUpPayment(orderId, msgEl, { seconds = 180, announce = false } = {}){
  aervaStopFollowUp();
  if(!orderId || typeof guestAuthToken !== 'function' || !guestAuthToken()) return;
  const state = { orderId, until: Date.now() + seconds * 1000, timer: null };
  aervaFollowUp = state;
  if(announce && msgEl){
    msgEl.textContent = 'If you completed the payment, we are checking it with your bank now — please keep this page open.';
    msgEl.style.color = '#1c1b19'; msgEl.style.display = 'block';
  }
  const tick = async () => {
    if(aervaFollowUp !== state) return;
    try{
      const r = await fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/verify-payment', { method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() }, body: JSON.stringify({ checkOrder: orderId }) });
      const d = await r.json().catch(() => ({}));
      if(aervaFollowUp !== state) return;
      if(r.ok && (d.verified || d.refunded || d.pending || d.held)){
        aervaStopFollowUp();
        aervaShowPaymentResult(d, { confirmEl: msgEl, errorEl: msgEl, btn: null });
        if(d.verified && typeof loadMyBookings === 'function') setTimeout(loadMyBookings, 1000);
        return;
      }
      if(r.ok && d.failed){ aervaStopFollowUp(); if(announce && msgEl){ msgEl.textContent = 'The payment did not go through, so nothing was booked. No money was taken.'; msgEl.style.color = '#a3402f'; } return; }
    }catch(e){ /* try again */ }
    if(Date.now() > state.until){
      aervaStopFollowUp();
      if(announce && msgEl){ msgEl.textContent = 'We could not confirm a payment yet. If money was taken from your account, the booking is confirmed — or the money refunded in full — automatically within a few minutes, and we email you either way.'; msgEl.style.color = '#1c1b19'; }
      return;
    }
    state.timer = setTimeout(tick, 4000);
  };
  state.timer = setTimeout(tick, 2500);
}
// Closed, failed, timed out, released, or the price changed: end it now.
function aervaEndCheckout(reason){
  const state = aervaCheckout;
  if(!state) return;
  aervaStopCheckout();
  try{ state.rzp && state.rzp.close && state.rzp.close(); }catch(e){}
  // The server is told why: a window the guest closed can never become a
  // booking; one whose time ran out still can if the payment was already
  // on its way (15 seconds' grace, api/_booking-rules.js).
  if(reason === 'closed' || reason === 'failed' || reason === 'expired') aervaReleaseHold(state.orderId, reason);
  // A payment may still have been on its way (e.g. a card at the bank's OTP
  // step): check with the server and show the real outcome.
  if(reason === 'expired') aervaFollowUpPayment(state.orderId, state.msgEl, { seconds: 180 });
  else if(reason === 'closed' || reason === 'failed') aervaFollowUpPayment(state.orderId, state.msgEl, { seconds: 45 });
  const released = state.holdsDates ? ' Your dates have been released.' : '';
  const messages = {
    closed: 'Payment cancelled. Nothing was booked.' + released,
    failed: 'The payment did not go through, so nothing was booked.' + released,
    expired: 'The ' + aervaWindowLabel(state.seconds) + ' payment window has ended.' + released + ' If you had already paid (for example on your bank’s OTP page), keep this page open — the result will show here in a moment. Otherwise you can start again.',
    released: 'This payment was cancelled, so nothing was booked.' + released,
    price_changed: 'Prices have been changed recently. Tap Continue to payment to see the new price.'
  };
  // Information, not an error: shown in the page's normal text colour.
  if(state.msgEl){
    state.msgEl.textContent = messages[reason] || messages.released;
    state.msgEl.style.color = reason === 'failed' ? '#a3402f' : '#1c1b19';
    state.msgEl.style.display = 'block';
  }
}

// ---- "Prices have been changed recently" ----
// The page sends the price stamp of each listing it is showing; if the host
// changed a price since, the server returns the new breakdown instead of
// opening payment, and the guest confirms it first.
let aervaPriceAccepted = {};
function aervaPricesSeen(items){
  const out = {};
  (items || []).forEach(x => { if(x && x.id != null) out[String(x.id)] = x.price_changed_at || null; });
  Object.keys(aervaPriceAccepted).forEach(k => { if(k in out) out[k] = aervaPriceAccepted[k]; });
  return out;
}
function aervaShowPriceChange(msgEl, data, btn){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const inr = (n) => moneyBoth(n);
  msgEl.style.display = 'block';
  msgEl.style.color = '#1c1b19';
  msgEl.innerHTML = `<div class="price-changed">
      <p class="price-changed-title">Prices have been changed recently. The new price is below.</p>
      ${(data.lines || []).map(l => `<div class="sum-row"><span>${esc(l.label)}</span><span>${inr(l.amount)}</span></div>`).join('')}
      <div class="sum-row price-changed-total"><span>New total</span><span>${inr(data.total)}</span></div>
      <button type="button" class="btn solid price-changed-go" style="width:100%; margin-top:12px;">Continue with the new price</button>
    </div>`;
  msgEl.querySelector('.price-changed-go').addEventListener('click', () => {
    aervaPriceAccepted = Object.assign({}, aervaPriceAccepted, data.pricesSeen || {});
    msgEl.style.display = 'none'; msgEl.innerHTML = '';
    if(btn) btn.click();
  });
}

// ---- Release the payment window's hold on the dates ----
// (api/create-order.js releaseHold). Best effort: the hold expires on its own.
function aervaReleaseHold(orderId, reason){
  if(!orderId) return;
  try{
    fetch((window.AERVA_API || (window.AERVA_API || 'https://aerva-in.vercel.app')) + '/api/create-order', { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ releaseHold: orderId, reason: reason || 'closed' }), keepalive: true }).catch(function(){});
  }catch(e){}
}

// ---- Refund policy wording — must match api/_cancellations.js ----
function cancellationPolicyText(policy){
  return policy === 'firm'
    ? 'Firm — full refund 30+ days before check-in; 50% from 5 to 29 days; within 4 days the host decides. Aerva’s service fee is non-refundable; the deposit is always refunded.'
    : 'Flexible — full refund 30+ days before check-in; 80% from 10 to 29 days; 50% from 5 to 9 days; 30% from 2 to 4 days; less than 2 days before, the host decides. Aerva’s service fee is non-refundable; the deposit is always refunded.';
}

// ---- Photos in a booking's chat ----
// During a confirmed booking (until check-out) the guest and host can send
// each other photos, up to 6 a message (guest-profile.js 'send').
const CHAT_PHOTO_MAX = 6;
function chatPhotosHtml(photos){
  if(!Array.isArray(photos) || !photos.length) return '';
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  return `<div class="chat-photos chat-photos-${Math.min(photos.length, 3)}">${photos.map(u => /^https:\/\//.test(u)
    ? `<a href="${esc(u)}" target="_blank" rel="noopener"><img src="${esc(u)}" alt="Photo" loading="lazy"></a>` : '').join('')}</div>`;
}
// A "Photos" button before `beforeEl` (the message box), with previews
// above `rowEl`. Photos upload as soon as they are picked.
function makeChatPhotoPicker(beforeEl, rowEl){
  if(!beforeEl || !rowEl) return null;
  const btn = document.createElement('button');
  btn.type = 'button'; btn.className = 'chat-photo-btn'; btn.title = 'Add photos'; btn.setAttribute('aria-label', 'Add photos');
  btn.innerHTML = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="10" r="2"/><path d="M21 16l-5-5-8 8"/></svg>';
  btn.style.display = 'none';
  const input = document.createElement('input');
  input.type = 'file'; input.accept = 'image/jpeg,image/png,image/webp'; input.multiple = true; input.style.display = 'none';
  const strip = document.createElement('div'); strip.className = 'chat-photo-strip'; strip.style.display = 'none';
  beforeEl.parentNode.insertBefore(btn, beforeEl);
  beforeEl.parentNode.insertBefore(input, beforeEl);
  rowEl.parentNode.insertBefore(strip, rowEl);
  let items = [];                  // { id, url, status: 'up' | 'ok' | 'err', preview }
  let allowed = false;
  const draw = () => {
    strip.style.display = items.length ? '' : 'none';
    strip.innerHTML = items.map(it => `<div class="chat-photo-thumb${it.status === 'err' ? ' err' : ''}"><img src="${it.preview}" alt="">${it.status === 'up' ? '<span class="chat-photo-busy">…</span>' : ''}${it.status === 'err' ? '<span class="chat-photo-busy">!</span>' : ''}<button type="button" data-rm="${it.id}" aria-label="Remove">×</button></div>`).join('')
      + (items.length ? `<span class="chat-photo-note">${items.length}/${CHAT_PHOTO_MAX}</span>` : '');
    strip.querySelectorAll('[data-rm]').forEach(b => b.addEventListener('click', () => { items = items.filter(x => String(x.id) !== b.dataset.rm); draw(); }));
  };
  btn.addEventListener('click', () => input.click());
  input.addEventListener('change', async () => {
    const files = [...input.files].slice(0, Math.max(0, CHAT_PHOTO_MAX - items.length));
    input.value = '';
    for(const f of files){
      const it = { id: Date.now() + Math.random(), status: 'up', preview: URL.createObjectURL(f) };
      items.push(it); draw();
      try{ it.url = (await aervaUploadFiles([f], 'chat-photo'))[0]; it.status = 'ok'; }
      catch(e){ it.status = 'err'; }
      draw();
    }
  });
  return {
    setAllowed(on){ allowed = !!on; btn.style.display = allowed ? '' : 'none'; if(!allowed){ items = []; draw(); } },
    get allowed(){ return allowed; },
    busy(){ return items.some(i => i.status === 'up'); },
    urls(){ return items.filter(i => i.status === 'ok' && i.url).map(i => i.url); },
    clear(){ items = []; draw(); }
  };
}

// ---- Uploading files (evidence for a reported problem) ----
async function aervaUploadFiles(files, payload){
  const { upload } = await import('https://esm.sh/@vercel/blob/client');
  const out = [];
  for(const f of files){
    if(f.size > 8 * 1024 * 1024) throw new Error(`"${f.name}" is larger than 8 MB.`);
    const r = await upload(f.name, f, { access: 'public', handleUploadUrl: SUITES_API_BASE + '/api/blob-upload',
      clientPayload: JSON.stringify({ purpose: payload, token: guestAuthToken() || '' }) });
    out.push(r.url);
  }
  return out;
}

// ---- Confirmed email and phone number, required to start a checkout (api/_guest-id.js) ----
// What a booking needs to be CONFIRMED — name, phone code, photo ID — is in
// aerva-guest-verify.js (api/_guest-verify.js); the host still checks a
// photo ID at check-in.
// Opens where the booking message shows, asks only for what is missing,
// then continues to payment by pressing the same button again.
function aervaShowNeeds(msgEl, data, btn){
  const needs = data.needs || [];
  // A gift's buyer and a group's organiser verify their details first (api/_guest-verify.js).
  if(needs.includes('verification')){
    const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    msgEl.style.display = 'block';
    msgEl.style.color = '#1c1b19';
    msgEl.innerHTML = `<div class="price-changed"><p class="price-changed-title">Verify your details first</p>
      <p style="margin:0 0 10px;">${esc(data.error || 'Please verify your details in your profile first.')}</p>
      <a class="btn solid" href="index.html?view=profile&verify=phone" style="width:100%;">Verify my details</a></div>`;
    return;
  }
  if(needs.includes('login')){
    msgEl.style.display = 'block';
    msgEl.style.color = '#1c1b19';
    msgEl.innerHTML = `<div class="price-changed"><p class="price-changed-title">Please log in to book</p>
      <p style="margin:0 0 10px;">Every booking needs an Aerva account: one email address and one mobile number.</p>
      <a class="btn solid" href="guest-login.html?next=${encodeURIComponent(location.href)}" style="width:100%;">Log in or create an account</a></div>`;
    return;
  }
  // The number typed in the booking form is filled in here for the guest.
  const col = btn && btn.closest ? btn.closest('.listing-col-booking') : null;
  const typed = col && col.querySelector('input[type="tel"]') ? col.querySelector('input[type="tel"]').value.trim() : '';
  const typedEmail = col && col.querySelector('input[type="email"]') ? col.querySelector('input[type="email"]').value.trim() : '';
  aervaIdPanel(msgEl, { needs, message: data.error, phone: typed, email: typedEmail, onDone: () => { msgEl.style.display = 'none'; msgEl.innerHTML = ''; if(btn) btn.click(); } });
}
async function aervaIdPanel(host, { needs = ['email'], message = '', onDone, phone = '', email = '' } = {}){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  // An account is ONE email address and ONE phone number. The email is
  // confirmed by a code sent to it (api/_email-otp.js) — email costs
  // nothing to send, every SMS is billed. The number is what the host
  // uses to reach the guest about the stay.
  let have = {};
  try{
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=bookingRequirements', { headers: { 'Authorization': 'Bearer ' + guestAuthToken() } });
    have = await r.json();
  }catch(e){}
  const askEmail = needs.includes('email') && !have.emailConfirmed;
  const askPhone = needs.includes('phone') && !have.hasPhone;
  if(!askEmail && !askPhone){ if(typeof onDone === 'function') onDone(); return; }

  host.style.display = 'block';
  host.style.color = '#1c1b19';
  host.innerHTML = `<div class="price-changed">
    <p class="price-changed-title">${esc(message || 'Confirm your details to book')}</p>
    ${askEmail ? `<label class="payout-label" for="otpEmail">Email address</label>
      <input id="otpEmail" type="email" inputmode="email" autocomplete="email" value="${esc(have.email || email || '')}" placeholder="you@email.com" style="width:100%; box-sizing:border-box; padding:11px; margin:6px 0 6px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px;">
      <p class="id-note">We send a one-time code here. Your booking confirmation comes to this address too.</p>
      <button type="button" class="btn solid" id="otpSend" style="width:100%;">Email me a code</button>
      <div id="otpStep2" hidden>
        <label class="payout-label" for="otpCode" style="margin-top:12px; display:block;">Enter the code</label>
        <input id="otpCode" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="6-digit code" style="width:100%; box-sizing:border-box; padding:11px; margin:6px 0 8px; border:1px solid #d9cfc2; border-radius:8px; font-size:18px; letter-spacing:0.18em;">
        <div id="otpReauth" hidden>
          <label class="payout-label" for="otpReauthInput" id="otpReauthLabel" style="display:block;"></label>
          <input id="otpReauthInput" style="width:100%; box-sizing:border-box; padding:11px; margin:6px 0 8px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px;">
        </div>
        <button type="button" class="btn solid" id="otpConfirm" style="width:100%;">Confirm email</button>
        <button type="button" class="filter-clear" id="otpAgain" style="margin-top:8px;">Send it again</button>
      </div>` : ''}
    ${askPhone ? `<div id="phoneStep"${askEmail ? ' hidden' : ''}>
      <label class="payout-label" for="needPhone"${askEmail ? ' style="margin-top:14px; display:block;"' : ''}>Mobile number</label>
      <input id="needPhone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(phone || '')}" placeholder="10-digit mobile number" style="width:100%; box-sizing:border-box; padding:11px; margin:6px 0 6px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px;">
      <p class="id-note">Your host uses this to reach you about your stay.</p>
      <button type="button" class="btn solid" id="phoneSave" style="width:100%;">Save and continue</button>
    </div>` : ''}
    <p id="needMsg" class="id-note" style="margin:8px 0 0;"></p></div>`;

  const msg = host.querySelector('#needMsg');
  const say = (t, bad) => { msg.classList.toggle('id-warn', !!bad); msg.textContent = t; };
  const post = (body) => fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() }, body: JSON.stringify(body) })
    .then(async r => ({ ok: r.ok, d: await r.json().catch(() => ({})) }));
  // Once the email is confirmed, the number is asked for (if it is still
  // missing); once both are in, checkout carries on where it left off.
  const finish = () => {
    const step = host.querySelector('#phoneStep');
    if(step && step.hidden){                       // email done, number still to come
      step.hidden = false;
      host.querySelector('#needPhone').focus();
      say('Email confirmed. One more thing.');
      return;
    }
    if(typeof onDone === 'function') onDone();
  };

  const sendBtn = host.querySelector('#otpSend');
  if(sendBtn){
    const send = async (btn) => {
      const email = host.querySelector('#otpEmail').value.trim();
      if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return say('Enter a valid email address.', true);
      btn.disabled = true; btn.textContent = 'Sending…'; say('');
      const { ok, d } = await post({ mode: 'emailOtpRequest', email });
      btn.disabled = false; btn.textContent = btn.id === 'otpSend' ? 'Email me a code' : 'Send it again';
      if(!ok) return say(d.error || 'Could not send the code. Please try again.', true);
      host.querySelector('#otpStep2').hidden = false;
      host.querySelector('#otpCode').focus();
      say(`Code sent to ${email}. It is good for ${d.expiresInMinutes || 10} minutes — check your spam folder if it is not there.`);
    };
    sendBtn.addEventListener('click', (e) => send(e.currentTarget));
    host.querySelector('#otpAgain').addEventListener('click', (e) => send(e.currentTarget));
    host.querySelector('#otpConfirm').addEventListener('click', async (e) => {
      const btn = e.currentTarget;
      const code = host.querySelector('#otpCode').value.trim();
      if(!code) return say('Enter the code from your email.', true);
      // Changing the sign-in email also needs the current password, or a
      // code sent to the current address (api/guest-profile.js answers
      // { reauth } to say which); the field appears once asked for.
      const reauthBox = host.querySelector('#otpReauth');
      const reauthInput = host.querySelector('#otpReauthInput');
      const body = { mode: 'emailOtpVerify', email: host.querySelector('#otpEmail').value.trim(), code };
      if(!reauthBox.hidden && reauthInput.value.trim()){
        if(reauthBox.dataset.kind === 'password') body.currentPassword = reauthInput.value;
        else body.currentEmailCode = reauthInput.value.trim();
      }
      btn.disabled = true; btn.textContent = 'Checking…'; say('');
      const { ok, d } = await post(body);
      if(!ok){
        btn.disabled = false; btn.textContent = 'Confirm email';
        if(d.reauth === 'password' || d.reauth === 'currentEmailCode'){
          const isPw = d.reauth === 'password';
          if(reauthBox.dataset.kind !== d.reauth){
            reauthBox.dataset.kind = d.reauth;
            reauthInput.value = '';
            reauthInput.type = isPw ? 'password' : 'text';
            reauthInput.autocomplete = isPw ? 'current-password' : 'one-time-code';
            reauthInput.inputMode = isPw ? 'text' : 'numeric';
            reauthInput.maxLength = isPw ? 200 : 6;
            reauthInput.placeholder = isPw ? '' : '6-digit code';
            host.querySelector('#otpReauthLabel').textContent = isPw
              ? 'Your current password'
              : 'Code sent to your current address' + (d.sentTo ? ' (' + d.sentTo + ')' : '');
          }
          reauthBox.hidden = false;
          reauthInput.focus();
        }
        return say(d.error || 'That code did not match.', true);
      }
      // A changed sign-in email signs out every other device; this one gets
      // a fresh session so it stays logged in.
      if(d.sessionToken) safeStorage.set('aerva_guest_session', d.sessionToken);
      btn.textContent = 'Confirmed';
      finish();
    });
  }

  const phoneBtn = host.querySelector('#phoneSave');
  if(phoneBtn) phoneBtn.addEventListener('click', async (e) => {
    const btn = e.currentTarget;
    btn.disabled = true; btn.textContent = 'Saving…'; say('');
    const { ok, d } = await post({ mode: 'savePhone', phone: host.querySelector('#needPhone').value });
    if(!ok){ btn.disabled = false; btn.textContent = 'Save and continue'; return say(d.error || 'Could not save your number.', true); }
    if(typeof onDone === 'function') onDone();
  });
}

// ---- Guest: report a problem during the stay (api/_stay-disputes.js) ----
function openReportProblem(orderId, listingName, arrivalOnly){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const overlay = document.createElement('div');
  overlay.className = 'payout-overlay';
  const field = 'width:100%; box-sizing:border-box; padding:11px; margin:6px 0 12px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px; background:#fff;';
  overlay.innerHTML = `<div class="payout-sheet" role="dialog" aria-label="Report a problem">
    <button type="button" class="payout-close" aria-label="Close">×</button>
    <h2 style="font-family:'Bodoni Moda', Georgia, serif; font-weight:500; font-size:24px; margin:4px 0 6px;">Report a problem</h2>
    <p class="payout-muted" style="margin:0 0 14px;">${esc(listingName)}</p>
    <p class="step-help">Tell your host and Aerva what is wrong, with photos. Aerva decides after hearing your host.</p>
    <p class="step-help" id="rpPromise" style="background:#f4eadc; border-radius:8px; padding:10px 12px;"><strong>Aerva’s check-in promise:</strong> if the place does not exist, or is not as listed or not available when you arrive, report it now, on your check-in day (no later than 10 AM the next day). Waiting can cost you your booking payment. Aerva treats it as urgent. If Aerva confirms it, you are offered other places nearby (you pay only any difference; if it costs less, the difference comes back as Aerva credit) — or everything you paid is refunded in full, including Aerva’s service fee.</p>
    <label class="payout-label" for="rpReason">What is the problem?</label>
    <select id="rpReason" style="${field}">
      <option value="arrival_fake">On arrival: the property does not exist</option>
      <option value="arrival_failed">On arrival: not as listed, or not available</option>
      <option value="not_as_described">Not as described in the listing</option>
      <option value="unsafe">Unsafe or not working (water, power, locks, etc.)</option>
      <option value="not_clean">Not clean</option>
      <option value="no_access">Could not get in</option>
      <option value="host_conduct">Host behaviour</option>
      <option value="other">Something else</option>
    </select>
    <label class="payout-label" for="rpDetails">Describe it</label>
    <textarea id="rpDetails" rows="4" maxlength="2000" style="${field}"></textarea>
    <label class="payout-label" for="rpFiles">Photos or documents (at least one, up to 8)</label>
    <input id="rpFiles" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" style="margin:6px 0 14px; font-size:15px;">
    <button type="button" class="btn solid" id="rpSend" style="width:100%;">Send report</button>
    <p id="rpMsg" style="font-size:14px; color:#a3402f; margin-top:10px;"></p>
  </div>`;
  // Escape closes the sheet, and focus starts inside it (keyboard / screen readers).
  const onEsc = (e) => { if(e.key === 'Escape' && overlay === [...document.querySelectorAll('.payout-overlay')].pop()) close(); };
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onEsc); };
  document.addEventListener('keydown', onEsc);
  setTimeout(() => { const b = overlay.querySelector('.payout-close'); if(b && overlay.isConnected) b.focus(); }, 0);
  overlay.addEventListener('click', (e) => { if(e.target === overlay) close(); });
  overlay.querySelector('.payout-close').addEventListener('click', close);
  // The guest staying on a gift reports problems on arrival only.
  if(arrivalOnly) overlay.querySelectorAll('#rpReason option').forEach(o => { if(!/^arrival_/.test(o.value)) o.remove(); });
  document.body.appendChild(overlay);
  overlay.querySelector('#rpSend').addEventListener('click', async () => {
    const msg = overlay.querySelector('#rpMsg'); const btn = overlay.querySelector('#rpSend');
    const files = [...overlay.querySelector('#rpFiles').files].slice(0, 8);
    if(!files.length){ msg.textContent = 'Please add at least one photo or document.'; return; }
    btn.disabled = true; btn.textContent = 'Sending…'; msg.textContent = '';
    try{
      const evidence = await aervaUploadFiles(files, 'dispute-evidence');
      const r = await fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
        body: JSON.stringify({ mode: 'raiseDispute', orderId, reason: overlay.querySelector('#rpReason').value, details: overlay.querySelector('#rpDetails').value, evidence }) });
      const d = await r.json();
      if(!r.ok) throw new Error(d.error || 'Could not send your report.');
      const urgent = /^arrival_/.test(overlay.querySelector('#rpReason').value);
      overlay.querySelector('.payout-sheet').innerHTML = urgent
        ? '<h2 style="font-family:\'Bodoni Moda\', Georgia, serif; font-weight:500;">Aerva is on it</h2><p>Your report is urgent: Aerva is checking it with your host now. If it is confirmed, you will see other places to choose from in My Bookings (and by email), or you can have everything refunded in full.</p><button type="button" class="btn solid" style="width:100%;" onclick="this.closest(\'.payout-overlay\').remove(); if(typeof loadMyBookings === \'function\') loadMyBookings();">Close</button>'
        : '<h2 style="font-family:\'Bodoni Moda\', Georgia, serif; font-weight:500;">Report sent</h2><p>Your host has been told, and Aerva will decide after hearing them. We will email you the outcome.</p><button type="button" class="btn solid" style="width:100%;" onclick="this.closest(\'.payout-overlay\').remove()">Close</button>';
    }catch(err){ msg.textContent = err.message; btn.disabled = false; btn.textContent = 'Send report'; }
  });
}

// ---- Guest: change a booking ----
// New dates, guests, pets and add-ons; the new price and the difference are
// shown before anything is sent. The request goes to the host in Messages.
async function openChangeBooking(orderId, listingName, chose){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const inr = (n) => moneyBoth(n);
  const overlay = document.createElement('div');
  overlay.className = 'payout-overlay';
  overlay.innerHTML = `<div class="payout-sheet" role="dialog" aria-label="Change booking">
    <button type="button" class="payout-close" aria-label="Close">×</button>
    <h2 style="font-family:'Bodoni Moda', Georgia, serif; font-weight:500; font-size:24px; margin:4px 0 6px;">Change booking</h2>
    <p class="payout-muted" style="margin:0 0 14px;">${esc(listingName)}</p>
    <div id="chBody"><p class="payout-muted">Loading…</p></div>
  </div>`;
  // Escape closes the sheet, and focus starts inside it (keyboard / screen readers).
  const onEsc = (e) => { if(e.key === 'Escape' && overlay === [...document.querySelectorAll('.payout-overlay')].pop()) close(); };
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onEsc); };
  document.addEventListener('keydown', onEsc);
  setTimeout(() => { const b = overlay.querySelector('.payout-close'); if(b && overlay.isConnected) b.focus(); }, 0);
  overlay.addEventListener('click', (e) => { if(e.target === overlay) close(); });
  overlay.querySelector('.payout-close').addEventListener('click', close);
  document.body.appendChild(overlay);
  const body = overlay.querySelector('#chBody');
  const auth = { 'Authorization': 'Bearer ' + guestAuthToken() };
  let o;
  try{
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=changeOptions&orderId=' + encodeURIComponent(orderId), { headers: auth });
    o = await r.json();
    if(!r.ok){ body.innerHTML = `<p class="payout-muted">${esc(o.error || 'This booking cannot be changed.')}</p>`; return; }
  }catch(err){ body.innerHTML = '<p class="payout-muted">Could not load this. Try again.</p>'; return; }
  if(o.openChange){ body.innerHTML = `<p>You already have a change open: ${esc(o.openChange.summary)}.</p>`; return; }
  const field = 'width:100%; box-sizing:border-box; padding:11px; margin:6px 0 12px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px; background:#fff;';
  // A stay whose host has other properties (same co-hosts): choose what to do first.
  if(o.onlyTransfer){
    if(!o.canTransfer){ body.innerHTML = '<p class="payout-muted">This booking can no longer be changed.</p>'; return; }
    aervaTransferForm(body, o, orderId, { esc, inr, field, auth });
    return;
  }
  if(o.canTransfer && !chose){
    body.innerHTML = `<p class="step-help">What would you like to do?</p>
      <button type="button" class="btn solid" id="chPickChange" style="width:100%; margin:6px 0;">Change dates, guests or add-ons</button>
      <button type="button" class="btn" id="chPickMove" style="width:100%; margin:6px 0;">Move nights to another property of this host</button>`;
    body.querySelector('#chPickMove').addEventListener('click', () => aervaTransferForm(body, o, orderId, { esc, inr, field, auth }));
    body.querySelector('#chPickChange').addEventListener('click', () => { overlay.remove(); openChangeBooking(orderId, listingName, true); });
    return;
  }
  const num = (id, label, value, min, max) => `<label class="payout-label" for="${id}">${label}</label>
    <select id="${id}" style="${field}">${Array.from({ length: max - min + 1 }, (_, i) => min + i).map(n => `<option value="${n}"${n === value ? ' selected' : ''}>${n}</option>`).join('')}</select>`;
  const maxG = o.limits.maxGuests || 16;
  const isStay = o.kind === 'stay';
  body.innerHTML = `
    ${bookStep(1, isStay ? 'New dates' : 'New date')}
    ${o.kind === 'pair' ? '<p class="step-help">This experience includes a stay. Both move together.</p>' : ''}
    ${o.started ? `<p class="step-help">${isStay ? `Your stay has started (from 12 AM on the check-in date), so check-in stays ${esc(new Date(o.current.arrival + 'T00:00:00Z').toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }))}. You can bring check-out forward: the check-in night stays part of your stay. <strong>Leaving early: you won’t get anything back for the nights you don’t stay.</strong>` : 'This has already started, so the date cannot move. You can change the number of guests.'}${o.windowEndsLabel ? ` Changes during a stay can be asked for until ${esc(o.windowEndsLabel)} (the property’s time).` : ''}</p>` : ''}
    <label class="payout-label" for="chIn">${isStay ? 'Check-in' : 'Date'}</label>
    <input id="chIn" type="date" value="${esc(o.current.arrival)}" min="${esc(o.today)}" ${o.started ? 'disabled' : ''} style="${field}">
    ${isStay ? `<label class="payout-label" for="chOut">Check-out</label>
    <input id="chOut" type="date" value="${esc(o.current.departure)}"${o.started ? ` min="${esc([o.today, new Date(new Date(o.current.arrival + 'T00:00:00Z').getTime() + 864e5).toISOString().slice(0, 10)].sort().pop())}"` : ''} style="${field}">` : ''}
    ${bookStep(2, 'Who is coming')}
    ${num('chAdults', 'Adults (18 or over)', Math.max(1, o.current.guests), 1, maxG)}
    ${num('chChildren', 'Children (2–17)', 0, 0, maxG)}
    ${o.limits.petFriendly ? num('chPets', 'Pets', o.current.pets, 0, o.limits.maxPets != null ? o.limits.maxPets : 5)
      + (o.limits.petTypes.length ? `<div id="chPetTypes" style="margin:-4px 0 12px;">${o.limits.petTypes.map(t => `<label style="margin-right:14px; font-size:15px;"><input type="checkbox" value="${esc(t)}"${o.current.petTypes.includes(t) ? ' checked' : ''}> ${esc(t)}</label>`).join('')}</div>` : '') : ''}
    ${o.limits.amenities.length ? `${bookStep(3, 'Add-ons')}<div id="chAmenities">${o.limits.amenities.map(a => `<label style="display:flex; justify-content:space-between; gap:10px; padding:8px 0; border-bottom:1px solid #eee; font-size:15px;"><span><input type="checkbox" value="${a.id}"${o.current.amenityIds.includes(a.id) ? ' checked' : ''}> ${esc(a.name)}</span><span>${inr(a.price)} a night</span></label>`).join('')}</div>` : ''}
    <button type="button" class="btn solid" id="chQuote" style="width:100%; margin-top:16px;">See the new price</button>
    <div id="chResult"></div>
    <p id="chMsg" class="payout-muted" style="margin-top:10px; color:#a3402f;"></p>`;
  const read = () => ({
    arrival: overlay.querySelector('#chIn').value, departure: overlay.querySelector('#chOut') ? overlay.querySelector('#chOut').value : '',
    adults: Number(overlay.querySelector('#chAdults').value), children: Number(overlay.querySelector('#chChildren').value), infants: 0,
    pets: overlay.querySelector('#chPets') ? Number(overlay.querySelector('#chPets').value) : 0,
    petTypes: [...overlay.querySelectorAll('#chPetTypes input:checked')].map(i => i.value),
    amenityIds: [...overlay.querySelectorAll('#chAmenities input:checked')].map(i => Number(i.value))
  });
  const post = (payload) => fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, auth), body: JSON.stringify(payload) })
    .then(async r => ({ ok: r.ok, d: await r.json().catch(() => ({})) }));
  // An edit after pricing makes the shown quote stale: clear it so the
  // request sent is always the one the guest sees priced.
  body.querySelectorAll('input, select').forEach(el => el.addEventListener('change', () => {
    overlay.querySelector('#chResult').innerHTML = ''; overlay.querySelector('#chMsg').textContent = '';
  }));
  overlay.querySelector('#chQuote').addEventListener('click', async () => {
    const msg = overlay.querySelector('#chMsg'); const out = overlay.querySelector('#chResult');
    msg.textContent = ''; out.innerHTML = '';
    const change = read();
    const { ok, d } = await post({ mode: 'changeQuote', orderId, change });
    if(!ok){ msg.textContent = d.error || 'Could not price this change.'; return; }
    const line = (l, v) => `<div class="payout-line"><span>${esc(l)}</span><span>${v}</span></div>`;
    const kept = Math.max(0, Number(d.couponNotReturned) || 0);
    const diffText = d.difference > 0 ? `You pay ${inr(d.difference)} more` : d.difference < 0 ? (-d.difference - kept > 0 ? `You get back ${inr(-d.difference - kept)}` : 'Nothing is refunded') : d.leavingEarly ? 'Nothing comes back' : 'The total stays the same';
    // Leaving early (owner, 10 Nov 2026 01:28): said before the guest confirms.
    const early = d.leavingEarly ? `<p class="step-help" id="chLeavingEarly" style="background:#fff4e5; border:1px solid #e8c48a; border-radius:8px; padding:10px 12px; margin:10px 0;"><strong>${esc(d.leavingEarly.message || 'Leaving early: you won’t get anything back for the nights you don’t stay.')}</strong> The dates are freed, your host is paid for the original dates, and nothing is refunded or held as credit (${inr(d.leavingEarly.notRefunded)} for the nights you don’t stay).</p>` : '';
    out.innerHTML = `${bookStep(o.limits.amenities.length ? 4 : 3, 'Check the new total')}
      <p class="step-help">${d.summary ? d.summary.split('; ').map(esc).join('<br>') : 'Nothing has changed yet.'}</p>
      ${d.lines.map(l => line(l.label, inr(l.amount))).join('')}
      <div style="border-top:1px solid var(--hairline); margin-top:8px; padding-top:4px;"></div>
      ${line('Current total', inr(d.oldTotal))}
      ${line('New total', '<strong>' + inr(d.newTotal) + '</strong>')}
      <div class="sum-row" style="font-weight:600; font-size:18px; padding-top:10px;"><span>${diffText}</span><span></span></div>
      ${early}
      <p class="pay-note" style="text-align:left;">Your host is asked first. ${d.difference > 0 ? 'Once they accept, you pay the difference to confirm.' : d.difference < 0 ? (kept > 0 ? `Once they accept, the difference is refunded to your original payment, except ${inr(kept)} that was paid by coupon — a coupon is returned only when the host cancels. Aerva\u2019s service fee stays as charged.` : 'Once they accept, the difference is refunded to your original payment. Aerva\u2019s service fee stays as charged.') : ''} Until then your booking stays as it is.</p>
      ${d.summary ? '<button type="button" class="btn solid" id="chSend" style="width:100%; margin-top:10px;">Send change request to host</button>' : ''}`;
    const send = out.querySelector('#chSend');
    if(send) send.addEventListener('click', async () => {
      if(d.leavingEarly && !confirm('Leaving early: you won’t get anything back for the nights you don’t stay. Send the request?')) return;
      send.disabled = true;
      const res = await post({ mode: 'requestChange', orderId, change });
      if(!res.ok){ msg.textContent = res.d.error || 'Could not send the request.'; send.disabled = false; return; }
      body.innerHTML = '<p>Your change request has been sent to your host in Messages. We will email you when they answer.</p>';
      if(typeof loadMyBookings === 'function') loadMyBookings();
    });
  });
}

// ---- Guest: move nights to another property of the same host ----
// 1. Choose the nights. 2. See only the host's properties free for them
// (same host and co-hosts). 3. See the payment summary — Aerva's 5%
// transfer fee included — and send the request. The host or a co-host
// accepts; only then is anything paid or refunded (_booking-transfers.js).
function aervaTransferForm(body, o, orderId, { esc, inr, field, auth }){
  const addDay = (d, n) => { const x = new Date(d + 'T00:00:00Z'); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };
  // At least one night stays at this property: by default the last nights move, and never all of them.
  let firstAllowed = [o.today, o.started ? addDay(o.current.arrival, 1) : o.current.arrival].sort().pop();
  const defaultFrom = firstAllowed === o.current.arrival ? addDay(firstAllowed, 1) : firstAllowed;
  body.innerHTML = `
    ${bookStep(1, 'Which nights move')}
    <p class="step-help">Choose the first and last night you would like to spend at another property of this host. Your check-in and check-out dates stay the same — the nights are split between the two properties. Any nights can move (the start, the end or the middle), but at least one night must stay here.${o.started ? ' You have checked in, so the check-in night stays.' : ''}</p>
    <label class="payout-label" for="trFrom">First night at the other property</label>
    <input id="trFrom" type="date" value="${esc(defaultFrom > o.lastNight ? firstAllowed : defaultFrom)}" min="${esc(firstAllowed)}" max="${esc(o.lastNight)}" style="${field}">
    <label class="payout-label" for="trLast">Last night at the other property</label>
    <input id="trLast" type="date" value="${esc(o.lastNight)}" min="${esc(firstAllowed)}" max="${esc(o.lastNight)}" style="${field}">
    <button type="button" class="btn solid" id="trFind" style="width:100%; margin-top:6px;">Find available properties</button>
    <div id="trTargets"></div>
    <div id="trResult"></div>
    <p id="trMsg" class="payout-muted" style="margin-top:10px; color:#a3402f;"></p>`;
  const msg = body.querySelector('#trMsg');
  const range = () => { const from = body.querySelector('#trFrom').value, last = body.querySelector('#trLast').value; return { from, to: last ? addDay(last, 1) : '' }; };
  const post = (payload) => fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, auth), body: JSON.stringify(payload) })
    .then(async r => ({ ok: r.ok, d: await r.json().catch(() => ({})) }));
  const clearBelow = () => { body.querySelector('#trTargets').innerHTML = ''; body.querySelector('#trResult').innerHTML = ''; msg.textContent = ''; };
  body.querySelector('#trFrom').addEventListener('change', clearBelow);
  body.querySelector('#trLast').addEventListener('change', clearBelow);
  body.querySelector('#trFind').addEventListener('click', async () => {
    clearBelow();
    const { from, to } = range();
    if(!from || !to || to <= from){ msg.textContent = 'Choose the first and last night.'; return; }
    if(from <= o.current.arrival && to >= o.current.departure){ msg.textContent = 'At least one night must stay at this property. Choose fewer nights to move.'; return; }
    const box = body.querySelector('#trTargets');
    box.innerHTML = '<p class="payout-muted">Checking availability…</p>';
    let d;
    try{
      const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=transferTargets&orderId=' + encodeURIComponent(orderId) + '&from=' + from + '&to=' + to, { headers: auth });
      d = await r.json();
      if(!r.ok){ box.innerHTML = ''; msg.textContent = d.error || 'Could not look for other properties.'; return; }
    }catch(e){ box.innerHTML = ''; msg.textContent = 'Could not look for other properties. Try again.'; return; }
    if(!d.targets.length){ box.innerHTML = `<p class="step-help">None of this host’s other properties is free for ${d.nights === 1 ? 'that night' : 'those ' + d.nights + ' nights'}. Try other nights.</p>`; return; }
    box.innerHTML = `${bookStep(2, 'Where to')}
      <p class="step-help">Free for ${d.nights === 1 ? 'that night' : 'all ' + d.nights + ' nights'}, with the same host and co-hosts:</p>
      ${d.targets.map((t, i) => `<label style="display:flex; gap:12px; align-items:center; padding:10px; margin:6px 0; border:1px solid #d9cfc2; border-radius:10px; cursor:pointer;">
        <input type="radio" name="trTarget" value="${i}"${i === 0 ? ' checked' : ''}>
        ${t.photo ? `<img src="${esc(t.photo)}" alt="" style="width:64px; height:48px; object-fit:cover; border-radius:6px;">` : ''}
        <span style="flex:1;"><strong>${esc(t.name)}</strong>${t.city ? `<br><span class="payout-muted">${esc(t.city)}</span>` : ''}<br><span class="payout-muted">${esc(t.cancellationPolicy)} cancellation policy</span></span>
        <span style="white-space:nowrap; text-align:right;">${inr(t.priceForNights)}<br><span class="payout-muted" style="font-size:12px;">incl. GST, fee, deposit</span></span></label>`).join('')}
      <button type="button" class="btn solid" id="trQuote" style="width:100%; margin-top:10px;">See the payment summary</button>`;
    box.querySelector('#trQuote').addEventListener('click', async () => {
      const t = d.targets[Number((box.querySelector('input[name=trTarget]:checked') || {}).value) || 0];
      const change = { kind: 'transfer', moveFrom: d.moveFrom, moveTo: d.moveTo, targetListingId: t.listingId, targetRoomId: t.roomId };
      const out = body.querySelector('#trResult'); out.innerHTML = ''; msg.textContent = '';
      const { ok, d: q } = await post({ mode: 'changeQuote', orderId, change });
      if(!ok){ msg.textContent = q.error || 'Could not price this.'; return; }
      const line = (l, v) => `<div class="payout-line"><span>${esc(l)}</span><span>${v}</span></div>`;
      const kept = Math.max(0, Number(q.couponNotReturned) || 0);
      const diffText = q.difference > 0 ? `You pay ${inr(q.difference)} more` : q.difference < 0 ? (-q.difference - kept > 0 ? `You get ${inr(-q.difference - kept)} back as Aerva credit` : 'Nothing comes back') : 'The total stays the same';
      out.innerHTML = `${bookStep(3, 'Payment summary')}
        <p class="step-help">${esc(q.summary)}.</p>
        ${q.lines.map(l => line(l.label, inr(l.amount))).join('')}
        <div style="border-top:1px solid var(--hairline); margin-top:8px; padding-top:4px;"></div>
        ${line('Current total', inr(q.oldTotal))}
        ${line('New total', '<strong>' + inr(q.newTotal) + '</strong>')}
        <div class="sum-row" style="font-weight:600; font-size:18px; padding-top:10px;"><span>${diffText}</span><span></span></div>
        <p class="pay-note" style="text-align:left;">Your host is asked first. Once they accept, you complete the transfer in My Bookings within 24 hours: ${q.difference > 0 ? 'by paying the difference.' : q.difference < 0 ? `by accepting the difference as Aerva credit${kept > 0 ? ` (except ${inr(kept)} that was paid by coupon)` : ''} — use it on another booking, or have it refunded to your original payment method at any time from My Bookings.` : 'by confirming it.'} Aerva’s transfer fee is ${inr(q.transfer.transferFee)} and is not refundable once the transfer is complete. If your host declines, or you do not complete it, nothing changes and nothing is charged.</p>
        <div style="margin-top:12px; padding:12px 14px; border:1px solid #c9a96a; border-radius:10px; background:#fbf6ec;">
          <p style="margin:0 0 6px; font-weight:600;">Before you send this, please read</p>
          <ul style="margin:0; padding-left:18px; font-size:14px; line-height:1.55;">
            <li><strong>What is charged:</strong> Aerva’s transfer fee of ${inr(q.transfer.transferFee)} (5% of the moved nights at the current property) is already counted in the new total. ${q.difference > 0 ? `You pay ${inr(q.difference)} more.` : q.difference < 0 ? `After it, ${inr(-q.difference - kept)} comes back to you as Aerva credit${kept > 0 ? ` (${inr(kept)} paid by coupon is not returned)` : ''}.` : 'You pay nothing more and get nothing back.'} Nothing else is added.</li>
            <li><strong>If your host declines</strong>, or you do not complete it within 24 hours of their acceptance: nothing changes and nothing is charged.</li>
            <li><strong>Once completed, it is final.</strong> The transfer cannot be undone, and no part of the booking can be changed, moved, split again, shortened <strong>or cancelled</strong> — even if your plans change.</li>
            <li>Each part gets its own confirmation code. Your check-in and check-out dates stay the same.</li>
            ${q.difference < 0 ? '<li>Aerva credit can be used on any booking, or refunded to your original payment method at any time from My Bookings; whatever is left when it ends is refunded automatically.</li>' : ''}
            <li>If something is not working after the transfer, raise a request in the Resolution Center. Aerva will look at it and make the final decision.</li>
          </ul>
          <label style="display:flex; gap:8px; align-items:flex-start; margin-top:10px; font-size:14px;"><input type="checkbox" id="trAgree" style="margin-top:3px;"> I understand: once completed, this transfer is final and the booking cannot be changed or cancelled.</label>
        </div>
        <p class="pay-note" style="text-align:left;">The moved nights become a separate booking at ${esc(q.transfer.toName)}. Its ${esc(q.transfer.newPolicy)} cancellation policy applies only if the host or Aerva cancels; you can no longer cancel.</p>
        <button type="button" class="btn solid" id="trSend" style="width:100%; margin-top:10px;">Send transfer request to host</button>`;
      out.querySelector('#trSend').addEventListener('click', async (ev) => {
        const send = ev.currentTarget;
        if(!out.querySelector('#trAgree').checked){ msg.textContent = 'Please tick the box to confirm you understand the transfer is final.'; return; }
        send.disabled = true;
        const res = await post({ mode: 'requestChange', orderId, change: Object.assign({ understood: true }, change) });
        if(!res.ok){ msg.textContent = res.d.error || 'Could not send the request.'; send.disabled = false; return; }
        body.innerHTML = '<p>Your transfer request has been sent to your host in Messages. We will email you when they answer.</p>';
        if(typeof loadMyBookings === 'function') loadMyBookings();
      });
    });
  });
}

// ---- Complete your account (guests, under 5 minutes; _setup-steps.js) ----
// Email → name → phone → photo (optional), in that order, above My Bookings.
async function aervaGuestSetupBanner(container, token){
  try{
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=setupSteps', { headers: { 'Authorization': 'Bearer ' + token } });
    const d = await r.json();
    const items = (r.ok && d.items) || [];
    let box = document.getElementById('guestSetupBanner');
    const left = items.filter(i => !i.done && !i.optional);
    if(!left.length){ if(box) box.remove(); return; }
    if(!box && container && container.parentNode){ box = document.createElement('div'); box.id = 'guestSetupBanner'; container.parentNode.insertBefore(box, container); }
    if(!box) return;
    const esc = escapeMessageHtml;
    box.style.cssText = 'margin:0 0 18px; padding:14px 16px; border:1px solid #e3d6c1; border-radius:12px; background:#fbf8f3;';
    box.innerHTML = `<strong>Complete your account</strong> <span style="opacity:0.7; font-size:13.5px;">· ${left.length} step${left.length === 1 ? '' : 's'} left, about 2 minutes</span>
      <ol style="margin:8px 0 0; padding-left:20px; font-size:14px; line-height:1.8;">${items.map(i => `<li>${i.done ? `<span style="opacity:0.6;">✅ ${esc(i.label)}</span>` : `<a href="${esc(i.href)}" style="color:var(--gold-text);">${esc(i.label)}</a>${i.optional ? ' <span style="opacity:0.6;">(optional)</span>' : ''} <span style="opacity:0.65; font-size:13px;">— ${esc(i.optional ? String(i.why || '').replace(/^Optional\s*[—–-]\s*/i, '') : i.why)}</span>`}</li>`).join('')}</ol>`;
  }catch(e){ /* the bookings still load */ }
}

// ---- Aerva's check-in promise (api/_checkin-promise.js) ----
// On the booking card: where a report on arrival stands, the places Aerva
// offers (accept one, or decline all for a full refund), the question
// "Is this place real and as listed?", and — on a booking Aerva moved —
// one line saying so. Everything server-side decides; this only shows it.
function aervaCheckinPromiseHtml(b){
  const esc = escapeMessageHtml;
  const money = (n) => moneyBoth(n);
  const box = 'margin:10px 0 0; padding:12px 14px; border:1px solid #e3d9cb; border-radius:10px; background:#fbf8f3; font-size:14px; line-height:1.55;';
  let html = '';
  const c = b.checkin;
  if(c){
    const ch = b.open_change;
    const paying = ch && ch.status === 'awaiting_payment' && Number(ch.difference) > 0;
    html += `<div class="cp-box" style="${box}" onclick="event.stopPropagation()">
      <strong>Aerva’s check-in promise</strong><br><span>${esc(c.statusText || '')}</span>${c.note ? `<br><span style="opacity:0.8;">${esc(c.note)}</span>` : ''}`;
    if(c.offers && c.offers.length){
      html += `<p style="margin:8px 0 6px;">Choose a place for ${esc(new Date(c.offers[0].from + 'T00:00:00Z').toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' }))} – ${esc(new Date(c.offers[0].to + 'T00:00:00Z').toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' }))}. You pay only the difference:</p>`;
      html += c.offers.map(o => `<div class="cp-offer" style="display:flex; gap:10px; align-items:flex-start; flex-wrap:wrap; justify-content:space-between; padding:10px 0; border-top:1px solid #eadfcf;">
          <div style="flex:1 1 220px; min-width:0;"><strong>${esc(o.name)}</strong>${o.distanceKm != null ? ` <span style="opacity:0.7;">· ${esc(String(o.distanceKm))} km away</span>` : ''}<br>
            <span style="font-size:13px; opacity:0.85;">${o.nights} night${o.nights === 1 ? '' : 's'}: stay ${money(o.subtotal)} · GST ${money(o.gst)} · service fee ${money(o.fee)}${o.deposit ? ` · refundable deposit ${money(o.deposit)}` : ''} = <strong>${money(o.total)}</strong></span><br>
            <span style="font-size:13px;">You paid ${money(o.oldTotal)} · ${o.difference > 0 ? `<strong>you pay ${money(o.difference)} more</strong>` : o.difference < 0 ? `<strong>${money(-o.difference)} back to you as Aerva credit</strong>` : '<strong>nothing more to pay</strong>'}</span></div>
          ${paying ? '' : `<button type="button" class="btn solid" data-cp-accept="${b.id}" data-cp-option="${Number(o.n)}" style="min-height:44px; padding:10px 18px;">Choose this place</button>`}
        </div>`).join('');
      if(paying) html += `<p style="margin:8px 0;"><button type="button" class="btn solid" data-pay-change="${ch.id}" style="min-height:44px; padding:10px 18px;">Pay ${money(ch.difference)} to confirm your new place</button></p>`;
    }
    if(c.canDecline) html += `<p style="margin:8px 0 0;"><button type="button" class="filter-clear" data-cp-decline="${b.id}">${c.offers && c.offers.length ? 'None of these — refund me in full' : 'Refund me in full instead'}</button> <span style="font-size:12.5px; opacity:0.75;">Everything you paid comes back, including Aerva’s service fee.</span></p>`;
    html += '<p class="cp-msg" style="color:#a3402f; margin:6px 0 0;"></p></div>';
  }
  if(b.can_confirm_real){
    html += `<div class="cp-box" style="${box}" onclick="event.stopPropagation()"><strong>Is this place real and as listed?</strong>
      <p style="margin:4px 0 8px;">Help other guests: confirm it, or use Report a problem (with a photo) if it does not exist, or is not as listed or not available.</p>
      <button type="button" class="btn solid" data-cp-real="${b.id}" style="min-height:44px; padding:10px 18px;">This place is real and as listed</button><p class="cp-msg" style="color:#a3402f; margin:6px 0 0;"></p></div>`;
  } else if(b.confirmed_real && b.status === 'paid'){
    html += '<p style="font-size:13px; opacity:0.75; margin:8px 0 0;">You confirmed this place is real and as listed. Thank you.</p>';
  }
  if(b.checkin_summary){
    const s = b.checkin_summary;
    html += `<p style="font-size:13.5px; margin:8px 0 0;">Booked by Aerva under its check-in promise (instead of ${esc(s.from)}). You paid ${money(s.originalTotal)}${s.difference > 0 ? ` + ${money(s.difference)}` : s.difference < 0 ? ` − ${money(-s.difference)} back as Aerva credit` : ''} = <strong>${money(s.total)}</strong>.</p>`;
  }
  return html;
}
function aervaBindCheckinPromise(container, bookings){
  const post = async (body) => {
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() }, body: JSON.stringify(body) });
    const d = await r.json().catch(() => ({}));
    if(!r.ok) throw new Error(d.error || 'Could not do this right now.');
    return d;
  };
  const say = (btn, t) => { const m = btn.closest('.cp-box') && btn.closest('.cp-box').querySelector('.cp-msg'); if(m) m.textContent = t; };
  container.querySelectorAll('[data-cp-accept]').forEach(btn => btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    if(!confirm('Choose this place? Your booking moves there; the price difference is shown above.')) return;
    btn.disabled = true;
    try{
      const d = await post({ mode: 'acceptRebook', orderId: Number(btn.dataset.cpAccept), option: Number(btn.dataset.cpOption) });
      if(d.pay > 0 && d.changeId){ aervaPayChange(Number(d.changeId), btn); return; }
      loadMyBookings();
    }catch(err){ say(btn, err.message); btn.disabled = false; }
  }));
  container.querySelectorAll('[data-cp-decline]').forEach(btn => btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    if(!confirm('Have everything you paid refunded in full (price, GST, deposit and Aerva’s service fee)? The booking is then closed.')) return;
    btn.disabled = true;
    try{ await post({ mode: 'declineRebook', orderId: Number(btn.dataset.cpDecline) }); loadMyBookings(); }
    catch(err){ say(btn, err.message); btn.disabled = false; }
  }));
  container.querySelectorAll('[data-cp-real]').forEach(btn => btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    btn.disabled = true;
    try{ await post({ mode: 'confirmStay', orderId: Number(btn.dataset.cpReal) }); loadMyBookings(); }
    catch(err){ say(btn, err.message); btn.disabled = false; }
  }));
}
// The booking summary page: one amount for a booking Aerva moved.
function aervaPromiseSummaryHtml(b, inr){
  const s = b.checkin_summary;
  if(!s) return '';
  const esc = escapeMessageHtml;
  return `<div class="bk-card" style="margin:0 0 16px;">
    <h3>Aerva’s check-in promise</h3>
    <p class="bk-note" style="margin:0 0 8px;">Your original booking (${esc(s.from)}${s.fromCode ? `, ${esc(s.fromCode)}` : ''}) could not go ahead as listed, so Aerva booked you here instead. It is one booking:</p>
    <div class="bk-row"><span>Paid for your original booking</span><span>${inr(s.originalTotal)}</span></div>
    ${s.difference ? `<div class="bk-row"><span>${s.difference > 0 ? 'Difference you paid' : 'Difference back to you as Aerva credit'}</span><span>${s.difference > 0 ? '+' : '−'}${inr(Math.abs(s.difference))}</span></div>` : ''}
    <div class="bk-row bk-total"><span>Your booking now</span><span>${inr(s.total)}</span></div>
  </div>`;
}

// ---- Your booking at a glance (owner, 9 Nov 2026: no surprises) ----
// What the guest can still do on this booking, and until when — from the
// booking's own policy, check-in date and what the server says is open.
function aervaBookingGlance(b){
  const esc = escapeMessageHtml;
  const arr = String(b.arrival || '').slice(0, 10);
  if(!arr) return '';
  const minus = (n) => { const d = new Date(arr + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - n); return d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' }); };
  const next = (() => { const d = new Date(arr + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 1); return d.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'UTC' }); })();
  const policy = (b.cancellation_policy || b.listing_cancellation_policy || 'flexible') === 'firm' ? 'firm' : 'flexible';
  const items = [];
  if(b.transferred){
    items.push('This booking was transferred: it can no longer be changed or cancelled. For any problem, raise a request in the Resolution Center; Aerva decides.');
  } else {
    // The free cancellation add-on: a full refund until 48 hours before check-in.
    if(b.free_cancel_included === true && b.free_cancel_until_label && b.can_cancel_request !== false){
      items.push(b.free_cancel_active
        ? `Full refund until ${b.free_cancel_until_label} (the property’s time): this booking includes free cancellation. Cancel before then and the booking price, GST and deposit come back at once — no wait for your host. The service fee is not refunded. After that, the refund policy below applies.`
        : `Free cancellation ended ${b.free_cancel_until_label} (the property’s time); the refund policy below applies.`);
    } else if(Number(b.free_cancel_fee) > 0 && b.free_cancel_until_label && b.can_cancel_request !== false){
      items.push(b.free_cancel_active
        ? `Full refund until ${b.free_cancel_until_label} (the property’s time): you added free cancellation. Cancel before then and the booking price, GST and deposit come back at once — no wait for your host. The add-on and the service fee are not refunded. After that, the refund policy below applies.`
        : `Free cancellation ended ${b.free_cancel_until_label} (the property’s time); the refund policy below applies. The add-on is not refunded.`);
    }
    if(b.can_cancel_request !== false && b.group){
      // A confirmed group booking is non-refundable (_cancellations.js groupNoRefund), whatever the listing's policy.
      items.push('Cancel: this is a non-refundable group booking. If plans change, nothing is refunded for the stay, its GST or the service fee, whatever the listing’s policy; any deposit goes back to each payer.');
      items.push('Natural disaster or government order (with proof), any time before check-in: Aerva decides. If approved, each payer gets their own share as Aerva credit (use it for new dates, or have it refunded to their own payment any time). If not, the booking stands.');
    } else if(b.can_cancel_request !== false){
      items.push(policy === 'firm'
        ? `Cancel (Firm): full refund of the price and GST until ${minus(30)}; 50% until ${minus(5)}; after that your host decides. Service fee not refunded; deposit always refunded.`
        : `Cancel (Flexible): full refund until ${minus(30)}; 80% until ${minus(10)}; 50% until ${minus(5)}; 30% until ${minus(2)}; after that your host decides. Service fee not refunded; deposit always refunded.`);
      // The brackets end at the check-in time on that date, not at midnight
      // (_booking-rules.js checkInMomentMs; 2:00 PM when the listing has none).
      items[items.length - 1] = items[items.length - 1].replace('. Service fee', ` (each date until ${b.check_in_time || '2:00 PM'}, the check-in time, property’s time). Service fee`);
      items.push('Natural disaster or government order (with proof), any time before check-in: Aerva decides. If approved, what you paid becomes Aerva credit (use it for new dates, or have it refunded to your original payment any time) and any deposit is refunded to your payment. If not, the booking stands.');
    } else {
      items.push('Your stay has started: it can no longer be cancelled.');
    }
    if(b.can_change !== false) items.push(`Change dates, guests or add-ons${b.group ? ' (guests can only be added)' : ', or move nights to another property of this host'}: until 10 AM on ${next} (the property’s time). Before check-in a cheaper change refunds the difference; leaving early after check-in gives nothing back for the nights you don’t stay.`);
    if(!b.stay_window_closed) items.push(`Report a problem during the stay: by 10 AM on ${next}, with photos.`);
    items.push('Aerva’s check-in promise: if on arrival the place does not exist, or is not as listed or not available, report it on your check-in day, no later than 10 AM the next day (with a photo) — waiting can cost you your booking payment. Aerva moves you to another place (you pay only any difference) or refunds everything, including the service fee.');
  }
  return `<details class="booking-glance" style="margin:8px 0 0; font-size:13.5px;" onclick="event.stopPropagation()">
    <summary style="cursor:pointer; color:var(--gold-text);">Your booking at a glance</summary>
    <ul style="margin:6px 0 0; padding-left:18px; line-height:1.55;">${items.map(x => `<li>${esc(x)}</li>`).join('')}</ul></details>`;
}

// ---- Nearby: things to do and getting around (api/_nearby.js) ----
// Places from OpenStreetMap near the property: things to do, metro and
// railway stations, bus stations, taxi stands, airports, and taxi apps.
// Every link goes to a third party, so it opens only after the guest has
// read and agreed to the notice (aervaOpenThirdParty), which Aerva records.
async function aervaLoadNearby(root){
  const box = root && root.querySelector('[data-nearby-for]');
  if(!box || box.dataset.loaded) return;
  box.dataset.loaded = '1';
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const id = box.dataset.nearbyFor;
  box.innerHTML = '<div class="listing-modal-section-title" style="margin-top:22px;">Nearby</div><p style="font-size:13px; opacity:0.6;">Finding things to do and ways to get around…</p>';
  let d;
  try{
    const r = await fetch(SUITES_API_BASE + '/api/get-listings?nearby=' + encodeURIComponent(id));
    d = await r.json();
    if(!r.ok) throw new Error(d.error || 'unavailable');
  }catch(e){ box.innerHTML = ''; return; }
  const T = d.transport || {};
  const transportRows = [].concat(T.metro || [], T.train || [], T.bus || [], T.taxi || [], T.airport || []);
  if(!(d.things || []).length && !transportRows.length && !(d.taxiApps || []).length){ box.innerHTML = ''; return; }
  const dir = (p, mode) => `https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}&travelmode=${mode}`;
  const row = (p, kind, mode) => `<li style="display:flex; justify-content:space-between; gap:10px; padding:8px 0; border-bottom:1px solid #eee; font-size:14px;">
      <span><strong>${esc(p.name)}</strong><br><span style="opacity:0.7;">${esc(p.label)} · ${Number(p.km)} km</span></span>
      <span style="white-space:nowrap; text-align:right;"><a href="#" data-tp-link="${esc(p.link)}" data-tp-name="${esc(p.name)}" data-tp-kind="${kind}" style="color:var(--gold-text);">${esc(p.linkKind || 'Details')}</a><br>
      <a href="#" data-tp-link="${esc(dir(p, mode))}" data-tp-name="${esc('Directions to ' + p.name)}" data-tp-kind="directions" style="color:var(--gold-text);">Directions</a></span></li>`;
  box.innerHTML = `<div class="listing-modal-section-title" style="margin-top:22px;">Nearby</div>
    <div style="display:flex; gap:8px; margin:6px 0 8px;">
      <button type="button" class="filter-clear nb-tab" data-tab="things" style="font-weight:600;">Things to do</button>
      <button type="button" class="filter-clear nb-tab" data-tab="around">Getting around</button>
    </div>
    <div class="nb-pane" data-pane="things">${(d.things || []).length ? '<ul style="list-style:none; margin:0; padding:0;">' + d.things.map(p => row(p, 'thing', 'driving')).join('') + '</ul>' : `<p style="font-size:13px; opacity:0.7;">${d.unavailable ? 'Nearby places could not be loaded just now. Please try again later.' : 'Nothing listed nearby yet.'}</p>`}</div>
    <div class="nb-pane" data-pane="around" style="display:none;">
      ${transportRows.length ? '<ul style="list-style:none; margin:0; padding:0;">' + transportRows.map(p => row(p, 'transport', p.label === 'Airport' || /Airport/.test(p.label) ? 'driving' : 'transit')).join('') + '</ul>' : `<p style="font-size:13px; opacity:0.7;">${d.unavailable ? 'Stations nearby could not be loaded just now. Please try again later.' : 'No stations listed nearby yet.'}</p>`}
      ${(d.taxiApps || []).length ? `<p style="font-size:14px; margin:10px 0 0;">Book a taxi: ${d.taxiApps.map(a => `<a href="#" data-tp-link="${esc(a.link)}" data-tp-name="${esc(a.name)}" data-tp-kind="taxi" style="color:var(--gold-text);">${esc(a.name)}</a>`).join(' · ')}</p>` : ''}
    </div>
    <p style="font-size:12px; opacity:0.65; margin:10px 0 0; line-height:1.5;">These are third-party places and services, shown for information only. Aerva does not own, check, book or run them and is not responsible for them. ${esc(d.attribution || '')}</p>`;
  box.querySelectorAll('.nb-tab').forEach(b => b.addEventListener('click', () => {
    box.querySelectorAll('.nb-tab').forEach(x => x.style.fontWeight = x === b ? '600' : '');
    box.querySelectorAll('.nb-pane').forEach(x => x.style.display = x.dataset.pane === b.dataset.tab ? '' : 'none');
  }));
  box.querySelectorAll('[data-tp-link]').forEach(a => a.addEventListener('click', (e) => {
    e.preventDefault();
    aervaOpenThirdParty({ link: a.dataset.tpLink, name: a.dataset.tpName, kind: a.dataset.tpKind, listingId: id });
  }));
}
// The third-party notice: shown every time, agreed to by ticking, recorded, then the link opens.
function aervaOpenThirdParty({ link, name, kind, listingId }){
  if(!/^https?:\/\//i.test(String(link || ''))) return;
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  let host = ''; try { host = new URL(link).hostname.replace(/^www\./, ''); } catch (e) { return; }
  const overlay = document.createElement('div');
  overlay.className = 'payout-overlay';
  overlay.innerHTML = `<div class="payout-sheet" role="dialog" aria-label="Leaving Aerva">
    <button type="button" class="payout-close" aria-label="Close">×</button>
    <h2 style="font-family:'Bodoni Moda', Georgia, serif; font-weight:500; font-size:22px; margin:4px 0 8px;">You are leaving Aerva</h2>
    <p style="font-size:15px; margin:0 0 10px;"><strong>${esc(name)}</strong> opens on <strong>${esc(host)}</strong>, a third-party website.</p>
    <ul style="font-size:14px; line-height:1.6; padding-left:18px; margin:0 0 12px;">
      ${kind === 'host_recommendation' ? '<li>This is your host’s own suggestion. Aerva has not checked or endorsed it.</li>' : ''}
      <li>Aerva does not own, check, book, run or recommend this place, activity, transport or service, and is not part of any arrangement you make with it.</li>
      <li>Aerva is not responsible for anything that happens there or through it — including fraud, scams, violence, injury, loss, damage, delays, prices or the accuracy of what is shown.</li>
      <li>Any booking, payment, ride or visit is between you and that provider, under their terms. Please take care: check reviews, pay only through official channels, and call 112 in an emergency.</li>
    </ul>
    <label style="display:flex; gap:8px; align-items:flex-start; font-size:14px;"><input type="checkbox" id="tpAgree" style="margin-top:3px;"> I understand and agree. I am choosing to visit a third party at my own risk.</label>
    <button type="button" class="btn solid" id="tpGo" style="width:100%; margin-top:14px;">Continue to ${esc(host)}</button>
    <p id="tpMsg" style="font-size:13px; color:#a3402f; margin:8px 0 0;"></p>
  </div>`;
  // Keyboard: focus moves into the notice (it is added at the end of the
  // page, so Tab from the link would otherwise walk the page behind it),
  // Escape closes only the notice, and focus goes back to the link.
  const opener = document.activeElement;
  const onKey = (e) => { if(e.key === 'Escape'){ e.preventDefault(); e.stopImmediatePropagation(); close(); } };
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey, true); if(opener && opener.focus && document.contains(opener)) opener.focus(); };
  overlay.addEventListener('click', (e) => { if(e.target === overlay) close(); });
  overlay.querySelector('.payout-close').addEventListener('click', close);
  document.body.appendChild(overlay);
  overlay.querySelector('.payout-sheet').setAttribute('aria-modal', 'true');
  document.addEventListener('keydown', onKey, true);
  overlay.querySelector('#tpAgree').focus();
  overlay.querySelector('#tpGo').addEventListener('click', () => {
    if(!overlay.querySelector('#tpAgree').checked){ overlay.querySelector('#tpMsg').textContent = 'Please tick the box to continue.'; return; }
    const q = new URLSearchParams({ nearbyConsent: '1', listing: String(listingId || ''), item: String(name || ''), link: String(link), kind: String(kind || '') });
    const headers = {}; try { const t = guestAuthToken(); if(t) headers['Authorization'] = 'Bearer ' + t; } catch (e) {}
    fetch(SUITES_API_BASE + '/api/get-listings?' + q.toString(), { headers }).catch(() => {});
    window.open(link, '_blank', 'noopener,noreferrer');
    close();
  });
}

// ---- What's special here / Recommended by your host (owner, 9 Nov 2026) ----
// The host's own words from the listing (api/_listing-special.js). Every
// piece of text is escaped. A recommendation's link is a third party, so it
// opens only through the "You are leaving Aerva" notice (aervaOpenThirdParty),
// recorded with kind 'host_recommendation'.
function aervaSpecialHereHtml(listing){
  const esc = escapeMessageHtml;
  const items = (Array.isArray(listing && listing.special_highlights) ? listing.special_highlights : []).map(t => String(t || '').trim()).filter(Boolean).slice(0, 5);
  const story = String((listing && listing.special_story) || '').trim();
  if(!items.length && !story) return '';
  return `<section class="special-here" aria-labelledby="specialHere${Number(listing.id)}">
    <h2 class="special-here-title" id="specialHere${Number(listing.id)}">What’s special here</h2>
    ${items.length ? `<ul class="special-here-list">${items.map(t => `<li><span class="special-here-mark" aria-hidden="true">✦</span><span>${esc(t)}</span></li>`).join('')}</ul>` : ''}
    ${story ? `<p class="special-here-story">${esc(story)}</p>` : ''}
  </section>`;
}
const AERVA_REC_KINDS = [['things_to_do', 'Things to do'], ['food_drink', 'Food & drink'], ['experience', 'Experience'], ['shopping', 'Shopping'], ['getting_around', 'Getting around'], ['other', 'Other']];
function aervaHostRecsHtml(listing){
  const esc = escapeMessageHtml;
  const recs = (Array.isArray(listing && listing.host_recommendations) ? listing.host_recommendations : []).filter(r => r && String(r.name || '').trim()).slice(0, 10);
  if(!recs.length) return '';
  const groups = AERVA_REC_KINDS.map(([k, label]) => ({ label, items: recs.filter(r => (AERVA_REC_KINDS.some(x => x[0] === r.kind) ? r.kind : 'other') === k) })).filter(g => g.items.length);
  const card = (r) => {
    const link = /^https?:\/\//i.test(String(r.link || '')) ? String(r.link) : '';
    let host = '';
    if(link){ try { host = new URL(link).hostname.replace(/^www\./, ''); } catch (e) { host = ''; } }
    return `<li class="host-rec">
      <div class="host-rec-top"><strong>${esc(r.name)}</strong>${r.distance ? `<span class="host-rec-dist">${esc(r.distance)}</span>` : ''}</div>
      ${r.note ? `<p class="host-rec-note">${esc(r.note)}</p>` : ''}
      ${link && host ? `<a href="#" class="host-rec-link" data-hrec-link="${esc(link)}" data-hrec-name="${esc(r.name)}" data-hrec-listing="${Number(listing.id)}">Visit ${esc(host)} <span aria-hidden="true">↗</span></a>` : ''}
    </li>`;
  };
  return `<section class="host-recs" aria-labelledby="hostRecs${Number(listing.id)}">
    <div class="listing-modal-section-title" style="margin-top:22px;" id="hostRecs${Number(listing.id)}">Recommended by your host</div>
    ${groups.map(g => `<h3 class="host-recs-kind">${esc(g.label)}</h3><ul class="host-recs-list">${g.items.map(card).join('')}</ul>`).join('')}
    <p class="host-recs-note">Your host’s own suggestions. Aerva has not checked them and does not endorse or run them.</p>
  </section>`;
}
document.addEventListener('click', (e) => {
  const a = e.target && e.target.closest ? e.target.closest('[data-hrec-link]') : null;
  if(!a) return;
  e.preventDefault();
  aervaOpenThirdParty({ link: a.dataset.hrecLink, name: a.dataset.hrecName, kind: 'host_recommendation', listingId: a.dataset.hrecListing });
});

// ---- "Make more of your stay": Aerva experiences the host suggests ----
// Shown only while booking that stay (under the price summary), on the
// booking confirmation and in My Bookings — never on the listing page.
// get-listings ?suggestedFor= returns only experiences still live. These
// are Aerva's own pages, so no third-party notice; they open in a new tab
// so the booking in progress is not lost. (The experience page does not
// take a date from its link yet, so the stay's dates are not passed.)
const aervaSuggestedCache = {};
function aervaSuggestedExperiences(listingId){
  const id = Number(listingId) || 0;
  if(!aervaSuggestedCache[id]){
    aervaSuggestedCache[id] = fetch(SUITES_API_BASE + '/api/get-listings?suggestedFor=' + id)
      .then(r => r.ok ? r.json() : { experiences: [] }).then(d => Array.isArray(d.experiences) ? d.experiences : [])
      .catch(() => { delete aervaSuggestedCache[id]; return []; });
  }
  return aervaSuggestedCache[id];
}
function aervaLoadSuggestedExperiences(root){
  if(!root || !root.querySelectorAll) return;
  const esc = escapeMessageHtml;
  root.querySelectorAll('.sx-slot[data-suggest-exp-for]').forEach(slot => {
    if(slot.dataset.loaded) return;
    slot.dataset.loaded = '1';
    aervaSuggestedExperiences(slot.dataset.suggestExpFor).then(list => {
      if(!list.length){ slot.innerHTML = ''; return; }
      const dur = (e) => e.durationDays && e.durationDays > 1 ? `${e.durationDays} days` : e.durationHours ? `${Number(e.durationHours)} hour${Number(e.durationHours) === 1 ? '' : 's'}` : '';
      // guestPrice returns trusted markup (the guest's currency); everything else is escaped.
      const price = (e) => e.price != null && Number.isFinite(Number(e.price)) ? (typeof guestPrice === 'function' ? guestPrice(Number(e.price)) : '₹' + Math.round(Number(e.price)).toLocaleString('en-IN')) + (e.priceUnit === 'per_person' ? ' / person' : '') : '';
      slot.innerHTML = `<div class="sx-box">
        <div class="sx-title">Make more of your stay — experiences on Aerva</div>
        <div class="sx-list">${list.map(e => `<a class="sx-card" href="index.html?experience=${Number(e.id)}" target="_blank" rel="noopener">
          ${e.photo ? `<img src="${esc(e.photo)}" alt="" loading="lazy">` : '<span class="sx-noimg" aria-hidden="true"></span>'}
          <span class="sx-text"><span class="sx-name">${esc(e.name)}</span><span class="sx-meta">${[price(e), esc(dur(e))].filter(Boolean).join(' · ')}</span></span>
        </a>`).join('')}</div>
      </div>`;
    });
  });
}

// ---- Guest: complete an accepted transfer that costs the same or less ----
async function aervaConfirmTransfer(changeId, btn){
  if(!confirm('Complete this transfer? Your booking will be split as shown and this is final: no part can be changed, moved, split again, shortened or cancelled afterwards. For any problem, raise a request in the Resolution Center; Aerva decides. Any difference (after Aerva’s transfer fee) is held for you as Aerva credit, which you can have refunded to your original payment at any time from My Bookings.')) return;
  const label = btn ? btn.textContent : '';
  if(btn){ btn.disabled = true; btn.textContent = 'Confirming…'; }
  const note = document.createElement('p');
  note.className = 'offer'; note.style.cssText = 'margin-top:8px;';
  if(btn && btn.parentNode) btn.parentNode.appendChild(note);
  try{
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
      body: JSON.stringify({ mode: 'confirmTransfer', changeId }) });
    const d = await r.json().catch(() => ({}));
    if(!r.ok) throw new Error(d.error || 'Could not confirm the transfer.');
    note.style.color = '#2f6b3a';
    note.textContent = 'Transfer complete. We have emailed you the details' + (d.heldAsCredit ? `; ${moneyBoth(d.heldAsCredit)} is held for you as Aerva credit (My Bookings).` : '.');
    if(typeof loadMyBookings === 'function') setTimeout(loadMyBookings, 1500);
  }catch(err){ note.style.color = '#a3402f'; note.textContent = err.message; if(btn){ btn.disabled = false; btn.textContent = label; } }
}

// A message that ends with a link to the Resolution Center (Aerva Support).
// Owner, 10 Nov 2026: every issue goes through it — no message tells anyone
// to email Aerva. qs prefills the new request (category=…&order=…&listing=…).
function aervaHelpMessage(el, text, qs){
  if(!el) return;
  el.textContent = text + ' ';
  const a = document.createElement('a');
  a.href = 'index.html?view=help&new=1' + (qs ? '&' + qs : '');
  a.textContent = 'Raise a request in the Resolution Center';
  el.appendChild(a);
}

// ---- Guest: pay the difference for an accepted change ----
// Same strict payment window as a booking.
async function aervaPayChange(changeId, btn){
  const label = btn ? btn.textContent : '';
  if(btn){ btn.disabled = true; btn.textContent = 'Preparing payment…'; }
  const note = document.createElement('p');
  note.className = 'offer'; note.style.cssText = 'color:#a3402f; margin-top:8px;';
  if(btn && btn.parentNode) btn.parentNode.appendChild(note);
  let order;
  try{
    const r = await fetch(SUITES_API_BASE + '/api/create-order', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + guestAuthToken() },
      body: JSON.stringify({ payChange: changeId }) });
    order = await r.json();
    if(!r.ok) throw new Error(order.error || 'Could not start the payment.');
  }catch(err){ note.textContent = err.message; if(btn){ btn.disabled = false; btn.textContent = label; } return; }
  if(btn){ btn.disabled = false; btn.textContent = label; }
  if(typeof Razorpay === 'undefined'){ note.textContent = 'Payment gateway did not load. Please check your connection and try again.'; return; }
  if(!order.keyId){ note.textContent = 'Payment is not available right now. Please try again in a few minutes.'; return; }
  const rzp = new Razorpay({
    key: order.keyId, order_id: order.orderId, amount: order.amount, currency: order.currency,
    timeout: order.holdSeconds || undefined, name: 'Aerva', description: order.description || 'Booking change',
    theme: { color: '#a9884f' },
    handler: async function(response){
      aervaCheckoutSucceeded();
      try{
        const v = await fetch(SUITES_API_BASE + '/api/verify-payment', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(response) });
        const d = await v.json();
        note.style.color = d.verified || d.pending ? '#2f6b3a' : '#a3402f';
        if(d.verified) note.textContent = 'Payment received. Your booking has been changed — we have emailed you the details.';
        else if(d.message) note.textContent = d.message;
        else aervaHelpMessage(note, 'We could not confirm this payment.', 'category=change_booking');
        if(typeof loadMyBookings === 'function') setTimeout(loadMyBookings, 1500);
      }catch(e){ aervaHelpMessage(note, 'Payment went through, but we could not confirm it automatically. Keep your payment ID and', 'category=change_booking'); }
    },
    modal: { ondismiss: function(){ aervaEndCheckout('closed'); } }
  });
  rzp.on('payment.failed', function(){ aervaEndCheckout('failed'); });
  rzp.open();
  aervaWatchCheckout(rzp, order, note, { holdsDates: !!order.holdSeconds });
}

// ---- Guest: request a cancellation ----
// The request goes to the host in the booking's message thread; the host
// answers there. The guest sees only what applies to THIS booking now.
async function openPolicyCancel(orderId, listingName){
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const inr = (n) => moneyBoth(n);
  const overlay = document.createElement('div');
  overlay.className = 'payout-overlay';
  overlay.innerHTML = `<div class="payout-sheet" role="dialog" aria-label="Request cancellation">
    <button type="button" class="payout-close" aria-label="Close">×</button>
    <h2 style="font-family:'Bodoni Moda', Georgia, serif; font-weight:500; font-size:24px; margin:4px 0 6px;">Request cancellation</h2>
    <p class="payout-muted" style="margin:0 0 14px;">${esc(listingName)}</p>
    <div id="pcBody"><p class="payout-muted">Loading…</p></div>
  </div>`;
  // Escape closes the sheet, and focus starts inside it (keyboard / screen readers).
  const onEsc = (e) => { if(e.key === 'Escape' && overlay === [...document.querySelectorAll('.payout-overlay')].pop()) close(); };
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onEsc); };
  document.addEventListener('keydown', onEsc);
  setTimeout(() => { const b = overlay.querySelector('.payout-close'); if(b && overlay.isConnected) b.focus(); }, 0);
  overlay.addEventListener('click', (e) => { if(e.target === overlay) close(); });
  overlay.querySelector('.payout-close').addEventListener('click', close);
  document.body.appendChild(overlay);
  const body = overlay.querySelector('#pcBody');
  const auth = { 'Authorization': 'Bearer ' + guestAuthToken() };
  let q = null;
  try{
    const r = await fetch(SUITES_API_BASE + '/api/guest-profile?mode=cancellationQuote&orderId=' + encodeURIComponent(orderId), { headers: auth });
    q = await r.json();
    if(!r.ok){ body.innerHTML = `<p class="payout-muted">${esc(q.error || 'This booking cannot be cancelled here.')}</p>`; return; }
  }catch(err){ body.innerHTML = '<p class="payout-muted">Could not load this. Try again.</p>'; return; }
  const line = (label, value) => `<div class="payout-line"><span>${esc(label)}</span><span>${value}</span></div>`;
  const planText = () => {
    const reason = overlay.querySelector('#pcReason').value;
    if(reason !== 'change_of_plans'){
      // A natural disaster or government order: Aerva decides (owner, 10 Nov 2026).
      const nd = q.naturalDisaster || {};
      return '<p class="payout-muted" style="margin:8px 0;">Aerva checks your proof and decides \u2014 your host can\u2019t decline it. If Aerva approves, what you paid (booking price, GST and Aerva\u2019s service fee' + (q.freeCancel ? ', and the free cancellation add-on' : '') + ') becomes <strong>Aerva credit</strong>, and any security deposit is refunded to your original payment: use it for new dates, or have it refunded to your original payment any time from My Bookings. If not, nothing changes and your booking stands. Aerva\u2019s decision is final.</p>'
        + (nd.credit ? line('Aerva credit if approved', '<strong>' + inr(nd.credit) + '</strong>') : '') + (nd.coupon ? line('Back as a coupon (the part paid by coupon)', inr(nd.coupon)) : '') + (nd.cash ? line(q.groupNoRefund ? 'Security deposit, refunded to each payer' : 'Security deposit, refunded to your original payment', inr(nd.cash)) : '');
    }
    if(!q.allowed) return `<p class="payout-muted" style="margin:8px 0;">${esc(q.error || '')}</p>`;
    if(q.hostDecides) return `<p class="payout-muted" style="margin:8px 0;">Your host decides the refund.</p>${line('Deposit refunded', inr(q.ifNoRefund.deposit))}${line('Aerva service fee (non-refundable)', inr(q.ifNoRefund.feeKept))}${q.ifNoRefund.addOnKept ? line('Free cancellation add-on (not refunded; its window has passed)', inr(q.ifNoRefund.addOnKept)) : ''}`;
    // A confirmed group booking is non-refundable: cancelled at once, only the deposit comes back (_cancellations.js groupNoRefund).
    if(q.groupNoRefund) return `<p class="payout-muted" style="margin:8px 0;"><strong>This is a non-refundable group booking.</strong> If you cancel, the booking is cancelled at once for everyone, with no wait for your host, and nothing is refunded for the stay, its GST or Aerva’s service fee, whatever the listing’s policy.</p>${line('Refunded for the stay', '<strong>' + inr(q.refundBooking || 0) + '</strong>')}${q.deposit ? line('Security deposit, refunded to each payer', inr(q.deposit)) : ''}${line('Aerva service fee (non-refundable)', inr(q.feeKept))}`;
    // Free cancellation add-on, still in its window: cancelled at once, no host answer.
    if(q.instant) return `<p class="payout-muted" style="margin:8px 0;">${(q.freeCancel || {}).included ? 'This booking includes free cancellation' : 'You added free cancellation'}, and it is still before ${esc((q.freeCancel || {}).untilLabel || '')} (the property’s time): your booking is cancelled at once, with no wait for your host.</p>${line('You get back', '<strong>' + inr(q.refundCash) + '</strong>')}${q.couponLost ? line('Paid by coupon (not returned)', inr(q.couponLost)) : ''}${line('Aerva service fee (non-refundable)', inr(q.feeKept))}${q.addOnKept ? line('Free cancellation add-on (non-refundable)', inr(q.addOnKept)) : ''}`;
    return `${line('If your host accepts, you get back', '<strong>' + inr(q.refundCash) + '</strong>')}${q.couponBack ? line('Plus, as a coupon', inr(q.couponBack)) : ''}${q.couponLost ? line('Paid by coupon (not returned)', inr(q.couponLost)) : ''}${line('Aerva service fee (non-refundable)', inr(q.feeKept))}${q.addOnKept ? line('Free cancellation add-on (not refunded; its window has passed)', inr(q.addOnKept)) : ''}`;
  };
  body.innerHTML = `<label class="payout-label" for="pcReason">Reason</label>
    <select id="pcReason" style="width:100%; padding:11px; margin:6px 0 10px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px; background:#fff;">
      <option value="change_of_plans">Change of plans</option>
      <option value="environmental">Natural disaster (flood, cyclone, earthquake, landslide, fire)</option>
      <option value="travel_restriction">Government order or travel restriction (lockdown, road closed by authorities)</option>
    </select>
    <div id="pcPlan"></div>
    <div id="pcProofWrap" style="display:none;">
      <label class="payout-label" for="pcProof">Proof (required)</label>
      <p class="payout-muted" style="margin:2px 0 6px; font-size:13px;">For example a photo or news report of the disaster, or the official order or notice. Photos or PDF, up to 5. Only your host and Aerva see it.</p>
      <input id="pcProof" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf" style="margin:0 0 12px; font-size:15px;">
    </div>
    <label class="payout-label" for="pcNote" id="pcNoteLabel">Message to your host (optional)</label>
    <textarea id="pcNote" rows="3" maxlength="800" style="width:100%; box-sizing:border-box; padding:11px; margin:6px 0 12px; border:1px solid #d9cfc2; border-radius:8px; font-size:16px;"></textarea>
    <button type="button" class="btn" id="pcGo" style="width:100%;">Send request to host</button>
    <p id="pcMsg" class="payout-muted" style="margin-top:10px;"></p>`;
  const plan = overlay.querySelector('#pcPlan');
  const refresh = () => {
    plan.innerHTML = planText();
    const cop = overlay.querySelector('#pcReason').value === 'change_of_plans';
    overlay.querySelector('#pcProofWrap').style.display = cop ? 'none' : '';
    const go = overlay.querySelector('#pcGo');
    if(go && !go.disabled) go.textContent = cop && q.groupNoRefund ? 'Cancel now (nothing refunded for the stay)' : cop && q.instant ? 'Cancel now (free cancellation)' : cop ? 'Send request to host' : 'Send to Aerva with proof';
    const nl = overlay.querySelector('#pcNoteLabel'); if(nl) nl.textContent = cop ? 'Message to your host (optional)' : 'What happened (optional — your host and Aerva see it)';
  };
  overlay.querySelector('#pcReason').addEventListener('change', refresh);
  refresh();
  overlay.querySelector('#pcGo').addEventListener('click', async () => {
    const msg = overlay.querySelector('#pcMsg');
    const btn = overlay.querySelector('#pcGo');
    const reasonCode = overlay.querySelector('#pcReason').value;
    const files = [...overlay.querySelector('#pcProof').files].slice(0, 5);
    if(reasonCode !== 'change_of_plans' && !files.length){ msg.textContent = 'Please attach proof (a photo, a news report, or the official order or notice).'; return; }
    btn.disabled = true; msg.textContent = '';
    try{
      const evidence = files.length ? await aervaUploadFiles(files, 'cancellation-proof') : [];
      const r = await fetch(SUITES_API_BASE + '/api/guest-profile', { method: 'POST', headers: Object.assign({ 'Content-Type': 'application/json' }, auth),
        body: JSON.stringify({ mode: 'requestCancellation', orderId, reasonCode, details: overlay.querySelector('#pcNote').value.trim(), evidence }) });
      const d = await r.json().catch(() => ({}));
      if(!r.ok){ msg.textContent = d.error || 'Could not send the request.'; btn.disabled = false; return; }
      body.innerHTML = d.cancelled && q.groupNoRefund
        ? `<p>The group booking is cancelled. Nothing is refunded for the stay${d.refundCash ? `; the security deposit (${inr(d.refundCash)}) goes back to each payer’s own payment, usually in 5–7 working days` : ''}. Everyone in the group has been told.</p>`
        : d.cancelled
        ? `<p>Your booking is cancelled. ${inr(d.refundCash || 0)} is refunded to your original payment method${d.creditBack ? `, and ${inr(d.creditBack)} goes back on your Aerva credit` : ''}. Refunds usually arrive in 5–7 working days.</p>`
        : reasonCode !== 'change_of_plans' ? '<p>Your request and proof have been sent to Aerva. Aerva checks the proof and decides; we will email you. Your host has been told.</p>'
        : '<p>Your request has been sent to your host in Messages. We will email you when they answer.</p>';
      if(typeof loadMyBookings === 'function') loadMyBookings();
    }catch(err){ msg.textContent = 'Could not send the request. Try again.'; btn.disabled = false; }
  });
}

// =====================================================================
// Gift bookings and group (split-payment) bookings — owner's rules, 9 Nov 2026
// (api/_gifts.js, api/_group-bookings.js).
// =====================================================================
const AG_ESC = (t) => String(t == null ? '' : t).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const AG_API = () => (window.AERVA_API || 'https://aerva-in.vercel.app');
const AG_INR = (n) => '₹' + Math.round(Number(n) || 0).toLocaleString('en-IN');
const AG_DAY = (d) => d ? new Date(String(d).slice(0, 10) + 'T00:00:00Z').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }) : '';
const AG_NAME_OK = (v) => !!v && !/\d/.test(v) && /^[\p{L}\p{M} .'’-]+$/u.test(v) && /\p{L}/u.test(v);
const agToken = () => (typeof guestAuthToken === 'function' ? guestAuthToken() : null);
async function agFetch(path, opts = {}){
  const headers = Object.assign({ 'Content-Type': 'application/json' }, agToken() ? { 'Authorization': 'Bearer ' + agToken() } : {}, opts.headers || {});
  const r = await fetch(AG_API() + path, Object.assign({}, opts, { headers }));
  const d = await r.json().catch(() => ({}));
  return { ok: r.ok, status: r.status, data: d };
}
function agClock(sec){
  sec = Math.max(0, Math.round(Number(sec) || 0));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  return (h ? h + ':' + String(m).padStart(2, '0') : String(m)) + ':' + String(s).padStart(2, '0');
}
// Equal shares in whole rupees, remainder on the last places (as the server).
function agSplit(total, n){
  const t = Math.round(Number(total) || 0); n = Math.max(1, Math.round(Number(n) || 1));
  const base = Math.floor(t / n), rem = t - base * n;
  return Array.from({ length: n }, (_, i) => base + (i >= n - rem ? 1 : 0));
}

// ---- Checkout: the two options under "Your details" ----
function aervaBookOptionsHtml(){
  return `<div class="ag-options" id="listingBookOptions">
    <label class="ag-opt" id="listingFreeCancelOpt" hidden><input type="checkbox" id="listingFreeCancelToggle">
      <span><strong id="listingFreeCancelTitle">Free cancellation</strong><em id="listingFreeCancelText">Cancel for a full refund until 48 hours before check-in.</em></span></label>
    <label class="ag-opt"><input type="checkbox" id="listingGiftToggle">
      <span><strong>This stay is for someone else</strong><em>Send it as a gift. You pay for and manage the booking; they get the stay details (never the price) and accept it.</em></span></label>
    <div class="ag-sub" id="listingGiftFields" hidden>
      <p class="ag-help">Who is staying? Their name as on their government ID — the host checks it at check-in.</p>
      <div class="ag-grid">
        <div class="field"><label for="giftFirstName">Their first name <span style="color:#a3402f;">*</span></label><input id="giftFirstName" type="text" autocomplete="off" placeholder="First name"></div>
        <div class="field"><label for="giftLastName">Their last name <span style="color:#a3402f;">*</span></label><input id="giftLastName" type="text" autocomplete="off" placeholder="Last name"></div>
      </div>
      <div class="field" style="margin-top:10px;"><label for="giftEmail">Their email <span style="color:#a3402f;">*</span></label><input id="giftEmail" type="email" autocomplete="off" placeholder="their@email.com"></div>
      <div class="field" style="margin-top:10px;"><label for="giftPhone">Their mobile <span class="label-hint">(optional — they confirm it when accepting)</span></label><input id="giftPhone" type="tel" autocomplete="off" placeholder="Mobile number"></div>
      <div class="field" style="margin-top:10px;"><label for="giftMessage">Gift message <span class="label-hint">(optional)</span></label>
        <textarea id="giftMessage" maxlength="300" rows="3" placeholder="A few words for them"></textarea>
        <span class="ag-count" id="giftMessageCount">0 / 300</span></div>
      <p class="ag-help">Contact details in the message are removed, as in Messages.</p>
    </div>
    <label class="ag-opt"><input type="checkbox" id="listingSplitToggle">
      <span><strong>Split the payment with friends</strong><em>Everyone pays for their own place. You pay for yours now; your friends have 2 hours. The place is not held until the last payment, and a confirmed group booking is non-refundable.</em></span></label>
    <p class="ag-help" id="splitNeedsTwo" hidden>Splitting needs at least 2 guests — add a guest under “Who is coming” to use it.</p>
    <div class="ag-sub" id="listingSplitFields" hidden>
      <div class="field"><label for="splitPayNow">Places you pay for now</label><select id="splitPayNow"></select></div>
      <p class="ag-help" id="splitSummary">Choose your dates and guests to see each place’s share.</p>
      <p class="ag-help ag-warn" id="splitNotHeld"><strong>Not held until the last payment.</strong> Anyone else can still book these dates while your friends pay; if that happens, everyone who paid is refunded in full. The last payment holds the place for its 3 minutes and confirms the booking.</p>
      <label class="ag-opt ag-tick" id="splitCommitOpt"><input type="checkbox" id="splitCommit">
        <span><strong>I’ll pay for any places my friends don’t pay within 2 hours.</strong><em>If places are unpaid at 2 hours, you have 30 minutes to pay the rest. If you don’t, nothing is booked, everyone is refunded in full, and the unpaid amount is recorded on your account.</em></span></label>
      <label class="ag-opt ag-tick" id="splitNonRefOpt"><input type="checkbox" id="splitNonRef" class="ag-nonref">
        <span><strong>${'I understand'}: once the booking is confirmed it is non-refundable.</strong><em>If plans change, nothing is refunded, whatever the listing’s refund policy (any deposit is still refunded). Only a natural disaster or government order approved by Aerva, a cancellation by the host, or Aerva’s check-in promise changes that.</em></span></label>
      <p class="ag-help">Coupons, Aerva credit and free cancellation cannot be used on a split payment.</p>
    </div>
  </div>`;
}
let agLastSplit = null;
function aervaRefreshSplit(q){
  if(q) agLastSplit = q;
  const sel = document.getElementById('splitPayNow');
  const sum = document.getElementById('splitSummary');
  const toggle = document.getElementById('listingSplitToggle');
  if(!sel || !agLastSplit) return;
  const n = Math.max(1, Number(agLastSplit.guests) || 1);
  if(toggle){
    toggle.disabled = n < 2;
    toggle.closest('.ag-opt').classList.toggle('is-off', n < 2);
    const why = document.getElementById('splitNeedsTwo'); if(why) why.hidden = !(n < 2);
    if(n < 2 && toggle.checked){ toggle.checked = false; aervaSyncBookOptions(); }
  }
  const keep = Number(sel.value) || 1;
  sel.innerHTML = Array.from({ length: Math.max(1, n - 1) }, (_, i) => `<option value="${i + 1}">${i + 1} place${i ? 's' : ''}${i === 1 ? ' (e.g. a couple)' : ''}</option>`).join('');
  sel.value = String(Math.min(keep, Math.max(1, n - 1)));
  const shares = agSplit(agLastSplit.total, n);
  const k = Number(sel.value) || 1;
  if(sum) sum.innerHTML = n < 2 ? 'Splitting needs at least 2 guests.'
    : `${n} places · each <strong>${AG_INR(shares[0])}</strong>${shares[n - 1] !== shares[0] ? ` (last place ${AG_INR(shares[n - 1])})` : ''} — the whole total, including GST, service fee${/deposit/i.test(document.getElementById('listingPriceSummary') ? document.getElementById('listingPriceSummary').textContent : '') ? ' and deposit' : ''}. You pay <strong>${AG_INR(shares.slice(0, k).reduce((a, b) => a + b, 0))}</strong> now.`;
}
function aervaSyncBookOptions(e){
  const gift = document.getElementById('listingGiftToggle'), split = document.getElementById('listingSplitToggle');
  if(!gift || !split) return;
  // One or the other: a gift is paid by the buyer alone.
  if(e && e.target === gift && gift.checked) split.checked = false;
  if(e && e.target === split && split.checked) gift.checked = false;
  // Free cancellation is for a stay one guest pays for: not with a split.
  const fcToggle = document.getElementById('listingFreeCancelToggle');
  if(fcToggle){
    if(e && e.target === split && split.checked && fcToggle.checked){ fcToggle.checked = false; aervaRepriceListing(); }
    if(e && e.target === fcToggle && fcToggle.checked && split.checked){ split.checked = false; }
    fcToggle.disabled = split.checked;
    const opt = document.getElementById('listingFreeCancelOpt');
    if(opt) opt.classList.toggle('is-off', split.checked);
  }
  document.getElementById('listingGiftFields').hidden = !gift.checked;
  document.getElementById('listingSplitFields').hidden = !split.checked;
  const coupon = document.getElementById('listingCouponField');
  if(coupon) coupon.style.display = split.checked ? 'none' : '';
  const btn = document.getElementById('listingBookNowBtn');
  if(btn && !btn.disabled) btn.textContent = split.checked ? 'Pay for my places' : gift.checked ? 'Continue to payment (gift)' : 'Continue to payment';
  aervaRefreshSplit();
}
// The listing page priced again (the free cancellation add-on changes the total).
function aervaRepriceListing(){
  try{
    const last = typeof updateListingPriceSummary === 'function' ? updateListingPriceSummary._last : null;
    if(last) updateListingPriceSummary(last.listing, last.arrival, last.departure);
  }catch(err){}
}
// The add-on as the server's quote offers it: shown only when offered
// (check-in more than 48 hours away), with its price and end, and unticked
// when it is not.
function aervaShowFreeCancelOffer(q){
  const opt = document.getElementById('listingFreeCancelOpt');
  const t = document.getElementById('listingFreeCancelToggle');
  if(!opt || !t) return;
  const st = q && Array.isArray(q.stays) ? q.stays[0] : null;
  const fc = st && st.freeCancel;
  // The summary's "Free cancellation available at checkout" line goes when
  // these dates can't have it (check-in within 48 hours).
  const avail = document.getElementById('listingFreeCancelAvail');
  if(avail) avail.hidden = !(fc && fc.offered);
  // The same line above the calendar (it would otherwise still promise it).
  document.querySelectorAll('[data-free-cancel-line]').forEach(el => { el.hidden = !(fc && fc.offered); });
  if(!fc || !fc.offered){ opt.hidden = true; if(t.checked){ t.checked = false; } return; }
  opt.hidden = false;
  // The host offers it free: part of every booking, nothing to tick or pay.
  t.disabled = !!fc.included;
  if(fc.included){
    t.checked = true;
    document.getElementById('listingFreeCancelTitle').textContent = `Free cancellation included (until ${fc.untilLabel}) — no charge`;
    document.getElementById('listingFreeCancelText').textContent = `Included by your host at no charge. Cancel before ${fc.untilLabel} (the property’s time, 48 hours before check-in) for a full refund of the booking price, its GST and any deposit, at once, with no wait for your host. Aerva’s service fee is not refunded. After that, the listing’s refund policy applies.`;
    return;
  }
  document.getElementById('listingFreeCancelTitle').textContent = `Free cancellation (until ${fc.untilLabel}) — ${fmtGuest(fc.fee)} + GST`;
  document.getElementById('listingFreeCancelText').textContent = `The host’s price for this stay. Cancel before ${fc.untilLabel} (the property’s time, 48 hours before check-in) for a full refund of the booking price, its GST and any deposit, at once, with no wait for your host. The add-on and Aerva’s service fee are not refunded. After that, the listing’s refund policy applies.`;
}
document.addEventListener('change', (e) => {
  if(e.target && e.target.id === 'listingFreeCancelToggle'){ aervaSyncBookOptions(e); aervaRepriceListing(); }
  if(e.target && (e.target.id === 'listingGiftToggle' || e.target.id === 'listingSplitToggle')) aervaSyncBookOptions(e);
  if(e.target && e.target.id === 'splitPayNow') aervaRefreshSplit();
});
document.addEventListener('input', (e) => {
  if(e.target && e.target.id === 'giftMessage'){ const c = document.getElementById('giftMessageCount'); if(c) c.textContent = [...e.target.value].length + ' / 300'; }
});
// Reads the options; false (with the message shown) when something is missing.
function aervaReadBookOptions(errorEl, guests){
  const out = {};
  const fail = (m) => { errorEl.textContent = m; errorEl.style.display = 'block'; return false; };
  const gift = document.getElementById('listingGiftToggle'), split = document.getElementById('listingSplitToggle');
  if(gift && gift.checked){
    const v = (id) => (document.getElementById(id) || {}).value || '';
    const first = v('giftFirstName').trim(), last = v('giftLastName').trim(), email = v('giftEmail').trim(), phone = v('giftPhone').trim(), message = v('giftMessage').trim();
    if(!AG_NAME_OK(first) || !AG_NAME_OK(last)) return fail('Please enter the recipient’s first and last name as on their government ID: letters, spaces, dots, apostrophes and hyphens only.');
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail('Please enter the recipient’s email address.');
    if(phone && phone.replace(/\D/g, '').length < 10) return fail('Please enter a valid mobile number for the recipient, or leave it empty.');
    if([...message].length > 300) return fail('The gift message can be at most 300 characters.');
    out.gift = { firstName: first, lastName: last, email, phone: phone || undefined, message: message || undefined };
  }
  if(split && split.checked){
    if(!(guests >= 2)) return fail('Splitting the payment needs at least 2 guests.');
    if(!(document.getElementById('splitCommit') || {}).checked) return fail('Please tick “I’ll pay for any places my friends don’t pay within 2 hours.” to split the payment.');
    if(!(document.getElementById('splitNonRef') || {}).checked) return fail('Please tick that you understand: once the booking is confirmed it is non-refundable.');
    out.group = { payNow: Number((document.getElementById('splitPayNow') || {}).value) || 1, commit: true, nonRefundable: true };
  }
  return out;
}

// ---- After paying for places: back to the group page ----
function aervaAfterGroupPayment(verifyData){
  const token = verifyData.group.token;
  const note = verifyData.verified ? 'paid' : (verifyData.refunded ? 'refunded' : 'pending');
  try{ sessionStorage.setItem('aerva_group_note', JSON.stringify({ token, note, message: verifyData.message || '' })); }catch(e){}
  if(new URLSearchParams(window.location.search).get('group') === token && typeof aervaShowGroupPage === 'function') aervaShowGroupPage(token);
  else window.location.href = 'index.html?group=' + encodeURIComponent(token);
}

function agShowView(title){
  if(typeof hideMainViews === 'function') hideMainViews();
  document.body.classList.remove('showing-hero');
  const v = document.getElementById('groupGiftView');
  if(v) v.style.display = 'block';
  document.title = title + ' — Aerva';
  window.scrollTo({ top: 0 });
  return document.getElementById('groupGiftBody');
}
function agStayHead(st, sub){
  return `<div class="ag-stay">
    ${st.photo ? `<img class="ag-stay-photo" src="${AG_ESC(st.photo)}" alt="">` : ''}
    <div class="ag-stay-text"><h2 class="ag-title">${AG_ESC(st.name || 'Your stay')}</h2>
      <p class="ag-meta">${AG_ESC([st.area, st.city].filter((x, i, a) => x && a.indexOf(x) === i).join(', '))}</p>
      <p class="ag-dates">${AG_ESC(AG_DAY(st.arrival))} → ${AG_ESC(AG_DAY(st.departure))}${st.nights ? ` · ${st.nights} night${st.nights === 1 ? '' : 's'}` : ''}${st.guests ? ` · ${st.guests} guest${st.guests === 1 ? '' : 's'}` : ''}</p>
      ${sub || ''}</div></div>`;
}
const agLoginLinks = (back, email, why) => {
  const next = encodeURIComponent(back);
  const em = email ? '&email=' + encodeURIComponent(email) : '';
  return `<div class="ag-actions"><a class="btn solid" href="guest-login.html?next=${next}&mode=login${em}&reason=${why}">Log in</a>
    <a class="btn" href="guest-login.html?next=${next}&mode=signup${em}&reason=${why}">Create account</a></div>`;
};

// ---- The group page: index.html?group=<token> ----
let agGroupTimer = null, agGroupPoll = null, agGroupFlash = null;
async function aervaShowGroupPage(token){
  const box = agShowView('Group booking');
  if(!box) return;
  clearInterval(agGroupTimer); clearInterval(agGroupPoll);
  const back = 'index.html?group=' + encodeURIComponent(token);
  if(!agToken()){
    box.innerHTML = '<p class="loading">Loading…</p>';
    const r = await agFetch('/api/get-listings?groupPreview=' + encodeURIComponent(token), { method: 'GET' });
    if(!r.ok){ box.innerHTML = `<p class="ag-error">${AG_ESC(r.data.error || 'This link is not valid.')}</p>`; return; }
    const p = r.data;
    box.innerHTML = `${agStayHead(p.stay)}
      <div class="ag-card"><p class="ag-lead"><strong>${AG_ESC(p.organiserFirstName || 'Your friend')}</strong> is booking this stay for ${p.places} people and splitting the payment.</p>
      <p>Each place is <strong>${AG_INR(p.perPlace)}</strong>${p.lastPlace !== p.perPlace ? ` (last place ${AG_INR(p.lastPlace)})` : ''}.</p>
      ${p.secondsLeft != null ? `<p class="ag-count-big" data-ag-countdown="${p.secondsLeft}">${agClock(p.secondsLeft)} left</p>` : `<p>${p.status === 'open' ? '' : 'This group is no longer taking payments.'}</p>`}
      <p>To see who has paid and pay for your place, log in or create an Aerva account.</p>
      ${agLoginLinks(back, '', 'group')}</div>`;
    agTickCountdowns(box);
    return;
  }
  let note = null;
  try{ note = JSON.parse(sessionStorage.getItem('aerva_group_note') || 'null'); if(note && note.token === token) sessionStorage.removeItem('aerva_group_note'); else note = null; }catch(e){}
  const draw = async () => {
    const r = await agFetch('/api/guest-profile?mode=group&token=' + encodeURIComponent(token), { method: 'GET' });
    if(!r.ok){ box.innerHTML = `<p class="ag-error">${AG_ESC(r.data.error || 'Could not load this group.')}</p>`; return null; }
    const g = r.data;
    // Keep what the person is typing when the status refreshes.
    const keep = {}; ['agPayFirst', 'agPayLast', 'agPayPhone', 'agPayPlaces'].forEach(id => { const el = document.getElementById(id); if(el) keep[id] = el.value; });
    const ticked = !!(document.querySelector('#groupGiftBody .agreement-check') || {}).checked;
    box.innerHTML = agGroupHtml(g, note || agGroupFlash);
    note = null; agGroupFlash = null;
    Object.entries(keep).forEach(([id, v]) => { const el = document.getElementById(id); if(el && v) el.value = v; });
    agBindGroup(box, g, draw);
    if(ticked){ setTimeout(() => { const c = document.querySelector('#groupGiftBody .agreement-check'); if(c) c.checked = true; }, 0); }
    agTickCountdowns(box);
    return g;
  };
  box.innerHTML = '<p class="loading">Loading…</p>';
  const g = await draw();
  if(g && ['open', 'awaiting_confirm', 'awaiting_gap', 'confirming'].includes(g.status)){
    agGroupPoll = setInterval(() => { if(!document.querySelector('.razorpay-container') && !(typeof aervaCheckout !== 'undefined' && aervaCheckout)) draw(); }, 10000);
  }
}
function agTickCountdowns(root){
  clearInterval(agGroupTimer);
  const els = [...root.querySelectorAll('[data-ag-countdown]')];
  if(!els.length) return;
  const ends = els.map(el => Date.now() + Number(el.dataset.agCountdown) * 1000);
  agGroupTimer = setInterval(() => {
    els.forEach((el, i) => {
      const left = Math.max(0, Math.round((ends[i] - Date.now()) / 1000));
      el.textContent = agClock(left) + (el.dataset.agSuffix != null ? el.dataset.agSuffix : ' left');
      el.classList.toggle('is-soon', left <= 300);
    });
  }, 1000);
}
function agGroupHtml(g, note){
  const pct = Math.round(100 * g.paidPlaces / g.places);
  const link = location.origin + location.pathname.replace(/[^/]*$/, '') + 'index.html?group=' + encodeURIComponent(g.token);
  const statusLine = {
    open: `<span class="ag-pill ag-open">Open</span> <span class="ag-count-big" data-ag-countdown="${g.secondsLeft || 0}">${agClock(g.secondsLeft)} left</span>`,
    awaiting_confirm: `<span class="ag-pill ag-wait">Waiting for ${g.isOrganiser ? 'you' : AG_ESC(g.organiserFirstName || 'the organiser')}</span> <span class="ag-count-big" data-ag-countdown="${g.confirmSecondsLeft || 0}">${agClock(g.confirmSecondsLeft)} left</span>`,
    awaiting_gap: `<span class="ag-pill ag-wait">${g.isOrganiser ? 'Pay the rest' : `Waiting for ${AG_ESC(g.organiserFirstName || 'the organiser')} to pay the rest`}</span> <span class="ag-count-big" data-ag-countdown="${g.confirmSecondsLeft || 0}">${agClock(g.confirmSecondsLeft)} left</span>`,
    confirming: '<span class="ag-pill ag-wait">Being confirmed…</span>',
    confirmed: g.bookingCancelled ? '<span class="ag-pill ag-off">Booking cancelled</span>' : '<span class="ag-pill ag-done">Confirmed</span>',
    cancelled: `<span class="ag-pill ag-off">${g.outcomeKind === 'booked' ? 'Booked by someone else' : g.outcomeKind === 'not_completed' ? 'Not completed' : 'Did not go ahead'}</span>`,
    failed: '<span class="ag-pill ag-off">Not opened</span>',
    starting: '<span class="ag-pill ag-wait">Starting…</span>'
  }[g.status] || '';
  const noteHtml = note ? `<div class="ag-note ${note.note === 'paid' || note.note === 'added' ? 'is-ok' : 'is-bad'}">${note.note === 'added' ? AG_ESC(note.message) : note.note === 'paid' ? 'Payment received — thank you. Your place is counted.' : AG_ESC(note.message || 'Your payment is being checked.')}</div>` : '';
  const payers = g.payers.map(p => `<li><span class="ag-dot is-paid"></span>${AG_ESC(p.firstName)}${p.organiser ? ' <em>(organiser)</em>' : ''} — ${p.places} place${p.places === 1 ? '' : 's'}</li>`).join('');
  const failed = (g.failed || []).map(f => `<li><span class="ag-dot is-failed"></span>${AG_ESC(f.firstName)}: ${AG_ESC(f.note)}</li>`).join('')
    + (g.rejected || []).map(f => `<li><span class="ag-dot is-failed"></span>${AG_ESC(f.firstName)}: ${AG_ESC(f.note)}</li>`).join('');
  const share = g.status === 'open' ? `<div class="ag-card"><h3 class="ag-h3">Share with your group</h3>
      <div class="ag-share"><input id="agShareLink" readonly value="${AG_ESC(link)}">
      <button type="button" class="btn" id="agCopyLink">Copy link</button>
      <a class="btn" id="agWhatsApp" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(`Join our stay at ${g.stay.name} (${AG_DAY(g.stay.arrival)}): pay for your place (${AG_INR(g.perPlace)}) here — ${link}`)}">Share on WhatsApp</a></div></div>` : '';
  let pay = '';
  if(g.status === 'open'){
    const opts = Array.from({ length: Math.max(0, g.placesLeft) }, (_, i) => `<option value="${i + 1}">${i + 1} place${i ? 's' : ''}</option>`).join('');
    pay = g.placesLeft > 0 ? `<div class="ag-card" id="agPayCard"><h3 class="ag-h3">${g.myPlaces ? 'Pay for more places' : 'Pay for your place'}</h3>
      <p class="ag-help">Your name as on your government ID, and a mobile number — saved to your account.</p>
      <div class="ag-grid"><div class="field"><label for="agPayFirst">First name</label><input id="agPayFirst" autocomplete="given-name"></div>
      <div class="field"><label for="agPayLast">Last name</label><input id="agPayLast" autocomplete="family-name"></div></div>
      <div class="ag-grid" style="margin-top:10px;"><div class="field"><label for="agPayPhone">Mobile number</label><input id="agPayPhone" type="tel" autocomplete="tel"></div>
      <div class="field"><label for="agPayPlaces">Places</label><select id="agPayPlaces">${opts}</select></div></div>
      <p class="ag-help" id="agPayAmount"></p>
      ${agNonRefTick(g)}
      <button type="button" class="btn solid" id="groupPayBtn" style="width:100%; margin-top:8px;">Pay</button>
      <p class="ag-error" id="agPayError" hidden></p></div>`
      : `<div class="ag-card"><p>Every place is paid for, or being paid for right now. If a payment does not go through, its place opens again in a few minutes.</p></div>`;
  }
  // Guests added after confirmation: one payment confirms them on the same booking.
  if(g.status === 'confirmed' && g.pendingAdd){
    const pa = g.pendingAdd;
    pay = pa.beingPaid ? `<div class="ag-card"><p>Someone is paying for the ${pa.guests} added guest${pa.guests === 1 ? '' : 's'} right now. If it does not go through, you can pay in a few minutes.</p></div>`
      : `<div class="ag-card" id="agPayCard"><h3 class="ag-h3">Pay for the added guest${pa.guests === 1 ? '' : 's'}</h3>
      <p>${pa.guests} guest${pa.guests === 1 ? ' was' : 's were'} added. The booking goes from ${AG_INR(pa.oldTotal)} to <strong>${AG_INR(pa.newTotal)}</strong>; the extra <strong>${AG_INR(pa.amount)}</strong> confirms ${pa.guests === 1 ? 'them' : 'them'} at once on the same booking. The organiser or anyone with the link can pay it.</p>
      <p class="ag-help">Your name as on your government ID, and a mobile number — saved to your account.</p>
      <div class="ag-grid"><div class="field"><label for="agPayFirst">First name</label><input id="agPayFirst" autocomplete="given-name"></div>
      <div class="field"><label for="agPayLast">Last name</label><input id="agPayLast" autocomplete="family-name"></div></div>
      <div class="field" style="margin-top:10px;"><label for="agPayPhone">Mobile number</label><input id="agPayPhone" type="tel" autocomplete="tel"></div>
      ${agNonRefTick(g)}
      <button type="button" class="btn solid" id="groupPayBtn" data-amount="${pa.amount}" style="width:100%; margin-top:8px;">Pay ${AG_INR(pa.amount)}</button>
      <p class="ag-error" id="agPayError" hidden></p></div>`;
  }
  // The balance the paid places owe after a guest was added.
  const topup = g.topup && g.topup.owed > 0 ? `<div class="ag-card" id="agTopupCard"><h3 class="ag-h3">Balance to pay: ${AG_INR(g.topup.owed)}</h3>
      <p>A guest was added and the price per place went up, so the places already paid owe ${AG_INR(g.topup.owed)} more in all. One payment covers it — the organiser or anyone in the group can pay it. The booking is confirmed once every place and this balance are paid.</p>
      ${g.topup.beingPaid ? '<p class="ag-help">Someone is paying it right now.</p>' : g.topup.canPay ? `${agNonRefTick(g)}<button type="button" class="btn solid" id="agPayTopup">Pay the balance (${AG_INR(g.topup.owed)})</button><p class="ag-error" id="agTopupError" hidden></p>` : ''}</div>` : '';
  // Add a guest: places only go up; never above the listing's capacity.
  const addMax = Math.max(0, Number(g.canAddMax) || 0);
  const capLine = g.maxGuests ? `This place takes at most ${g.maxGuests} guests.` : '';
  const addControls = (label) => addMax > 0
    ? `<div class="ag-add-row"><div class="field"><label for="agAddPlaces">Guests to add</label><select id="agAddPlaces">${Array.from({ length: Math.min(addMax, 10) }, (_, i) => `<option value="${i + 1}">${i + 1} guest${i ? 's' : ''}</option>`).join('')}</select></div>
       <button type="button" class="btn solid" id="agAddGuest">${label}</button></div>
       <p class="ag-help">${AG_ESC(capLine)} Places can only be added, never removed.</p>`
    : `<p class="ag-cap" id="agCapMsg">${AG_ESC(capLine)} Your group already has ${g.guestsNow} — no more guests can be added.</p>`;
  const atDecisionAdd = g.isOrganiser && g.canAdd && g.status === 'awaiting_gap';
  const addCard = g.canAdd && !atDecisionAdd && (g.status === 'open' || g.status === 'confirmed') ? `<div class="ag-card" id="agAddCard"><h3 class="ag-h3">Add a guest</h3>
      <p>${g.status === 'confirmed' ? 'The booking is priced again for the new number of guests with the listing’s normal price. Once the extra amount is paid, the guests are confirmed on the same booking — no wait for the host.' : 'The stay is priced again for the new number of guests with the listing’s normal price, and split again by places. Places already paid keep what they paid.'}</p>
      ${addControls('Add')}<p class="ag-error" id="agAddError" hidden></p></div>` : '';
  const notices = (g.notices || []).length ? `<div class="ag-card"><h3 class="ag-h3">Updates</h3><ul class="ag-list ag-notices">${g.notices.slice().reverse().map(n => `<li>${AG_ESC(n.text)}</li>`).join('')}</ul></div>` : '';
  // At 2 hours with places unpaid: the organiser pays the rest (their commitment).
  let decide = '';
  if(g.isOrganiser && g.rest && g.status === 'awaiting_gap'){
    const q = g.rest;
    decide = `<div class="ag-card ag-decide" id="agRestCard"><h3 class="ag-h3">Pay the remaining ${AG_INR(q.amount)} to confirm</h3>
      <p>${q.paidPlaces} of ${g.places} places were paid in 2 hours. As you agreed when you started the group, pay the remaining <strong>${AG_INR(q.amount)}</strong> within the time left to confirm the booking for all ${g.places} guests.</p>
      <p class="ag-help">The place is not held meanwhile: if someone else books it first, everyone is refunded in full. If you don’t pay in time, nothing is booked, everyone is refunded in full, and the unpaid amount is recorded on your account.</p>
      ${q.beingPaid ? '<p class="ag-help">Your payment is in progress.</p>' : `${agNonRefTick(g)}<div class="ag-actions"><button type="button" class="btn solid" id="agPayGap">Pay ${AG_INR(q.amount)} and confirm</button></div>`}
      ${atDecisionAdd ? `<p class="ag-help" style="margin-top:12px;"><strong>Or add guest(s)</strong> (once): the group reopens for 30 minutes, priced for the new number of guests. Anything still unpaid then is yours to pay.</p>
          ${addControls('Add and pay')}<p class="ag-error" id="agAddError" hidden></p>` : ''}
      <p class="ag-error" id="agDecideError" hidden></p></div>`;
  } else if(!g.isOrganiser && (g.status === 'awaiting_confirm' || g.status === 'awaiting_gap')){
    decide = `<div class="ag-card"><p>Not every place was paid in 2 hours. ${AG_ESC(g.organiserFirstName || 'The organiser')} is paying the rest${g.rest ? ` (${AG_INR(g.rest.amount)})` : ''} to confirm the booking. If it isn’t paid in time, you are refunded in full. We email you either way.</p></div>`;
  }
  const outcome = g.status === 'confirmed' && g.bookingCancelled
    ? `<div class="ag-card ag-outcome"><p><strong>This group booking was confirmed and has since been cancelled.</strong></p>${g.myPlaces || g.isOrganiser ? '<p>See <a href="index.html?view=my-bookings">My Bookings</a> and the updates below for what happens to your share.</p>' : ''}</div>`
    : g.status === 'confirmed'
    ? `<div class="ag-card"><p><strong>${AG_ESC(g.outcome || 'Confirmed.')}</strong></p>${g.myPlaces || g.isOrganiser ? '<p>It is in your <a href="index.html?view=my-bookings">My Bookings</a>, with the check-in details and the group’s messages with the host.</p>' : ''}</div>`
    : g.status === 'cancelled' || g.status === 'failed' ? `<div class="ag-card ag-outcome" id="agOutcome">${g.outcomeKind === 'booked' || g.outcomeKind === 'unavailable'
        ? `<h3 class="ag-h3">${g.outcomeKind === 'booked' ? 'This place got booked by someone else' : 'This place is no longer available'}</h3><p>${AG_ESC(g.outcome)}</p>`
        : g.outcomeKind === 'not_completed' ? `<h3 class="ag-h3">The group’s booking wasn’t completed</h3><p>Not every place was paid, and the rest was not paid within 30 minutes of the 2-hour mark, so nothing was booked.</p>`
        : `<p>${AG_ESC(g.outcome || 'This group booking did not go ahead.')}</p>`}
      ${g.myPaid ? `<p>Your ${AG_INR(g.myPaid)} is refunded in full to your original payment method.</p>` : ''}
      ${g.outcomeKind === 'booked' || g.outcomeKind === 'unavailable' ? '<div class="ag-actions"><a class="btn solid" href="index.html">Find another stay</a></div>' : ''}</div>` : '';
  const notHeld = g.status === 'open' ? (g.datesHeld
      ? '<p class="ag-note is-ok" id="agHeldNote">The last payment is in progress: the place is held for its 3 minutes.</p>'
      : `<p class="ag-note ag-warn" id="agNotHeldNote"><strong>Not held until the last payment.</strong> ${AG_ESC((g.notHeldNotice || '').replace(/^The place is not held until the last payment\. /, ''))}</p>`) : '';
  return `${noteHtml}${agStayHead(g.stay, `<p class="ag-status">${statusLine}</p>`)}
    <div class="ag-card"><div class="ag-progress"><span style="width:${pct}%"></span></div>
      <p class="ag-lead"><strong>${g.paidPlaces} of ${g.places}</strong> places paid${g.status === 'open' ? ` · <strong>${g.placesLeft}</strong> left${g.beingPaid ? ` · ${g.beingPaid} being paid now` : ''}` : ''}</p>
      <p>${g.status === 'open' && g.placesLeft > 0 ? 'Each place still to pay' : 'Each place'}: <strong>${AG_INR(g.perPlace)}</strong>${g.lastPlace !== g.perPlace ? ` (last place ${AG_INR(g.lastPlace)})` : ''} · whole stay ${AG_INR(g.total)}, including GST, service fee and any deposit.</p>
      ${g.extraWindow ? `<p class="ag-help">Guests were added at the 2-hour mark: this is the 30-minute extra window. Anything still unpaid then is for ${AG_ESC(g.organiserFirstName || 'the organiser')} to pay.</p>` : ''}
      ${notHeld}
      ${payers ? `<ul class="ag-list">${payers}</ul>` : ''}${failed ? `<ul class="ag-list ag-failed">${failed}</ul>` : ''}
      ${g.myPaid ? `<p class="ag-help">Your share: you paid ${AG_INR(g.myPaid)}${g.myPlaces ? ` for ${g.myPlaces} place${g.myPlaces === 1 ? '' : 's'}` : ''}.</p>` : ''}
    </div>
    ${outcome}${decide}${topup}${pay}${addCard}${share}${notices}
    <p class="ag-help"><strong>Non-refundable group booking.</strong> Once confirmed, nothing is refunded if plans change, whatever the listing’s policy (any deposit is refunded). A natural disaster or government order approved by Aerva, or a cancellation by the host, gives each person their own share as Aerva credit; if Aerva’s check-in promise is not kept, each person is refunded in full. ${AG_ESC(g.organiserFirstName || 'The organiser')} manages the booking.</p>`;
}
// The tick every payer gives before paying (owner, 10 Nov 2026).
function agNonRefTick(g){
  return `<label class="ag-opt ag-tick" style="margin-top:10px;"><input type="checkbox" class="ag-nonref">
    <span><strong>I understand: once the booking is confirmed it is non-refundable.</strong><em>${AG_ESC(String((g && g.nonRefundableText) || '').replace(/^I understand: once the booking is confirmed it is non-refundable\.\s*/, ''))}</em></span></label>`;
}
function agBindGroup(box, g, redraw){
  const copy = document.getElementById('agCopyLink');
  if(copy) copy.addEventListener('click', async () => {
    const input = document.getElementById('agShareLink');
    try{ await navigator.clipboard.writeText(input.value); copy.textContent = 'Copied'; }catch(e){ input.select(); copy.textContent = 'Press Ctrl+C'; }
    setTimeout(() => { copy.textContent = 'Copy link'; }, 1800);
  });
  const placesEl = document.getElementById('agPayPlaces');
  const amountEl = document.getElementById('agPayAmount');
  const paintAmount = () => {
    if(!placesEl || !amountEl) return;
    const k = Number(placesEl.value) || 1;
    // The lowest free places are taken; the last places may be a rupee more.
    let amt;
    if(Array.isArray(g.freeShares)) amt = g.freeShares.slice(0, k).reduce((a, b) => a + b, 0);
    else {
      const free = g.places - g.paidPlaces - g.beingPaid;
      const start = g.places - free;
      amt = g.shares.slice(start, start + k).reduce((a, b) => a + b, 0);
    }
    amountEl.innerHTML = `You pay <strong>${AG_INR(amt)}</strong> for ${k} place${k === 1 ? '' : 's'}.`;
    const btn = document.getElementById('groupPayBtn');
    if(btn && !btn.disabled) btn.textContent = `Pay ${AG_INR(amt)}`;
  };
  if(placesEl){ placesEl.addEventListener('change', paintAmount); paintAmount(); }
  if(document.getElementById('agPayFirst') && typeof aervaPrefillPromise !== 'undefined'){
    if(typeof aervaPrefillBooking === 'function') aervaPrefillBooking();
    (aervaPrefillPromise || Promise.resolve({})).then(d => {
      if(!d) return;
      const put = (id, v) => { const el = document.getElementById(id); if(el && !el.value && v) el.value = v; };
      put('agPayFirst', d.firstName); put('agPayLast', d.lastName); put('agPayPhone', String(d.phone || '').replace(/^\+91(?=[6-9]\d{9}$)/, ''));
    });
  }
  const payBtn = document.getElementById('groupPayBtn');
  if(payBtn) payBtn.addEventListener('click', () => agStartGroupPayment(g, { places: placesEl ? (Number(placesEl.value) || 1) : 1 }, payBtn, document.getElementById('agPayError'), redraw));
  const topupBtn = document.getElementById('agPayTopup');
  if(topupBtn) topupBtn.addEventListener('click', () => agStartGroupPayment(g, { topup: true }, topupBtn, document.getElementById('agTopupError'), redraw));
  const addBtn = document.getElementById('agAddGuest');
  if(addBtn) addBtn.addEventListener('click', async () => {
    const err = document.getElementById('agAddError');
    const k = Number((document.getElementById('agAddPlaces') || {}).value) || 1;
    if(!confirm(`Add ${k} guest${k === 1 ? '' : 's'}? The stay is priced again for ${Number(g.guestsNow || g.places) + k} guests. Places can never be removed once added.`)) return;
    addBtn.disabled = true; err.hidden = true;
    const r = await agFetch('/api/guest-profile', { method: 'POST', body: JSON.stringify({ mode: 'groupAddGuest', token: g.token, places: k }) });
    addBtn.disabled = false;
    if(!r.ok){ err.textContent = r.data.error || 'Could not add the guest.'; err.hidden = false; return; }
    const d = r.data;
    agGroupFlash = { note: 'added', message: d.status === 'confirmed'
      ? (d.pendingAdd ? `Guest${k === 1 ? '' : 's'} added. Pay ${AG_INR(d.pendingAdd.amount)} below (or share the link) to confirm ${k === 1 ? 'them' : 'them'} on the booking.` : `Guest${k === 1 ? '' : 's'} added.`)
      : `Guest${k === 1 ? '' : 's'} added — now ${d.places} places, ${AG_INR(d.perPlace)} each. Pay for the new place${k === 1 ? '' : 's'} below, or share the link.` };
    await redraw();
    const sel = document.getElementById('agPayPlaces');
    if(sel && [...sel.options].some(o => Number(o.value) === k)){ sel.value = String(k); sel.dispatchEvent(new Event('change')); }
    const card = document.getElementById('agPayCard'); if(card) card.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
  const gapBtn = document.getElementById('agPayGap');
  if(gapBtn) gapBtn.addEventListener('click', () => agStartGroupPayment(g, { gap: true }, gapBtn, document.getElementById('agDecideError'), redraw));
}
async function agStartGroupPayment(g, what, btn, errEl, redraw){
  const fail = (m) => { errEl.textContent = m; errEl.hidden = false; btn.disabled = false; };
  errEl.hidden = true;
  const body = { agreementVersion: window.AERVA_POLICIES && window.AERVA_POLICIES.agreements && window.AERVA_POLICIES.agreements.version };
  // Every payer ticks the non-refundable notice (the server checks it too).
  const card = btn.closest('.ag-card');
  const nonRef = card && card.querySelector('.ag-nonref');
  if(nonRef && !nonRef.checked) return fail('Please tick that you understand: once the booking is confirmed it is non-refundable.');
  body.nonRefundable = true;
  if(what.gap) body.groupGap = g.token;
  else if(what.topup) body.groupTopup = g.token;
  else {
    const first = document.getElementById('agPayFirst').value.trim(), last = document.getElementById('agPayLast').value.trim(), phone = document.getElementById('agPayPhone').value.trim();
    if(!AG_NAME_OK(first) || !AG_NAME_OK(last)) return fail('Please enter your first and last name as on your government ID: letters, spaces, dots, apostrophes and hyphens only.');
    if(phone.replace(/\D/g, '').length < 10) return fail('Please enter your mobile number.');
    const box = btn.previousElementSibling && btn.previousElementSibling.classList.contains('agreement-box') ? btn.previousElementSibling : document.querySelector('#agPayCard .agreement-box');
    const check = box && box.querySelector('.agreement-check');
    if(check && !check.checked) return fail('Please tick the booking agreement to continue.');
    Object.assign(body, { groupPay: g.token, places: what.places, firstName: first, lastName: last, phone });
  }
  btn.disabled = true;
  const r = await agFetch('/api/create-order', { method: 'POST', body: JSON.stringify(body) });
  if(!r.ok) { fail(r.data.error || 'Could not start the payment.'); if(r.status === 409) setTimeout(redraw, 1500); return; }
  const order = r.data;
  if(typeof Razorpay === 'undefined') return fail('Payment gateway did not load. Please check your connection and try again.');
  const rzp = new Razorpay({ key: order.keyId, order_id: order.orderId, amount: order.amount, currency: 'INR', name: 'Aerva', description: g.stay.name + ' — group booking',
    timeout: order.holdSeconds || undefined, theme: { color: '#a9884f' },
    prefill: { contact: what.gap || what.topup ? undefined : String(body.phone || '').replace(/\D/g, '') },
    handler: async function(response){
      aervaCheckoutSucceeded();
      try{
        const v = await fetch(AG_API() + '/api/verify-payment', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(response) });
        const d = await v.json();
        if(d.group && d.group.token) aervaAfterGroupPayment(d); else redraw();
      }catch(e){ redraw(); }
    },
    modal: { ondismiss: function(){ aervaEndCheckout('closed'); btn.disabled = false; setTimeout(redraw, 800); } } });
  rzp.on('payment.failed', function(){ aervaEndCheckout('failed'); btn.disabled = false; setTimeout(redraw, 800); });
  rzp.open();
  aervaWatchCheckout(rzp, order, errEl, { holdsDates: false });
}

// ---- The gift page: index.html?gift=<token> (or ?giftId= from My Bookings) ----
async function aervaShowGiftPage(token, giftId){
  const box = agShowView('Your gift');
  if(!box) return;
  const back = token ? 'index.html?gift=' + encodeURIComponent(token) : 'index.html?giftId=' + encodeURIComponent(giftId);
  box.innerHTML = '<p class="loading">Loading…</p>';
  if(!agToken()){
    if(!token){ box.innerHTML = `<div class="ag-card"><p>Please log in to see your gift.</p>${agLoginLinks(back, '', 'gift')}</div>`; return; }
    const r = await agFetch('/api/get-listings?giftPreview=' + encodeURIComponent(token), { method: 'GET' });
    if(!r.ok){ box.innerHTML = `<p class="ag-error">${AG_ESC(r.data.error || 'This gift link is not valid.')}</p>`; return; }
    const p = r.data;
    box.innerHTML = `${agStayHead(p.stay, `<p class="ag-status"><span class="ag-pill ag-gift">A gift from ${AG_ESC(p.gift.from)}</span></p>`)}
      ${p.gift.message ? `<blockquote class="ag-quote">“${AG_ESC(p.gift.message)}”<cite>— ${AG_ESC(p.gift.from)}</cite></blockquote>` : ''}
      <div class="ag-card">${p.gift.accepted ? '<p>This gift has already been accepted.</p>' : `<p class="ag-lead">Hello ${AG_ESC(p.gift.to)} — to accept your stay, log in or create your Aerva account. Then add your name and a mobile number your host can reach you on.</p>`}
      ${agLoginLinks(back, p.gift.email, 'gift')}</div>`;
    return;
  }
  const q = token ? 'token=' + encodeURIComponent(token) : 'giftId=' + encodeURIComponent(giftId);
  const r = await agFetch('/api/guest-profile?mode=gift&' + q, { method: 'GET' });
  if(!r.ok){ box.innerHTML = `<div class="ag-card"><p class="ag-error">${AG_ESC(r.data.error || 'This gift could not be opened.')}</p></div>`; return; }
  agDrawGift(box, r.data, { token, giftId });
}
function agAcceptedHtml(v, st){
  return `${agStayHead(st, `<p class="ag-status"><span class="ag-pill ag-done">Gift accepted</span> <span class="ag-meta">from ${AG_ESC(v.from)}</span></p>`)}
    <div class="ag-card">
      ${st.confirmationCode ? `<div class="confirm-code"><span class="confirm-code-label">Confirmation code</span><span class="confirm-code-value">${AG_ESC(st.confirmationCode)}</span></div>` : ''}
      ${st.address ? `<p><strong>Address:</strong> ${AG_ESC(st.address)}</p>` : ''}
      <p>Check-in from ${AG_ESC(st.checkIn || '2:00 PM')} · check-out by ${AG_ESC(st.checkOut || '11:00 AM')}</p>
      <p class="ag-help">Carry a government photo ID: your host checks it at check-in. ${AG_ESC(v.from)} manages the booking (dates, changes, cancellations).</p>
      <div class="ag-actions"><a class="btn solid" href="index.html?view=my-bookings">See it in My Bookings</a>${st.orderId ? `<button type="button" class="btn" id="agGiftChat">Message the host</button>` : ''}</div></div>`;
}
function agDrawGift(box, v, ref){
  const st = v.stay;
  if(v.status === 'accepted_by_you'){
    box.innerHTML = agAcceptedHtml(v, st);
    const chat = document.getElementById('agGiftChat');
    if(chat && typeof openChatForOrder === 'function') chat.addEventListener('click', () => openChatForOrder(st.orderId, st.name));
    return;
  }
  const head = `${agStayHead(st, `<p class="ag-status"><span class="ag-pill ag-gift">A gift from ${AG_ESC(v.from)}</span></p>`)}
    ${v.message ? `<blockquote class="ag-quote">“${AG_ESC(v.message)}”<cite>— ${AG_ESC(v.from)}</cite></blockquote>` : ''}`;
  if(v.isBuyer){ box.innerHTML = head + '<div class="ag-card"><p>This is the gift you sent. Only the person you sent it to can accept it. You can change the recipient in My Bookings until check-in.</p></div>'; return; }
  if(v.status === 'accepted_by_other'){ box.innerHTML = head + '<div class="ag-card"><p>This gift has already been accepted.</p></div>'; return; }
  if(!v.canAccept){ box.innerHTML = head + '<div class="ag-card"><p>This gift link has already been used. If this gift is for you, log in with the email it was sent to, or ask the person who sent it for a new link.</p></div>'; return; }
  box.innerHTML = head + `<div class="ag-card" id="agAcceptCard"><h3 class="ag-h3">Accept the gift</h3>
    <p class="ag-help">Your name as on your government ID (the host checks it at check-in) and a mobile number your host can reach you on.</p>
    <div class="ag-grid"><div class="field"><label for="agGiftFirst">First name</label><input id="agGiftFirst" autocomplete="given-name" value="${AG_ESC(v.prefill.firstName)}"></div>
    <div class="field"><label for="agGiftLast">Last name</label><input id="agGiftLast" autocomplete="family-name" value="${AG_ESC(v.prefill.lastName)}"></div></div>
    <div class="field" style="margin-top:10px;"><label for="agGiftPhone">Mobile number</label><input id="agGiftPhone" type="tel" autocomplete="tel" value="${AG_ESC(String(v.prefill.phone || '').replace(/^\+91(?=[6-9]\d{9}$)/, ''))}"></div>
    <button type="button" class="btn solid" id="agAcceptBtn" style="width:100%; margin-top:14px;">Accept the gift</button>
    <p class="ag-error" id="agAcceptError" hidden></p></div>`;
  const btn = document.getElementById('agAcceptBtn');
  btn.addEventListener('click', async () => {
    const err = document.getElementById('agAcceptError');
    const first = document.getElementById('agGiftFirst').value.trim(), last = document.getElementById('agGiftLast').value.trim(), phone = document.getElementById('agGiftPhone').value.trim();
    err.hidden = true;
    if(!AG_NAME_OK(first) || !AG_NAME_OK(last)){ err.textContent = 'Please enter your first and last name as on your government ID: letters, spaces, dots, apostrophes and hyphens only.'; err.hidden = false; return; }
    if(phone.replace(/\D/g, '').length < 10){ err.textContent = 'Please enter a mobile number your host can reach you on.'; err.hidden = false; return; }
    btn.disabled = true; btn.textContent = 'Accepting…';
    const r = await agFetch('/api/guest-profile', { method: 'POST', body: JSON.stringify({ mode: 'acceptGift', token: ref.token || undefined, giftId: ref.giftId || undefined, firstName: first, lastName: last, phone }) });
    if(!r.ok){ err.textContent = r.data.error || 'Could not accept the gift.'; err.hidden = false; btn.disabled = false; btn.textContent = 'Accept the gift'; return; }
    box.innerHTML = agAcceptedHtml(v, r.data.stay);
    const chat = document.getElementById('agGiftChat');
    if(chat && typeof openChatForOrder === 'function') chat.addEventListener('click', () => openChatForOrder(r.data.stay.orderId, r.data.stay.name));
  });
}

// ---- My Bookings ----
function aervaSharedBookingCard(b){
  const esc = AG_ESC;
  const when = `${esc(AG_DAY(b.arrival))} → ${esc(AG_DAY(b.departure))}`;
  if(b.pending_group){
    const g = b.group || {};
    return `<div class="listing-card booking-card ag-mb" style="margin-bottom:14px;"><div class="listing-info">
      <h3>${esc(b.suite_name || 'Group booking')}</h3>
      <div class="listing-meta">${when} · ${g.places} guests · <span class="ag-pill ${b.status === 'cancelled' ? 'ag-off' : 'ag-wait'}">${b.status === 'cancelled' ? 'Did not go ahead' : 'Group booking'}</span></div>
      <p class="ag-mb-note">${esc(g.note || '')}</p>
      <div class="booking-actions"><a class="filter-clear" href="index.html?group=${encodeURIComponent(g.token)}" onclick="event.stopPropagation()">${g.organiser && (g.status === 'awaiting_confirm' || g.status === 'awaiting_gap') ? 'Pay the rest' : 'Open the group page'}</a></div>
    </div></div>`;
  }
  const upcoming = b.status === 'paid' && String(b.departure).slice(0, 10) >= String(b.local_today || '').slice(0, 10);
  const tag = b.shared === 'gift'
    ? `<span class="ag-pill ag-gift">Gifted to you</span> <span class="ag-meta">from ${esc(b.gift_from)}</span>`
    : `<span class="ag-pill ag-done">${esc(b.group.label || 'Non-refundable group booking')}</span> <span class="ag-meta">your share: ${b.group.myPaid ? AG_INR(b.group.myPaid) + ' for ' : ''}${b.group.myPlaces} place${b.group.myPlaces === 1 ? '' : 's'} · organised by ${esc(b.group.organiserFirstName || 'a friend')}</span>`;
  const accept = b.shared === 'gift' && !b.gift_accepted && upcoming
    ? `<a class="btn solid" href="index.html?giftId=${encodeURIComponent(b.gift_id)}" onclick="event.stopPropagation()" style="min-height:44px; padding:10px 18px;">Accept the gift</a>` : '';
  const canChat = (b.shared === 'group' || b.gift_accepted) && (b.status === 'paid' || b.status === 'cancelled');
  const checkin = (b.shared === 'group' || b.gift_accepted) && b.status === 'paid'
    ? `<div class="ag-checkin">${b.confirmation_code ? `<div class="confirm-code"><span class="confirm-code-label">Confirmation code</span><span class="confirm-code-value">${esc(b.confirmation_code)}</span><button type="button" class="confirm-code-copy" data-copy-code="${esc(b.confirmation_code)}">Copy</button></div>` : ''}
        ${b.listing_address ? `<p><strong>Address:</strong> ${esc(b.listing_address)}</p>` : ''}
        <p>Check-in from ${esc(b.check_in_time || '2:00 PM')} · check-out by ${esc(b.check_out_time || '11:00 AM')}. Carry a government photo ID.</p></div>` : '';
  return `<div class="listing-card booking-card ag-mb" style="margin-bottom:14px;"><div class="listing-info">
    <h3>${esc(b.suite_name || '')}</h3>
    <div class="listing-meta">${when} · ${b.guests} guest${b.guests === 1 ? '' : 's'} · ${b.status === 'paid' ? (upcoming ? 'Confirmed' : 'Completed') : 'Cancelled'}</div>
    <p class="ag-mb-note">${tag}</p>
    ${b.gift_message ? `<blockquote class="ag-quote ag-quote-sm">“${esc(b.gift_message)}”</blockquote>` : ''}
    ${checkin}
    <div class="booking-actions">${accept}${canChat ? `<button type="button" class="filter-clear" data-order-id="${b.id}" data-listing-name="${esc(b.suite_name || '')}">${upcoming ? 'Message host' : 'View messages'}</button>` : ''}${b.can_report_arrival ? `<button type="button" class="filter-clear" data-report-problem="${b.id}" data-listing-name="${esc(b.suite_name || '')}" data-arrival-only="1">Report a problem on arrival</button>` : ''}</div>
    <p class="ag-help">${b.shared === 'gift' ? esc(b.gift_from) : esc(b.group.organiserFirstName || 'The organiser')} manages this booking (changes and cancellations).</p>
  </div></div>`;
}
function aervaOwnBookingExtrasHtml(b){
  const esc = AG_ESC;
  let out = '';
  if(b.gift) out += `<p class="ag-mb-note"><span class="ag-pill ag-gift">Gift for ${esc(b.gift.recipientName)}</span> <span class="ag-meta">${esc(b.gift.status === 'accepted' ? 'Accepted' : 'Waiting for ' + b.gift.recipientFirstName + ' to accept')}</span></p>`;
  if(b.group) out += `<p class="ag-mb-note"><span class="ag-pill ag-done">${esc(b.group.label || 'Non-refundable group booking')}</span> <span class="ag-meta">${b.guests || b.group.places} guests · your share: ${b.group.myPaid ? AG_INR(b.group.myPaid) + ' for ' : ''}${b.group.myPlaces} place${b.group.myPlaces === 1 ? '' : 's'} · <a href="index.html?group=${encodeURIComponent(b.group.token)}" onclick="event.stopPropagation()">group page</a></span></p>`;
  return out;
}
function aervaOwnBookingButtonsHtml(b){
  if(b.can_gift) return `<button type="button" class="filter-clear" data-send-gift="${b.id}">Send as a gift</button>`;
  if(b.gift && b.can_change_gift) return `<button type="button" class="filter-clear" data-change-gift="${b.id}">Change recipient</button><button type="button" class="filter-clear" data-stop-gift="${b.id}">Stop gift</button>`;
  return '';
}
function aervaBindGiftGroupButtons(container, bookings){
  container.querySelectorAll('[data-send-gift], [data-change-gift]').forEach(btn => btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const id = Number(btn.dataset.sendGift || btn.dataset.changeGift);
    aervaOpenGiftForm(bookings.find(x => Number(x.id) === id));
  }));
  container.querySelectorAll('[data-stop-gift]').forEach(btn => btn.addEventListener('click', async (e) => {
    e.stopPropagation();
    if(!confirm('Stop the gift? You become the guest staying again, and the link stops working.')) return;
    btn.disabled = true;
    const r = await agFetch('/api/guest-profile', { method: 'POST', body: JSON.stringify({ mode: 'withdrawGift', orderId: Number(btn.dataset.stopGift) }) });
    if(!r.ok){ alert(r.data.error || 'Could not stop the gift.'); btn.disabled = false; return; }
    if(typeof loadMyBookings === 'function') loadMyBookings();
  }));
}
function aervaOpenGiftForm(b){
  if(!b) return;
  const old = document.getElementById('agGiftModal'); if(old) old.remove();
  const g = b.gift || {};
  const [gf, ...gl] = String(g.recipientName || '').split(' ');
  const wrap = document.createElement('div');
  wrap.id = 'agGiftModal'; wrap.className = 'ag-modal'; wrap.setAttribute('role', 'dialog'); wrap.setAttribute('aria-modal', 'true');
  wrap.innerHTML = `<div class="ag-modal-box"><button type="button" class="ag-modal-x" aria-label="Close">×</button>
    <h3 class="ag-h3">${b.gift ? 'Change who this stay is for' : 'Send as a gift'}</h3>
    <p class="ag-help">${AG_ESC(b.suite_name || '')} · ${AG_ESC(AG_DAY(b.arrival))}. You keep managing the booking; refunds go to your payment. They get the stay details (never the price) and accept it with their name and phone.</p>
    <div class="ag-grid"><div class="field"><label for="agMFirst">Their first name</label><input id="agMFirst" value="${AG_ESC(b.gift ? gf : '')}"></div>
    <div class="field"><label for="agMLast">Their last name</label><input id="agMLast" value="${AG_ESC(b.gift ? gl.join(' ') : '')}"></div></div>
    <div class="field" style="margin-top:10px;"><label for="agMEmail">Their email</label><input id="agMEmail" type="email" value="${AG_ESC(g.recipientEmail || '')}"></div>
    <div class="field" style="margin-top:10px;"><label for="agMPhone">Their mobile (optional)</label><input id="agMPhone" type="tel"></div>
    <div class="field" style="margin-top:10px;"><label for="agMMsg">Gift message (optional)</label><textarea id="agMMsg" maxlength="300" rows="3">${AG_ESC(g.message || '')}</textarea></div>
    <button type="button" class="btn solid" id="agMSend" style="width:100%; margin-top:14px;">${b.gift ? 'Send to the new recipient' : 'Send the gift'}</button>
    <p class="ag-error" id="agMErr" hidden></p></div>`;
  document.body.appendChild(wrap);
  const close = () => wrap.remove();
  wrap.querySelector('.ag-modal-x').addEventListener('click', close);
  wrap.addEventListener('click', (e) => { if(e.target === wrap) close(); });
  wrap.querySelector('#agMSend').addEventListener('click', async () => {
    const v = (id) => wrap.querySelector('#' + id).value.trim();
    const err = wrap.querySelector('#agMErr');
    if(!AG_NAME_OK(v('agMFirst')) || !AG_NAME_OK(v('agMLast'))){ err.textContent = 'Please enter their first and last name as on their government ID: letters, spaces, dots, apostrophes and hyphens only.'; err.hidden = false; return; }
    const btn = wrap.querySelector('#agMSend'); btn.disabled = true;
    const r = await agFetch('/api/guest-profile', { method: 'POST', body: JSON.stringify({ mode: 'sendGift', orderId: b.id,
      recipient: { firstName: v('agMFirst'), lastName: v('agMLast'), email: v('agMEmail'), phone: v('agMPhone') || undefined, message: v('agMMsg') || undefined } }) });
    if(!r.ok){ err.textContent = r.data.error || 'Could not send the gift.'; err.hidden = false; btn.disabled = false; return; }
    close();
    if(typeof loadMyBookings === 'function') loadMyBookings();
  });
}
